CREATE TABLE IF NOT EXISTS session_evaluation (
    session_id VARCHAR(64) PRIMARY KEY,
    scene_id VARCHAR(64),
    accuracy_score NUMERIC(5, 2) NOT NULL,
    fluency_score NUMERIC(5, 2) NOT NULL,
    grammar_score NUMERIC(5, 2) NOT NULL,
    vocabulary_score NUMERIC(5, 2) NOT NULL,
    naturalness_score NUMERIC(5, 2) NOT NULL,
    final_score NUMERIC(5, 2) NOT NULL,
    summary TEXT NOT NULL,
    strengths TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    improvements TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT session_evaluation_session_id_check
        CHECK (BTRIM(session_id) <> ''),
    CONSTRAINT session_evaluation_scene_id_check
        CHECK (scene_id IS NULL OR BTRIM(scene_id) <> ''),
    CONSTRAINT session_evaluation_accuracy_score_check
        CHECK (accuracy_score BETWEEN 0 AND 100),
    CONSTRAINT session_evaluation_fluency_score_check
        CHECK (fluency_score BETWEEN 0 AND 100),
    CONSTRAINT session_evaluation_grammar_score_check
        CHECK (grammar_score BETWEEN 0 AND 100),
    CONSTRAINT session_evaluation_vocabulary_score_check
        CHECK (vocabulary_score BETWEEN 0 AND 100),
    CONSTRAINT session_evaluation_naturalness_score_check
        CHECK (naturalness_score BETWEEN 0 AND 100),
    CONSTRAINT session_evaluation_final_score_check
        CHECK (final_score BETWEEN 0 AND 100),
    CONSTRAINT session_evaluation_summary_check
        CHECK (BTRIM(summary) <> '')
);

ALTER TABLE session_evaluation
ADD COLUMN IF NOT EXISTS scene_id VARCHAR(64);

UPDATE session_evaluation AS evaluation
SET scene_id = message.scene_id
FROM (
    SELECT DISTINCT ON (session_id) session_id, scene_id
    FROM session_message
    ORDER BY session_id, message_no
) AS message
WHERE evaluation.session_id = message.session_id
  AND evaluation.scene_id IS NULL;

CREATE INDEX IF NOT EXISTS idx_session_evaluation_scene_id
ON session_evaluation (scene_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_session_evaluation_created_at
ON session_evaluation (created_at DESC);

COMMENT ON TABLE session_evaluation IS
'一场会话结束后的综合练习评分；每个 session_id 只保存一份结果';

COMMENT ON COLUMN session_evaluation.session_id IS
'会话业务标识，与其他会话表保持 VARCHAR(64)，不设置数据库外键';

COMMENT ON COLUMN session_evaluation.scene_id IS
'场景业务标识，用于保留同一场景的历次五维评分，不设置数据库外键';

COMMENT ON COLUMN session_evaluation.strengths IS
'本场会话表现较好的方面';

COMMENT ON COLUMN session_evaluation.improvements IS
'本场会话需要改进的方面';

CREATE OR REPLACE FUNCTION set_session_evaluation_updated_at()
RETURNS TRIGGER
AS 'BEGIN NEW.updated_at = CURRENT_TIMESTAMP; RETURN NEW; END;'
LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS session_evaluation_set_updated_at
ON session_evaluation;

CREATE TRIGGER session_evaluation_set_updated_at
BEFORE UPDATE ON session_evaluation
FOR EACH ROW
EXECUTE FUNCTION set_session_evaluation_updated_at();
-- ===== Practice sessions =====
CREATE TABLE IF NOT EXISTS practice_session (
    session_id VARCHAR(64) PRIMARY KEY,
    user_id UUID NOT NULL,
    scene_id VARCHAR(64),
    scene_type VARCHAR(32) NOT NULL,
    status VARCHAR(16) NOT NULL,
    started_at TIMESTAMPTZ NOT NULL,
    ended_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT practice_session_scene_type_check
        CHECK (scene_type IN (
            'FREE_CHAT',
            'CUSTOM_SCENE',
            'INTERVIEW_SCENE',
            'IELTS_SCENE'
        )),
    CONSTRAINT practice_session_status_check
        CHECK (status IN (
            'CREATED',
            'CONNECTING',
            'WAITING_CLIENT',
            'ACTIVE',
            'PAUSED',
            'INTERRUPTED',
            'COMPLETED',
            'FAILED'
        )),
    CONSTRAINT practice_session_time_check
        CHECK (ended_at IS NULL OR ended_at >= started_at)
);

CREATE INDEX IF NOT EXISTS idx_practice_session_user_started_at
ON practice_session (user_id, started_at DESC);

CREATE INDEX IF NOT EXISTS idx_practice_session_user_completed_at
ON practice_session (user_id, ended_at DESC)
WHERE status = 'COMPLETED' AND ended_at IS NOT NULL;

COMMENT ON TABLE practice_session IS
'全场景练习会话事实；学习时长由 started_at 与 ended_at 计算，不保存聚合统计值';

COMMENT ON COLUMN practice_session.user_id IS
'逻辑关联 user.id，不设置数据库外键';

COMMENT ON COLUMN practice_session.scene_id IS
'场景业务 ID；自由对话和后续无需持久化场景定义的类型也允许记录';
-- ===== IELTS question bank, practice and evaluation =====
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE IF NOT EXISTS ielts_topic (
    id VARCHAR(64) PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    topic_type VARCHAR(24) NOT NULL,
    category VARCHAR(32) NOT NULL,
    source VARCHAR(32) NOT NULL,
    status VARCHAR(16) NOT NULL DEFAULT 'READY',
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS ielts_question (
    id VARCHAR(64) PRIMARY KEY,
    topic_id VARCHAR(64) NOT NULL,
    part VARCHAR(8) NOT NULL,
    sort_no INTEGER NOT NULL,
    question_text TEXT NOT NULL,
    cue_points JSONB NOT NULL DEFAULT '[]'::JSONB,
    recommended_expressions JSONB NOT NULL DEFAULT '[]'::JSONB
);

CREATE INDEX IF NOT EXISTS idx_ielts_topic_filter
ON ielts_topic (topic_type, category, status);

CREATE INDEX IF NOT EXISTS idx_ielts_topic_title_trgm
ON ielts_topic USING GIN (title GIN_TRGM_OPS);

CREATE INDEX IF NOT EXISTS idx_ielts_question_topic
ON ielts_question (topic_id, part, sort_no);

COMMENT ON TABLE ielts_topic IS
'雅思口语训练题组。Part 1 为问题池，Part 2 和 Part 3 为绑定题组。';

COMMENT ON COLUMN ielts_topic.id IS '题组唯一标识。';
COMMENT ON COLUMN ielts_topic.title IS '题组标题，也是关键词搜索和相关性搜索的目标字段。';
COMMENT ON COLUMN ielts_topic.topic_type IS '题组类型：PART_1_POOL 或 PART_2_3_BUNDLE。';
COMMENT ON COLUMN ielts_topic.category IS '训练分类，例如人物、地点、事件、事物、居住、工作或学习。';
COMMENT ON COLUMN ielts_topic.source IS '题目来源，例如 CAMBRIDGE 或 XDF_2026_01_04。';
COMMENT ON COLUMN ielts_topic.status IS '题组状态：READY、PENDING_REVIEW 或 DISABLED。';
COMMENT ON COLUMN ielts_topic.created_at IS '题组创建时间。';
COMMENT ON COLUMN ielts_topic.updated_at IS '题组最后更新时间。';

COMMENT ON TABLE ielts_question IS
'雅思口语具体问题，通过 topic_id 与题组进行应用层逻辑关联，不设置数据库外键。';

COMMENT ON COLUMN ielts_question.id IS '问题唯一标识。';
COMMENT ON COLUMN ielts_question.topic_id IS '所属题组 ID，仅作应用层逻辑关联。';
COMMENT ON COLUMN ielts_question.part IS '问题所属部分：PART_1、PART_2 或 PART_3。';
COMMENT ON COLUMN ielts_question.sort_no IS '问题在当前题组及 Part 中的展示顺序。';
COMMENT ON COLUMN ielts_question.question_text IS '问题正文，Part 2 保存主题描述。';
COMMENT ON COLUMN ielts_question.cue_points IS 'Part 2 的提示要点；Part 1 和 Part 3 使用空数组。';
COMMENT ON COLUMN ielts_question.recommended_expressions IS '该问题对应的推荐表达及中文解释。';

