INSERT INTO ielts_question (
    id, topic_id, part, sort_no, question_text, cue_points, recommended_expressions
)
VALUES
    ('ielts_q_a7c706c0b8b1c18de66d5fcb', 'ielts_group_77f5e1acf5794d2745851ec5', 'PART_1', 1, 'How do you usually spend your weekends? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it depends. If weather permits, I will go jogging or go out with friends. In contrast, if the weather is bad, I will stay indoors and read novels. I enjoy doing what I feel like doing and not being restricted by errands.\n\nit depends 视情况而定 be restricted by errands 受差使的限制","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_91a68659891d572f8447b5c7', 'ielts_group_77f5e1acf5794d2745851ec5', 'PART_1', 2, 'Which is your favourite part of the weekend? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I love Friday evenings when everyone is laid back, because the entire weekend is waiting ahead. On Friday evenings, I usually eat out with friends and then stay up for a movie or a TV show, knowing that I''ll be able to sleep in the next morning\n\nlaid back 放松的 eat out 出去吃饭\n\nstay up 熬夜 sleep in 睡懒觉","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d808b5e20e10b03276c482c5', 'ielts_group_77f5e1acf5794d2745851ec5', 'PART_1', 3, 'Do you think your weekends are long enough? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"No, I wish I had more spare time to entertain myself and loosen up after a whole week''s toil. If I had longer weekends, I would be able to exercise on a weekly basis. I might take up swimming and cycling or join the gym to work out. \n\nloosen up 放松 toil 辛苦\n\non a weekly basis 每周 take up 开始做某事\n\nwork out 锻炼","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fab42fb18f424ff372515926', 'ielts_group_77f5e1acf5794d2745851ec5', 'PART_1', 4, 'How important do you think it is to have free time at the weekends? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It is absolutely essential. First of all, I can spend some quality time with my family. In addition, a good weekend can help me unwind mentally and physically. I usually find myself more efficient and productive in the following week if I''ve had enough quality sleep on the weekend. I guess it''s probably because our brains need rests in order to memorise and process things better.\n\nQuality time 品质时间（指和家人共度的愉快时光） unwind mentally and physically 放松身心\n\nProductive 高效的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8eee6ae4b3910fe987db45dd', 'ielts_group_fc280cf842396bee1e3f02f5', 'PART_2', 1, 'Describe someone you know who does something well.', '["who this person is","How you know this person","what they do well","and explain why this person is so good at doing this."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"人物简介-The person I''m going to tell you about is someone I''ve admired for a long time. He was my high school English teacher, one of the most respected teachers among the students. He was extremely talented in teaching and proficient in English.\n\n认识经历-My first impression with him was when he came into our classroom to teach the first lesson. We all liked him immediately because of his cheerful and radiant charisma. His class was pretty impressive as well, as he demonstrated his professional knowledge, engaging personality and a strong sense of humour.\n\n才能介绍-He has all the distinctive characteristics of a good foreign language teacher, I remember at that time, he adopted a communicative teaching method to interact with the students and organised classroom activities. He covered a lot of knowledge points during class, not only language and linguistics, but also history, culture and arts. He was also good at putting theories into practice and turning complicated problems into interesting or even inspiring stories.\n\n解释原因-I highly regard him as an excellent teacher, not only because of the practical language skill she taught us or the thought-provoking lectures he gave, but also because he helped us achieve insight into the world and maintain a healthy outlook on life.","translation":"","usageNote":"原题库提供的参考表达"},{"type":"EXPRESSION","expression":"admire","translation":"钦佩 impressive 给人印象深刻的","usageNote":""},{"type":"EXPRESSION","expression":"respected","translation":"受到尊敬的 demonstrate 展现","usageNote":""},{"type":"EXPRESSION","expression":"be proficient in","translation":"精通某事 professional knowledge 专业知识","usageNote":""},{"type":"EXPRESSION","expression":"cheerful","translation":"快乐的 engaging personality 迷人的个性","usageNote":""},{"type":"EXPRESSION","expression":"radiant","translation":"光芒四射的 a strong sense of humour 很强的幽默感","usageNote":""},{"type":"EXPRESSION","expression":"charisma","translation":"魅力 distinctive characteristics 特色","usageNote":""},{"type":"EXPRESSION","expression":"communicative teaching method","translation":"交际教学法 inspiring 具有启发性的","usageNote":""},{"type":"EXPRESSION","expression":"interact with","translation":"和…互动 thought-provoking 发人深省的","usageNote":""},{"type":"EXPRESSION","expression":"linguistics","translation":"语言学","usageNote":""},{"type":"EXPRESSION","expression":"achieve insight into the world","translation":"得到对世界的理解","usageNote":""},{"type":"EXPRESSION","expression":"put theories into practice","translation":"把理论运用到实践中","usageNote":""},{"type":"EXPRESSION","expression":"maintain a healthy outlook on life","translation":"保持积极的人生观","usageNote":""}]'::JSONB),
    ('ielts_q_c1b089e00eb62085aeeba53e', 'ielts_group_fc280cf842396bee1e3f02f5', 'PART_3', 1, 'What skills and abilities do people most want to have today? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It seems that the most desirable skill for many people at present is the ability to earn more money, because money is fundamental for a better life. In order to make more money, people attend classes on how to do well in the stock market or make profitable investments. From my perspective, however, the most important skills should be getting to know yourself and managing your time efficiently to learn, create and contribute. If you acquire enough skills in that, you don''t have to worry about your finances because money will keep flowing into your bank account. \n\ndesirable 想要得到的 fundamental 基本的\n\nstock market 股票市场 make a profitable investment 做有利可图的投资\n\nflow into your bank account 流进你的银行账户","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_179a13c958d3f5fe97ca421a', 'ielts_group_fc280cf842396bee1e3f02f5', 'PART_3', 2, 'Which skills should children learn at school? Are there any skills which they should learn at home?What are they?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"The most important skills are those that prepare children to become independent and productive citizens when they grow up. Therefore, the aims of school education should not be restricted to the development of academic skills, but communication skills, teamwork ability, logical reasoning methods and learning capacity, which are essential for working in the society. Additionally, life skills are often learned through the examples set by parents and teachers. These skills include being responsible and being respectful. This should be done both at home and at school.\n\nacademic skill学术技能 communication skill 交流能力\n\nteamwork ability 团队合作能力 logical reasoning method 逻辑推理能力\n\nlearning capacity 学习能力 life skill 生活技能","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d2d24a2b7baa408169c27679', 'ielts_group_fc280cf842396bee1e3f02f5', 'PART_3', 3, 'Which skills do you think will be important in the future? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''m not sure, but I''d hazard a guess that the future world would demand more abilities to keep up with the latest ideas and technology. To be more specific, we need to be adaptable, quick-thinking and always ready for changes, because it is conceivable that scientific breakthroughs will drive forward the human society at an amazing speed. Having said that, the basic requirements on human beings will never change, namely, a sense of responsibility, kindness to help and willingness to cooperate. \n\nkeep up with 跟上 adaptable 能适应（社会）的\n\nquick-thinking 反应快的 be ready for changes 随时能应对改变\n\nit is conceivable that 可想而知 scientific breakthrough 科学突破\n\na sense of responsibility 责任感","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9b2d8bd7486ad8ca197502b1', 'ielts_group_fc280cf842396bee1e3f02f5', 'PART_3', 4, 'Which kinds of jobs have the highest salaries in your country? Why is this?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, we often picture rich people as business leaders, doctors or lawyers, because these occupations require more professional knowledge, qualifications and expertise. However, the amount of salaries people receive for a certain job changes with the times. For example, when there is an economic boom, financial advisors and stock brokers may expect a salary raise. During peak holiday seasons, tour guides can also earn a very decent salary.\n\npicture…as… 把…想象成… professional knowledge 专业知识\n\nqualification 资格 expertise 专业资历\n\neconomic boom 经济繁荣期 financial advisor 金融咨询师\n\nstock broker 股票经纪人 peak holiday season 高峰度假期","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_579b8d353bc91c1cef8e1e6c', 'ielts_group_fc280cf842396bee1e3f02f5', 'PART_3', 5, 'Are there any other jobs that you think should have high salaries? Why do you think that?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"To be honest, I can’t think of any job in particular right now, but I believe salary has something to do with the responsibilities you take. People who shoulder more responsibilities should receive higher salaries. For instance, if you are an engineer in charge of the research and development of a key production the company, you should receive far more money than some of your co-workers. \n\nhas something to do with 和…有关 shoulder 肩负，承担\n\nin charge of 管理","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_15c8554e3b7fde60d03c4224', 'ielts_group_fc280cf842396bee1e3f02f5', 'PART_3', 6, 'Some people say it would be better for society if everyone got the same salary. What do you think about that? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t think so. People are engaged in different industries and contribute differently to the society, Even in a small company, each employee should receive salary commensurate with their performance. Only in this way will the staff get fair treatment and become highly motivated to work efficiently and happily.\n\ncommensurate with 和…相匹配的 fair treatment 公正的待遇\n\nbecome highly motivated 有充足的动力","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9ffb54601d0fd5229a307cef', 'ielts_group_68f7ea2a1936fad32064fca4', 'PART_1', 1, 'What types of music do you like to listen to? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In general, I would say that I''m not picky with the genre of music. I mean, I love any type of songs with catchy tunes or thoughtful lyrics. To keep up with the latest trend, I would listen to the songs that are on the top of the charts.\n\nbe picky with对….挑剔 genre类型\n\ncatchy tunes引人注意 thoughtful lyrics动人的歌词\n\nkeep up with跟上，赶得上 on the top of the charts 高居排行榜","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_331e2a38b5d4a6f150eb5f0b', 'ielts_group_68f7ea2a1936fad32064fca4', 'PART_1', 2, 'At what times of day do you like to listen to music? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I would have to say that it really depends. If I have some free time in the evenings, I will turn on the CD player and sound box and hum along with the singer. If I''m fairly busy, then it''s more likely that I will only listen to music on my smartphone when I''m on the subway.\n\nsound box音箱 hum发出低哼声","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c386c8de9d8dde9c7aa37b38', 'ielts_group_68f7ea2a1936fad32064fca4', 'PART_1', 3, 'Did you learn to play a musical instrument when you were a child? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I began to learn piano when I was five. The teacher said that music was in my blood, so my mom saved every penny to pay for my tuition, hoping that I could become a musician, but I was young and carefree at that time, and didn''t work very hard.\n\nsave every penny to省下每分钱去做… carefree无忧无虑的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0f44c8292f34a81d2f87f5fe', 'ielts_group_68f7ea2a1936fad32064fca4', 'PART_1', 4, 'Do you think all children should learn to play a musical instrument? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In fact, I guess that in many ways learning to play a musical instrument is beneficial for the kids, because it cultivates their artistic taste and enhances their mental development. But you also have to understand that not all kids are interested in music; instead, they might be more into handicrafts, painting or sports, so it will be better if they follow their own heart. \n\ncultivate培养 artistic taste 艺术品位\n\nenhance提高，加强 mental development 心智的发展\n\nhandicraft手工艺，手工艺品","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2d9559492c068c226cbafdf5', 'ielts_group_6f049c05be622ee6b9fb8e81', 'PART_2', 1, 'Describe a shop near where you live that you sometimes use.', '["what sorts of product or service it sells","what the shop looks like","where it is located","and explain why you use this shop."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"商店简介：I''d like to talk about a convenience store which is only 5 minutes''walk to my community. It''s nice place with a variety of daily essentials such as sauces, toiletries and skincare products. It also sells household items like cleaning supplies, hardware and kitchen utensil.\n\n商店陈设：The decor of the shop is hideous — ugly pictures on the wall and plastic flowers on the counter. However, the setting is orderly and the shelves are well-organized. There are three main aisles in the shop and when you walk by the shelves, you''ll find that all the goods are categorised into specific groups. Next to the counter, there are big containers of candies and nuts. It is very convenient for you to pick up some candies and weigh them on the scales on the counter.\n\n地理位置：The shop is located in the middle of my residential area, among some restaurants and cafes. So it is a perfect place for you to take an after-meal walk while picking up your favourite goods.\n\n解释原因：The main reason why I''m so fond of this little shop is that you can always get some good deals in it. Besides, the shop assistants are very smart, friendly and attentive.","translation":"","usageNote":"原题库提供的参考表达"},{"type":"EXPRESSION","expression":"daily essential","translation":"生活必需品 sauce调料","usageNote":""},{"type":"EXPRESSION","expression":"toiletry","translation":"洗漱和化妆用品 skincare product护肤品","usageNote":""},{"type":"EXPRESSION","expression":"house hold item","translation":"家居用品 hardware五金","usageNote":""},{"type":"EXPRESSION","expression":"kitchen utensil","translation":"厨房用具 decor装饰","usageNote":""},{"type":"EXPRESSION","expression":"counter","translation":"柜台 setting环境，布置","usageNote":""},{"type":"EXPRESSION","expression":"shelf","translation":"货架 aisle走廊","usageNote":""},{"type":"EXPRESSION","expression":"be categorised into","translation":"被分成..类 scale秤","usageNote":""},{"type":"EXPRESSION","expression":"after-meal walk","translation":"餐后散步 get some good deals买到便宜的好货","usageNote":""},{"type":"EXPRESSION","expression":"attentive","translation":"殷勤的","usageNote":""}]'::JSONB),
    ('ielts_q_aceacc345f45301643cb3d47', 'ielts_group_6f049c05be622ee6b9fb8e81', 'PART_3', 1, 'What types of local business are there in your neighbourhood? Are there any restaurants, shops or dentists for example?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, the place where I live is a large community with hundreds of residents. There are convenience stores offering daily necessities. There are also small department stores selling household supplies. But what I like best are the fruit stands on the two sides of the streets, which provide fruits that are fresh and in season. As for restaurants, you name it! There are all kinds of hot pot restaurants, cafeterias, fast food chains for you to grab a bite.\n\ncommunity小区 resident居民 \n\nconvenience store便利店 daily necessity 日常必需品\n\nhоuѕеhоld supply家居用品 fruit stand 水果摊\n\nin season当季的 You name it!表示应有尽有\n\ngrab a bite 吃点东西","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f8c5b9dca67fde107f581160', 'ielts_group_6f049c05be622ee6b9fb8e81', 'PART_3', 2, 'Do you think local businesses are important for a neighbourhood? In what way?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, certainly in some ways, the running of local businesses is mutually beneficial for the residents and and the business owners. Some earn money by providing services. Others spend money and enjoy a convenient life. But we also have to be aware that some local businesses are unlicensed and illegal, like refreshment stations that have hygiene problems or retailers that sell fake goods.\n\nmutually beneficial互利的 unlicensed and illegal未经许可和非法的\n\nrefreshment station小吃饮料店 hygiene卫生","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b9b941cb6cd4b3ad0e1104b5', 'ielts_group_6f049c05be622ee6b9fb8e81', 'PART_3', 3, 'How do large shopping malls and commercial centres affect small local businesses? Why do you think that is?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think there are several reasons why people choose to go to large shopping malls instead of small shops. Firstly, there is a variety of choice for quality items in the shopping malls, so you can always ensure the quality of the things you buy. Secondly, shopping malls offer holiday sales when everyone can hunt for a bargain. Last but not least, if you are not satisfied with a product you bought from the shopping malls, you can always take it back and get a refund as long as you keep the receipt. But if you go to traditional markets, you can''t try the clothes on to see if they fit you or not.\n\nquality item高质量的产品 holiday sale 假期打折活动\n\nhunt for a bargain讨价还价 get a refund 退货\n\nreceipt 收据","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_dee8d1852e0d3164b7d2e4c9', 'ielts_group_6f049c05be622ee6b9fb8e81', 'PART_3', 4, 'Why do some people want to start their own business?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In my view, there are probably a number of factors involved. The chief cause might be that people are motivated by their dreams and want to do what they like. As well as this, people always believe that being self-employed means earning a lot of money, though in reality it is not that easy, especially for first year start-ups. Additionally, there are people who become their own boss because they don''t want to be controlled by others.\n\nbe motivated by 得到….的鼓舞 be self employed 个体经营\n\nstart-ups 新兴公司","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2252c3efb45741980e3de476', 'ielts_group_6f049c05be622ee6b9fb8e81', 'PART_3', 5, 'Are there any disadvantages to running a business? Which is the most serious?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I am sure most people would agree that there are some negative aspects. I guess the most adverse feature would be that you have to assume heavy responsibilities and be prepared for any possible risks. For example, you need to sit down and think about all of the co8ts of doing and administering the business, making sure that it is profitable. Another trouble may be that you have to work around the clock and burn the midnight oil every day, unless you can find some really good employees whom you can trust while you are away.\n\nassume responsibilities 承担责任 be prepared for risks 做好应对危机的准备\n\nwork around the clock夜以继日地工作 burn the midnight oil开夜车，熬夜工","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4b3e94d41525ec67a1755322', 'ielts_group_6f049c05be622ee6b9fb8e81', 'PART_3', 6, 'What are the most important qualities that a good business person needs? Why is that?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"A good business person should be versatile. The first important quality I can think of is the ability to deal with people effectively. Different people have diversified needs which should be well-considered and taken care of. Besides, a good business person also needs to be visionary and. down to earth at the same time. Other qualities include being conscientious, broad-minded, self-assured and collaborative.\n\nversatile 多才多艺的 deal with people和人打交道\n\ndiversified needs 多样化的需求 visionary 有远见的\n\ndown to earth 脚踏实地的 conscientious认真尽责的，小心谨慎的\n\nbroad-minded心胸宽广的 self-assured自信的\n\ncollaborative合作的，协作的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b09d20682cd9516e4fdf1a0b', 'ielts_group_2f06a06285774f1c0753f32b', 'PART_1', 1, 'Do you enjoy travelling? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Absolutely. I''m an inquisitive person, and it always gets me excited to explore curious places, to experience different cultures, to search for exotic delicacies, and most importantly, to encounter interesting people.\n\ninquisitive 好问的，爱追究到底的 exotic 有异域风情的\n\ndelicacy 美味佳肴 encounter 遇见","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1a968566d0a38592caf5e351', 'ielts_group_2f06a06285774f1c0753f32b', 'PART_1', 2, 'Have you done much travelling? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, sort of. I mean, quantitatively I''ve traveled a lot. I''ve been to more than 50 domestic tour sites so far, as well as a couple of foreign countries. But each time I was only able to stay for no more than a week. It was never enough.\n\nsort of 稍微，有点 quantitatively 从数量上来说\n\ndomestic 国内的，内部的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_081eed3e1058ec98ad6b3995', 'ielts_group_2f06a06285774f1c0753f32b', 'PART_1', 3, 'Do you think it''s better to travel alone or with other people? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Personally, I''d prefer to travel alone because my way of travelling is a bit different. You see, I don''t go to popular tourist attractions where you can see nothing but crowds. And I rarely take pictures so that I travel really fast. On top of everything, I hate shopping. So there would be too much compromise to make for both my friends and me if we travel together.\n\ntourist attraction 旅游景点 on top of everything最重要的是\n\ncompromise 妥协","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cb592576886d7e0be2e7da88', 'ielts_group_2f06a06285774f1c0753f32b', 'PART_1', 4, 'Where would you like to travel in the future? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There are hundreds of places that I''d love to travel in the future, but there are two pilgrimages that I have to make. The first place is Tibet. It''s always been in my wildest dreams to attempt the almighty Mount Everest, to bear witness and to learn to respect the holiness of nature. The other place would be anywhere near the North Pole where I can see the mysterious aurora. \n\npilgrimage 朝圣之路 attempt 尝试，试图（挑战，战胜）\n\nalmighty 神圣的，强大的 bear witness 见证\n\nholiness 神圣，庄严","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_43905251c3392e3d951d1fa5', 'ielts_group_daf5de8eb77a7f3a79309007', 'PART_2', 1, 'Describe a child that you know.', '["who this child is and how often you","see him or her","how old this child is","what he or she is like","and explain what you feel about this child."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Who the child is & How old the child: My nephew is 9 years old.\n\nHow often you see him or her: Actually I don''t get to see him often because he lives with his parents in another city which is far away from my hometown. Every year they would come back to visit us during the Spring Festival.\n\nWhat he or she is like: Everyone in the family adores him because he is really smart and talented. His mother is a primary school teacher. She started to teach him to recognize pictures and to distinguish sounds only a few months after he was born. He was able to mumble short sentences after 15 months, and was able to recite a few poems and to solve some basic math problems at the age of 3. He went to school when he was only 5, and became a school legend ever since.\n\nHe enjoys reading, and he has a wide range of interests in reading, such as biology, history, astrology, biography and so on. And he likes to watch documentary films as well, about the same subjects of course.\n\nI once asked him, when he was reading a history book during one Spring Festival, why he didn''t go have fun. Book in band, eyes still gluing to the page, he said something which struck me shockingly, \"I''m having fun right now.\"","translation":"","usageNote":"原题库提供的参考表达"},{"type":"EXPRESSION","expression":"adore","translation":"喜欢 recognize 认识，辨认","usageNote":""},{"type":"EXPRESSION","expression":"distinguish","translation":"辨认，区分 mumble 咕哝，含糊地说话","usageNote":""},{"type":"EXPRESSION","expression":"recite","translation":"背诵，朗诵 legend 传奇","usageNote":""},{"type":"EXPRESSION","expression":"a wide range of","translation":"范围广泛的 documentary film 纪录片","usageNote":""},{"type":"EXPRESSION","expression":"glue to","translation":"粘住，盯住 strike 打击，震撼","usageNote":""},{"type":"EXPRESSION","expression":"shockingly","translation":"令人吃惊的","usageNote":""}]'::JSONB),
    ('ielts_q_db273b97a290769480bd6868', 'ielts_group_daf5de8eb77a7f3a79309007', 'PART_3', 1, 'How much time do children spend with their parents in your country? Do you think that is enough?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I would say, on average, children don''t get to spend much time with their parents in China. This is mainly because young parents today are under great financial burden, so much so that in most cases they both have to do full-time jobs. And when they come back home, they would be too tired to spend much time with their kids. There are also many cases where parents have to work far from home to be able to bring food on the table and to keep the family running. This explains why in most Chinese families, grandparents are taking care of the young generation.\n\non average 一般，平均来说 in most cases 大部分情况下\n\nbring food on the table 养家糊口","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_bbd138f9954921e5047a1023', 'ielts_group_daf5de8eb77a7f3a79309007', 'PART_3', 2, 'How important do you think spending time together is for the relationships between parents and children? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It is of vital importance. I think the key to developing close relationships between parents and children is good communication, which requires great time and effort to establish. To begin with, they need to spend a lot of time together to develop enough intimacy so that children would feel comfortable and relaxed when staying with parents. In addition, parents and children need to go through difficulties and obstacles together to build up trust among them. It''s highly important for the children to know that whenever there is a problem, parents are the ones to turn to.\n\nvital 重要的，至关生死的 establish 建立，创立\n\nintimacy 亲密度 obstacle 困难，障碍","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5ff8e24569aeb595b54ed3f8', 'ielts_group_daf5de8eb77a7f3a79309007', 'PART_3', 3, 'Have relationships between parents and children changed in recent years? Why do you think that is?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I can''t help noticing that in many families, parents and children are sharing almost equal status in the family, which was very much unheard of decades ago. Parents are no longer playing dictators who would expect their children to act and behave exactly the way they want them to. They have learnt to respect their children''s own choices, and only offer advice and support when needed. On the other hand, children are becoming less rebellious since there isn''t much for them to fight against. I think what causes the change is culture exchange. In a multi-cultural environment, people are more likely to be open-minded and tolerant.\n\nstatus 身份，地位 unhеаrd оf 少有的，前所未闻的\n\nplaying dictator 独裁，专制 rebellious 叛逆的，反抗的\n\ntolerant 宽容的，容忍的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_89a3fc522a202f539f04264b', 'ielts_group_daf5de8eb77a7f3a79309007', 'PART_3', 4, 'What are the most popular free-time activities with children today?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Children today don''t usually go out to play with other kids as I would do when I was little, and toys seems to have lost their charms as well. They now prefer to spend their holidays travelling, watching TV programmes, or playing online games. In most cases, watching TV programmes and playing games would be the popular choices, but when the holiday is long enough, children would beg their parents to take them onto a trip. I think it''s within children''s nature to be curious about the world, so it must be much more\" exciting to explore new places making new friends than to stay at home facing the same people and doing the same things. On top of that, modern technology has made traveling much easier and affordable to most families. At the age of 10, my nephew has already been to 17 countries in the world. I really wish that I were young again.\n\ncharm 魅力，魔力 prefer to 宁愿\n\ncurious 好奇的 on top of that 除此之外","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4b776e316e4b5aceee1746bc', 'ielts_group_daf5de8eb77a7f3a79309007', 'PART_3', 5, 'Do you think the free-time activities children do today are good for their health? Why is that?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think it depends on what they do and how they do it. Travelling is definitely good for people''s health. When you travel, chances are that you’ll do a lot of hiking, you''ll probably participate in a variety of outdoor activities, and you are likely to live a rather regular life due to the disconnection from the Internet and games. And games, on the other hand, can lead to serious health problems. Games are addictive in nature to which children are vulnerable. Kids who are obsessed with online games are exposed to the potential danger of having myopia, spinal curvature and muscular atrophy, because they sit for long hours with eyes gluing to the screen.\n\nchances are that... 很可能的情况是 participate in参与\n\na variety of 各种各样的 due to 因为\n\naddictive 令人上瘾的 in nature本质上\n\nvulnerable 脆弱的，易受伤害的 be obsessed with 对某事着迷\n\nbe exposed to暴露于 myopia 近视\n\nspinal curvature 脊柱弯曲 muscular atrophy 肌肉萎缩","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_db1c86d6a01a39f132b2c353', 'ielts_group_daf5de8eb77a7f3a79309007', 'PART_3', 6, 'How do you think children''s activities will change in the future? Will this be a positive change?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think parents today have already recognised the detriment of children staying indoors too much. Soot I in the future I believe parents will spend more time with their children and they would travel together, go hiking and camping together, do some sports together and spend more time outdoors together. This will definitely exert a positive influence on children because it''s good for children''s health as I mentioned before, and more importantly, it could provide more opportunities for children and parents to stay together as a family, to understand each other better, to bond more tightly, so that children can grow in a healthier environment.\n\nrecognise认出，识别，承认 detriment危害\n\nexert施加（影响，压力等） influence影响\n\nbond黏合，团结 tightly紧密地","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e9e40dc8a026ba93165de6aa', 'ielts_group_6a0ee143437af4dfe3b683de', 'PART_1', 1, 'Did you go to secondary/high school near to where you lived? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Not really, my high school is a bit far from where I lived. It ''s about an hour bus-ride away, if the traffics not too heavy I remember I used to have to get up around six o''clock in the morning to catch the 6:30 bus. It was really a torture in winter. But I don’t regret choosing it. After all, it was considered the very best high school in town.\n\na bit一点儿；有些 torture折磨","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_82907dc6077411d03f56de5e', 'ielts_group_6a0ee143437af4dfe3b683de', 'PART_1', 2, 'What did you like about your secondary/high school? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There are a couple of things I like about, or even feel proud of my high school. I think the most amazing thing about my school is that it encourages and respects individuality, which means students are free to make a lot of choices. For example, wearing uniform was not mandatory unless for special occasions.\n\nindividuality个性 mandatory强制的，必须的\n\noccasion时机，场合","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_df1d7932bd3033e6e1766dcf', 'ielts_group_6a0ee143437af4dfe3b683de', 'PART_1', 3, 'Tell me about anything you didn''t like at your school.', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I can''t actually recall anything I dislike about my school right now except that the school playground was too small. My high school was founded 70 years ago. It was big enough back then, when it only had to accommodate one tenth of the amount of students today, There were only four basketball courts, so every day it was super crowded.\n\nrecall回忆","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_174a1d221863cde1b6d6b242', 'ielts_group_6a0ee143437af4dfe3b683de', 'PART_1', 4, 'How do you think your school could be improved? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"As I just mentioned, my school is very small, and many of the school buildings are pretty old. I think it''ll be great if my high school buy a piece of new land somewhere and build a new campus with enough space to build all kinds of facilities.\n\ncampus校园","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_21841f729f85326bddf8081c', 'ielts_group_723dbc63f8854d127611385d', 'PART_2', 1, 'Describe something you don''t have now but would really like to own in the future.', '["what this thing is","how long you have wanted to own it","where you first saw it","and explain why you would like to own it."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"What this thing is, How long I have wanted to own it: Well, I found it really challenging to single out one item from the list of things I''d like to possess in the future. Most of the things I fantasized about are remotely unattainable, but if I have to choose one to talk about, it would be the Bugatti Veyron super sports car.\n\nWhere I first saw it: Actually I''ve never had the opportunity to see one in real life. Everything I know about Bugatti is from either magazines or documentary films.\n\nWhy I would like to own it: I have been obsessed with cars since childhood. My father was a locomotive driver back then. He used to buy all kinds of books and magazines about engines and automobiles, and he loved to teach me to recognise and appreciate those fancy cars. Gradually, I became a big fan.\n\nI love a variety of world-class vehicles, but Bugatti Veyron is one of a kind. With the top speed of 430 kilometers per hour, it''s the fastest mass-produced vehicle on earth. Its mighty W16 engine can produce as much as 1200horsepower, and the uniquely designed automatic dual- gearboxes allow nearly no power loss during the transmission, which empowers the vehicle to accelerate from 0 to 100 km/h within only 2.5 seconds. But that''s not the ultimate, face-melter. At the speed of 100 km/h, this iron beast can be called to a, full halt in just 2.2 seconds.\n\nBugatti is probably not one of the best-looking vehicles, nor is it the most expensive one, but it is the very beauty in my dream.\n\nsingle out挑选 unattainable难以获得的，不切实际的\n\nlocomotive机车 world-class世界级的\n\nempower授权，使能够 accelerate加速\n\nface-melter让人吃惊的东西 call to a full halt完全停止\n\none of a kind独-无二的，自成一派的 mass-produced量产的\n\nmighty强大的 empower授权，使能够\n\naccelerate加速 face-melter让人吃惊的东西\n\ncall to a full halt完全停止","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8a29fd5be749116a267a8761', 'ielts_group_723dbc63f8854d127611385d', 'PART_3', 1, 'What types of things do young people in your country most want to own today? Why is this?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it''s hard to say. As a matter of fact, I don''t even know what I want, However, I think in general there are few things that people in China would like to add into their possessions. On top of the list is a house. It comes on top because, first of all, we all need a roof to shelter, and secondly, owning a house has become a luxury in China since the housing price is ridiculously high today. Listed next to a house is a private car, the fancier the better. To young people, a car stands for much more than a means of transportation. It functions as a name card which manifests one''s economic status, social class, aesthetic taste, and even personalities.\n\nshelter躲避，避难 luxury奢侈品\n\nfunction运行 aesthetic美学的，审美的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b09b481e7d99ad4d85b30d87', 'ielts_group_723dbc63f8854d127611385d', 'PART_3', 2, 'Why do some people feel they need to own things?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Personally, I believe that we all, one way or another, share the same kind of feeling. The craving for properties is hardwired into people''s brain since primitive time when people still had to struggle for existence. People had to collect everything they can get in hand so as to survive floods, droughts, starvation, plagues, social turbulence, wars and so on. It gives people a sense of security, which is one of our basic emotional needs. Now that we are almost free from those worries, this powerful instinct still governs our behavioral pattern and drives us to pursue things that we don''t actually need.\n\none way or anther无论如何 craving渴望，欲望\n\nhardwired嵌入的 primitive原始的\n\nplague瘟疫 social turbulence社会动荡\n\nbe free from摆脱，不受制约的 govern指导，控制\n\nbehavioral pattern行为模式 pursue追求","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_973e8fa760a427a7e80b92bc', 'ielts_group_723dbc63f8854d127611385d', 'PART_3', 3, 'Do you think that owing lots of things makes people happy? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Much as I find it hard to admit, I believe owing lots of things does give people a sense of happiness. From the scientific point of view, happiness is simply the bio-electric signal perceived by our brain which is caused by a neurotransmitter called dopamine. And recent studies have discovered that collecting things would increase the level of dopamine in human brain. I know there are people saying something like \"I have a lot of money, but I don''t feel happy\". However, I think the problem is not about having a lot of money, but about missing something else such as family, love, vacation and recognition. So such claim actually approves that we always want some more.\n\nPerceive接收，感知 neurotransmitter神经介质\n\ndopamine 多巴胺 approve 证明","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_aa5527844da7f4c7052599f2', 'ielts_group_723dbc63f8854d127611385d', 'PART_3', 4, 'Do you think television and films can make people want to get new possessions? Why do they have this effect?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Absolutely, such is human nature that the more we know, the more we want. Television and films constantly feed people with information about different life styles, new technologies, fashion trends, and luxurious items, creating an ever-developing concept of better life\" to catch up with. What makes things worse is TV commercials. They create false needs, sell false hopes, and make false promises. ''d lose my count if were to recall everything I bought which I rarely used, but still, I keep buying things. As the society develops, so grows my lust. It''s simply something I cannot resist.\n\nhuman nature人类天性 constantly不间断地\n\never-developing不断变化的 recall回议\n\nlust欲望 resist抵制，抗拒","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0d8d6141e5f0b98c20def223', 'ielts_group_723dbc63f8854d127611385d', 'PART_3', 5, 'Are there any benifits to society of people wanting to get new possessions? Why do you think this is?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Of course there are benefits to it, I think people''s desire for new possessions is indeed the ultimate driving force that pushes the society to develop and to move forward. If it were not for this powerful drive, we wouldn''t have had been able to accumulate enough food and properties to support massive population, without which the first human civilization wouldn''t have had emerged. In modern ages, on one hand, it motivates people to work hard so as to earn new possessions; on the other hand, it inspires people to devise new contraptions and conceptions to meet the public needs.\n\nultimate终极的 drive驱动力\n\naccumulate积累 massive大量的\n\nemerge出现 motivate激发，刺激\n\ninspire启发 devise发明，设计\n\ncontraption设计，装置","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ec05c505a30b95b953fd4824', 'ielts_group_723dbc63f8854d127611385d', 'PART_3', 6, 'Do you think people will consider that having lots of possessions is a sign of success in the future? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think we need to broaden our understanding about possessions. In my understanding, they could be either tangible or intangible. Tangible possessions range from money, jewelry, clothing to new gadgets, real estate properties and automobiles, while intangible possessions include occupational qualifications, academic degrees, reputation, friendship. Facebook fans and equipment in computer games. One way or another, we are all pursuing something we highly value and appreciate, and having a large possession of whatever it is can definitely give us a strong sense of success and happiness.\n\nbroaden拓展 tangible/intangible有形的/无形的\n\nrange from…to…范围包括… gadget装备，设备\n\nreal estate properties房产 occupational qualification职业证书\n\nreputation声誉，声望","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_48766e7a896c705ee542367b', 'ielts_group_0238d10e334b7fc92e420460', 'PART_1', 1, 'What sorts of food do you like eating most? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Ooh, I love sweet food. You know, pie, cookie, cake, chocolate, ice-cream... you name it. I think the sweets has a magic power to cheer me up and keep my spirits high.\n\nyou name it 凡是你能想到的 cheer someone up 使某人振作起来 \n\nkeep someone''s spirit high 使某人保持兴奋","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_02066617da103b5734b330cf', 'ielts_group_0238d10e334b7fc92e420460', 'PART_1', 2, 'Who normally does the cooking in your home? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"My dad does more cooking at home these days. The reason is rather simple: my mom is a lousy cook. To speak fairly, she used to be popular in the kitchen, till one day, she went to a nutrition class, and everything was ruined. She began to give up using spices and sauces, then moved on to declare a war against salt and fat. So my dad sort of got promoted.\nlousy 糟糕的 nutrition 营养；营养学\nruin 毁灭；毁坏 declare war against 向…宣战 \npromote 提拔；升职","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c910435e23c678fb77cc53f0', 'ielts_group_0238d10e334b7fc92e420460', 'PART_1', 3, 'Do you watch cookery programmes on TV? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"No, I don''t. As a matter of fact, I rarely watch telly. The only TV programme I watch occasionally is NBA games. As for cookery programmes, I doubt that I would grow any interests in it. I''m okay with learning how to cook to the point where I''m capable of feeding myself. Beyond that, I don''t want to waste my time.\nTelly 电视（英国俚语） grow interest in something 对某事产生兴趣","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_66b0bc1f140feb569d0cf2de', 'ielts_group_0238d10e334b7fc92e420460', 'PART_1', 4, 'In general, do you prefer eating out or eating at home? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, in general I don''t have a choice, and to people without choices, preference is a luxury. You see, just because my dad is dominating the kitchen now doesn''t mean he is a good cook; it''s just my mom''s worse. So ... yup, eating out would be a relief.\nluxury 奢侈品 dominate 统治；占主导地位\nrelief 安慰；解脱","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8eb2a73ecc4efd3ef8588725', 'ielts_group_857c5988d17a79cb8203cae7', 'PART_2', 1, 'Describe a house/apartment that someone you know lives in.', '["whose house/apartment this is","where the house/apartment is","what it looks like inside","and explain what you like or dislike about this person''s house/apartment."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"房产归属：My father has a friend who is a post-modern sculptor. I call him Uncle Wu.\n\n地理位置：He lives in a big home-studio in Chaoyang District in Beijing, near the North Fifth Ring Road. He named it Wu Zhi Zhai, which means the house of innocence and ignorance.\n\n内容装潢：The studio is converted from an obsolete warehouse. About 20 years ago, young Uncle Wu went to Beijing with nothing but dreams. He couldn''t afford to live in a decent place in town, so he had to take shelter under such poor condition. Back then there was no Fifth Ring Road yet, and the location of the warehouse was unheard of even to some of the locals. He started his art creation there, and gradually became famous. After he earned his first bucket of gold, he bought this warehouse and turned it into a fascinating art work.\n\nThe first thing he did was to replace its leaky roof with an arrangement of translucent and transparent reinforced glasses. Coming next, he took out the concrete floor and filled it with soil. Now it was only natural for him to plant all kinds of vegetation, which, of course, he did. In the south of the house he paved a yard with pebbles, and built a small two-story house there. Curious-looking metal sculptures are displayed in the garden, blending in with plants, looking alive.\n\n个人喜好：I like this house as much as I like his idea that these artificial sculptures are lifeless without being displayed in the garden, which reminds people that humans are innocent and ignorant in front of nature.\n\n重点词句\n\npost-modern 后现代 sculptor 雕塑家\n\ninnocence 纯真 ignorance 无知\n\nconvert 改造 obsolete 废弃的\n\ndecent 得体的;像样的 take shelter 躲避\n\nunheard of 不知名的;前所未闻的 fascinating 迷人的\n\ntranslucent 半透明的 transparent 透明的\n\nreinforced 强化的 concrete 混凝土\n\npebble 鹅卵石 blend in 融入","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a527b373d49a9a3b791fd803', 'ielts_group_857c5988d17a79cb8203cae7', 'PART_3', 1, 'What kinds of home are most popular in your country? Why is this?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Definitely not a big house in the countryside. First of all, it''s too expensive. Second, traffic in China is no joke; no one would really enjoy living too far off the city centre except some super-rich people who have too much time and money to squander and who don''t commute at all. I think the ideal type of home in China is a medium-size apartment on higher floors in a high-rise building that is not too far from the city centre with a good view outside the window and all the modern conveniences available in the neighbourhood: shopping centres, hospitals, entertainments, parks, sports facilities, schools, etc. \n\nno joke 不是闹着玩的 squander 浪费 \ncommute 通勤；上下班 convenience 便捷 (此处意指各类便捷设施，为可数名词）\nfacilities 设施；设备","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5426a6317299376de849c572', 'ielts_group_857c5988d17a79cb8203cae7', 'PART_3', 2, 'What do you think are the advantages of living in a house rather than an apartment?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, can I say I don''t know since I''ve never lived in a house? The only difference I can think of now is that you may have a garden or probably an additional backyard of your own, but I personally don''t see it as an advantage at all. Chinese people don''t really appreciate the culture of gardening. We don''t know what to do with an open lot especially when it''s not big enough to do farming on. And besides, nowadays, who has the time to take care of branches and leaves anyway? Another difference is that there would be less people around if you lived in a house. But we Chinese people love having a lot of neighbours so that when we need help, helping hands come fast. So, like I said, living in a house doesn''t seem very appealing.\n\nappreciate 欣赏；喜欢 gardening 园艺\nlot 空地 helping hand 援手；帮助\nappealing 有诱惑力的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1a86dc73866fbdbadb14440f', 'ielts_group_857c5988d17a79cb8203cae7', 'PART_3', 3, 'Do you think that everyone would like to live in a larger home? Why is that?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think that varies from case to case. For people who currently dwell in a small place, a larger home is absolutely what they would fight for. My family crowded in a small apartment when I was young. There wasn''t enough space to stand a desk in my bedroom so I had to do my homework on bed. Now I have a room twice bigger, but doing cleaning has become a new problem. Chinese philosophy believes that beyond the limits is as bad as falling short. So I would say everyone would like to live in a home that is big enough.\n\nvary 区分；区别 dwell 居住\ncrowd 挤；塞 ( 此处指居住 ) fall short 不够；不足","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b84d054100b8f4cffaecf1a3', 'ielts_group_857c5988d17a79cb8203cae7', 'PART_3', 4, 'How easy is it to find a place to live in your country？', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It''s hard to say. It largely depends on two things: the depth of your pocket, and the complexity of your requirement. If budget doesn''t concern you, just call a rental agency, tell them what you need, and then all you have to do is to wait. And this can be easily done on a smart phone today. An ideal home is only a clicking away. If you don''t have high expectations, It''ll be easy as well. However, if you are trying to strike a balance between economy and comfort, you''ll need a lot of patience.\n\nthe depth of pocket 口袋深度(指经济状况) complexity 复杂度\nbudget 预算 strike balance between...and... 在…之间寻找平衡","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_22095f9e802c09d2286f2d0e', 'ielts_group_857c5988d17a79cb8203cae7', 'PART_3', 5, 'Do you think it''s better to rent or to buy a place to live in? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Unless I have decided to settle down in a place for the rest of my life, I would otherwise choose to rent a house. First of all, housing price here is preposterous. In my hometown, the average annual income is approximately thirty thousand RMB. Even if one can manage to save half of the money, it''ll still take forty years for him or her to finally be able to buy a house. And my hometown is only a third-tier city, so you can imagine what it''s like in major metropolises such as Beijing and Shanghai.\n\nsettle down 定居 preposterous 荒唐的 \nannual 每年的 approximately 大约 \nmetropolis 大都市","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_aa37b50a345ee4957a081102', 'ielts_group_857c5988d17a79cb8203cae7', 'PART_3', 6, 'Do you agree that there is a right age for young adults to stop living with their parents? Why is that?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, it makes perfect sense. I think it''s very important for young adults to stop living with parents so that they could really learn to take responsibilities and to be independent. Parents, especially Chinese parents, are over-protective, or, say, manipulative. They would try all possible means to make sure that their kids are safely on the \"right track\". As a result, many youngsters in China, whenever in trouble, turn to their parents for help, instead of trying to find solutions by themselves. In China, every one grow sold, but not everyone grows mature. I seriously believe that this needs to be changed.\n\nmake sense 有道理 over-protective 保护欲望过强 \nmanipulative 有操纵欲的 mature 成熟","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_49f14d8069555c744aa5f8de', 'ielts_group_114210b402b42fb688136c68', 'PART_1', 1, 'How often do you go out with friends? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''m a student, I don''t have to go out to meet my friends — we see each other every day. And when the school''s off, I hang out with friends from my neighbourhood. We play basketball, watch films, listen to music ... just goofing around, you know.\nhang out 聚会；玩耍 goof around 打发时间","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2ae6f11463f8e5ed7c16a2c2', 'ielts_group_114210b402b42fb688136c68', 'PART_1', 2, 'Tell me about your best friend at school.', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"My best friend is Josh. We have been sworn brothers since junior-high. I mean, seriously, we literally took an oath to have each other''s back. His family moved into my neighbourhood when I was ten. We soon became buddies because we share a lot of similarities. We both are food suckers, music lovers and trouble makers. We even look similar. It''s good to have a friend like him.\nsworn brother 死党，哥们 literally 确实；字面意思上的\ntake oath 发誓 have someone’s back 照顾某人\nbuddy 好朋友","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c1d2a0fadd8146d4b8cc5202', 'ielts_group_114210b402b42fb688136c68', 'PART_1', 3, 'How friendly are you with your neighbours? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I guess I''m too young to be friendly with my neighbours. I mean, I say hello to everyone, and I won''t hesitate to land a hand when they need help, but I rarely talk to my neighbours, except kids of my age. \nhesitate 犹豫 land a hand 提供帮助","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8725283a614c886202ce3297', 'ielts_group_114210b402b42fb688136c68', 'PART_1', 4, 'Which is more important to you, friends or family? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"One day, when I were much older, I might regret what I''m about to say. But for now, I really think friends are more important than family. Yes, I know my family love me and will support me unconditionally, but they sometimes don''t seem to understand me. And I can''t expect they do because we grow up in very different situations. So, much as I love my family, I still think friends are more important for now.\nregret 后悔 unconditionally 无条件的\nfor now 就目前而言","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_74208bcd9a07f17b0ffc6512', 'ielts_group_f3736b67d6873886938f6bce', 'PART_2', 1, 'Describe a writer you would like to meet.', '["who the writer is","what you know about this writer already","what you would like to find out about him/her","and explain why you would like to meet this writer."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"话题卡说明：\n作者身份：It would be my greatest honour if I had the opportunity to meet Kevin Kelly—a visionary thinker, an adventurous traveler, a passionate photographer, and a prolific writer.\n已知信息：He is known as the founding executive editor of Wired magazine, the co-sponsor of the first Hackers Conference, and the author of a great many marvelous publications including Out of Control, What Technology Wants, and The Inevitable. In his most noted work Out of Control, Kevin presented an argument that intelligence is not generated from a powerful centralized brain-like processor, but from a rather unorganized network of simple and small units such as a bee -hive. Every unit is specialized to tackle one simple task, but when the network is big enough, a systemic complexity would emerge, and intelligence would thus appear. This book is said to have had profound impact upon Steve Jobs, which inspired him to come up with the “Cloud” technology. \n为何见面以及想了解什么信息：In his new book What Technology Wants, Kevin takes a step further and starts to question the nature of life. In his model, life is a counterforce against the ever-growing entropy of the universe. He named it “Extropy\", and thereby assume that life, by essence, is information, and technology is fundamentally a form of life.\nBut what is information? If Extropy, namely life, is by definition orderliness, does that mean information is supposed to be orderly organized? Is chaos a kind of information? If not, then when we talk about chaos, what exactly are we talking about? All these questions are haunting me, begging for answers. So, if I had the opportunity to meet Mr. Kelly, we''d have so much to talk about.","translation":"","usageNote":"原题库提供的参考表达"},{"type":"EXPRESSION","expression":"Visionary","translation":"有远见的 Adventurous 有冒险精神的","usageNote":""},{"type":"EXPRESSION","expression":"Prolific","translation":"多产的 Marvelous 不可思议的","usageNote":""},{"type":"EXPRESSION","expression":"Argument","translation":"论证 Generate 产生；发生","usageNote":""},{"type":"EXPRESSION","expression":"Processor","translation":"处理器 Bee-hive 蜂窝","usageNote":""},{"type":"EXPRESSION","expression":"Systematic","translation":"系统的 Complexity 复杂性","usageNote":""},{"type":"EXPRESSION","expression":"Emerge","translation":"涌现 Impact 影响；冲击","usageNote":""},{"type":"EXPRESSION","expression":"Question","translation":"质问 Counterforce 反作用力","usageNote":""},{"type":"EXPRESSION","expression":"Entropy","translation":"熵","usageNote":""},{"type":"EXPRESSION","expression":"By essence","translation":"从本质上来说","usageNote":""},{"type":"EXPRESSION","expression":"Fundamentally","translation":"从根本上说","usageNote":""},{"type":"EXPRESSION","expression":"By definition","translation":"根据定义","usageNote":""},{"type":"EXPRESSION","expression":"Chaos","translation":"混乱；混沌","usageNote":""},{"type":"EXPRESSION","expression":"Haunt","translation":"萦绕","usageNote":""}]'::JSONB),
    ('ielts_q_abdbd08bcbf22a95c7fcaa49', 'ielts_group_f3736b67d6873886938f6bce', 'PART_3', 1, 'What kinds of book are most popular with children in your country? Why do you think that is?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, you got me on this. I mean, I don''t know what kids are reading today. My guess is, and no offence, that boys still dig science fictions and history, and girls fairy tales and fable stories. Anyway that''s what everyone reads when I was a child. And I can''t honestly explain why. Some scientists are trying to figure out why men and women show talents in very different fields. They believe such difference is hard-wired within our brains or something. It''s just way too complicated.\nno offence 无意冒犯 dig 喜欢 \nfable story 寓言故事 hard-wired 与生俱来的，固有的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8de3b43ca40b4d5fcf478294', 'ielts_group_f3736b67d6873886938f6bce', 'PART_3', 2, 'Why do you think some children do not read books very often?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It wouldn''t surprise me, since many adults today don’t read much, if they read at all. To kids, parents are like role models. Children tend to learn pretty much everything from their parents because they think they can trust them. That''s why family influence plays a vital role in the development of juveniles. Another reason, of course, is that children are exposed to too much temptation today. Video games,TV series, entertainment shows, you name it. They are distractive, and some are even addictive. It wouldn''t wonder kids don''t have time for reading now.\nrole model 榜样 play a role in 扮演某种角色 \nvital 重要的 juvenile 青少年\nexpose 暴露，接触 temptation 诱惑\ndistractive 分散注意力的 addictive 易上瘾的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5e5498640d8348a9a5d3de2a', 'ielts_group_f3736b67d6873886938f6bce', 'PART_3', 3, 'How do you think children can be encouraged to read more?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Children don''t need encouragement to do more reading, they need environment. As I mentioned just now, parents need to create an atmosphere of reading at home. Kids are naturally curious. They are eager to absorb new information from their surroundings so as to form understanding about the world. They are like Alice in the wonderland; all you need to do is to lead them to the rabbit hole, and they''ll set out to do the digging. Unfortunately, many kids fail to see that there are rabbit holes hidden in books.\natmosphere 氛围 curious 好奇的\nabsorb 吸收 the rabbit hole 《爱丽丝梦游仙境》里面的场景，意指充满神秘感的事物\nset out 动身；出发","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2e21e816aeeb581fa158d4dc', 'ielts_group_f3736b67d6873886938f6bce', 'PART_3', 4, 'Are there any occasions when reading at speed is a useful skill to have? What are they?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I might need a second, you know, I''ve never thought about it before. Can I talk about IELTS exam? You know, in the reading test this morning, I think I totally screwed up. I did one or two practice tests prior to the exam. I scored pretty high in reading except that I didn''t time myself. So what got me this morning was not the vocabulary, nor was the complex sentence structure, but the clock hung above the wall of the test room. I simply just couldn''t finish it. Should I fail this time, I would really have to work on my reading speed.\nscrew up 搞砸 prior to 在......之前","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_85ba46cab7eac16cb700dd1d', 'ielts_group_f3736b67d6873886938f6bce', 'PART_3', 5, 'Are there any jobs where people need to read a lot? What are they?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, there are many of them. Almost all scholars are bookworms, such as historians, sociologists, anthropologists, linguists, etc. Teachers read even more. On the one hand, they have to keep up with the latest discoveries in the realm of the subjects they teach, on the other hand, they need to keep updating their knowledge of teaching. Besides that, government officers also have to read a lot. They read newspapers and magazines and piles of documents every day because they need to have a clear picture about the status quo so that they can make reasonable policies to deal with the situations.\nkeep up with 跟上 realm 领域；王国 \nupdate 更新 status quo 现状","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2438da0c5185d8f07a6cd829', 'ielts_group_f3736b67d6873886938f6bce', 'PART_3', 6, 'Do you think that reading novels is more interesting than reading factual books?Why is that?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, this is tricky. I mean, there are novels, and there are novels. I loathe pulp love stories which are conjured up by arrogant popular young writers who has very little comprehension of true love, and I abhor magic fictions such as Harry Porter which are essentially naive fairy tales embellished with confusing medieval jargons. So, in most cases, I prefer to read something factual. At least, I can gain useful information from it. But I do love novels written by some of the masters, who has rich life experience, deep insights of the world, and unique style in language. Reading their works is like stepping into another world, living a different life. It''s a wonderful experience,\ntricky 复杂的 loathe 厌恶；讨厌\npulp 庸俗的 conjure up 编造\ncomprehension 理解 abhor 厌恶；讨厌\nnaive 幼稚的 embellish 润色\nmedieval 中世纪的 jargon 术语 \ninsight 洞察力，深刻见解","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8256ddde73c1a44811c98280', 'ielts_group_80475e6f6c11c8ae9262ea53', 'PART_1', 1, 'What type of photos do you like taking? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I enjoy taking all sorts of photos, including people, natural scenery, magnificent buildings and so on. I like taking photos of people on special occasions such as weddings and graduations the best. It is great to capture and eternalise those wonderful moments.\n\nnatural scenery 自然景观 capture and eternalise捕捉并使其成为永恒","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f269941b6ced571405952ce6', 'ielts_group_80475e6f6c11c8ae9262ea53', 'PART_1', 2, 'What do you do with photos you take? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"They are stored in my smart phone, and I look at them whenever I feel nostalgic. I have also printed out and framed some of them. You can see them on my bedroom walls. They''re there to remind me of the people that I care about and my fond memories.\nfeel nostalgic产生怀旧感 fond memories美好回忆","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_946b28fcdc7bc2d6dd8b2d0d', 'ielts_group_80475e6f6c11c8ae9262ea53', 'PART_1', 3, 'When you visit other places, do you take photos or buy postcards? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Both, actually. Sending postcards is certainly a good way to send your regards, but I always take some photos myself. At the end of the day, each of the photos taken by me is one of a kind. You will never find them anywhere else.\n\nsend one''s regards送去某人的问候 at the end of the day说到底\none of a kind独一无二","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_35981a10388bbfc6bd44ed38', 'ielts_group_80475e6f6c11c8ae9262ea53', 'PART_1', 4, 'Do you like people taking photos of you? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Not really. I''m a bit camera-shy, and I have no idea how to behave in front of a camera. I''m so jealous of those photogenic people who are able to strike a cool pose easily.\n\ncamera-shy 不喜欢被拍照的 photogenic people 上相的人\nstrike a cool pose 摆出一个酷的姿势","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f84b3a1ac5af82ea3f7962ed', 'ielts_group_365a7431bc6cfb95f6c4909b', 'PART_2', 1, 'Describe a day that you thought the weather was perfect.', '["where you were on this day","what the weather was like on this day","what you did during the day","and explain why you thought the weather was perfect on this day."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"身在何处：I''d like to talk about this beautiful autumn day in 2014 when the weather was exceptionally good. I was in my hometown Beijing, which was the host city of the 2014 APEC meeting.\n\n天气如何：It was the first day of the APEC meeting in early November. After a long spell of smoggy days in October, we finally saw the azure sky with white cloud. What made it even better was that the temperature. It was just about right for outdoor activities.\n\n当天行动：In order to celebrate the APEC event, the residents of Beijing were given a few extra days off. Some people chose to travel to other places, but I decided to stay in Beijing to appreciate its scenic beauty on such nice days. A couple of friends and I went to Beihai Park and took quite a few pictures there, including the beautiful white tower and people who were boating on the lake.\n\n内心感受：The great weather of that day was particularly memorable because of the huge contrast between that day and the severely smoggy days before and after that. This weather condition was even crowned \"APEC blue\" by the media to signify its rarity. After all, it was a result of the government action that thousands of factories were shut down during that period and the number of vehicles on the streets was also cut in half. We were all hoping that the nice weather would last for a few more weeks but it didn''t.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_71a39f260e64a762b25a5d1e', 'ielts_group_365a7431bc6cfb95f6c4909b', 'PART_3', 1, 'What types of weather do people in your country dislike most? Why is that?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I would say Chinese people hate smoggy days the most. Due to the severe industrial pollution and car exhaust emission, a great part of China was affected by smog. People are worried that such a weather condition would constitute a huge health hazard. Scientific studies have shown that smog is directly linked to a number of respiratory diseases, even lung cancer.\n\nsevere industrial pollution严重工业污染 car exhaust emission汽车尾气排放\nconstitute a huge health hazard成为巨大健康危害 is directly linked to... 和...有直接关联\nrespiratory disease呼吸系统疾病 lung cancer肺癌","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1356ffe02b5d49d8ce8aef78', 'ielts_group_365a7431bc6cfb95f6c4909b', 'PART_3', 2, 'What jobs can be affected by different weather conditions? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, a number of occupations may be affected, particularly those involving the operation of vehicles, be it a car, a plane or a ship. Bad weather conditions would mean that it is more likely to cause accidents. For example, many taxi drivers choose not to work on snowy days because the snow makes the roads extremely slippery and it can be quite dangerous to drive on such days.\n\ninvolve包括 operation of vehicles驾驶交通工具\nbe it a car, a plane or a ship无论是汽车、飞机还是轮船 extremely slippery特别滑","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b803a74ab59939d6324ca958', 'ielts_group_365a7431bc6cfb95f6c4909b', 'PART_3', 3, 'Are there any important festivals in your country that celebrate a season or type of weather?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Absolutely! The most important festival in Chinese culture is the Spring Festival, also known as Chinese New Year. As the name suggests, it celebrates the beginning of the new year of the lunar calendar and a new spring. People would decorate the front doors of their homes with Spring Couplets. Spring has a special meaning in China. It stands for youth, hope and potential. Some would even say that \"the whole year''s work depends on a good start in spring\".\n\nalso known as也被称为 as the name suggests正如名字所示\ndecorate the front doors装饰前门 Spring Couplets春联\nstand for代表 The whole year''s work depends on good start in spring.一年之计在于春。","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9b03b98bfea8d9b9a1997c5a', 'ielts_group_365a7431bc6cfb95f6c4909b', 'PART_3', 4, 'How important do you think it is for everyone to check what the next day''s weather will be? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I would say it is quite important for people to check the next day''s weather. One has to make decisions as to what to wear the next day, whether to bring an umbrella and even what kind of transportation to take. If it rains, it''s probably a good idea to go with public transportation since people have to drive more slowly on rainy days and there are more traffic accidents.\n\nmake decisions as to 做关于...的决定 go with public transportation 选择公共交通\ntraffic accident 交通事故","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_966b6546e552db80e5915939', 'ielts_group_365a7431bc6cfb95f6c4909b', 'PART_3', 5, 'What is the best way to get accurate information about the weather?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In my opinion, the best way to do is to check the weather app on your smart phone. I no longer watch weather forecast on TV these days since weather can be quite fickle and prone to change within a short period of time. The weather forecasts on those apps are more accurate since they are updated hourly or even more frequently to be more precise.\n\nin my opinion在我看来 smart phone智能手机 \nfickle变化无常 prone to change 容易改变\nbe updated hourly 每小时更新 frequently 频繁地","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c53cf3049b5d9f9f29f94186', 'ielts_group_365a7431bc6cfb95f6c4909b', 'PART_3', 6, 'How easy or difficult is it to predict the weather in your country? Why is that?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I suppose it really depends on which part of China we are talking about since it is such a huge country. For the inland part, the weather is usually easier to forecast as it is generally more stable. However, for the coastal parts, especially those in the subtropics which are greatly affected by the subtropical monsoons, it might be much more challenging to predict the weather.\ndepend on取决于 inland内陆的\nmore stable更加稳定 coastal沿海的\nsubtropics亚热带地区 subtropical monsoon亚热带季风\nmuch more challenging更有挑战性。","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_99ff71efff5b75ea6ae7dd1c', 'ielts_group_fbbda32a8f9b929096b71867', 'PART_1', 1, 'How did your parents choose your name(s)?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, actually my parents didn''t choose my name. They were trying to find a name with good meanings, but it turned out to be much more difficult than they had thought it would be. Eventually, they sought my grandmother''s help, and she named me.\n\nturn out to be结果是 eventually最终\nseek one''s help寻求某人的帮助","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_39caf5609ba982923503aee7', 'ielts_group_fbbda32a8f9b929096b71867', 'PART_1', 2, 'Does your name have any special meaning?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"As I said earlier, my grandmother named me. She picked the Chinese characters bearing the meaning of \"being healthy forever\" for my name, which represented her sincere wish that I would grow up healthily.\n\nbear the meaning of 具有......的含义 represent one''s sincere wish代表某人真诚的祝愿","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9d8775b5226df006fd205bfd', 'ielts_group_fbbda32a8f9b929096b71867', 'PART_1', 3, 'Is your name common or unusual in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it''s not exactly that unusual since the meaning of my given name is rather ordinary, but given that my surname is among the rarest ones in China, I have not suffered the embarrassment of meeting someone who shares exactly the same name with me.\n\nrather ordinary 相当普通 among the rarest 最少见的...之一 \nsuffer the embarrassment of... 遇到......的尴尬情况","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b0f2a85d1be25d8ca3127bcf', 'ielts_group_fbbda32a8f9b929096b71867', 'PART_1', 4, 'If you could change your name, would you? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Never in a million years! I consider my name as one of the greatest gifts from my grandmother. It''s a token of her love for me, and I would never consider changing it.\n\nnever in a million years 永远不会 a token of one''s love 某人爱的象征","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7cf1d3bcdb669b1c1160484d', 'ielts_group_7b6194c023847b90b752594b', 'PART_2', 1, 'Describe a TV documentary you watched that was particularly interesting.', '["what the documentary was about","why you decided to watch it","what you learnt during the documentary","and explain why the TV documentary was particularly interesting."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"节目类型：I''m going to talk about this really fun documentary about New Zealand which I saw on TV a couple of years ago. It was by far one of the best documentaries that I have ever watched.\n观看原因：I did not watch it on purpose. I was just flipping through the channels when I came across this show. There was a Maori guy with tattoos all over his face who instantly grabbed my attention.\n观看收获：I have learnt so many things about New Zealand from that show, including its location, its climate and its culture. The vast forests and magnificent mountains looked so impressive on the TV screen. It was said that the Lord of the Rings trilogy was shot there. As a sports fan, I also found out that New Zealand people are crazy about rugby, a sport which I have always wanted to have a try myself.\n有趣之处：What I found most fascinating about the show was the introduction of the Maori culture. It was such an eye-opening experience to learn that you can tell so many things, such as accolades and statuses, of a Maori person from the jade they are wearing and the tattoos on their faces. The highlight of the show was the haka, originally a war dance aiming to intimidate enemies and now more commonly seen performed by the New Zealand sports teams before a match starts. On the show a Maori guy explained to the audience the meaning of each hand gesture or pose they have. It was so much fun learning about this stuff that I plan to travel to New Zealand really soon to see all those things with my own eyes.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e3d82cb3ae8db0504ff7deeb', 'ielts_group_7b6194c023847b90b752594b', 'PART_3', 1, 'What are the most popular kinds of TV programmes in your country? Why is this?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I would say reality shows and talent shows are probably the most popular ones. Most of the reality shows have garnered a lot of public attention because of their star-studded cast. Talent shows,on the other hand, are trying to get the public root for some contestants who are just ordinary people.It would seem that people can relate to these contestants better and want to witness their growth, particularly those who are underdogs, some of whom even went on to win the competitions at the end.\n\nreality show 真人秀 talent show才艺秀\ngarner a lot of public attention获得公众很大的关注 star-studded cast群星荟萃的演员阵容 \nroot for 为...鼓劲 relate to 与...感同身受\nwitness one''s growth见证某人的成长 underdog处于劣势的人","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7a8627e6925a1f712d4389ca', 'ielts_group_7b6194c023847b90b752594b', 'PART_3', 2, 'Do you think there are too many game shows on TV nowadays? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Not really. Although there have been more and more of them on TV, they still constitute a small percentage of all TV shows. If you’re not really into game shows, there''re plenty of other types of programmes for you to choose from. More game shows simply means fiercer competitions for audience rating between different networks and TV stations. This pushes the creators of the shows to come up with better ideas.\n\nconstitute a small percentage占很小的百分比 not really into不是很喜欢\nfiercer competition更激烈的竞争 audience rating 收视率\ncome up with to 想出","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5f8cfe9e8161cfef2139eb1b', 'ielts_group_7b6194c023847b90b752594b', 'PART_3', 3, 'Do you think TV is the main way for people to get the news in your country? What other ways are there?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I suppose it depends on the age of people we are talking about. Most of the senior citizens are still watching the news on TV regularly; however, younger people prefer to get news on their smart phones since it''s more up-to-date and more efficient. Newspaper used to be a major outlet of news as well, but the sales of copies of newspaper have been dwindling as the news Apps on smart phones and tablets are taking their places.\n\ndepend on 取决于 senior citizen老年人\nup-to-date最新的 major outlet 主要途径\ndwindle 减少 tablet 平板电脑\ntake one''s place 取代某人的位置","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_bbb47ffc42d51b901e9d8d03', 'ielts_group_7b6194c023847b90b752594b', 'PART_3', 4, 'What types of products are advertised most often on TV?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"According to my observation, food and household products are being advertised most frequently on TV. It stands to reason that housewives constitute a major part of all TV, audience and therefore are targeted by the TV stations. At the end of the day, most of the household purchase decisions are made by them. It is definitely worthwhile to catch as much of their attention as possible.\n\naccording to one''s observation据某人观察 household products家用产品\nIt stands to reason that... ...是合乎常理的事 constitute a major part of...构成...的一个主要部分\nbe targeted被当作目标 at the end of the day 说到底\nworthwhile值得的 catch one''s attention引起...的关注","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fd36446a06f92ebee577ed44', 'ielts_group_7b6194c023847b90b752594b', 'PART_3', 5, 'Do you think that people pay attention to adverts on TV? Why do you think that is?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"To be honest, I don''t think most people pay much attention to TV commercials unless those commercials are quite interesting. One major reason for this is most of the ads are being played between episodes of a TV series or two different shows. Most people would use that time to go to the bathroom or to stand up and stretch a little bit. That is also why time slots for ads right after and before each show are the most expensive.\n\nto be honest实话实说 TV commercial电视广告\nTV series 电视剧 stretch伸展\ntime slot 播放时段","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_079c313bfc7577e5f59b119a', 'ielts_group_7b6194c023847b90b752594b', 'PART_3', 6, 'How important are regulations on TV advertising?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Regulations on TV advertising play a rather significant part in the protection of public interest. It is essential to thoroughly prescribe standards as to what can be advertised on TV and how they can be advertised, and it is even more important to supervise and monitor the TV stations compliance with such regulations. Any breach of these rules should be subject to penalty in order to deter any further noncompliance.\n\nplay a rather significant part扮演相当重要的角色 public interest公众利益\nthoroughly prescribe standards全面制定标准 supervise and monitor监管\ncompliance合规行为 breach of these rules违规行为\nsubject to penalty交付罚金 deter further noncompliance防止更多违规行为","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3b741645145347d3cf713063', 'ielts_group_da3f34e24310316b74551888', 'PART_1', 1, 'Is it important to you to eat healthy food? [Why?/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Absolutely. I eat a lot of green vegetables and fruits. Junk food is a luxury which I indulge myself with only once a month. Some friends call me a health freak, but I think it''s totally worth it.\n\nindulge myself with.. 用…纵容自己 health freak 健康狂人","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8887da9be9bc1bf4c627b65a', 'ielts_group_da3f34e24310316b74551888', 'PART_1', 2, 'If you catch a cold, what do you do to help you feel better? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, normally I will drink a lot of water and get plenty of rest. I don''t really like taking medicine because of the side effects. I think it''s a lot better to rely on your immune system to heal yourself.\n\nside effects 副作用 rely on one''s immune system依靠自身的免疫系统","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b0eaef27fee61d0c0427fd44', 'ielts_group_da3f34e24310316b74551888', 'PART_1', 3, 'Do you pay attention to public information about health? [Why?/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, but quite selectively. I mean, some advice and tips on the Internet can be really helpful but there is also a lot of misleading information out there. A seemingly well-written report could be just another sales stunt. Therefore, it''s important to pick and choose.\n\nmisleading information 误导性信息 pick and choose 精挑细选\n\nsales stunt 销售噱头","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a45ff9135c85fa0b063b66bc', 'ielts_group_da3f34e24310316b74551888', 'PART_1', 4, 'What could you do to have a healthier lifestyle?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I suppose I could go to bed a little earlier. Sometimes I stay up quite late to watch TV or play computer games. I even pulled an all-nighter last month to play this online game with my friends. Now come to think of it, I probably shouldn''t have done that.\n\nstay up late 熬夜","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c2ae3cf9696e93ff64d2bab5', 'ielts_group_93c0d6df6b5cc880f3e36dae', 'PART_2', 1, 'Describe an occasion when you had to wait a long time for someone or something to arrive.', '["who or what you were waiting for","how long you had to wait","why you had to wait a long time","and explain how you felt about waiting a long time."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"整体介绍： I''d like to talk about the time when I waited for a whole day for a camera to be delivered to me. \n\n等待何物： Last year I bought a Fujifilm instant camera online as a birthday gift for my friend Wei. I ordered it on Tuesday and it was supposed to be delivered to me on Thursday. I thought it was perfect because Friday was her birthday and I would have enough time to wrap the gift and give it to her at the party we were throwing for her.\n\n为何等待： However, on Wednesday morning it started to snow and the roads became quite slippery. I received a phone call from the delivery company saying that the delivery might be delayed because several highways were sealed, but they would try their best to make it.\n\n内心感受： I was quite anxious the whole time while waiting for the camera. As I had feared there was no delivery on Thursday. The next day I called the company again and they told me that the camera was on its way but there was no guarantee it would arrive on that day. I explained to them it was an important gift and requested them to give it some priority. I was pacing the room when the doorbell rang at 5p.m. I rushed to the intercom to open the door for the delivery man. You have no idea how relieved I felt when I finally got it in my hand. It was definitely an unforgettable experience.","translation":"","usageNote":"原题库提供的参考表达"},{"type":"EXPRESSION","expression":"instant camera","translation":"拍立得 wrap the gift包装礼物","usageNote":""},{"type":"EXPRESSION","expression":"throw a party for...","translation":"为..办聚会 quite slippery非常滑","usageNote":""},{"type":"EXPRESSION","expression":"several highways were sealed","translation":"几条高速路被封 As I had feared正如我所担心的","usageNote":""},{"type":"EXPRESSION","expression":"there was no guarantee","translation":"不能保证 give it some priority给一些优先权","usageNote":""},{"type":"EXPRESSION","expression":"pace the room","translation":"在房间里踱步 rush to the intercom赶去门禁对讲机","usageNote":""}]'::JSONB),
    ('ielts_q_f28e8ac98796058cdad891d1', 'ielts_group_93c0d6df6b5cc880f3e36dae', 'PART_3', 1, 'In what kinds of situations should people always arrive early?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, in situations when time is of the essence, I suppose. For example, if you need to take a plane you should always arrive at the airport early because the security check takes a long time and the plane will not wait for you. Also, if your lateness may be taken as a sign of disrespect, for example, if you are meeting someone for the first time it is quite rude to be late.\n\ntime is of the essence 时间至关重要 a sign of disrespect 不尊重的表现\n\nsecurity check 安检","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1a9c2bcc50ad5dee308df712', 'ielts_group_93c0d6df6b5cc880f3e36dae', 'PART_3', 2, 'How important it is to arrive early in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I suppose it depends on who you are meeting with and what you are meeting for. If you are meeting a friend for a casual meal or something, he or she probably wouldn''t be too upset if you run a bit late.However, if you are meeting with someone you are not that familiar with, or for some important matters, it is quite advisable that you get there a bit early. After all, punctuality is a sign of reliability. Being late is not exactly fashionable in Chinese culture.\n\nfor a casual meal 简单吃个饭 punctuality 守时\n\nrun a bit late 来迟一些 reliability 可靠\n\nit is quite advisable that 非常建议…","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_84e37fc3d406523eeb2b1fe6', 'ielts_group_93c0d6df6b5cc880f3e36dae', 'PART_3', 3, 'How can modern technology help people to arrive early?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Many people are using their smartphones to make sure that they won''t be late for important events. Once you have put them on your calendar, a reminder will pop up on the screen and the alarm clock will go off one hour before the event. If you have installed a fight app, it will send you reminders three hours before your departure time automatically. Some traffic apps can help you calculate the fastest route to get to your destination. This helps you to arrive early as well.\n\nput them on one''s calendar 记录在日历上 install a fight app 安装飞机航班软件\n\npop up 弹出来 departure time 起飞时间\n\nalarm clock will go off 闹铃会响 calculate the fastest route 计算最快路径","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_41f08cb742c621d00ffa237b', 'ielts_group_93c0d6df6b5cc880f3e36dae', 'PART_3', 4, 'What kinds of jobs require the most patience?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In my opinion, jobs involving children are probably the most demanding as far as is concerned. Unlike adults, most children are still learning how to communicate effectively with others. Sometimes they have difficulty expressing their wants and needs. And when they don''t get what they want, they may even throw a temper tantrum. It takes a lot of patience to spend hours and hours with children.\n\nthe most demanding 要求最高的 express their wants and needs 表达他们的需求\n\nas far as patience is concerned 说到耐心 throw a temper tantrum 乱发脾气\n\ncommunicate effectively 有效交流","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b5d8f8cff1e860024a4bb48e', 'ielts_group_93c0d6df6b5cc880f3e36dae', 'PART_3', 5, 'Is it always better to be patient in work (or studies)?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yeah, I think so. Generally speaking when you lose your patience it is more likely for you to make mistakes and fail to notice the details. A patient person is also usually better at communicating with co-workers because he or she is more willing to listen. This will encourage collegiality and allow the whole team to work more efficiently.\n\ngenerally speaking 一般来讲 communicate with co-workers 和同事交流\n\nlose one''s patience 失去耐心 encourage collegiality 增强协作\n\nfail to notice 没能注意到","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b56d76273e74c06565739bd5', 'ielts_group_93c0d6df6b5cc880f3e36dae', 'PART_3', 6, 'Do you agree or disagree that the older people are, the more patient they are?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yeah, it''s probably right. І mean, when you are also inclined to become wiser because you have much experience of life. You will be better at handling complex information and analyse it. Therefore, you don''t get confused as often and won''t lose patience easily. Plus: your experience may also teach you to be more patient with others because you are more tolerant of others''faults.\n\nbe inclined to 倾向于 get confused 感到困惑\n\nHandle complex information 处理复杂信息\n\nbe more tolerant of others''faults 对别人的缺点更包容","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_763f6eb8149dd0476b254431', 'ielts_group_316b768c2971d4afea3494b4', 'PART_1', 1, 'Did you enjoy singing when you were younger? [Why?/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yeah, I really enjoyed it a lot. Back in primary school I was in the chorus and performed in front of the whole school. In high school there was also a phase when I loved singing karaoke so much that I did it every week.\n\nin the chorus 在合唱团 there was a phase when... 有那么一段时间","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_aafefa5091c2961ef81e6636', 'ielts_group_316b768c2971d4afea3494b4', 'PART_1', 2, 'How often do you sing now? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Not quite often compared with the past. I can''t even recall the last time I went to a karaoke bar. Suffice it to say that this microphone hog has retired. Sometimes I hum a little tune when I take a shower,but never too loudly.\n\nSuffice it to say that... 只想说 hum a little tune 哼个小曲\n\nmicrophone hog 麦霸","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7c1c7e95cb6deb5faaf50597', 'ielts_group_316b768c2971d4afea3494b4', 'PART_1', 3, 'Do you have a favourite song you like listening to? [Why?/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, it''s \"Listening for the weather\" by a New Zealand singer named Bic Runga. It may not be a hitsong but whenever I listen to it, it just chases my blues away and puts my mind at ease.\n\na hit song 轰动一时的歌曲 put one''s mind at ease 让某人心情安定\n\nchase one''s blues away 驱散某人的忧郁","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3c103046f1d4e4348ab0d384', 'ielts_group_316b768c2971d4afea3494b4', 'PART_1', 4, 'How important is singing in your culture?[Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think it''s quite a big deal. For Chinese people singing karaoke is a very popular way to let off steam and socialise with others. Recently there are more and more karaoke booths in big shopping malls and they are always full. It just shows how much Chinese people like to sing.\n\nquite a big deal 很重要的事 karaoke booths 迷你KTV\n\nlet off steam 宣泄压力，放送","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b6d6a66eb0d09f5f6440ac9a', 'ielts_group_809bf08571b17ccf3ff1de65', 'PART_2', 1, 'Describe a film/movie actor from your country who is very popular.', '["who this actor is","what kinds of films/movies he/she acts in","what you know about this actor''s life","and explain why this actor is so popular"]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"哪位演员： I''d like to talk about Zhang Ziyi who is one of the biggest names in the film industry in China.\n\n出演电影： She made her film debut in 1998 and shortly after that she got her big break by playing a memorable character in the Oscar-winning film \"Crouching Tiger, Hidden Dragon\". Since then she appeared in a number of influential fims of many different genres, including comedy, thriller, action and even art flms.\n\n个人生活： As I know, she studied dancing in high school and attended the Central Academy of Drama. She is married to a famous rock singer named Wang Feng and they have a daughter together.\n\n备受欢迎： Speaking of her popularity, Ziyi first drew public attention because she was picked by famous director Zhang Yimou to play the leading role in her first film. Later thanks to her training in dancing, she was able to put on breathtaking performances in three well-known Kungfu films, \"Crouching Tiger, Hidden Dragon\" , \"Hero\" and \"House of Flying Daggers\". She was able to give elegance and vivacity to her Kungfu moves and left a long-lasting impression on the audience.\n\nFrom then on she has been slowly but surely polishing her acting skills to perfection. With the outstanding job she did in \"The Grand Master\", she had won all major Chinese film awards for best actress in a leading role. Until today no other Chinese actress has been able to do that with just one film. Such an achievementcertainly helped her gain popularity among film-goers of all ages.\n\nThere is no doubt that she is one of the greatest actresses in China.\n\none of the biggest names 最有名的人之一 make one''s flm debut 演出首部电影作品\n\nget one''s big break 获得重要的突破机会 Crouching Tiger, Hidden Dragon《卧虎藏龙》\n\nfilms of many different genres 不同主题类型的电影 \n\nCentral Academy of Drama 中央戏剧学院\n\ndraw public attention获得公众关注 play the leading role 饰演主角\n\nthanks to 多亏了 put on breathtaking performances 做出令人惊艳的表演\n\nHouse of Flying Daggers《十面埋伏》 elegance and vivacity 优雅和生动\n\nleave a long-lasting impression 留下久久挥之不去的印象 slowly but surely 穏扎稳打地\n\npolish one''s acting skills 磨炼演技 best actress in a leading role 最佳女主角\n\nfilm-goers of all ages 各个年龄段的影迷","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_25373fcfe613a79dc9d23c54', 'ielts_group_809bf08571b17ccf3ff1de65', 'PART_3', 1, 'What are the most popular types of films in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I would say sci-fi and comedies. Hollywood superhero films have been widely popular in China and the box office performance of this genre is second to none. I suppose people are attracted to the dazzling special effects in these action packed films. Comedies are also doing a wonderful job because they can offer some light-hearted fun to those who are under a lot of pressure from their work or studies.\n\nsci-fi and comedies 科幻和喜剧 dazzling special effects 令人目眩的特效\n\nbox offce performance 票房表现 action-packed films 动作丰富有趣的电影\n\nsecond to none 首屈一指的 offer some light-hearted fun 让人放松快乐","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_88f09c2073d18f6964279937', 'ielts_group_809bf08571b17ccf3ff1de65', 'PART_3', 2, 'What is the difference between watching a film in the cinema and watching a film at home?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I suppose when you watch a film in the cinema the sound and visual effects are probably better because of the mega screens and powerful stereo systems. When you watch it at home you will have more control over how you want to play it. For example, you can pause it when you need to hit the loo and you can fast forward the parts that you don''t like.\n\nsound and visual effects 视听效果 hit the loo 上厕所\n\nmega screens 超大屏幕 fast forward 快进\n\npowerful stereo systems 强劲的音响系统","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_91740f42e1239c1640bfc943', 'ielts_group_809bf08571b17ccf3ff1de65', 'PART_3', 3, 'Do you think cinemas will close in the future?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t think so. Some people are saying that since VR technology is developing so fast cinemas will become redundant someday, but I disagree. I believe going to a cinema is not just about watching the film, but the whole experience. You will get this great feeling when the whole audience burst into laughter because of a funny scene or break into applause at the end of a great film.\n\nVR (Virtual Reality) technology 虚拟现实技术 burst into laughter 哄堂大笑\n\nbecome redundant 变得多余 break into applause 齐声鼓掌","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_aabaf7bbe483aab0e40e0ed2', 'ielts_group_809bf08571b17ccf3ff1de65', 'PART_3', 4, 'How important is the theatre in your country''s history?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I would say it played a rather significant part in our history. When we talk about Chinese theatre, I suppose the first thing people think of is Bejing Opera. This great art form dates back to the 18th century and has been considered a national treasure. In the past since there were not that many types of entertainment, many people went to the theatres regularly to enjoy Beijing Opera. In Qing Dynasty it became so popular that almost everyone could sing one song or two from the most famous plays.\n\nplay a rather significant part 扮演相当重要的角色 a national treasure 国家瑰宝\n\ndate back to 追溯到","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_65c60f43f46431ea2e7076d5', 'ielts_group_809bf08571b17ccf3ff1de65', 'PART_3', 5, 'How strong a tradition is it today in your country to go to the theatre?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Unfortunately, I don''t think it is as strong a tradition to go to the theatre as it was in the past. Beijing Operais more of an acquired taste. It takes time to learn its vocabulary and understand the stories. Nowadays there are so many other types of entertainment for people to choose from. Therefore, theatre is losing its attraction for young people, which is really sad if you ask me.\n\nan acquired taste 逐渐培养的爱好 learn its vocabulary 学习戏剧语言\n\nIt takes time to... 需要花时间来...... lose its attraction 失去吸引力","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9c91935ca3342d8d2036ba9e', 'ielts_group_809bf08571b17ccf3ff1de65', 'PART_3', 6, 'Do you think the theatre should be run as a business as a public service?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I believe it should be run as a hybrid. The business part gives people who work in the theatre an incentive to better themselves. However, the problem with business is that it''s too profit-driven. If a business is not bringing enough profit, it will be closed. The theatre should be more than that because it''s a part of our cultural legacy which should be more accessible. And for such a reason it should also be partially run as a public service.\n\nhybrid 混合体 too profit-driven 利益驱动性太强\n\ngive...an incentive 给...一些激励 cultural legacy 文化遗产\n\nbetter themselves让他们做得更好 accessible 可接近的，可获得的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_068901282f0954c17b2df1ab', 'ielts_group_1ab7feaaca382654dbbe5d0c', 'PART_1', 1, 'Where do you buy most of your clothes? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I do almost all my shopping online. I just love that you can easily shop from the comfort of your home, and find anything from budget clothes to designer labels. It''s so convenient. But it''s easy to overspend too.\nshop from the comfort of your home 舒服地在家购物 designer labels 设计师品牌\nbudget clothes便宜的衣服","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fa78329ffcd30bf3131c5221', 'ielts_group_1ab7feaaca382654dbbe5d0c', 'PART_1', 2, 'How often do you buy new clothes for yourself? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I buy new clothes seasonally or when there''s a good sale. I try to stick to my budget and not to splurge on every latest fashion item, although it''s not been easy.\nbuy new clothes seasonally 每季买衣服 latest fashion item 最新时尚单品\nsplurge on 在......上挥霍","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0532dfe578bd96266cf801f4', 'ielts_group_1ab7feaaca382654dbbe5d0c', 'PART_1', 3, 'How do you decide which clothes to buy? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"For me quality always comes first. I believe the trick to looking polished is to get hold of a few classic, high-quality essentials that never go out of style. So I always go for the best quality within my price range.\nlook polished 着装考究 go out of style 过时\nclassic, high-quality essentials 必备的经典，高品质单品","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_77346d6b6a58a8cc427b3d33', 'ielts_group_1ab7feaaca382654dbbe5d0c', 'PART_1', 4, 'Have the kinds of clothes you like changed in recent years? [Why?/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes I think so. I used to find myself standing in front of a closet full of clothes while not being able to find the right piece to wear. But now I feel much clearer about my personal style and I always have a few outfits on standby.\na closet full of clothes 满柜子的衣服 have a few outfits on standby 有一些常备的整套装备 personal style 自我风格","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1022a36e4ed0ceacca9ea313', 'ielts_group_23c192703c78af237cf6a6ad', 'PART_2', 1, 'Describe an interesting discussion you had about how you spend your money.', '["who you had the discussion with","why you discussed this topic","what the result of the discussion was","and explain why this discussion was interesting for you."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍：Funny I should get this topic. I mean I''m probably one of the least financially savvy people in the world. But I guess I can talk about a discussion I once had with my best friend.\n选择要点：First, I think I''ll tell you something about my best friend, Lily. We go back a long way and she was always a precocious child.\n比较对比：Unlike other young people, me included, who always have an empty wallet towards the end of each month, she spends her money wisely. And it seems that she always knows how to get her money''s worth for whatever she buys.\n展开细节：So one day this topic came up in our conversation and I asked about her secret to money management. And she told me that the first step is, surprise, surprise, creating a budget. As a hopeless impulse shopper, I asked her how to avoid buying things on the spur of the moment and she said that her trick was to reward herself with occasional treats, like going to the spa or the theater, just to keep her spirits up. That''s why she always sets aside a small amount of money in her budget for those things. I remember we also argued whether it''s better to buy name brands or generic brands and she insisted that one should know when to spend for quality, investing more in higher-quality essentials, like an ice pair of jeans that goes with anything and lasts for a long time.\n使用否定：I wouldn''t say that this conversation has changed my life, because as we know,it''s always easier said than done. But I''m lucky to have such a friend who I can emulate.\n做出推测：I suppose I would''ve saved a lot by now if I had really followed her advice.","translation":"","usageNote":"原题库提供的参考表达"},{"type":"EXPRESSION","expression":"financially savvy","translation":"有理财头脑 go back a long way 认识很久","usageNote":""},{"type":"EXPRESSION","expression":"a precocious child","translation":"聪明早熟的孩子 spend money wisely 合理消费","usageNote":""},{"type":"EXPRESSION","expression":"get one''s money''s worth","translation":"钱花得值 this topic came up 聊起这个话题","usageNote":""},{"type":"EXPRESSION","expression":"create a budget","translation":"作预算 impulse shopper 冲动型消费者","usageNote":""},{"type":"EXPRESSION","expression":"on the spur of the moment","translation":"一时冲动 set aside 留出(一些钱)","usageNote":""},{"type":"EXPRESSION","expression":"name brand","translation":"名牌商品 generic brand 普通商品","usageNote":""},{"type":"EXPRESSION","expression":"invest in","translation":"投资于","usageNote":""}]'::JSONB),
    ('ielts_q_c7d1a37b96ca9d8a4d9d6da9', 'ielts_group_23c192703c78af237cf6a6ad', 'PART_3', 1, 'Why do some parents give their children money to spend each week?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think there''re a couple of reasons why parents give their children allowances, but the most important one is to teach their children financial literacy. Allowances are a child''s first exposure to money management and they can also be a powerful tool to teach them about patience and decision making. For example, if they really want an expensive toy, they have to decide whether they should save up to buy it or they should rethink its value. I understand some parents are worried that free money could spoil children, but I believe it''s really up to what kind of strategies the parents use; for example, tying allowances to chores is a great way to teach children responsibility.\n\ngive allowances 给零花钱 save up 存钱\nfinancial literacy 理财常识 spoil children 宠溺孩子\nfirst exposure to money management 对理财的第一次接触 \ntie allowances to chores 把零花钱和完成任务挂钩","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_633b4ea913e278592c1e9d6c', 'ielts_group_23c192703c78af237cf6a6ad', 'PART_3', 2, 'Do you agree that schools should teach children how to manage money?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Absolutely. In fact, I''m outraged that money management is not featured in most of the schools in China.I mean, if the purpose of public schooling is to raise sensible, functioning members of society, then financial literacy should definitely be part of the curriculum. And I also strongly believe that this education should start early when children are forming their good habits. If some parents or schools are uncomfortable with letting their children handle money at an early age, they could use alternatives or games, like the board game Monopoly to teach children the basics of personal finance.\n\nfunctioning members of society 在社会中发挥作用的人 at an early age 小时候\npart of the curriculum 教学大纲的一部分 alternatives 替代品\nform one''s good habits 行程良好的习惯","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_dbf3621cc146257dacb7598d', 'ielts_group_23c192703c78af237cf6a6ad', 'PART_3', 3, 'Do you think it is a good idea for students to earn money while studying?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well generally, I don''t think students should work unless the circumstances force them to, like they have other family members to support. Of course you can argue that having a job builds character and helps the students gain experience so that they are better prepared for the real world, but trying to work a full time job, or even a part time job while attending college will almost inevitably lead to inferior results in both areas. Studying for a degree is already a full time job. And education is supposed to be students focus and top priority at this stage, not just a hoop to jump through. Plus, what''s the point of listing on your resume the experience of working part time at a grocery store that has nothing to do with your career goals? I believe it''s way more beneficial for college students to volunteer in fields that are related to their future career.\n\nthe circumstances force one to 形势所逼 \n\nbuild character 锻炼品格\n\ngain experience 积累经验 \n\nbetter prepared for the real world 为更好地适应现实社会做准备","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e804e57e4f74efeae059d941', 'ielts_group_23c192703c78af237cf6a6ad', 'PART_3', 4, 'Do you think it is true that in today''s society money cannot buy happiness?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Wow, this is a question that never gets old, isn''t it? For me, I''m convinced that money does make us happier, but only up to a certain point. I certainly don''t think we can be truly happy when we struggle to make ends meet, especially if we cannot afford our children''s education or the medicine that can save our loved ones. However, I''m skeptical of the idea that more money will bring more happiness. I admit that today''s society has become more materialistic, but it still can''t change the fact that we are social animals and we crave love and affection, which money cannot buy. Money can even undermine your happiness level, as I''ve heard some people who had won the lottery ended up faring worse, I think happiness has a lot to do with your health, self-esteem, social support and money is not always a positive factor here.\n\nup to a certain point 到一定的程度而言 undermine one''s happiness level 破坏幸福感\nmake ends meet [习语] 捉襟见肘，入不敷出 wіn thе lоttеrу 中彩票\nloved ones 亲人朋友 fare worse 生活得更不好\nmaterialistic 物质至上的 social support 社会支持\ncrave love and affection 渴望爱和真情","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_181b9cc8dfbca70a43dbb1fc', 'ielts_group_23c192703c78af237cf6a6ad', 'PART_3', 5, 'What disadvantages are there in a society where the gap between rich and poor is very large?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, a huge wealth gap will definitely lead to a lot of social problems. It seems to me that we are wired to value equality above growth. We are more satisfied with ourselves if we know our neighbors and old schoolmates are earning just as much as we do. On the contrary, growing income inequality will generate a widespread sense of injustice among people of lower class. And even the upper class will feel less secure because there is a breakdown of community ties. What''s worse, as more and more wealth gets concentrated in the hands of a few powerful individuals, there will be less and less social mobility, which will result in an even greater wealth gap and the vicious circle kicks in.\n\nwe are wired to value equality above growth 我们天生的思维方式就是不患寡而患不均\n\ngrowing income inequality 不断加剧的收入差\n\nsense of injustice 不公平的感觉\n\nlower class 低收入阶层 upper class 中高收入阶层\n\na breakdown of community ties 社区失去凝聚力\n\nwealth gets concentrated in the hands of a few powerful individuals 财富聚集到少数有权势的人的手里\n\nsocial mobility 社会流动性\n\nthe vicious circle kicks in 恶性循环开始","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f1cd15a1850c05d14ed975fd', 'ielts_group_23c192703c78af237cf6a6ad', 'PART_3', 6, 'Do you think richer countries have a responsibility to help poorer countries?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I think it''s not only a moral obligation but it''s also beneficial for the global economy as a whole. Just as the wealth gap within a country will lead to social issues, global economic inequality also has detrimental effects on world peace and international trade. However, by help I don''t mean simply \"aid\". Humanitarian aid is no doubt necessary when disaster strikes, but regular, continuous economic aid is likely to do more harm than good, because it will easily disrupt the local economy and corrupt the government. In my opinion, richer countries should offer poorer countries help in the form of education programs, medical and technological support, which has a better chance of translating into social progress.\n\nmoral obligation 道德义务 disrupt the local economy 破坏当地经济\nas a whole 作为一个整体 corrupt the government 导致政府腐败\nhave detrimental effects on 对......有严重危害 translate into 变成\nhumanitarian aid 人道捐助","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_610dd787784b6198ad0b4634', 'ielts_group_faa47c79d8b5b97ac6c179e8', 'PART_1', 1, 'Did you enjoy doing art lessons when you were a child? [Why?Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes I did. I was really fond of drawing when I was little. And I guess the art lessons were one of the few times in a day when we didn''t have to sit still and try to remember everything the teacher said. It''s great fun to get my hands dirty and make a mess of the paint and brushes.\nfond of 喜欢 make a mess of 把…弄得一团乱\nget one''s hands dirty 把手弄脏","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9779c10ff15607d372b3162e', 'ielts_group_faa47c79d8b5b97ac6c179e8', 'PART_1', 2, 'Do you ever draw or paint pictures now? [Why?Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Almost never ... oh wait a minute, I just remembered that I have just finished one page of a coloring book that is all the rage these days, you know, the kind of book full of intricate patterns that you can fill with colors. Technically it''s just coloring not painting, but I did find it very therapeutic.\nall the rage [习语]非常流行 therapeutic 有解压治愈作用的\nintricate pattern 精细复杂的因素","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f2122c373901bef350d785ac', 'ielts_group_faa47c79d8b5b97ac6c179e8', 'PART_1', 3, 'When was the last time you went to an art gallery or exhibition? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, last month maybe? I do enjoy looking at artsy stuff, these days meaning Instagram or other photo apps. But going to the exhibitions, I can take it or leave it. My best friend is quite keen so I go with her from time to time.\nartsy stuff [非正式]有艺术感的东西 take it or leave it 无所谓","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ff66f14077335fe779bed58b', 'ielts_group_faa47c79d8b5b97ac6c179e8', 'PART_1', 4, 'What kind of pictures do you like having in your home? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"What kind of pictures? I would have to say photography. I’m not a good photographer myself, but I would love to have some tasteful black and white photos hanging on the wall. I think they really bring an artistic touch to the space.\nhanging on the wall挂在墙上 bring an artistic touch带来艺术气息","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_db9e72f25175bdcbdc427fb0', 'ielts_group_d42ba5227e4e2d714232a3ea', 'PART_2', 1, 'Describe a time when you visited a friend or family member at their workplace.', '["who you visited","where this person worked","why you visited this person''s workplace","and explain how you felt about visiting this person''s workplace."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍：Companies and organizations in China don''t often have open house day for visitors. So I guess I can talk about a time when I visited a friend at her studio where she set up her own business.\n选择要点：First, I think I''ll tell you something about my friend, Joanne, who''s an avid traveller. She used to have an office job but decided to quit because she couldn''t stand the monotony. As luck would have it, during one of her trips,she met a computer programmer who shared her vision, and together they built a website that features original and inexpensive travel plans for young people.\n比较对比：But the real \"wow \"factor of her business is the studio she designed, which is in a shipping container, no less.\n让步：Although it took me almost two hours to finally get to the studio, which is in a suburb, it blew me away the moment I saw it.\n展开细节：She had window walls installed which makes the room bright and airy. Other sides of the container were painted bright orange, which created a lovely contrast against the trees that surrounded it. There''s even a patio, which was an unfolding door. Inside there was not much room but it felt very cozy with old furniture, travel photos on the wall, and knick-knacks collected during trips.\n使用否定：I wouldn''t say it''s the best workplace Id ever seen, but it certainly is one of the most special. And I''m really happy that my friend is enjoying her life and work.\n作出推测：If I had half her courage and resourcefulness, I''d be living my dream now.\n\n重点词句\n\nopen house day 开放参观日 shipping container 集装箱\nset up one''s own business 自己创业 blow one away 让某人彻底震惊\nan avid traveller 热爱旅行的人 create a contrast against ...与..形成对比\nan office job 办公室工作 patio 露天可供休息的庭院\nmonotony 单调枯燥 knick-knack 小玩意\nas luck would have it 幸运的是 resourcefulness 才干\nthe“wow\" factor 令人赞叹的特点","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_90f13c53ddab6ccbe060da33', 'ielts_group_d42ba5227e4e2d714232a3ea', 'PART_3', 1, 'What things make an office comfortable to work in?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"First of all, the physical environment: lighting, air quality, noise and the level of upkeep, they all affect our performance at work. Of course everyone loves to have an office that is bright, airy, quiet and clean. Color is also a huge factor. People doing creative job may prefer to have bright, bold colors in their office, while others may find it hard to concentrate in such a place, and prefer traditional opaque walls and neutral color furniture. So I think it really depends on the nature of the work and the personality of the employee.\nlighting 照明采光 opaque wall 不透光的墙壁\nair quality 空气质量 neutral color 中性色彩\nthe level of upkeep 整洁程度 the nature of the work 工作性质\nbold color 鲜明的色彩","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0b185b7c71e3ba5c75fd3015', 'ielts_group_d42ba5227e4e2d714232a3ea', 'PART_3', 2, 'Why do some people prefer to work outdoors?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I know I would like to work outdoors if I could. It''s proven that sunlight exposure releases endorphins that make us feel good. And many people also like to have the freedom of moving around while they''re working, instead of feeling confined to a small cubicle. I, for one, find taking a walk a much better way to clear my mind and work out problems than sitting at my computer all day.\nsunlight exposure releases endorphins 晒太阳身体会释放内啡肽\nbe confined to a small cubicle 被关在小隔间里 work out problems解决问题\nclear one''s mind 理清思路 sit at one''s computer 坐在电脑前","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8e967d34ede95b3788f9863a', 'ielts_group_d42ba5227e4e2d714232a3ea', 'PART_3', 3, 'Do you agree that the building people work in is more important than the colleagues they work with?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Not really. I do admit the physical environment we are in has a profound effect on us, and we''re really susceptible to environmental cues - that''s what supermarkets have been doing to make us shop more. But I still believe ultimately it''s the people we re working with, the morale of the company,and the social support at the workplace that determine our work efficiency and job satisfaction.It''s hard to imagine we could enjoy our work even if we'' re in our dream office, when we are teamed with people we despise.\nhave a profound effect on 对…有深刻影响 social support 社会支持\nbe susceptible to environmental cues 容易受环境暗示的影响 job satisfaction 工作满意度 morale 士气 despise 厌恶","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d513d0ceaa238508aba8fb24', 'ielts_group_d42ba5227e4e2d714232a3ea', 'PART_3', 4, 'What would life be like if people didn''t have to work?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"That''s an interesting question. In fact, some philosophers have imagined a society where people don''t have to work for an income while products are distributed based on needs. Personally I don''t think such a system will ever be viable because we''re programmed to be opportunists, to take every advantage that''s available. This is how we survived evolution. So if we didn''t have to work for a living, we''d happily become free riders who will soon exhaust whatever the wealth that other hardworking people might have created. For me, work is social justice and therefore is indispensable.\nproducts are distributed based on needs 产品按需分配 free riders搭便车的人\nviable 可行的 exhaust 耗尽\ntake advantage of ... 占…的便宜 social justice 社会公正","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_32b0dd3c19f7ea48b687d7c2', 'ielts_group_d42ba5227e4e2d714232a3ea', 'PART_3', 5, 'Are all jobs of equal importance?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I guess to answer this question we have to first define \"importance\". If it means how much wealth the job generates then clearly some jobs are more important than others. And you can also argue that a teacher''s job is more important than a hedge fund manager''s because education can not be measured by money. However, in terms of the intrinsic value of work, which is to serve a purpose and make an honest living, I believe all jobs are equal.\nhow much wealth the job generates 工作创造多少财富 \nhedge fund manager 对冲基金经理 \ncan not be measured by money 不能以金钱衡量 the intrinsic value 内在的价值","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cf38d3f3d5d1a64fc5e0145b', 'ielts_group_d42ba5227e4e2d714232a3ea', 'PART_3', 6, 'Why do some people become workaholics?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I tend to think there'' re two kinds of workaholism. The first kind is when people really adore their work and they get a tremendous sense of achievement from it. As a result, they often seem very absorbed in their work and may have a tendency to overwork. However, I''m not sure if this should really be considered workaholism, because isn''t this what people need to do to become successful? Being driven and willing to work hard? On the other hand, there''re other workaholics who use work as an escape from other social or emotional pressure that they don''t want to deal with. In this case,they may display more obsessive-compulsive behaviors that will take a toll on not only their health but also their career.\nworkaholism 工作狂 \n\nan escape from other social or emotional pressure 一种逃离其他社会和情感压力的方式\nsense of achievement 成就感 \nbe absorbed in ...全心投入于… obsessive-compulsive behaviors 强迫性的行为\ndriven 积极进取的 take a roll on 对…产生负面影响","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e7440f7cb36d6c6448dcc817', 'ielts_group_e6a22eba88ea99c2488f5d6e', 'PART_1', 1, 'Where do you usually watch TV programmes/shows? [Why?/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well I think nowadays I hardly ever watch live TV on the actually TV set. I have subscribed to a few online TV streaming sites so I can easily watch the shows I like wherever I want, on my phone or laptop, tally commercial free, which of course is another important advantage.\n\nhardly ever 几乎没有 subscribe to 订阅\n\nonline TV streaming sites 网络电视 commercial free 无广告","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b3db05ba7085d13e188dfd74', 'ielts_group_e6a22eba88ea99c2488f5d6e', 'PART_1', 2, 'What''s your favourite TV programme/show? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Much as I hate to admit it, I am a reality TV junkie! I also watch stuff like comedies and crime TV programmes. But you could burn the house down around me while my favorite reality show is on! I know most of the shows are of little value but I just can''t help it!\n\nreality TV 真人秀 junkie [俚语]比喻对某事痴迷的人\n\ncomedy 喜剧 crime TV programme 犯罪剧\n\ncould burn the house down around me [比喻] 完全无视周遭 can''t help it 无法自拔","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9bbf953a1fabf49248399378', 'ielts_group_e6a22eba88ea99c2488f5d6e', 'PART_1', 3, 'Are there any programmes/shows you don''t like watching? [Why?/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it would have to be soaps. They are just so predictable and boring. I prefer shows like the British TV series Black Mirror. There''s always a twist at the end which will leave you wanting more. And I like those dystopian stories; they really make you think.\n\nsoaps 肥皂剧 predictable （情节）可以预测的\n\ntwist 情节反转 dystopian 反乌托邦的\n\nmake you think 引人思考","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4d0d46a2e7c7cb5f3f72a0a7', 'ielts_group_e6a22eba88ea99c2488f5d6e', 'PART_1', 4, 'Do you think you will watch more TV or fewer TV programmes/shows in the future? [Why?/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''d like to say fewer! I mean, I know I''d be better off spending time on something more productive. In fact, whenever I binge- watch some hit shows I feel guilty. But I don''t think I could simply quit it because if I did, I''d miss out on so many things that my friends would be talking about.\n\nbetter off 更好 productive 产生价值的\n\nbinge-watch 一次看很多集 miss out on [习语] 错过","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e9b9a4ed652d0e296476d4eb', 'ielts_group_a5b73a4b3bcd8ae7103e4f89', 'PART_2', 1, 'Describe someone you know who has started a business.', '["who this person is","what work this person does","why this person decided to start a business","and explain whether you would like to do the same kind of work as this person."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍： In recent years, there has been a surge in entrepreneurship in China and it seems that everybody is thinking about starting a business of some kind. But this person I''d like to talk about is truly a pioneer. His name is Mr. Luo.\n\n选择要点： First, I think I''ll explain what he does. Originally he was an anchor at Chinese Central Television, a job many people would kill for. But he saw an opportunity when more and more Chinese people started to use Wechat, an instant messaging and social networking app, so he quitted and started his own business. He started off by opening an account sharing book reviews and mini lectures on Wechat. And gradually he had had such a huge following that he opened up his website to well-known writers and professors to offer online courses for a price.\n\n比较对比： Contrary to popular belief that people won''t pay for anything they read online, Mr. Luo''s business has gone from strength to strength. Not only have people been willing to pay for knowledge\", they have also stayed very loyal to his website and seemed very happy to gobble up everything that was on offer.\n\n展开细节： Of course, Mr. Luo''s success was no accident. He didn''t get attention right away but he made a name for himself by delivering a high-quality minilecture every single morning for two years straight. And another reason for his success is his keen insight into the needs of China''s rising middle class, who is hungry for the information and knowledge that they believe would help them increase their wealth or improve the quality of their lives.\n\n使用否定： I wouldn''t say that he is my role model because I think I lack the business acumen and charisma he possesses. However, I do admire his persistence and courage to challenge the status quo.\n\n做出推测： I don''t think I would be able to do the same kind of work as he, but I''d love to start a course of my own on his website one day if I had the chance. Although I think there''s little likelihood of this happening because I don''t think I''ve got what it takes to be a lecturer!","translation":"","usageNote":"原题库提供的参考表达"},{"type":"EXPRESSION","expression":"a surge in entrepreneurship","translation":"创业的热潮 on offer提供的，出售中的","usageNote":""},{"type":"EXPRESSION","expression":"anchor","translation":"主播 no accident绝非偶然","usageNote":""},{"type":"EXPRESSION","expression":"something people would kill for make a name for oneself as…","translation":"建立起…..的名声","usageNote":""},{"type":"EXPRESSION","expression":"[习语]很多人梦寐以求的.... keen insight into","translation":"对.....敏锐的认识","usageNote":""},{"type":"EXPRESSION","expression":"instant messaging","translation":"即时通讯 rising middle class崛起的中产阶层","usageNote":""},{"type":"EXPRESSION","expression":"social networking","translation":"社交网络 business acumen商业头脑","usageNote":""},{"type":"EXPRESSION","expression":"have a huge following","translation":"有众多粉丝 charisma人格魅力","usageNote":""},{"type":"EXPRESSION","expression":"popular belief","translation":"一般大众的想法 status quo现状","usageNote":""},{"type":"EXPRESSION","expression":"go from strength to strength [","translation":"习语]不断壮大 there''s little likelihood of…几乎不可能......","usageNote":""},{"type":"EXPRESSION","expression":"stay loyal to","translation":"对...非常忠实 what it takes to be...[习语]成为需要……的东西","usageNote":""},{"type":"EXPRESSION","expression":"gobble up","translation":"狼吞虎咽","usageNote":""}]'::JSONB),
    ('ielts_q_14ea4621dcc03f5c07f7f9e1', 'ielts_group_a5b73a4b3bcd8ae7103e4f89', 'PART_3', 1, 'What kinds of jobs do young people not want to do in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I guess it really depends on one''s circumstances. But generally, I think the younger generation have received better education than their parents generation so they tend to have higher opinions of themselves and refuse to do the jobs that they think are beneath them, such as blue collar jobs or service jobs. On the other hand, I suppose most young people today would prefer to go see the world and work in a big city rather than be stuck in the small town where they were born, even though their parents may have had a good life all planned out for them - working as a civil servant in the local government, marrying early and buying a house near the best school in town. I guess it''s fortunate that not every child chooses to follow in their parents’ footsteps! After all, this is how the society progresses, isn''t it?\n\ndepend on one''s circumstances取决于个人境遇 the younger generation年轻一代\n\nhave high opinions of oneself自视甚高 beneath them 配不上他们的\n\na white/blue collar job白领/蓝领工作 go see the world 去看世界\n\nhave a life planed out for them为他们设计好了人生 civil servant 公务员\n\nfollow in one''s footsteps [习语]追随某人的足迹","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b67f19afdebcddbbb0982127', 'ielts_group_a5b73a4b3bcd8ae7103e4f89', 'PART_3', 2, 'Who is best at advising young people about choosing a job: teachers or parents?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it''s a tough question because I think ultimately it''s up to young people themselves to decide what they want to do with their lives, but I guess both teachers and parents have some useful perspectives to offer. A teacher may know more about the student''s academic performance thus could make a reasonable prediction about their potential in the field, while a parent may be a better judge of their children''s character, and they could also be good role models if they have had fulfilling careers themselves. However, both teachers and parents could be biased, so I believe it''s best to listen to different opinions so that you can make a well-informed decision yourself.\n\nultimately最终 up to[习语]取决于\n\noffer perspectives 提供视角 make a prediction about 作出预测\n\na good judge of character善于识人的人 role model 榜样\n\na fulfilling career有满足感的职业 biased 偏颇的，片面的\n\nmake a well-informed decision 做出明智的选择","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_378026223362897f9980c17a', 'ielts_group_a5b73a4b3bcd8ae7103e4f89', 'PART_3', 3, 'Is money always the most important thing when choosing a job?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Definitely not! I mean even if you believe in materialism and think more money will bring more happiness, it will still be very short-sighted to prioritize money over other factors like your passion, career path, work-life balance, etc. Because in the long run, it is those factors that will make sure you''re enjoying your life. In fact, I''d argue that money should probably come last when choosing a job, especially for a new graduate. I think it''s very important to think long term and remember that everybody has to pay their dues if they want to be successful. There''s a saying that goes “do what you love and the money will follow\". I think it makes sense because if you really find your passion, you''ll be highly motivated to work hard and think creatively and eventually be more successful at what you do.\n\nmaterialism 唯物主义 short-sighted 短视的\n\nprioritize A over...把A置于……之前 career path 职业发展\n\nwork-life balance 工作和生活的平衡 in the long run 从长远来看\n\nI''d argue that 我认为 think long term 从长计议\n\npay one''s dues [习语]（在成功之前）付出相应的努力 be highly motivated 有极大的动力","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5c805ea25129d0980a2b9f40', 'ielts_group_a5b73a4b3bcd8ae7103e4f89', 'PART_3', 4, 'Do you agree that many people nowadays are under pressure to work longer hours and take less holiday?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Totally. It seems that overwork is the norm in most of the big cities around the world. Some may do it voluntarily, but I guess most people. feel compelled to do so because of the fierce competition they are constantly worried about being replaced if they don''t work hard enough. Technology is not doing us any good either because now we are expected to respond to emails and messages at all hours, even when we''re on holiday, which means the line between work life and personal life is increasingly blurred, putting us in a position where we find it impossible to take time off.\n\nthe norm常态 feel compelled to被迫做某事\n\nfierce competition激烈的竞争 do someone good对某人有好处\n\nat all hours任何时间 the line between... and... is increasingly blurred ……之间的界限越来越模糊\n\nput... in a position...把某人置于某种境地 take time off休息","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5a4ef1dc04ab6e3e231f4ad7', 'ielts_group_a5b73a4b3bcd8ae7103e4f89', 'PART_3', 5, 'What is the impact on society of people having a poor work-life balance?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well obviously people''s health will suffer if they are constantly overloaded. Not only will fatigue lead to reduced productivity at work, but working late every night will also put a strain on people''s relationships with their family and friends, which will certainly have serious repercussions on people''s social life and the wider community. For example, children of an overworked couple are usually at risk of underachieving at school.\n\noverloaded超负荷的 fatigue劳累\n\nreduced productivity降低的生产力 put a strain on给……带来压力\n\nhave repercussions带来（通常是负面的）影响 at risk of面临……的风险\n\nunderachieve表现不佳","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a596bd0dc5eabde1df43a8e4', 'ielts_group_a5b73a4b3bcd8ae7103e4f89', 'PART_3', 6, 'Could you recommend some effective strategies for governments and employers to ensure people have a good work-life balance?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, this all sounds a bit paradoxical, doesn''t it? Forcing people to take more holiday? But I guess the government does need to make sure that employees have their legal entitlement to a break from work. Now exactly how this could be done is really beyond my knowledge but as far as I know, I think it''s really down to the employers to ensure they improve efficiency in the workplace rather than overload their staff. I think it''s really important to establish a company culture that sends the right message, such as “work hard, play hard” so the employees will know that they won''t be penalized for taking time off, instead they will be rewarded for coming up with creative solutions that allow them to finish work early.\n\nparadoxical矛盾的 legal entitlement to 对……的合法权利\n\nbeyond my knowledge 超出我的认知范围 as far as I know据我所知\n\nbe down to [习语]……的责任 send the right message 传递正确的理念\n\nbe penalized for 为……受到处罚","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_99389538f5faee2cf462736f', 'ielts_group_dcb4a2ff3d7efcbfbb91a072', 'PART_1', 1, 'Are you happy to be the age you are now? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I''d say so. I think I used to be a lot more awkward when I was a teenager, but now I''ve matured a lot and I think now I have a clearer picture of the direction I want my life to take.\n\nawkward尴尬的，懵懂的 mature成熟\n\ntake…direction走向...方向","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_739d9451ea366fd9fbed9eec', 'ielts_group_dcb4a2ff3d7efcbfbb91a072', 'PART_1', 2, 'When you were a child, did you think a lot about your future? [Why/Why not?] ?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t think so. I mean when you''re young, you tend to live in the present. I think I was a happy child so I was just blissfully oblivious of what was ahead.\n\nlive in the present活在当下 blissfully oblivious of对...幸运地无知\n\nahead在将来","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ce55fd69dd8732140b084872', 'ielts_group_dcb4a2ff3d7efcbfbb91a072', 'PART_1', 3, 'Do you think you have changed as you have got older? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think we all have, haven''t we? Don''t we all get more down-to earth and practical as we get older? But for me, I think I''m still as foolish as ever. \"Stay hungry, stay foolish\" - that''s my motto!\n\ndown-to-earth[习语]脚踏实地的 practical现实的\n\nas…as ever一如既往地..... motto座右铭","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b7b1084367c924c94c95ab68', 'ielts_group_dcb4a2ff3d7efcbfbb91a072', 'PART_1', 4, 'What will be different about your life in the future? [Why]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"What will be different? Hmm... I think studying abroad would definitely make a difference in my life. I''ll have to learn to be more independent and open-minded to survive living alone in a different culture. And of course I hope a master''s degree from a prestigious university will help me get ahead in the future.\n\nmake a difference带来（通常是积极的）改变 prestigious university名牌大学\n\nget ahead[习语]（在职场或生活中）占取先机","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_54e9c466438068e12d6482dd', 'ielts_group_d71418ecdecbb9c0966788ea', 'PART_2', 1, 'Describe a time when you started using a new technological device (e.g. a new computer or phone)', '["what device you started using","why you started using this device","how easy or difficult it was to use","and explain how helpful this device was to you."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍: I''m not really obsessed with electronics so I''m not always upgrading my phone to the latest model or trying out new gadgets. But anyway I think I can talk about the time when I first switched from PC to Mac last year.\n\n选择要点: First, I think ''ll tell you about why I made this decision. Well, actually I’d been using PC for years and it was not that I didn''t have anything to complain but it''s just a habit. But after my old laptop crashed the third time my friend convinced me to try the latest MacBook.\n\n比较对比: Now Apple has long had a reputation for brilliant product design, but this didn''t make my first encounter with a MacBook any less exciting. I hope this doesn''t sound too much like a product placement, but it really felt great to hold the laptop in your hands. The surface was cool to the touch, but it was slightly rounded so it had an organic feeling. It opened and closed all so elegantly and of course the much-coveted keyboard lived up to its reputation - it''s smooth and crisp.\n\n让步: Although the design really had me at first glance, it took me another month or so to finally get used to the operating system which is vastly different from Windows.\n\n举例: For example, I still find it hard to wrap my head around how iTunes works. “Synchronization” is a concept very difficult to grasp when you have been copying and pasting files for all your life.\n\n使用否定: But of course I wouldn''t say my MacBook is not user-friendly. On the contrary, it is all very intuitive. Once you get the hang of it, you’ll feel right at home with its use.I find it especially helpful because I''m also using an iPhone and and iPad. It would have been a total pain in the neck to transfer files across different systems. I should have bought a MacBook years ago!","translation":"","usageNote":"原题库提供的参考表达"},{"type":"EXPRESSION","expression":"be obsessed with electronics","translation":"痴迷于电子产品 crisp手感清脆的","usageNote":""},{"type":"EXPRESSION","expression":"upgrade to the latest model","translation":"换到最新型号 …had me at first glance第一眼就吸引了我","usageNote":""},{"type":"EXPRESSION","expression":"try out new gadget","translation":"试用新的电子设备 operating system操作系统","usageNote":""},{"type":"EXPRESSION","expression":"switch from…to...","translation":"从...换到 ....wrap one''s head around...[习语]理解......","usageNote":""},{"type":"EXPRESSION","expression":"crash （","translation":"电脑）崩溃 grasp a concept理解一个概念","usageNote":""},{"type":"EXPRESSION","expression":"have a reputation for","translation":"以...闻名 grasp a concept理解一个概念","usageNote":""},{"type":"EXPRESSION","expression":"product placement","translation":"植入广告 intuitive （操作）符合直觉的","usageNote":""},{"type":"EXPRESSION","expression":"cool to the touch","translation":"触感凉凉的 get the hang of… [习语]熟悉，弄明白","usageNote":""},{"type":"EXPRESSION","expression":"much-coveted","translation":"众人艳羡的 feel right at home感觉非常放松自信","usageNote":""},{"type":"EXPRESSION","expression":"live up to one''s reputation","translation":"名副其实 a pain in the neck [习语]烦人的事情","usageNote":""}]'::JSONB),
    ('ielts_q_d9d107f7fa3a717aa1e9487d', 'ielts_group_d71418ecdecbb9c0966788ea', 'PART_3', 1, 'What is the best age for children to start computer lessons?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Best age to start computer lessons... Haven''t the children today already taught themselves how to use the smart phones and tablet computers? I know many parents are worried about the negative effects of all the electronics, but in my opinion, it''s better to go with the flow. After all, technology is increasingly an integral part of our modern life and there are now a great number of educational apps that are great for children. Some of them are designed for toddlers! As far as I know, there are also apps and courses that are intended to help children become little computer programmers and they are hugely popular among children of all ages. So I guess my answer to this question is it''s never too early and it''s never too late!\"\ngo with the flow顺应时势 an integral part of ……的重要部分 \ntoddler 蹒跚学步的孩童 children of all ages 各年龄阶段的儿童\nIt''s never too early and it''s never too late. 什么时候开始都可以。","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_281b8ab41b0a4e4fd4c2ada5', 'ielts_group_d71418ecdecbb9c0966788ea', 'PART_3', 2, 'Do you think that schools should use more technology to help children learn?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"That''s a big yes for me. I think it''s safe to say that computer and internet literacy has become ever so vital in our modern society. Needless to say, computer-based or even better, tablet-based learning activities have a natural appeal to children. There''re other advantages, too. For example, by using a computer system, the students learning data could be recorded and later analyzed to provide valuable feedback to teaching and learning. Students of different levels could also be assigned different online practice to help them learn at their own pace.\ncomputer and internet literacy 对电脑和网络的了解 tablet-based 基于平板电脑的\nhave a natural appeal to 对……有天然的吸引力 provide valuable feedback 提供有价值的反馈\nat one''s own pace 根据某人自己的节奏","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a0db1ca5a35db3375bbf7a5e', 'ielts_group_d71418ecdecbb9c0966788ea', 'PART_3', 3, 'Do you agree or disagree that computers will replace teachers one day?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Now this I''d say no. Although I do believe some of the teacher''s responsibilities are bound to be replaced by computers, such as giving lectures or presentations. I mean why do you still have to sit through one lecture after another in class when all the great lessons on any topics are freely available online and can be watched anytime anywhere? However, I think it''s highly unlikely that teachers will begone from the classroom and every student will be looking at a screen. One reason is teaching is never one way and students thrive on timely and constructive feedback from the teacher and their peers. What''s more, as long as were still humans not cyborgs, we still crave social interaction and human relationships so I''d say teachers are here to stay.\nbe bound to ……一定会发生 sit through 坐着熬过\nthrive on因为……而成长，变强大 timely and constructive feedback及时而有建设性的反馈\ncyborg 半机械人 social interaction 社交\nhere to stay 不会消失","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0dd2f90d6dfc90d05c75ff09', 'ielts_group_d71418ecdecbb9c0966788ea', 'PART_3', 4, 'How much has technology improved how we communicate with each other?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, as always, technology cuts two ways. Long distance communication has certainly been made easier by mobile phones and video chats, and social networking sites have made it possible for almost any two people in the world to connect with each other. However, people are also complaining about the detrimental effects of technology on their real-life relationships as family and friends now spend more time looking at their phones than looking at each other. And some say the personalization algorithms used by Facebook, Twitter and other News apps arc creating this ''echo chamber'' where people no longer hear the opinions that are different from their own.\ncut two ways有利有弊 social networking sites 社交网站\ndetrimental effects 不利的影响 personalization algorithm 个性化推送\necho chamber 回音室现象","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_047d49256396ba36abeb21db', 'ielts_group_d71418ecdecbb9c0966788ea', 'PART_3', 5, 'Do you agree that there are still many more major technological innovations to?be made?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"That''s a difficult question since I''m not really following the news in the science world closely. However, I think human beings have a natural tendency to explore the unknown and there'' re still a lot of \"new frontiers\" to explore, such as the outer space, artificial intelligence and genetic engineering. So I think there''s every opportunity that more major technological innovations will be made in these fields. But I have to admit it seems we''ve reached the point now where the next big breakthrough will inevitably pose certain ethical challenges, like what has been described in the sci-f series ''Black Mirror'', where almost every seemingly innocuous innovation ends up in a terrible tragedy.\n\nhave a natural tendency to 有一种自然的倾向去…… explore the unknown 探索未知\n\nnew frontier新的前沿 the outer space 外太空\n\nartificial intelligence 人工智能 genetic engineering 基因工程\n\nthere''s every opportunity that 非常有可能 we''ve reached the point where 我们发展到了这样的阶段\n\npose ethical challenges 带来伦理的挑战 innocuous 无害的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c8772ded73b275cd5491847a', 'ielts_group_d71418ecdecbb9c0966788ea', 'PART_3', 6, 'Could you suggest some reasons why some people are deciding to reduce their use of technology?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, this is hardly surprising given the widespread internet addiction and all sorts of health conditions related to our dependency on technology. The Hollywood director Christopher Nolan famously doesn''t own a mobile phone, which hasn''t been stopping him from making some of the greatest movies of all time. He believes this is good for his creativity and time management. I just wish I could do the same! But then again, there''re so many technologies that we cannot simply do away with and I think it''s irrational to blame all our problems in life on the development of technology. Technophobia will not lead us anywhere!\n\ngiven... 考虑到……. dependency on technology 对科技的依赖\n\ntime management 时间管理 then again [ 习语]表转折\n\ndo away with 抛弃 irrational 不理性的\n\nblame something on 把某事怪罪到……上 technophobia 对科技的恐惧","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_440d07ceee81e3aadec42470', 'ielts_group_928177c0ed22b9e7930d4b08', 'PART_1', 1, 'When you go shopping, do you prefer to pay for things in cash or by card? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Definitely by card. It''s such a hassle to bring a handful of change with you all the time. Using a card, especially one with Quick Pass, can save you a lot of time.\n\na hassle to... 做……是件麻烦事 a handful of change 一大堆零钱\n\nQuick Pass 闪付 save...a lot of time 为……节省大量时间","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a978a1026fb59bee87a940ef', 'ielts_group_928177c0ed22b9e7930d4b08', 'PART_1', 2, 'Do you ever save money to buy special things? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, sometimes. I''m not making a lot of money since I''m still a student. So, whenever I have my eye on something which is a bit out of my price range, I''ll certainly have to save up in order to buy it at a later time.\n\nhave one''s eye on... 看上…… out of my price range 超出我能承受的价格范围\n\nsave up 存钱","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_225765b4ec107620dc1be278', 'ielts_group_928177c0ed22b9e7930d4b08', 'PART_1', 3, 'Would you ever take a job which had low pay? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it really depends on whether there are other incentives. For example, if there was a job that provides great learning opportunities, I wouldn''t be too worried if the pay wasn''t handsome enough. After all, I''m not the breadwinner in my family.\n\nother incentives 其他好处 breadwinner 赚钱养家的人","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b249439ae084d4b47f5e0df0', 'ielts_group_928177c0ed22b9e7930d4b08', 'PART_1', 4, 'Would winning a lot of money make a big difference to your life? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Absolutely! I would be able to help my parents pay off the mortgage. With that money I could also attend a better university overseas, which would definitely change my life. And, of course, a fancy diamond necklace would really put a cherry on top!\n\npay off the mortgage 还清房贷 a fancy diamond necklace 精美的钻石项链\n\nput a cherry on top 锦上添花","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3f946a9fa0906a6b25897680', 'ielts_group_e4ab6b6b5505800a7f38a38d', 'PART_2', 1, 'Describe an interesting discussion you had as part of your work or studies.', '["what the subject of the discussion was","who you discussed the subject with","what opinions were expressed","and explain why you found the discussion interesting."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"整体介绍： I''d like to talk about the discussion I had with my classmates on Artificial Intelligence when we were preparing for a group presentation for our science class in high school.\n\n和谁讨论： There were 4 people in our group, two guys named Yang and Ming, a girl named Lan, and I. We were discussing what should be included in our presentation, and apparently the team members had rather different ideas as to what our conclusion should be.\n\n观点表达： The guys were quite adamant that the benefits of AI are so far-reaching that any risks associated with it would seem insignificant and negligible in comparison. Lan and I were of the opinion that we should tread really carefully with AI, considering the possibility that one day we may reach the technological singularity which is known as the turning point when the intelligence of computers begins to surpass the collective intelligence of human beings.\n\n为何有趣： The discussion was riveting in that we covered a number of interesting issues relating to AI, from its history to its recent development, and even to the possible future depicted in the famous Matrix trilogy. Different ideas were exchanged, and we kept challenging each other to come up with more powerful arguments. It was truly an awesome discussion because apparently both sides did their research to support their opinions. If there had been a neutral bystander, he or she would have had a hard time deciding who should have won. This heated discussion also gave us an idea as to how exactly we should deliver the presentation—in the form of a debate! And as you may have guessed, it turned out really great. I shall always remember this truly interesting discussion.\n\n重点词句\n\nArtificial Intelligence人工智能 collective intelligence集体智慧\n\nadamant坚决的 riveting吸引人的\n\nfar-reaching影响深远的 be depicted in...在……被描绘\n\ninsignificant and negligible无足轻重的 the Matrix trilogy《黑客帝国》三部曲\n\ntread carefully慎重行事 a neutral bystander中立的旁观者\n\ntechnological singularity科技奇点 heated discussion激烈的讨论\n\nturning point转折点 in the form of... 以……的形式\n\nsurpass超越","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c0fb2ba58ba200b9601c48f4', 'ielts_group_e4ab6b6b5505800a7f38a38d', 'PART_3', 1, 'Why is it good to discuss problems with other people?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, two heads are better than one. Once you have shared a problem with others, they may be able to offer some new perspectives. Sometimes those who are closely involved may not see things so clearly, and it''s necessary to look at the problem with a fresh eye. I suppose in some cases, an in-depth discussion may also spark some new ideas which in turn will help solve a problem. So if you''re stuck with a problem, it''s a good idea to discuss it with others.\n\nTwo heads are better than one.三个臭皮匠，赛过诸葛亮 offer new perspectives提供新的视角\n\nwith a fresh eye 以全新的眼光 an in-depth discussion深度讨论\n\nspark new ideas 激发新的想法 be stuck with a problem 被问题难住了","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_617378336d0715de0f79c29d', 'ielts_group_e4ab6b6b5505800a7f38a38d', 'PART_3', 2, 'Do you think that it’s better to talk to friends and not family about problems?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I suppose it really depends on what kind of problems you have and what your expectations are when you talk to these people. In most of the cases, family members can give you some moral support to make you feel better, and it may also be a good idea to consult them with some personal issues. However, if your problems are purely academic or professional, there''s little they can do to help you. In such cases, it''s more advisable to seek the advice of a friend who is more familiar with these issues.\n\nmoral support 精神上的支持 consult...with... 征求某人关于某事的建议或意见\n\nit''s advisable to... 做……是很明智的 seek the advice of... 寻求……的建议","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b831853e57c64783ca2de0b7', 'ielts_group_e4ab6b6b5505800a7f38a38d', 'PART_3', 3, 'Is it always a good idea to tell lots of people about a problem?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Not really. When you encounter a problem, it''s understandable that you want to share it with those who are close to you. However, it''s not wise to trouble too many people with it. Telling different people about the same problem doesn''t make it go away. Another downside is that you may strike people as being self-absorbed and whiny. It''s much better to focus on solving the problem rather than complaining about it.\n\nencounter a problem 遇到问题 make a problem go away 解决问题\n\nstrike somebody as... 让某人觉得 self-absorbed and whiny 自恋且爱发牢骚","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2f3bab59b63fee598e94a737', 'ielts_group_e4ab6b6b5505800a7f38a38d', 'PART_3', 4, 'Which communication skills are most important when taking part in meetings with colleagues?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, you have to be able to express your opinions succinctly above all things. In order to communicate with others effectively, one usually needs to put ideas and opinions in a few words. You don''t want your listeners to run out of patience. Aside from that, being an attentive listener is also important. An essential element of successful communication is mutual respect. By listening to your colleagues attentively, you show them that you respect them and their opinions are valued.\n\nsuccinctly 简明扼要地 above all things 比其他都重要\n\nput...in a few words 把……长话短说 run out of patience 耗尽耐心\n\nmutual respect 互相尊重","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_03d4cb18c95229c44be90748', 'ielts_group_e4ab6b6b5505800a7f38a38d', 'PART_3', 5, 'What are the possible effects of poor written communication skills at work?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"If you cannot convey meanings clearly with your written works, there may be some serious problems. Poor written correspondence with colleagues could result in misunderstandings and an increase in the cost of communication. If your letters and reports to clients are not well written, your company''s name will suffer. More importantly, no boss would appreciate an employee who is not skillful with paperwork. All in all, it''s always wise to practice and polish your written communication skills.\n\nconvey meaning 表达含义 written correspondence 书面通讯\n\ncompany''s name will suffer 公司名誉会受损 all in all 总而言之\n\npractice and polish 练习并打磨","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ed16a67d5dad69caa31259fe', 'ielts_group_e4ab6b6b5505800a7f38a38d', 'PART_3', 6, 'What do you think will be the future impact of technology on communication in the workplace?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There is no doubt that technology has brought and will continually bring revolutionary changes to the workplace. Development in certain technologies such as voice recognition and Artificial Intelligence will certainly boost the efficiency of communication in the future. People will no longer need to type letters and messages out. Instead, they can simply say things out loud and those words will be transcribed by a computer. This can certainly save us a lot of time on correspondence.\n\nbring revolutionary changes 带来革命性的变化 voice recognition 语音识别\n\nboost the efficiency 大幅提升效率 type letters and messages out 把信和消息的内容打出来","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9e30c9ad87d3bfc4311364d5', 'ielts_group_4d22e75784312121bbff9673', 'PART_1', 1, 'Are there many animals or birds where you live? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I suppose. I live in a residential community in the city. I can often see some people walking their dogs in the morning or after dinner. However, there aren''t many birds there. The cleaners would chase away any birds in sight.\n\nresidential community 居民区 walking the dogs遛狗\n\nchase away 赶跑 in sight 目光所及","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9a813383fc22a8f5dffd6cab', 'ielts_group_4d22e75784312121bbff9673', 'PART_1', 2, 'How often do you watch programmes or read articles about wild animals? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, not so often these days. When I was a kid I used to watch documentaries about animals all the time, but now I simply don''t have the time for that. I suppose I''m no longer the wide-eyed child who has innate curiosity for everything.\n\nwide-eyed child 天真的孩子 innate curiosity 天生的好奇心","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_335da40ff0f86abe18e9ba46', 'ielts_group_4d22e75784312121bbff9673', 'PART_1', 3, 'Have you ever been to a zoo or a wildlife park? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Sure, I have been to several zoos in different places, but none of them compares to the night safari park I visited in Singapore. Never had I visited a park after dark before. It was the experience of a lifetime!\n\nnight safari park 夜间野生动物园 experience of a lifetime 一生难忘的经历","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_af236732108f06dd0a0b5e1b', 'ielts_group_4d22e75784312121bbff9673', 'PART_1', 4, 'Would you like to have a job working with animals? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"As much as I would love to say yes, I have to say no. Most mammals have an overpowering smell and I don''t think my sensitive nose can take that. I mean, I''m happy to watch animals from afar, but not when I have to get really close to one.\n\nan overpowering smell 强烈的气味 a sensitive nose 敏感的鼻子\n\nwatch...from afar 远远地看着……","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_567e706fe26bc10a8bb48eca', 'ielts_group_aca0b0ab827f8b299a7334ec', 'PART_2', 1, 'Describe a website you use that helps you a lot in your work or studies.', '["what the website is","how often you use the website","what information the website gives you","and explain how your work or studies would change if this website didn''t exist."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"整体介绍： Well, the website that I can think of immediately is the one called LexisNexis. It''s arguably the biggest legal research database online.\n\n使用频度： Since I''m a law student I need to use it all the time. I love using it because the information it contains is comprehensive and the operating features such as the search engine are rather user-friendly.\n\n所含信息： It contains all the legislation, cases and commentary that I need for my studies. Whenever I need to search for a case referred to in our casebooks, I will log onto this website to find the judgment and other relevant case law authorities. The commentary there can also help me understand the cases better.\n\n如果没有这个网站会怎样： It would be unthinkable how I should locate these invaluable learning materials if this website didn''t exist. No other website can provide such a complete collection of cases at all levels of courts. Looking for hard copies of the cases would be a complete nightmare. Without the commentary it would take a much longer time for me to thoroughly understand the judges'' reasoning process.\n\nSince the database also shows whether a judgment has been overturned by an appellate court or in a later case, I can always be sure that the cases I cite in my essays are the leading authorities. I can''t even begin to imagine how my life would be if this website was not there with each and every step of my studies of law. I''m so thankful that my university allows students to use it for free. \n\n重点词句\n\ncomprehensive全面的 a complete nightmare一场噩梦\n\noperating features操作特点 reasoning process推论过程\n\nuser-friendly易于使用的 overturn推翻\n\ncase law authorities权威案例 appellate court上诉法院\n\nit would be unthinkable...……是难以想象的 leading authorities顶级权威\n\ninvaluable learning materials宝贵的学习材料","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_169ede05c75d67821504d0fa', 'ielts_group_aca0b0ab827f8b299a7334ec', 'PART_3', 1, 'Why do some people find the internet addictive?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Because of the crazy amount of information there is! No matter what you are into, you can always find relevant information on the internet. If you keep searching, the amount of information is overwhelming! Another reason is that many websites are designed to get you hooked. For example once you have finished watching a video, a window will pop up to ask if you are interested in some similar ones. If you don''t have enough self-restraint, hours will have passed before you realise that you have watched many videos you didn''t originally plan to.\n\nbe into... 对……感兴趣 overwhelming 压倒性的\n\nget you hooked 让你感兴趣 pop up 弹出\n\nhave enough self-restraint 有足够的自制力","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_dafce37974167fd7567c9c46', 'ielts_group_aca0b0ab827f8b299a7334ec', 'PART_3', 2, 'What would the world be like without the internet?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it depends on whether you mean it had never existed or that it would cease to exist. If it had never been invented, the world would be quite different running at a much slower pace. News would not travel half as fast and communication would be a major issue for many. If for some reasons the internet ceased to exist, it would definitely be a huge retrograde step and the result would be devastating. The overall human productivity would decrease so much that the whole world would go into panic mode.\n\ncease to exist 不复存在 a much slower pace 慢得多的速度\n\na huge retrograde step 巨大的倒退 devastating 灾难性的\n\nhuman productivity 人类生产力 go into panic mode 陷入恐慌","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_75aad9bc07222ca1f47119a8', 'ielts_group_aca0b0ab827f8b299a7334ec', 'PART_3', 3, 'Do you think that the way people use the internet may change in the future?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, this I can say for sure. The fact is that the way people use the internet has been constantly changing in the last few decades, so it''s only natural that it will continue to evolve in the future. There is every reason for me to believe that internet will play an even more significant role in our lives, seeping into every detail of our daily routines from household chores to medical care. In this age of Big Data Revolution, the sky is the limit.\n\nThere is every reason to... 有充分的理由 …… seep into 渗透到\n\nBig Data Revolution 大数据革命 The sky is the limit. （发展）无可限量","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d0eae508f6e21a8036db9577', 'ielts_group_aca0b0ab827f8b299a7334ec', 'PART_3', 4, 'What are the ways that social media can be used for positive purposes?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There have already been cases where people use social media to help find missing persons, to seek assistance on certain problems and to call for donations for those in need. All in all, social media is quite useful when it comes to matters which require the collective input of a large number of people within a limited period of time. It allows news to travel faster, which in turn facilitates any urgent action that needs to be taken.\n\nfind missing persons 找到失踪的人 call for donations 呼吁捐赠\n\nthe collective input 集体的投入 facilitate any urgent action 促成任何紧急行动","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e4532cd9231b4184d963dcaf', 'ielts_group_aca0b0ab827f8b299a7334ec', 'PART_3', 5, 'Why do some individuals post highly negative comments about other people on social media?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it''s really hard to pinpoint why any given individual would do something like that. My guess is that while some may do it purely out of malice, others just want to reduce the pressure within. In this day and age, people are suffering more stress from their workplaces and schools than ever. Such stress keeps accumulating and people are in desperate need to let it out. Many people may also find it easier to say harsh things online because of the anonymity, which means they don''t have to face the other party in person and there is usually little consequence for them.\n\nto pinpoint... 准确指出 purely out of malice 纯粹出于恶意\n\nin this day and age 在现在这个年代 keep accumulating 不断积累\n\nin desperate need to... 急切需要…… anonymity 匿名性\n\nface... in person 本人直接面对…… little consequence 几乎没有什么后果","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_842e4c91a7bf82e2dcea94fc', 'ielts_group_aca0b0ab827f8b299a7334ec', 'PART_3', 6, 'Do you think that companies'' main form of advertising will be via social media in the future?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There is no doubt that social media will play an increasingly important role in advertising, but I wouldn''t go so far as to say that it would become the main medium. I reckon that TV stations and video websites would still take the lion''s share of advertising-generated revenue among all media platforms. After all, online videos and TV shows such as TV series and reality shows still draw in the biggest number of audience, which is unlikely to change in the foreseeable future.\n\nmain medium 主要媒介 take the lion''s share of... 占……的最大份额\n\nadvertising-generated revenue 广告收入 media platform 媒体平台\n\ndraw in... 吸引……来 in the foreseeable future 在可预见的未来","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_aaf186debed8cc4b70249048', 'ielts_group_24832b1a895e662fdf87fa62', 'PART_1', 1, 'What job would you like to have ten years from now? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Wow, that''s a tough job interview question, let me think. Generally I don''t think that far into the future or worry about stuff. But I do hope I can become an expert of some sort in my field and probably reach a more senior level over time as I develop additional experience and expertise.\n\nthink that far into the future 考虑那么久远的未来 \n\nreach a more senior level 获得更加高级的职位\n\nexpertise 专业技能","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4fe8a4851d1593e672d8ef6d', 'ielts_group_24832b1a895e662fdf87fa62', 'PART_1', 2, 'How useful will English be for your future? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Immensely. I mean as long as English is still the closest thing to the lingua franca of the world, I''ll have to master this language in order to communicate effectively with people from other countries. It will also make a huge difference in job hunting, too.\n\nthe closest thing to 最接近……的东西 lingua franca 通用语\n\nmake a huge difference 带来显著的影响 job hunting 求职","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8b5c03f0a24f9496c5fb9ca7', 'ielts_group_24832b1a895e662fdf87fa62', 'PART_1', 3, 'How much travelling do you hope to do in the future? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"As much as possible! Well, it''s my wish anyway. But I do hope I can make some time for travelling when I''m studying abroad. I''m planning to travel around Europe and I''m counting down the days until my trip to Paris!\n\nmake time for 为…….腾出时间 be planning to 计划做某事\n\ncounting down the days until [习语] 为某事倒计时（非常期待做某事）","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cefb948f3978d5ac74a87f27', 'ielts_group_24832b1a895e662fdf87fa62', 'PART_1', 4, 'How do you think your life will change in the future? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well that''s a very broad question. Let me think. I do hope a master''s degree from a reputable university will give me a head start on my career, but I''m not even sure there is a career for me in the future given the rapid advancement in technology. But I guess I''ll just roll with the punches!\n\nbroad question 宽泛的问题 give sb. a head start [习语] 给某人领先优势\n\ngiven… 鉴于…… roll with the punches [习语] 随机应变（尤指应对不利局面）","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_62dc5b7c274b66bf98bbf893', 'ielts_group_b03fd96ecce57ff15f430376', 'PART_2', 1, 'Describe a book that you enjoyed reading because you had to think a lot.', '["what this book was","why you decided to read it","what reading this book made you think about","and explain why you enjoyed reading this book."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍：\n\nThe book I''d like to talk about topped many books of the year list last year and I finally got around to reading it recently, it''s called Bad Blood: Secrets and Lies in a Silicon Valley Startup. I think the title pretty much sums up everything in the story - only it''s not a story, it''s nonfiction.\n\n选择要点：\n\nFirst I think I''ll tell you about the startup that''s centered around- Theranos, a combination of therapy and diagnosis was a company founded by a brilliant young Stanford dropout, Elizabeth Holmes, who promised to revolutionize the medical industry with a machine that would take a small sample of a customer''s blood and test for an overall picture of health. For a while she was seen as the female Steve Jobs and her company was valued up to $9 billion. But the only problem was, the technology never actually worked.\n\n比较对比：\n\nNow unlike any other scam artist, who would probably prey on gullible people, say, at the bottom of the food chain, Elizabeth went straight for the people at the top. Experienced politicians, Wall Street tycoons and even military personnel they all fell victim to her charm. And the endorsement of those important people had in turn consolidated her status and credibility, which sustained the big lie until the very last minute.\n\n使用让步：\n\nThis is the part that got me thinking the most - although it remains a mystery what Elizabeth said to her investors behind closed doors, because she refused to be interviewed by the author - a lesson can be learned, which is anyone, regardless of status and experience, can be fooled when their ego and greed are appealed to.\n\n做出推测：\n\nThis book was such a page turner that I found myself unable to put it down once I started. The description of the secretive and toxic culture within the company especially struck a chord with me. I kept thinking what I would have done if I had been one of the employees in the company. Would I be brave enough to stand up to this tyrannical leader?","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f7d9bd48f9458ab826f2dd38', 'ielts_group_b03fd96ecce57ff15f430376', 'PART_3', 1, 'What are the most popular types of children''s books in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it seems that picture books are very popular these days, especially English books and bilingual books. A lot of Chinese parents are keen on making their children bilingual from an early age and those books are considered essential. It has even become a business making up lists of picture books for children and you can search for the lists online and buy all the books in one go. Those often include phonics readers, fairy tales and science readers. Some of them are very fancy, with all kinds of added features like flaps, cutouts, pop-ups and so on.\n\npicture book 绘本 bilingual 双语的\n\nfrom an early age 从小 in one go 一口气\n\nphonics reader 自然拼读图书 fairy tale 童话故事\n\nflap （童书中的）小翻页 cutout 剪纸，镂空\n\npop-up book 立体书","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_27fdcc98d1b90afbce364e39', 'ielts_group_b03fd96ecce57ff15f430376', 'PART_3', 2, 'What are the benefits of parents reading books to their children?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Tons of! An obvious benefit is reading enhances a child''s vocabulary, and helps them understand different topics of the world. But there''s much more. By consistently reading to your child every day, your child will learn to concentrate and sit still for longer periods of time, which can help later on when they go to school. Another great benefit is reading develops children''s imagination and creativity. When we really engage in a book we imagine what the characters are doing and we visualize the places we''ve never been to in real life. These are what make reading stimulating and fun. With all of the negative effects of screen time, choosing a book that interests your child, and reading it together, is definitely a better option. There''s nothing better than cuddling up to your little one and reading a book or a bedtime story together.\n\nenhance vocabulary 提升词汇量 \n\nsit still for longer periods of time 更长时间地安静坐着\n\ndevelop imagination and creativity 发展想象力和创造性 \n\nengage in a book 专注于一本书\n\nscreen time 花在电子产品上的时间 \n\nThere''s nothing better than… 没有什么比……更好\n\ncuddle up to 跟……温馨地挤在一起 \n\nbedtime story 睡前故事","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9505c42069ae349480176406', 'ielts_group_b03fd96ecce57ff15f430376', 'PART_3', 3, 'Should parents always let children choose the books they read?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Definitely! I mean unless what they want to read is really not age-appropriate. But I strongly believe that generally, parents should give children choices when it comes to reading because it''s the best way to motivate them to read! I know some parents may think some books are better than the other, like classic literature is better than comic books, but I think they should actually celebrate that their kids are reading - not playing video games all day. Besides, who are we to determine what are good and bad books for individual readers? If children have an amazing experience with books, they will almost certainly expand their interest into other types of writing in the future. On the contrary, well-intentioned adults can do a huge disservice to kids when they doubt their ability to read or censor what they read and judge what they read.\n\nage-appropriate（媒体内容）适合这个年龄的 give someone choices 给某人选择的权利\n\nmotivate 鼓励 classic literature 经典文学作品\n\ncomic books 漫画书 \n\nwho are we to determine… 我们凭什么能够决定….\n\nwell-intentioned 怀着好意的 \n\ncensor 审查 \n\ndo a huge disservice to [习语] （通常指非本意的）带来损害，帮倒忙","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c4087e1fe54437f8a316835a', 'ielts_group_b03fd96ecce57ff15f430376', 'PART_3', 4, 'How popular are electronic books are in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Certainly more popular than five years ago. E-readers have become more affordable and there''re more e-books available online. I think it''s fair to say that we now have an enormous variety of content available at any time of day, in any format and through a range of digital devices. However, I reckon the majority of readers still prefer print books to digital products. I know many people who would sample a few pages online before buying a print version to read. But of course it all depends on the person. Some people enjoy the feel of a physical book in their hands while others like the handiness of an e-reader. As far as I know, there''re still too many people who don''t read at all!\n\naffordable 负担得起的 an enormous variety of content 无比丰富的内容\n\nformat 格式，形式 print book 纸质书籍\n\nsample a few pages 试看几页 it depends on the person 取决于个人\n\nphysical book 纸质书 handiness 便利性","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_dfce378f11200bd7f8df10f9', 'ielts_group_b03fd96ecce57ff15f430376', 'PART_3', 5, 'What are the advantages of parents reading electronic books (compared to printed books)?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, they are more portable - that''s probably the number one advantage of electronic books. You can have quick and easy access to hundreds of books on your device. While reading, you can also click on hot links to other places to find out more about the topic online. This could really come in handy when you are reading a science book to your child. Also, if you are very environmentally aware, this could be a good opportunity to teach your children about saving trees and helping reduce pollution from pulp mills.\n\nportable 便携的 have quick and easy access to… 快捷便利地获取……\n\nclick on hot link 点击链接 come in handy 带来便利\n\nenvironmentally aware 关心环境的 pulp mill 纸浆厂","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_dd8f15f2ed0c647df25b4f2d', 'ielts_group_b03fd96ecce57ff15f430376', 'PART_3', 6, 'Will electronic books ever completely replace printed books in the future?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, some people think it''s only a matter of time for printed books to disappear completely, but I''d hazard a guess that physical books are here to stay. I once read a very interesting argument that claimed paper was by far the best medium to store information - books are tough, hard to destroy, compared to a digital disk, and they don''t need any energy to operate. I think I''m quite convinced that there will always be a place for them. But this might all be because I have grown up reading paper books and find it harder to let them go. I guess younger generations who were raised with screens very much a part of their lives, would prefer a different world.\n\na matter of time 时间问题 I''d hazard a guess… 我猜测……\n\nbe here to stay 一直存在 store information 存储信息\n\nlet sth. go 放手（任由它们消失） \n\nbe raised with screens very much a part of their lives 从小电子产品就是生活的一部分","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_da352e554860790ab8c098a8', 'ielts_group_e792b64441a899bc245fd1e3', 'PART_1', 1, 'Which social media websites do you use?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, WeChat obviously. It is the top social network in China. It started out as an instant messaging app but soon expanded to a go-to source of social networking, entertainment and even personal finance. However, Weibo, the Chinese counterpart for Twitter, is still the most popular public microblogging network where news breaks first.\n\nsocial network 社交网 instant messaging 即时通讯\n\ngo-to source [习语]重要的来源 where news breaks first 新闻最先爆出的地方","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b1600a934bcbf64c1fec8c9b', 'ielts_group_e792b64441a899bc245fd1e3', 'PART_1', 2, 'How much time do you spend on social media sites? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Probably more than I should! I mean social media sites are built to get you hooked - like the infinite scroll - hours will have passed before you notice how much time you''ve wasted on endless stream of selfies, pet pictures, celebrity gossip, advertising and so on.\n\nget sb. hooked (on sth.) [习语]让某人上瘾 the infinite scroll 无限下拉刷新的功能\n\nendless stream 无穷无尽的信息流","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_72c41a1694cc8406cfc72f0b', 'ielts_group_e792b64441a899bc245fd1e3', 'PART_1', 3, 'What kind of information about yourself have you put on social media? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Not much, really. I''m a private person. I have no interest in broadcasting what I''m doing, who I''m with all the time. I''d rather sit across from my close friends at a cafe, our phones tucked away. and share the details of each others'' lives we don ''t care to share online.\n\nprivate person 重视个人隐私的人 sit across from 坐……对面\n\ntuck away 收起来 not care to 没兴趣做某事","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2151372d717c524aaa2cde76', 'ielts_group_e792b64441a899bc245fd1e3', 'PART_1', 4, 'Is there anything you don''t like about social media? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Definitely. A lot l''d say. There''s something about social media that makes us care how many friends, flowers, likes and retweets we have. We easily become obsessed with these numbers and unable to live in the moment. You are not enjoying your trip: you are just taking this opportunity to snap a few pictures to see how many likes and comments they''ll get.\n\nlike 点赞 retweet 转发\n\nlive in the moment 活在当下 snap a picture 拍照","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c6844d4f943a7c5528d24676', 'ielts_group_7e4b0bd283334e1f53c1f5dc', 'PART_2', 1, 'Describe something you liked very much which you bought for your home.', '["what you bought","when and where you bought it","why you chose this particular thing","and explain why you liked it so much."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"话题卡说明：\n\n拥有的物品( possession)也是雅思口语中的必备话题，本题需要注意限定范围，即购买的家用物品但同时选题空间也非常宽泛：家具、家用电器、装饰品都可以。使用以下策略可以有意识增加语法结构的丰富度。\n\n开篇介绍：\n\nSince I''m not the breadwinner in my family, I don''t get to decide on big purchases for my home like expensive furniture or appliances. However, I''d like to talk about a robot vacuum I bought that made my whole family very happy.\n\n选择要点：\n\nFirst, I think I''ll tell you how it looks and how it works. Like most robot vacuums, it''s round and flat, like a thick disk with motorized brushes at the bottom and a vacuum motor to collect dust and rubbish. It also has sensors for evading obstacles and avoiding fall. On top of that, it can automatically return to its docking station to recharge when its battery is low. It''s fascinating to watch how it works diligently around the house. I still remember how my parents were wide-eyed in amazement when I first showed them the magic.\n\n比较对比：\n\nEver since robot vacuums became a thing, there have been a host of models and brands with all kinds of fancy features. Although the one I bought doesn''t have all the bells and whistles of its competition, it''s no hassle to install. What I love most is that it''s got a lower profile so it can fit under more furniture. No more bending over to clean under the couch!\n\nAnother thing I like about this robot is that it is much quieter than a regular vacuum cleaner. After I preset the vacuuming time, I can just sit back and enjoy a clean room.\n\n使用否定：\n\nI wouldn''t say this vacuum has delivered us from chores altogether, since no rob vacuum is quite as powerful as a traditional vacuum and some elbow grease , but it has been a huge help in keeping things tidy between regular cleanings.\n\n做出推测：\n\nAfter six months of living with this new piece of technology, I can''t imagine living without it, I should have bought it earlier! l think I would definitely spring for a full-featured model if the old one were to break down.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_eab428d0f193b01061f2970a', 'ielts_group_7e4b0bd283334e1f53c1f5dc', 'PART_3', 1, 'Why do some people buy lots of things for their home?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, your home is your castle. I think people are entitled to buy whatever they see fit for their own home. But I guess we are all prone to buy more things than we need in this age of advertising and social media. Every advertisement carries the same message: your life will be better if you buy what we are selling. We begin to hear this message so many times and from so many angles, we begin to subtly believe it. Meanwhile, social media further encourages comparison and we usually end up buying stuff we don’t need just because people in our friendship circles have done the same. Of course sometimes there’re good reasons for buying lots of things. For example, your home can quickly get cluttered after a baby comes along!","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2420c79943f5b3ca73d5f2a2', 'ielts_group_7e4b0bd283334e1f53c1f5dc', 'PART_3', 2, 'Do you think it is very expensive to make a home look nice?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Not necessarily. If you shop for secondhand furniture and get creative with decoration, I think you can make your home look stylish on a budget. Also, devil is in the detail, so another way to spend your money wisely is to buy small things that attract attention, for example, eye-catching wall art or pillows - they give the room a polished look without setting you back too much. And since the minimalist movement is all the rage right now, the simplest way to make your home look nice is to declutter it, though it''s probably more expensive since you have to throw all the things away!","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f9736d027c2c4344d77382ca', 'ielts_group_7e4b0bd283334e1f53c1f5dc', 'PART_3', 3, 'Why don''t some people care about how their home looks?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Why don''t they care? This sounds a bit condescending, doesn''t it? Maybe they do care but they just cannot afford the maintenance? Or maybe they are too busy. Some people don''t care about the interior design because they like to spend more time outside. Home is where the heart is. It doesn''t have to be beautiful or impressive, as long as it is functional and comfortable and you share it with people you love, it is a good home. I, for one, am not interested in dusting knickknacks that are supposed to make my home look \"nicer\".","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cd19215cbbc97b881bb5588d', 'ielts_group_7e4b0bd283334e1f53c1f5dc', 'PART_3', 4, 'In what ways is living in a flat/apartment better than living in a house?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There''re many advantages of living in a flat or an apartment, especially if you have just started a graduate job or moved to a big city. The most obvious one is of course, costs. Not only is the rent of an apartment usually cheaper than the mortgage in a house, you will also have cheaper living costs, such as gas, water, and electricity because the square footage is smaller. If you don''t have a car, then the location of your property could be crucial. It''s much easier to find an apartment complex in a desirable city location, whereas houses are usually built in the suburbs - you''ll have to endure the long commute every day.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7544590d1dbaac05ea5b8e22', 'ielts_group_7e4b0bd283334e1f53c1f5dc', 'PART_3', 5, 'Do you think homes will look different in the future?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, in terms of architecture and layout I''m not sure if there will be any drastic changes in how homes look in the following decades. After all, the most cutting-edge homes today still have many of the same features that homes did fifty years ago. We still have kitchens, living rooms, bedrooms and bathrooms. We''re still sitting on sofas, eating at tables and sleeping on mattresses on bed frames. But if I have to predict what is going to change, it seems a given that most of our electronics and appliances will only get better and they are bound to change how we live our lives at home. For example, a smart home with all the appliances wirelessly connected and controlled by a single device is no longer science fiction. If I''m around in 50 years, I definitely want my house to be more efficient and green.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b49af8d98952da82de931088', 'ielts_group_7e4b0bd283334e1f53c1f5dc', 'PART_3', 6, 'Do you agree that the kinds of homes people prefer change as they get older?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes. We all have different needs for accommodation at different stages of our lives. while a young graduate may be happy to share a flat in the city center with a stranger, a married couple with kids will have to think about space, privacy, neighborhood and so on. As people get older they are also more likely to own a property rather than rent one. Home ownership gives the family a sense of stability and security. It''s also viewed as a hedge against inflation. Obviously, when so many factors now come into play, your priorities and preferences change.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1dbd330b5b61c3ae9b94efff', 'ielts_group_b2e2ad85299d0221ea8bd4ed', 'PART_1', 1, 'How often do you see your neighbours? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think I only see them in person several times a year, no kidding. However, I do always hear the person who lives next to me banging the door when going outside. It seems that almost every single day he is in a bad mood.\n\nsee sb. in person亲眼见到某人 live next to me住在隔壁\n\nbang the door 大声关门 in a bad mood心情不好","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_08d4769c0aa6b8869354b5a7', 'ielts_group_b2e2ad85299d0221ea8bd4ed', 'PART_1', 2, 'Do you invite your neighbours to your home? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"No, not really, I barely even know them, let alone inviting them over to my home to do some stuff. Well, not only me, in my city, it seems that people who live in apartment buildings are all like this. We''ve got different working schedules and we don''t have time to meet each other face-to-face in everyday life.\n\nbarely 几乎不 let alone 更不用说\n\napartment building 公寓楼 working schedule 工作时间表","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB)
ON CONFLICT (id) DO UPDATE SET
    topic_id = EXCLUDED.topic_id,
    part = EXCLUDED.part,
    sort_no = EXCLUDED.sort_no,
    question_text = EXCLUDED.question_text,
    cue_points = EXCLUDED.cue_points,
    recommended_expressions = EXCLUDED.recommended_expressions;

