-- IELTS user settings, generated training content and IELTS-specific reports.
-- ielts.ielts_id identifies the generated IELTS scene. A practice_session
-- links its own session_id to this value through practice_session.scene_id.

CREATE TABLE IF NOT EXISTS user_ielts (
    user_id UUID PRIMARY KEY,
    target_score NUMERIC(3, 1),
    today_completed_count SMALLINT NOT NULL DEFAULT 0,
    preferred_voice VARCHAR(64),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT user_ielts_target_score_check
        CHECK (target_score IS NULL OR target_score BETWEEN 0 AND 9),
    CONSTRAINT user_ielts_today_completed_count_check
        CHECK (today_completed_count BETWEEN 0 AND 5),
    CONSTRAINT user_ielts_preferred_voice_check
        CHECK (preferred_voice IS NULL OR BTRIM(preferred_voice) <> '')
);

COMMENT ON TABLE user_ielts IS
'用户 IELTS 配置及当日训练次数；today_completed_count 达到 5 后禁止创建新的 IELTS 练习';

COMMENT ON COLUMN user_ielts.user_id IS
'逻辑关联 user.id，不设置数据库外键';

COMMENT ON COLUMN user_ielts.target_score IS
'用户目标 IELTS Speaking Band，取值 0 至 9';

COMMENT ON COLUMN user_ielts.today_completed_count IS
'用户今日已完成的 IELTS 练习次数，取值 0 至 5；应用需在业务日切换时统一重置为 0';

COMMENT ON COLUMN user_ielts.preferred_voice IS
'用户在 IELTS 模式下使用的专属音色标识';

CREATE OR REPLACE FUNCTION set_user_ielts_updated_at()
RETURNS TRIGGER
AS 'BEGIN NEW.updated_at = CURRENT_TIMESTAMP; RETURN NEW; END;'
LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS user_ielts_set_updated_at ON user_ielts;

CREATE TRIGGER user_ielts_set_updated_at
BEFORE UPDATE ON user_ielts
FOR EACH ROW
EXECUTE FUNCTION set_user_ielts_updated_at();

CREATE TABLE IF NOT EXISTS ielts (
    ielts_id VARCHAR(64) PRIMARY KEY,
    user_id UUID NOT NULL,
    mode VARCHAR(24) NOT NULL,
    selected_part VARCHAR(8),
    selected_topic_id VARCHAR(64),
    content JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ielts_id_check
        CHECK (BTRIM(ielts_id) <> ''),
    CONSTRAINT ielts_mode_check
        CHECK (mode IN ('PART_PRACTICE', 'MOCK_TEST')),
    CONSTRAINT ielts_selected_part_check
        CHECK (selected_part IS NULL
            OR selected_part IN ('PART_1', 'PART_2', 'PART_3')),
    CONSTRAINT ielts_selected_topic_id_check
        CHECK (selected_topic_id IS NULL
            OR BTRIM(selected_topic_id) <> ''),
    CONSTRAINT ielts_content_object_check
        CHECK (JSONB_TYPEOF(content) = 'object'),
    CONSTRAINT ielts_content_parts_check
        CHECK (
            content ?& ARRAY['part1', 'part2', 'part3']
            AND JSONB_TYPEOF(content -> 'part1') = 'array'
            AND JSONB_TYPEOF(content -> 'part2') = 'array'
            AND JSONB_TYPEOF(content -> 'part3') = 'array'
        )
);

CREATE INDEX IF NOT EXISTS idx_ielts_user_created_at
ON ielts (user_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_ielts_selected_topic
ON ielts (selected_topic_id, created_at DESC)
WHERE selected_topic_id IS NOT NULL;

COMMENT ON TABLE ielts IS
'一次 IELTS 练习及其展示内容；会话消息和逐轮评分分别复用 session_message 与 turn_evaluation';

COMMENT ON COLUMN ielts.ielts_id IS
'生成后的 IELTS 场景 ID；practice_session 通过 scene_id 关联该记录，会话使用独立的 session_id';

COMMENT ON COLUMN ielts.user_id IS
'练习所属用户，逻辑关联 user.id，不设置数据库外键';

COMMENT ON COLUMN ielts.mode IS
'训练模式：PART_PRACTICE 为单 Part 练习，MOCK_TEST 为完整模考';

COMMENT ON COLUMN ielts.selected_part IS
'用户选择的训练 Part；完整模考等不限定单 Part 的模式允许为空';

COMMENT ON COLUMN ielts.selected_topic_id IS
'用户选择的题组 ID；随机题目或涉及多个题组时允许为空';

COMMENT ON COLUMN ielts.content IS
'用于前端统一解析的题目 JSON 快照，结构为 {part1: [{question, recommended_expressions}], part2: [...], part3: [...]}';

CREATE OR REPLACE FUNCTION set_ielts_updated_at()
RETURNS TRIGGER
AS 'BEGIN NEW.updated_at = CURRENT_TIMESTAMP; RETURN NEW; END;'
LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS ielts_set_updated_at ON ielts;

CREATE TRIGGER ielts_set_updated_at
BEFORE UPDATE ON ielts
FOR EACH ROW
EXECUTE FUNCTION set_ielts_updated_at();

CREATE TABLE IF NOT EXISTS ielts_evaluation (
    session_id VARCHAR(64) PRIMARY KEY,
    ielts_id VARCHAR(64) NOT NULL,
    part VARCHAR(8),
    assessment_type VARCHAR(16) NOT NULL,
    overall_band_score NUMERIC(3, 1) NOT NULL,
    fluency_coherence_score NUMERIC(3, 1) NOT NULL,
    lexical_resource_score NUMERIC(3, 1),
    grammatical_range_accuracy_score NUMERIC(3, 1),
    pronunciation_score NUMERIC(3, 1),
    summary TEXT NOT NULL,
    strengths TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    improvements TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    part_evaluations JSONB NOT NULL DEFAULT '[]'::JSONB,
    recommended_expressions TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ielts_evaluation_session_id_check
        CHECK (BTRIM(session_id) <> ''),
    CONSTRAINT ielts_evaluation_overall_band_score_check
        CHECK (overall_band_score BETWEEN 0 AND 9),
    CONSTRAINT ielts_evaluation_fluency_coherence_score_check
        CHECK (fluency_coherence_score BETWEEN 0 AND 9),
    CONSTRAINT ielts_evaluation_lexical_resource_score_check
        CHECK (lexical_resource_score IS NULL
            OR lexical_resource_score BETWEEN 0 AND 9),
    CONSTRAINT ielts_evaluation_grammar_score_check
        CHECK (grammatical_range_accuracy_score IS NULL
            OR grammatical_range_accuracy_score BETWEEN 0 AND 9),
    CONSTRAINT ielts_evaluation_pronunciation_score_check
        CHECK (pronunciation_score IS NULL
            OR pronunciation_score BETWEEN 0 AND 9),
    CONSTRAINT ielts_evaluation_part_check
        CHECK (part IS NULL OR part IN ('PART_1', 'PART_2', 'PART_3')),
    CONSTRAINT ielts_evaluation_assessment_type_check
        CHECK (assessment_type IN ('DIAGNOSTIC', 'FINAL')),
    CONSTRAINT ielts_evaluation_scope_check
        CHECK ((assessment_type = 'FINAL' AND part IS NULL)
            OR (assessment_type = 'DIAGNOSTIC' AND part IS NOT NULL)),
    CONSTRAINT ielts_evaluation_part_evaluations_check
        CHECK (JSONB_TYPEOF(part_evaluations) = 'array'),
    CONSTRAINT ielts_evaluation_summary_check
        CHECK (BTRIM(summary) <> '')
);

-- Compatibility for local databases that applied the earlier IELTS V4 before
-- the upstream V4 achievement migration was introduced. CREATE TABLE IF NOT
-- EXISTS does not add newly introduced columns to that existing table.
ALTER TABLE ielts_evaluation
    ADD COLUMN IF NOT EXISTS ielts_id VARCHAR(64),
    ADD COLUMN IF NOT EXISTS part VARCHAR(8),
    ADD COLUMN IF NOT EXISTS assessment_type VARCHAR(16),
    ADD COLUMN IF NOT EXISTS lexical_resource_score NUMERIC(3, 1),
    ADD COLUMN IF NOT EXISTS grammatical_range_accuracy_score NUMERIC(3, 1),
    ADD COLUMN IF NOT EXISTS pronunciation_score NUMERIC(3, 1),
    ADD COLUMN IF NOT EXISTS part_evaluations JSONB DEFAULT '[]'::JSONB,
    ADD COLUMN IF NOT EXISTS recommended_expressions TEXT[] DEFAULT ARRAY[]::TEXT[];

WITH evaluation_scope AS (
    SELECT evaluation.session_id,
           practice.scene_id AS ielts_id,
           generated.selected_part,
           ROW_NUMBER() OVER (
               PARTITION BY practice.scene_id
               ORDER BY practice.started_at, practice.session_id
           ) AS part_number
    FROM ielts_evaluation AS evaluation
    JOIN practice_session AS practice
      ON practice.session_id = evaluation.session_id
    JOIN ielts AS generated
      ON generated.ielts_id = practice.scene_id
)
UPDATE ielts_evaluation AS evaluation
SET ielts_id = COALESCE(evaluation.ielts_id, scope.ielts_id),
    part = COALESCE(
        evaluation.part,
        scope.selected_part,
        CASE MOD(scope.part_number - 1, 3)
            WHEN 0 THEN 'PART_1'
            WHEN 1 THEN 'PART_2'
            ELSE 'PART_3'
        END
    ),
    assessment_type = COALESCE(evaluation.assessment_type, 'DIAGNOSTIC'),
    part_evaluations = COALESCE(evaluation.part_evaluations, '[]'::JSONB),
    recommended_expressions = COALESCE(evaluation.recommended_expressions, ARRAY[]::TEXT[])
FROM evaluation_scope AS scope
WHERE scope.session_id = evaluation.session_id;

DO $migration$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM ielts_evaluation
        WHERE ielts_id IS NULL
           OR assessment_type IS NULL
           OR part_evaluations IS NULL
           OR recommended_expressions IS NULL
    ) THEN
        RAISE EXCEPTION
            'Cannot upgrade ielts_evaluation because one or more rows cannot be associated with an IELTS practice session';
    END IF;
END
$migration$;

ALTER TABLE ielts_evaluation
    ALTER COLUMN ielts_id SET NOT NULL,
    ALTER COLUMN assessment_type SET NOT NULL,
    ALTER COLUMN part_evaluations SET DEFAULT '[]'::JSONB,
    ALTER COLUMN part_evaluations SET NOT NULL,
    ALTER COLUMN recommended_expressions SET DEFAULT ARRAY[]::TEXT[],
    ALTER COLUMN recommended_expressions SET NOT NULL;

DO $migration$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'ielts_evaluation'::REGCLASS
          AND conname = 'ielts_evaluation_lexical_resource_score_check'
    ) THEN
        ALTER TABLE ielts_evaluation
            ADD CONSTRAINT ielts_evaluation_lexical_resource_score_check
            CHECK (lexical_resource_score IS NULL OR lexical_resource_score BETWEEN 0 AND 9);
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'ielts_evaluation'::REGCLASS
          AND conname = 'ielts_evaluation_grammar_score_check'
    ) THEN
        ALTER TABLE ielts_evaluation
            ADD CONSTRAINT ielts_evaluation_grammar_score_check
            CHECK (grammatical_range_accuracy_score IS NULL
                OR grammatical_range_accuracy_score BETWEEN 0 AND 9);
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'ielts_evaluation'::REGCLASS
          AND conname = 'ielts_evaluation_pronunciation_score_check'
    ) THEN
        ALTER TABLE ielts_evaluation
            ADD CONSTRAINT ielts_evaluation_pronunciation_score_check
            CHECK (pronunciation_score IS NULL OR pronunciation_score BETWEEN 0 AND 9);
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'ielts_evaluation'::REGCLASS
          AND conname = 'ielts_evaluation_part_check'
    ) THEN
        ALTER TABLE ielts_evaluation
            ADD CONSTRAINT ielts_evaluation_part_check
            CHECK (part IS NULL OR part IN ('PART_1', 'PART_2', 'PART_3'));
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'ielts_evaluation'::REGCLASS
          AND conname = 'ielts_evaluation_assessment_type_check'
    ) THEN
        ALTER TABLE ielts_evaluation
            ADD CONSTRAINT ielts_evaluation_assessment_type_check
            CHECK (assessment_type IN ('DIAGNOSTIC', 'FINAL'));
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'ielts_evaluation'::REGCLASS
          AND conname = 'ielts_evaluation_scope_check'
    ) THEN
        ALTER TABLE ielts_evaluation
            ADD CONSTRAINT ielts_evaluation_scope_check
            CHECK ((assessment_type = 'FINAL' AND part IS NULL)
                OR (assessment_type = 'DIAGNOSTIC' AND part IS NOT NULL));
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'ielts_evaluation'::REGCLASS
          AND conname = 'ielts_evaluation_part_evaluations_check'
    ) THEN
        ALTER TABLE ielts_evaluation
            ADD CONSTRAINT ielts_evaluation_part_evaluations_check
            CHECK (JSONB_TYPEOF(part_evaluations) = 'array');
    END IF;
END
$migration$;

CREATE INDEX IF NOT EXISTS idx_ielts_evaluation_ielts_scope
ON ielts_evaluation (ielts_id, assessment_type, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_ielts_evaluation_created_at
ON ielts_evaluation (created_at DESC);

COMMENT ON TABLE ielts_evaluation IS
'IELTS 单 Part 诊断或整场模考评分；同一 ielts_id 可关联三个 Part session';

COMMENT ON COLUMN ielts_evaluation.session_id IS
'逻辑关联 practice_session.session_id，并与 session_message、turn_evaluation 使用相同的 session_id';

COMMENT ON COLUMN ielts_evaluation.ielts_id IS
'逻辑关联 ielts.ielts_id，用于聚合同一次完整模考的三个 Part session';

COMMENT ON COLUMN ielts_evaluation.part IS
'DIAGNOSTIC 对应的 Part；FINAL 整场评分为空';

COMMENT ON COLUMN ielts_evaluation.assessment_type IS
'DIAGNOSTIC 为单 Part 诊断，FINAL 为三个 Part 的整场评分';

COMMENT ON COLUMN ielts_evaluation.overall_band_score IS
'IELTS Speaking 总 Band，取值 0 至 9';

COMMENT ON COLUMN ielts_evaluation.fluency_coherence_score IS
'Fluency and Coherence（流利度与连贯性）Band，取值 0 至 9';

COMMENT ON COLUMN ielts_evaluation.summary IS
'本场 IELTS 练习的总结性评价';

COMMENT ON COLUMN ielts_evaluation.strengths IS
'本场 IELTS 练习表现较好的方面';

COMMENT ON COLUMN ielts_evaluation.improvements IS
'本场 IELTS 练习需要改进的方面';

COMMENT ON COLUMN ielts_evaluation.part_evaluations IS
'FINAL 评分包含的各 Part 评分明细 JSON 数组；DIAGNOSTIC 默认为空数组';

COMMENT ON COLUMN ielts_evaluation.recommended_expressions IS
'本次评分汇总的推荐表达';

CREATE OR REPLACE FUNCTION set_ielts_evaluation_updated_at()
RETURNS TRIGGER
AS 'BEGIN NEW.updated_at = CURRENT_TIMESTAMP; RETURN NEW; END;'
LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS ielts_evaluation_set_updated_at
ON ielts_evaluation;

CREATE TRIGGER ielts_evaluation_set_updated_at
BEFORE UPDATE ON ielts_evaluation
FOR EACH ROW
EXECUTE FUNCTION set_ielts_evaluation_updated_at();

INSERT INTO ielts_question (
    id, topic_id, part, sort_no, question_text, cue_points, recommended_expressions
)
VALUES
    ('ielts_q_7cadf86ff405c68afc057efc', 'ielts_group_b2e2ad85299d0221ea8bd4ed', 'PART_1', 3, 'Do you think you are a good neighbour? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"3. Do you think you are a good neighbour? [Why/Why not?]\n\nI suppose I am. I''d say that what makes a person a good neighbor lies in how they behave towards others. Although nowadays I''m not familiar with who live next to me, at least I don''t trouble others. For example, I never turn on music at midnight, which is to ensure that I don''t make noise and disturb other people.\n\nlie in 在于 behave towards others 对待他人的行为举止\n\nturn on music 放音乐 disturb other people 打扰他人","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a89861b4bbcad2e0dde8541b', 'ielts_group_b2e2ad85299d0221ea8bd4ed', 'PART_1', 4, 'Has a neighbour ever helped you? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yeah. One of my neighbours has offered me help. A few days ago, a delivery guy sent me a package, but I wasn''t at home. The next-door person heard someone knocking my door without any response. He then came out and got my packages for me. How kind.\n\noffer me help 为我提供帮助 next-door person 隔壁邻居\n\nwithout any response 毫无回应","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2ec04eff7fc26389a274fd67', 'ielts_group_39318972febb6a4d5b2b32e4', 'PART_2', 1, 'Describe a very difficult task that you succeeded in doing as part of your work studies.', '["what task you did","why this task was very difficult","how you worked on this task","and explain how you felt when you had successfully completed this task."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"话题卡说明：\n\n这是一张比较常见的事件类话题卡，主要考查考生描述细节的能力，这个话题里包含了两方面的内容，考生在描述过程中既要展示出自己在工作或学习中遇到的艰巨任务，还要表达成功应对挑战的方式和感受。作答时考生需注意使用过去时。除此之外，此题需要考生在英文表述中体现very difficult和succeed的替换形式，比如tough、challenging、 accomplish等。可以和此话题串联的卡片包括Describe a happy experience you had、Describe a person who likes to talk a lot、Describe an interesting job you would like to do。","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_994e97667a51b0bca83024b1', 'ielts_group_39318972febb6a4d5b2b32e4', 'PART_3', 1, 'What are the most difficult jobs that people do?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, firstly, it''s necessary to define the so-called \"hardest jobs\". In my opinion, both physical and mental challenges during working deserve the title. For example, people who work as mountain guides, doctors, police officers are all considered to be the most challenging jobs, coz sometimes they have to put their lives at risk when doing their work. In spite of this, most people have always talked about how satisfying their jobs are.\n\nso-called所谓的 physical and mental challenges生理及心理的挑战\n\ndeserve the title值得这样的称谓 challenging有挑战性的\n\nput one’s lives at risk将生命置于危险之中 satisfying满意的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7432d997c5cd56de5a866ff4', 'ielts_group_39318972febb6a4d5b2b32e4', 'PART_3', 2, 'Why do you think some people choose to do difficult jobs?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I suppose the main reason why people want to go for the extremely tough jobs is because they find them so rewarding and have made a positive impact on society. By that I mean, on the one hand, they can get handsome amount of money by doing their job; on the other hand, knowing they have contributed a lot to the society can be gratifying.\n\ngo for选择 tough困难的\n\nrewarding有回报的 make a positive impact on society对社会有积极的影响\n\nget handsome amount of money赚大钱 contribute a lot奉献很多\n\ngratifying心满意足的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7853bdae219170156d1edb69', 'ielts_group_39318972febb6a4d5b2b32e4', 'PART_3', 3, 'Do you agree or disagree that all jobs are difficult sometimes?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I tend to agree that almost every single job is challenging in certain situations. For example, some people might say that working as a driver is an easy job, what they do is just sit in a car, or a train to chauffeur passengers. However, whilst driving, you need to pay full attention to what happens in front of you, and after driving for a few hours, a driver might find it hard to open their eyes, but they have to control themselves so as to ensure the safety of the passengers.\n\ncertain situations特定条件 chauffeur passengers接送乘客\n\npay full attention to全神贯注 ensure the safety of保证某事/某人的安全","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cd03e2a4bac491b3229570b1', 'ielts_group_39318972febb6a4d5b2b32e4', 'PART_3', 4, 'How important is it for everyone to have a goal in their personal life?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it''s incredibly important to set yourself a goal in life, then you’ll have a more meaningful life.\n\nEveryone should have an achievable goal at least. Without knowing what your aim is, it would be hard to put effort into anything; all you would do is waste your time away every day – how boring it would be.\n\nincredibly important极其重要 set yourself a goal给自己设定一个目标\n\nachievable可以实现的 put effort into付诸努力","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1e88db987733600a02f80242', 'ielts_group_39318972febb6a4d5b2b32e4', 'PART_3', 5, 'Is it always necessary to work hard in order to achieve career success?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes and No. As long as you''ve got a clear life vision for the purpose of doing jobs, you have a career that matters, then you should engage in it and accomplish it. However, during the process, people might feel overwhelmed by various complicated tasks. If they keep striving for them, their career journey will probably grind to a halt. Therefore, what they need to do is to commit themselves to moving forward; in other words, it''s essential to divide your ultimate target into different stages, so as to balance some difficult and easy tasks during his time.\n\nlife vision人生愿景 engage in全情投入\n\naccomplish圆满完成 feel overwhelmed感觉受到打击\n\nstriving for全力拼搏 grind to a halt逐渐停止 ultimate target最终目标","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ac5402282c84906e897d711b', 'ielts_group_39318972febb6a4d5b2b32e4', 'PART_3', 6, 'Do you think that successful people are always happy people?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"No, not really, even though there have been stereotypes that if a person is successful in doing something, he/she must''ve always been in a good mood, because those people own everything that ordinary people ever drеаm аbоut, mоnеу, hіgh ѕосіаl ѕtаtuѕ, you name it. In spite of this, thеre’ve аlwауѕ bееn ups and downs in life. No matter how successful you are, you''ll meet some challenges or get stuck with some problems, which more or less will make you feel stressed and depressed.\n\nstereotype刻板印袭 been in a good mood处于好心情\n\nordinary реорle普通人 you name it应有尽有\n\nups and downs in life生活中的起伏 get stuck with陷入困境","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_44e532a74b85a51b9df6970a', 'ielts_group_176d11e356a9734b4346d069', 'PART_1', 1, 'Do you like the neighbourhood you live in? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, absolutely. It is a place that I''ve been living in my whole life, and it means a lot to me. I''m fond of listening to the birds'' chirping, neighbours’ talking each day. It seems that everything is harmonious around me.\n\nmeans a lot to me 对我很重要 be fond of 喜爱某事物 \n\nchirping 鸟叫 harmonious 和谐的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_470e3641b72ea2a963ca74dd', 'ielts_group_176d11e356a9734b4346d069', 'PART_1', 2, 'What do you do in your neighbourhood in your free time? [Why/why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"The area around me is quite convenient. A supermarket is a stone''s throw from my home, so, if I''m free, I’ll go there to buy some daily necessities. Apart from that, there''s a park nearby. For me, the place is definitely a haven of tranquility, whenever I’ve got spare time, I’ll take a stroll there.\n\na stone''s throw 距离很近 daily necessities 日常必需品\n\na haven of t tranquility 静谧天堂 take a stroll 悠闲漫步","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_90887c50b4948a3b71c6dbc2', 'ielts_group_176d11e356a9734b4346d069', 'PART_1', 3, 'What new things would you like to have in your neighbourhood? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Let''s see, what new stuff would be added in the area, oh, if there was a safe and secure parcel drop box installed in the place, everyone would be so pleased. You know, currently in my community, since most people have to work outside, many delivered packages are always piled up at the corner of a small convenient store. This has not only caused trouble to the owner, but the whole situation has made it hard to find one''s delivered items. If everyone''s parcels could be placed in their own drop box, it would be wonderful.\n\nsafe and secure 安全而有保障的 parcel drop box 快递箱\n\nbe so pleased 感到满意 pile up 堆起","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_776f79ef2b0c38f949dec644', 'ielts_group_176d11e356a9734b4346d069', 'PART_1', 4, 'Would you like to live in another neighbourhood in your town or city? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"If I got loads of money, I''d love to move into a more convenient place. Actually, I''ve seen an apartment building in my city where there''s a shopping centre on the ground floor. If I lived in the place, whenever I needed to buy something, I would just go downstairs, isn''t it a perfect place to live in?\n\nloads of 很多 apartment building公寓楼","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d03c97e21c0770cbde0bb97b', 'ielts_group_eae3f498fdb31cbfc98e73a7', 'PART_2', 1, 'Describe a website you have bought something from.', '["what the website is","what you bought from this website","how satisfied you were with what you bought","and explain what you liked and disliked about using this website."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"话题卡说明\n\n这是一张比较常见的抽象事物话题卡，主要考查考生能否恰当运用现在完成时和过去时有逻辑地回答问题。作答时考生需注意不同时态的正确使用。在描述网站时使用般现在时即听，描述买东西的过程时需用过去时态。另外，考生需要仔细审题。读题后会发现，题最后何要求生不光要表达对购物网站的喜爱之情，还要或多或少地体现一些不满的情绪。可以和此话题串联的卡片包括Describe a website you often visit; Describe a time you found some information on the Internet; Describe a time you receive money as a gift.\n\n整体介绍：A website I''ve bought an item from is a well-known one in my country, which is called Taobao.com.\n\n购买商品：Last month, I got an adorable costume for my cat from the website. It has a special design, with two fake arms on each side, and what the owner needs to do is to make sure the whole piece is put on a cat''s forelegs, then the magic comes—you can see the cat walking like a human. I purchased the item mainly because I wanted to surprise my cat on his very 1st birthday. As well as that, it was in a big sale, so I snapped it up immediately when I saw the price tag.\n\n满意与否：After waiting for a few days, I received the piece of clothing. The moment I got it, I dressed my cat up, and he really looked like a cute person walking in the room. Seeing this made me laugh my head off. So, as you see, I was so happy with the item, which is exactly how it''s described on the virtual shop. To be honest, I was quite curious about who got the idea of making a specially-designed costume for cats.\n\n个人评价：Well, speaking of how I feel about the website, I''d say that in general, I''m a big fan of it. First of all, no matter what I want to buy, I can always find the right item on it. On top of that, once I make a purchase, the second time I visit the website, there’ll be similar items recommended on the front page, which means the website knows me pretty well. But at the same time, this brings some problems. Sometimes, it''s really hard for me to resist the temptation of scrolling through the items, coz almost every single item is my kind of thing. During the process, time is going down the drain, and it is a big waste of time. So, I really need to set a time limit for doing the activity.\n\nspecial design特别设计 make a purchase购物 a big sale巨大折扣 resist the temptation of doing sth.抵制做某事的诱惑\n\nsnap sth. up抢购 scroll through浏览网页 price tag价签 ...is my kind of thing……是我喜爱的事物\n\nlaugh one''s head off开怀大笑 time goes down the drain浪费时间 virtual shop虚拟店铺 set a time limit 设定时限\n\na big fan of sth.喜爱某事","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f8a171520fd6ccda61607e25', 'ielts_group_eae3f498fdb31cbfc98e73a7', 'PART_3', 1, 'What kinds of things do people in your country often buy from online shops?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Chinese people are fond of buying all kinds of stuff in the virtual world, clothes, food, electronic devices, you name it. There''re countless choices. On top of that, E-retailers have always promoted their products by offering a big discount; it''s hard for buyers to resist the temptation of making online payments.\n\nvirtual world虚拟世界 countless choices无限选择\n\nE-retailers网络零售商 promote one''s products促销商品\n\noffer a big discount提供一个巨大的折扣 make online payments 在线支付","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e7d86196b50dd6d514d7339a', 'ielts_group_eae3f498fdb31cbfc98e73a7', 'PART_3', 2, 'Why has online shopping become so popular in many countries?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In my opinion, there are several reasons that make online shopping such a hit worldwide. First of all, people are totally into the activity because of its huge convenience. Online shopping is now possible on one''s mobile phone. It''s easy to access and the way of purchase is user-friendly, so almost all age groups are capable of learning how to do it within a few minutes. As well as that, you don''t need to struggle through the scrum of people to the counter after choosing what to buy. Now, with your computer set up, you can just sit at the desk and have a mug of tea, enjoying the shopping time on the virtual store. So, there''s no reason to avoid shopping online.such a hit如此流行 be totally into十分喜欢\n\neasy to access容易使用 user-friendly容易操作\n\nall age groups所有年龄 struggle through挣扎着穿过\n\nthe scrum of people拥挤的人群 sit at the desk坐在桌前","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_88804176c275e675b1ed2d59', 'ielts_group_eae3f498fdb31cbfc98e73a7', 'PART_3', 3, 'What are some possible disadvantages of buying things from online shops?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There''re a few main drawbacks of online shopping. One problem lies in the fact that what you see might not be the same as what is delivered to you, since we can only see the pictures, not the actual products. In the end, you might be disappointed. Even worse, if you want to exchange the unsatisfactory item, you may find out that you have to pay return shipping, which means you have to spend more money than you need to. This is another negative thing when shopping on the Internet. There''re a few main drawbacks of online shopping. One problem lies in the fact that what you see might not be the same as what is delivered to you, since we can only see the pictures, not the actual products. In the end, you might be disappointed. Even worse, if you want to exchange the unsatisfactory item, you may find out that you have to pay return shipping, which means you have to spend more money than you need to. This is another negative thing when shopping on the Internet.\n\ndeliver递送 actual实际的\n\ndisappointed失望的 even worse更糟糕的是\n\nunsatisfactory items不满意的商品 return shipping退货的运费\n\ndeliver递送 actual实际的\n\ndisappointed失望的 even worse更糟糕的是\n\nunsatisfactory items不满意的商品 return shipping退货的运费","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a25a5b122ad44dc9b9e21478', 'ielts_group_eae3f498fdb31cbfc98e73a7', 'PART_3', 4, 'Do you agree that the prices of all goods should be lower on internet shopping sites than in shops?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I tend to agree with the point. Compared with running a brick-and-mortar store, opening a virtual shop doesn''t need to be concerned about the gross margin and overheads of running businesses in a shopping centre. That''s why E-retailers often lower the price of their products. Accordingly, most consumers are drawn to the places to make online purchases. However, if all of the items sold are much cheaper on the Internet, then there''ll probably be fewer people going shopping in person. As a consequence, the physical stores might disappear completely, which would cause troubles to the whole society, such as job-loss, lack of social interaction, etc.\n\nbrick- and-mortar store实体店 gross margin毛利\n\noverheads of running business 做生意的日常开销 lower the price降低价格\n\naccordingly相应的 be drawn to 被吸引\n\ncause troubles造成困扰 job loss失业","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cc969c6b95053ec80b21c9d2', 'ielts_group_eae3f498fdb31cbfc98e73a7', 'PART_3', 5, 'Will large shopping malls continue to be popular, despite the growth of internet shopping?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, in spite of the increase of online shopping, it''s fairly likely that the shopping centres will be welcome in the future. Compared with shopping on the Internet, the physical stores give people opportunities to socialize. They can share something with friends and family during shopping, or even interact with strangers, like the shopping assistants. You know, this kind of face-to-face communication is much more effective than online interaction. What''s more, most of the shopping malls are not the only places for shopping, but they are also pleasant areas for having meals or doing other recreational activities; these are the things that people cannot experience in the virtual world.\n\nSo as you see, although virtual shops are increasing, it''s still quiet hard to make the great malls lose their popularity.\n\nin spite of 尽管如此 welcome 欢迎\n\nphysical store 实体店铺 give sb. opportunities to socialize 给某人提供社交机会\n\npleasant area 令人愉快的地方 recreational activity 娱乐活动\n\nlose one''s popularity不受欢迎","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b9a53f33e70592c767ab0387', 'ielts_group_eae3f498fdb31cbfc98e73a7', 'PART_3', 6, 'Do you think that some businesses (e.g. banks and travel agents) will only operate online in the future?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it’s really hard for me to say YES. I do admit that there are a large number of banks and travel agents opening online services, which has provided people with huge convenience. In spite of this, I believe that there will always be some people who love to personally visit the branches, and there will still be some services that require one’s presence at the places. Therefore, I foresee that there’ll be fewer physical banks and travel agents, but the places are less likely to completely disappear.\n\na large number of大量的 open online services开通网上服务\n\nprovided people with huge convenience给某人提供巨大便利 personally visit亲自前往\n\nforesee预测","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4842b087b50d7cc419a33b24', 'ielts_group_77a46ab7af5d623a5eecc380', 'PART_1', 1, 'What kinds of emails do you receive about your work or studies?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I receive plenty of internal emails from the corporate office in the form of event notification, company policy change as well as meeting request, normally with attachments involved. It''s a good way to keep me in the loop and record my daily workflow. But sometimes I get a bit inundated with the daily barrage of emails.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_043fbeadbc8df3ed38136ffa', 'ielts_group_77a46ab7af5d623a5eecc380', 'PART_1', 2, 'Do you prefer to email, phone or text your friends? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I text my friends quite a lot on a daily basis on my smart phone, as we can exchange messages instantly. My favorite bit of texting is that I can think over what I want to express. But I do make an occasional call to a close friend to have a heart-to-heart chat and when there''s something truly urgent, a phone call is a definite to reach out to my friends.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7407aab6d381aab73c0813b2', 'ielts_group_77a46ab7af5d623a5eecc380', 'PART_1', 3, 'Do you reply to emails and messages as soon as you receive them? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Personally, I have my email notifications turned off, so I only check my inbox when I have spare time and respond if it''s really needed. But I have my phone on all the time and it only takes a few seconds to compose my message, so I normally text back instantly. When I''m not willing to type, I simply use the Voice to Text feature, which really comes in handy.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ab72689c80fd4c5bc545fe18', 'ielts_group_77a46ab7af5d623a5eecc380', 'PART_1', 4, 'Are you happy to receive emails that are advertising things? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I can''t really put up with those emails containing commercial messages overwhelming my inbox. I don''t even subscribe to any of them but they just keep coming in constantly, taking up too much space. So I started to use e-mail sites with automatic filters that can block marketing messages or unwanted spams.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_eb798293544a7975f5521142', 'ielts_group_4256df9ea5c9efcd5a534bd1', 'PART_2', 1, 'Describe a hotel that you know.', '["where this hotel is","what this hotel looks like","what facilities this hotel has","and explain whether you think this is a nice hotel to stay in."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍\n\nI''m going to talk about W Resort Koh Samui in Thailand, which belongs to the famous W hotel chain. I made a reservation online for my holiday there and it totally exceeded my expectation. \n\n描述地点\n\nThe location is rather secluded, isolated from the hustle and bustle of those popular beaches. In fact, it''s got a beautiful private beach with pale golden sands sweeping all around. It also runs a complimentary shuttle bus a couple of times a day to the central part of the island, which caters for my need.\n\n描述外观内饰\n\nThere''re over 70 private retreats perching on a gentle slope of a small hill. All the tropical villas are fairly stylish with white walls and huge glass windows from the exterior side. I booked one with ocean views and when I stepped into the property, I felt like WOW, it was absolutely out of this world. I saw the colors boldly juxtaposed on the interior wall giving a vibe of modernity. The huge inner space is equipped with everything I need from electronics to Egyptian cotton tower, even a private pool is provided in the backyard.\n\n描述设施\n\nLike all the luxury resorts, this hotel has a range of facilities for relaxation. As far as I could remember, it''s got a seaview gym, a purple tennis court and a water sports centre where you can enjoy free daily fitness activities. I’m not a sporty type, so I spent most of my time in the WooBar enjoying the stunning panoramic views of the Gulf of Thailand and listening to DJ tracks. What also impressed me was the restaurant where gourmet meals were served as well as the spa center where I had authentic Thai massage.\n\n进行总结\n\nHonestly speaking, the overall price is not really wallet-friendly, I mean I spent a fortune. But I find it a second to none hotel where you can have a get away from your routine life and enjoy the tropical oasis. Plus, the staff there are impeccable, I mean, they can always make you feel like home. In a nutshell, it won''t let you down.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_dac3a293e939a9ef5bb25741', 'ielts_group_4256df9ea5c9efcd5a534bd1', 'PART_3', 1, 'What things are important when people are choosing a hotel?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I suppose the first factor people should consider is the price. It''s a sensible decision to choose the type of hotel that suits your travel budget so that you can save some cost during the trip. Let''s say, if you are a young adult on your budget tour, a youth hostel might be a great choice, for that it provides short-term sociable lodging at a much lower price. Another key aspect which should be well thought out is the location. When you are making a reservation, you need to evaluate the security level of that area to get rid of street crimes, as well as the handiness of transport to your arranged venues. Last but not least, it''s vital to keep an eye on the amenities available to avoid unpleasant surprises. It would drive you up the wall if the hotel doesn''t have wi-fi connection or you have to share a bathroom with dwellers you haven''t met before.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9f3f3eb0255558d96815436f', 'ielts_group_4256df9ea5c9efcd5a534bd1', 'PART_3', 2, 'Why do some people not like staying in hotels?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it''s understandable that some people hold negative views towards hotels. Broadly speaking, the majority of hotels tend to be more expensive than hostels, homestay, or camping facilities, but some hotels are not all they''re cracked up to be. It is the mismatch between the cost and the true level of amenities or service that let people down. Another compelling reason is that some hotels fail to protect people''s privacy and personal belongings. You can see this with the scene that as soon as you enter the hotel lobby, you may become the subject to the hidden cameras monitored by security staff. While you are in your room taking a rest, you may be interrupted by unexpected room checks or nasty flyers coming from the slot of the door. It has also been widely reported that even upmarket hotels have hygiene scandals, which breeds resentment of the public so that they end up losing confidence in the whole industry.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b2544880b25a1e167e241f70', 'ielts_group_4256df9ea5c9efcd5a534bd1', 'PART_3', 3, 'Do you think staying in a luxury hotel is a waste of money?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I guess so. I suppose some people may live simply during the year, but enjoy living in the lap of luxury in an upmarket hotel for holidays. That said, I still reckon that it''s not a wise decision if you squander your money on an extravagant short-term holiday in a luxurious hotel, though a personal butler and all those top-notch amenities would be provided, at the end of the day, you have to go back to your normal life and pay the bill. I''d go as far as to say, a much more sensible way is to put the experience of traveling at the first place, as the most meaningful and memorable experience are always in those brand new things you have never tried before, say, an exotic dish, a chat with local people rather than sleeping on a super comfy bed in an air conditioned room after calling room service for food.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f7b4fd3b0c0e71411461275e', 'ielts_group_4256df9ea5c9efcd5a534bd1', 'PART_3', 4, 'Do you think hotel work is a good career for life?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yeah, I''d say it''s a promising career. The industry of hospitality has been thriving to its highest extents in this era, driven by the fast growing tourism industry, which means it’s very likely for you to have a bright future if you embark on your career in this sector. Possibly, you may start at the very bottom of the career ladder, for instance, working as a waiter in the dining hall, but if you are willing to embrace challenges by improving your own professional skills and problem-solving skills, then you have tons of opportunities to work your way up the corporate ladder. On top of that, the lodging industry itself can bring you a sense of fulfillment in terms of socializing with people from all walks of life and taking good care of them. You may also develop a better understanding of life and society by having a wide circle of acquaintances.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_26999a96d7fe6c4eb066cf03', 'ielts_group_4256df9ea5c9efcd5a534bd1', 'PART_3', 5, 'How does working in a big hotel compare with working in a small hotel?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"To my knowledge, working in a big hotel or a brand hotel chain can provide you with more chances to work in a team with other people from all corners of the world, which can give you a good opportunity to maximize your working capabilities and enrich your practical skills. Mind you, if you work in a relatively smaller hotel, the chances are, you may end up working with the same colleagues for years. Another difference is the career development. Apparently, there are more positions and a much clearer career ladder for staff in giant hotel corporations so that you can set yourself targets to move forward. But at the same time, the majority of small hotels tend to keep their staff working at the same position, pretty much like a dead-end job with endless run-of-mill tasks. In a nutshell, it would be more beneficial to work in bigger ones.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_bc3732a6b3402a5fa94a9be0', 'ielts_group_4256df9ea5c9efcd5a534bd1', 'PART_3', 6, 'What skills are needed to be a successful hotel manager?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In my view, lodging manager is definitely a well-paid job, but as a matter of fact, it''s rather demanding by the sense that you are required to cope with the constantly changing working context both within the fellow workers you are in charge of, as well as the diversified clients you are facing every single day. In that case, a successful hotel manager needs to have excellent problem-solving skills which are based on the ability to notice every detail and their acute sense of empathy to other people''s situations. In addition, they are masters of communicating skills so that they can lead the team smoothly and be aware of the ultimate needs and desire of clients. On top of that, they should know how to stand in other people''s shoes, which is an important trait for people who work in hospitably industry, for that fundamentally, it is all about taking good care of others.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_83965e1f8f41259da09379a2', 'ielts_group_ab5eb837824a1b14cd351de9', 'PART_1', 1, 'How many languages can you speak? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, my mother tongue is Chinese, but I can currently speak two more languages. I''m an upper-intermediate user of English and I can get by in French, as I picked up a little back in my uni. Generally speaking, I feel very proud of being multi-lingual.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e2f2932eaaeb6581088e9975', 'ielts_group_ab5eb837824a1b14cd351de9', 'PART_1', 2, 'How useful will English be to you in your future? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''d say it definitely comes in useful in my future. I''m looking forward to getting my Master''s Degree in the UK, so I do expect to have a firm grasp of English as it''s a lingua franca of the world which can help me bridge communication gap.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6738f85bda2ebd9a7516a918', 'ielts_group_ab5eb837824a1b14cd351de9', 'PART_1', 3, 'What do you remember about learning languages at school? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, off the top of my head, I can remember nothing but endless dictation and grammar exercise. Honestly speaking, the language teaching in school is completely exam-oriented, so teachers simply shut their eyes to oral English. By the end of the day， we were not confident about holding conversations with foreigners. If I could turn the clock back, I would definitely spend more time polishing up my listening and speaking skills.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a1128bab81a4d2ae0d1fb9ac', 'ielts_group_ab5eb837824a1b14cd351de9', 'PART_1', 4, 'What do you think would be the hardest language for you to learn? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I suppose Arabic would be heavy going. It''s got those curvy lines and rather strict pronunciation rules and a variety of dialects. Plus, it''s read and written from the right to the left, which is totally opposite to my mother tongue. So I think it is something that I can''t even begin.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_924ca40ff2f09ebf56b0feb4', 'ielts_group_628141a2c1d7d676a1d49399', 'PART_2', 1, 'Describe a website that you bought something from.', '["what the website is","what you bought from this website","how satisfied you were with what you bought","and explain what you liked or disliked about using this website."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍\n\nI am a regular customer of JD.com, which is basically one of the largest online shopping websites based in China. It came into being as a website selling electrical appliances and gradually evolved into a giant Internet presence, where you can purchase almost anything you want.\n\n购买的物品\n\nI''ve ordered a range of stuff from it, like fresh produce, books, clothing, pet supplies and household appliances. Recently, I ordered a microwave oven at a very reasonable price.\n\n评价购买的物品\n\nI would say that I am always content with the products, as most of them are very good value for money. This microwave oven is no exception. It was basically on sale and I got an extra 20% discount as a premier member, so it was a complete bargain. In fact, what get me most was the quick delivery. I placed the order late at night but received the parcel the next day noon. I guess this is due to the advantage that they have their own staff in logistics, so a more reliable shipping can be guaranteed.\n\n网站的优点\n\nAs I''ve mentioned, it''s a website where I can do one-stop shopping. Plus, I can always get a good deal, especially when I buy things in bulk. In fact, my favorite bit is the perfect after-sale service. If I find any products do not come up to standard, the customer service center will immediately offer me a replacement or refund for free.\n\n网站的缺点\n\nBut I do hate the part of adverts. It''s a bit creepy that you’ll find the products you just browsed appeared in the column on the front-page, luring you into another consumerism trap. Another problem is that I gradually realized that I’ve been buying things I don''t really need simply for the flash sales. What a waste !","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cbe145843c3c3bde84b839ff', 'ielts_group_628141a2c1d7d676a1d49399', 'PART_3', 1, 'What kinds of things do people in your country often buy from online shops?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Broadly speaking, people tend to purchase all kinds of daily necessities on the Internet ranging from food to clothing. but there has been a growing trend that more and more people are willing to order products with higher value like household appliances, electronic devices and even jewelry online. I suppose the underlying reason is that people have become more confident about the quality of products online and are getting used to ordering things that way. You can see this with the constantly increasing turnover of online shopping platforms.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_46d9716ed46eeca90895eb3c', 'ielts_group_628141a2c1d7d676a1d49399', 'PART_3', 2, 'Why do you think online shopping has become so popular nowadays?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I reckon the fundamental reason is that customers can have a convenient purchasing experience online without going to a real place for shopping, which is absolutely time-saving. People all over the world also depend heavily on this way of shopping during the outbreak of Covid-19 for it can limit contact to its minimum. Another possible reason is that the price of goods online is generally lower than retailer stores as there are no rents costs, and more coupons and flash sales are given to the buyers. The popularity of smart phones has also provided people with easier access to online shopping. More purchases will be made with just a simple set of swipe and touch on the screen. No wonder more and more shopping apps are launched.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e0046018bff73ee7be43f733', 'ielts_group_628141a2c1d7d676a1d49399', 'PART_3', 3, 'What are some possible disadvantages of buying things from online shops?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think the major disadvantage is that customers don''t have the ability to inspect or try on their target items physically. Almost all the online sellers have provided detailed descriptions of the products as well as comments from previous buyers though, people still find themselves buying things which don''t truly meet their expectations. Another drawback is that people have to wait for the delivery or sometimes the things on your wishlists can be back-ordered, so you can''t get the products immediately after you pay in some cases. On top of that, your parcels might be damaged or even lost during delivery, which is not rare due to the fact that couriers might load and unload cargoes in a careless way.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_107ef9a056113f8f52cc9154', 'ielts_group_628141a2c1d7d676a1d49399', 'PART_3', 4, 'Why do many people today keep buying things which they do not need?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"For a start, I reckon that people are exposed to too much advertising from all sorts of media, which is way more powerful and persuasive than we could imagine. Another thing is the fan economy. You can see this with the fact that currently more and more companies have adopted influencer marketing which relies heavily on fans. So it''s very likely for people who are fans of key opinion leaders and celebrities to purchase products which have been endorsed by them without thinking. To my knowledge，this also has something to do with psychological side of things. Some people seem to have a higher degree of security when possessing more stuff, some people tend to get cheered up from purchasing stuff when they are in depression, others squander money on things they don''t really need simply to keep up with the Jones. At the end of the day, people won''t solve their actual problems by doing so. Instead, we may lose ourselves in the vicious circle.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fb05cac21465114a172a5419', 'ielts_group_628141a2c1d7d676a1d49399', 'PART_3', 5, 'Do you believe the benefits of a consumer society outweigh the disadvantages?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t really think so, but I have to admit that consumerism has boosted economy immensely in almost all the sectors in the society and it has indeed created more job opportunities in service industry. On top of that, the thriving market has been providing consumers with tremendous amount of choice when purchasing things. That said, we shouldn''t neglect the negative impact consumer society has on us. Mass production is homogenizing products rather than encouraging creativity and originality. For example, many garment companies tend to adopt the so-called color of the year, by the end of the day, what consumers can find in shops are highly identical in both color and design. For shoppers, we are simply filling the void of life by obtaining immediate gratification from the behavior of shopping. But sadly, we are ignoring the root of the problem. We should have spent quality time with family members or close friends rather than browsing the endless online shopping websites. To make the matter worse, consumerism has made people believe that everything in life is disposable and replaceable. It''s so pathetic that we may end up undermining our connection with others in real life.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4015212e8715dd2169927f83', 'ielts_group_628141a2c1d7d676a1d49399', 'PART_3', 6, 'How possible is it to avoid the culture of consumerism?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I suppose it largely depends on your attitude and way of life. For people who can''t distinguish from wants and needs or those who are keen on keeping up with the trend, I would say that''s impossible. But for people who are willing to reflect on their behaviors and are eager to seek for the essence of life, it''s very likely that they can throw off the shackles of consumerism. This can be seen from believers of minimalism, who are a group of people leading a life in which they keep practising the idea of preserving the most valuable things and rejecting unwanted things. What they focus is how to simplify their life and the relation between people and materialistic goods. In a nutshell, it''s not easy to boat against the current of consumerism, but if we don''t, we may possibly be enslaved by it.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_897b15d83fca86254e62b117', 'ielts_group_c79542b3407bbb05387ceb71', 'PART_1', 1, 'Did you learn to swim when you were a child? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I think it was during a summer vacation when I was in primary school. My dad took me to the local swimming pool and taught me how to float and then do the breaststroke. Later my parents enrolled me in the swimming course because they thought swimming was a great full body workout and a survival skill.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3930b7f0385177444de078c9', 'ielts_group_c79542b3407bbb05387ceb71', 'PART_1', 2, 'How often do you go swimming now? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In summer I go swimming on a weekly basis because it''s really a good way to exercise without sweating, but in winter I rarely go because I really dislike the chill you feel when you just get out of the water. And I think it''s really a hassle to change in and out of layers of clothes if you go swimming in winter.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0066ef522da23df1247d5b5b', 'ielts_group_c79542b3407bbb05387ceb71', 'PART_1', 3, 'What places are there for swimming where you live? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There''re indoor and outdoor swimming pools, because we''ve got balmy weather most of the year. It''s a coastal city, but people don''t usually go swimming in the sea for fear of the pollution. For families with children, there''re also water parks where children can enjoy a splash.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5bca7772c746613ea338090b', 'ielts_group_c79542b3407bbb05387ceb71', 'PART_1', 4, 'Do you think it would be more enjoyable to go swimming outdoors or at an indoor pool? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it largely depends on the weather. Outdoor pools are great when it''s warm and sunny, but if you don''t like to get sunburnt, you may want some shade. The best thing about an indoor pool is that you can always enjoy a dip there rain or shine, though the air inside may not be as fresh.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f2de9fd04604686e9a14fd3d', 'ielts_group_4f3e200c5df43d4b36070841', 'PART_2', 1, 'Describe a famous business person that you know about.', '["who this person is","what kind of business this person is involved in","what you know about this business person","and explain what you think of this business person."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍\n\nI''d like to talk about Sheryl Sandberg, the chief operating officer of the tech giant Facebook. I think she is probably the most high-profile female entrepreneur in the business world today.\n\n选择要点\n\nFirst, I think I''ll tell you what I know about her career path. After graduating from Harvard Business School, she first worked for the government, the US Treasury if I remember correctly. Later she joined Google where she established her reputation as one of the top executives in the country.\n\n比较对比\n\nWhen she first arrived at Facebook, she was viewed as a much-needed “adult in the room”, as opposed to the young founder Mark Zuckerberg, who was running the company as a frat house, not knowing how to build a sustainable, profitable business around this massively popular social networking site.\n\nOf course Sheryl was not the first outside executive Facebook tried to hire, but what set her apart was her incredible interpersonal skills, which allowed her to remain likable while wielding enormous power. This was also her unique approach to female leadership which made her an iconic figure for women who were able “have it all”, and this was further explored in her best-selling book Lean In.\n\n使用让步\n\nUnfortunately, in the wake of Facebook''s recent scandal regarding user privacy and abuses of the platform, Sheryl''s public image has shifted dramatically. Although she is still a successful billionaire many people look up to, her vision of women being able to “have it all” has utterly shattered.\n\n作出推测\n\nIt''s sad to see an inspirational story turn a cautionary tale, but again you have to wonder—who''s to blame? Would anyone, especially, would any male executive have done it differently in Sheryl''s shoes?","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_02d28be78de44b1b13d82b1c', 'ielts_group_4f3e200c5df43d4b36070841', 'PART_3', 1, 'What kinds of people are most famous in your country today?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think it''s really no different from any other country. People gain fame by being extraordinary, either extraordinarily good or bad. But generally, most celebrities come from the fields of sports and entertainment, which tend to attract the most public attention and media coverage. However, there seems to be something unique to Asian countries, which is this obsession with pop idols, especially those young, androgynous pretty boys. Some of them have such an enormous following that they can basically start a revolution if they want. Of course in this day and age, people with humble beginnings can also become megastars, thanks to social media. For example, one of the top Chinese influencers today is a young man who used to be a struggling salesperson. He made his name by live streaming applying different kinds of lipsticks on himself and now he sells thousands of lipsticks in minutes!","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b016c06202b81ec66013eaa2', 'ielts_group_4f3e200c5df43d4b36070841', 'PART_3', 2, 'Why are there so many stories about famous people in the news?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, celebrity and fame by definition is what attracts public attention. It''s only natural for the press to cater to the needs and desires of its audience. Now if you want to get to the bottom of this obsession, I guess the answer lies in our primate legacy. As a social animal, we have a natural instinct for social hierarchies and patterns of social affiliation. For one thing, we see celebrities as high-status individuals and we react to their opinions and behaviors. For another, celebrity gossip gives us essential clues about their social affiliation, like who is befriending whom or feuding with whom—useless information really, but it''s just trivial for our modern world. For our ancestors in the jungle, it could be a matter of life and death.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_44765cbe5c7cf3c2ff228640', 'ielts_group_4f3e200c5df43d4b36070841', 'PART_3', 3, 'Do you agree or disagree that many young people today want to be famous?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I totally agree. Social media has made becoming famous seem so easy and I bet a lot of young people today are dreaming of becoming a celebrity overnight. Obviously there are a lot of benefits that fame can bring. Money is the big one. The glamour and wealth that is always associated with fame certainly looks very appealing to ordinary people, especially when they find themselves bending over backwards only to be able to make ends meet. Those rags-to-riches stories are always the media''s favorite. Now another reason is the crave for attention. We all want to feel special, to be recognized, and to leave our mark on the world. However, we do need to be aware that people whose primary motivation in life is fame are bound to be disappointed because they will always want more.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_24a44e25b6e2991e4bb388ba', 'ielts_group_4f3e200c5df43d4b36070841', 'PART_3', 4, 'Do you think it is easy for famous people to earn a lot of money?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''d say so. Fame and fortune seem to go hand in hand. I think the major contributor is advertising – the more famous you are, the bigger market you can reach, and the more companies are willing to pay you to endorse their products, or work with you to raise their profile. However, fame may also bring misfortune if you don''t handle it well. The constant public scrutiny means any scandal or controversy will probably lead to cancelled contracts or job loss, or even the end of your career. On the other hand, if you are famous for the wrong reasons, like becoming famous for making yourself everyone''s laughing stock, I''m not sure if you can as easily cash in on your fame.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_46c1c56959230ab1e7dd8267', 'ielts_group_4f3e200c5df43d4b36070841', 'PART_3', 5, 'Why might famous people enjoy having fans?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think it''s human nature to seek recognition. Having fans makes you feel good about yourself. This is a kind of acceptance and approval that we social animals need. For people in the show business, their popularity and advertising value is almost always measured by the number of fans they have. Of course the more the better. I''ve heard that it''s common practice for some celebrities to buy so called “zombie fans” – fake followers on their social media, in order to appear more popular. For ordinary people though, I think social media has given us this opportunity to experience the illusion of being a star in our own little world, surrounded by fans sending their love with every “like” they click on our post.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8d405fc47f656a6d1503968c', 'ielts_group_4f3e200c5df43d4b36070841', 'PART_3', 6, 'In what ways could famous people use their influence to do good things in the world?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, there''re numerous ways. For starters, celebrities can donate money to charitable causes, which is probably the easiest way for them to give back. They can also use their influence to raise public awareness of social, environmental issues in the world. For example, Yao Ming is actively involved in the campaign against wildlife poaching and Emma Waston has repeatedly spoken out about women''s rights and gender equality. Their fame has certainly brought more public attention to and more discussions about those pressing issues. Another way for celebrities to use their influence for good is to be a role model for young people, which is probably the most challenging as the media is always looking for signs of any moral failings in them.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2edc773fa22e9c2bf72bfaaf', 'ielts_group_0289418712a43b1f2f6e8ced', 'PART_1', 1, 'How often do you wear jewellery? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I wear a jade bracelet every day because it''s supposed to bring me good luck. Every now and then I throw on a necklace if I feel my outfit is too boring. I think jewelry is a small accessory that makes you feel a little bit special, but I don''t like to go crazy on it.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_463075acadcef269d720a9ac', 'ielts_group_0289418712a43b1f2f6e8ced', 'PART_1', 2, 'What type of jewellery do you like best? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well it really depends on the occasion. In office I just wear small gemstone studs that look elegant; for parties I go for heavier jewellery such as gold or diamond necklaces. But my favorite jewellery items are watches. They are not really functional now that we have smartphones, but I think a good watch does make you look more professional and polished.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5a401ee4a4785df4912f45ba', 'ielts_group_0289418712a43b1f2f6e8ced', 'PART_1', 3, 'When do people like to give jewellery in your country [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Birthdays, anniversaries, what else? I guess any major milestones in life can be celebrated with some jewellery. I think the question is really more about whom than when. Jewellery is a personal and intimate gift, so it''s not considered appropriate to give to someone who''s not a close friend.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fc380b1cb32706c1da20b001', 'ielts_group_0289418712a43b1f2f6e8ced', 'PART_1', 4, 'Have you ever given jewellery to someone as a gift? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes. For my sister''s birthday this year, I bought a red string for her to wear on the wrist. According to Chinese folk belief, it''s a way to ward off evil spirits in her zodiac year. It''s superstition, but better safe than sorry!","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0ab8848d0f66aa5a4728d29f', 'ielts_group_a1a56ff2c48862b2ff449beb', 'PART_2', 1, 'Describe an interesting TV programme you watched about a science topic.', '["what science topic this TV programme was about","when you saw this TV programme","what you learnt from this TV programme about a science topic","and explain why you found this TV programme interesting."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇引入\n\nI''d like to talk about a science show called Mythbusters, which is definitely one of the most-watched science shows ever made. I used to watch it almost weekly on the Chinese Discovery Channel.\n\n节目简介\n\nEach MythBusters episode typically features two or more popular beliefs, internet rumors, or urban myths. During the show, each myth will be tested with a series of experiments, and eventually rated as “busted”, \"plausible\", or \"confirmed.\"\n\n科学背景\n\nSo the episode I remember most clearly was about a myth surrounding opera singers — whether they could break a glass with their singing. Theoretically speaking, as we know, you can make a glass resonate if you sing at its natural frequency. And if your voice is powerful enough, the glass will eventually break. But I had never seen that happen in real time and was really eager to see how this experiment would play out.\n\n节目过程\n\nIn the show, the mythbusters first tested this myth with a loudspeaker. It seemed quite easy. A straw was put in the glass to help the viewers see more clearly. As the singer started to sing into the microphone at the pitch that was the glass''natural frequency, the straw started to jump frantically in the glass. Within seconds, the glass shattered.\n\nThen they moved on to test if human voice alone can do the trick. After a few failed attempts by some opera singers, eventually, a heavy metal singer made it. It was really extraordinary, seeing the tough glass just give way right in front of his face! And this was made all the more spectacular by the footage captured on a high-speed camera, showing the small glass fragments flying off in all directions.\n\n评论节目\n\nI enjoy watching the show because it''s both educational and entertaining. Most importantly, it really drives home the idea of scientific method, which is never to take anything for granted, instead just let the experiment do the talking. In all, it''s a great show for all ages.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_47d37042a9c487ba10ecc09c', 'ielts_group_a1a56ff2c48862b2ff449beb', 'PART_3', 1, 'How interested are most people in your country in science?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it''s hard to say. I think it depends on the age and your education. Children generally are pretty keen on science because of their curiosity. They are always actively looking to explore and discover new things. In fact, many parents take an interest in science news and projects because of their children. If you live in a big city, you’ll also be more likely to develop a passion for science, because you''ll have more access to science museums, planetariums, or science conferences and events. Science seems more approachable, and there may be a stronger culture of learning in the community. However, people living in the countryside or small towns where science doesn’t seem to take center stage in everyday lives may have a negative or indifferent attitude towards science, finding it too abstract, impractical or intimidating because of all the jargons.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e9df47aab3c629281baaa789', 'ielts_group_a1a56ff2c48862b2ff449beb', 'PART_3', 2, 'Why do you think children today might be better at science than their parents?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, as science and technology are ever advancing, it certainly seems that children today will easily surpass their parents in their understanding of science. For example, there''re books called Quantum Physics for Babies, which the founder of Facebook Mark Zuckerberg has famously bought for his baby daughter! The internet has definitely played a big part, too. There''re already stories about some kids, self-taught using YouTube videos or other online resources, winning certain science awards or patenting brilliant inventions. On the other hand, some educators are worried that, because of excessive screen time and lack of outdoor experiences, children today may be missing out on something compared to previous generations, when children spent more time exploring nature and gained from the kind of learning that was inquiry-based rather than book or computer-based.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0386e5669a5a5328cf2e59be', 'ielts_group_a1a56ff2c48862b2ff449beb', 'PART_3', 3, 'How do you suggest the public can learn more about scientific developments?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, there''re numerous ways. First off, quality science TV could be a good source of information for the general public. With the visual clues and special effects, those abstract science concepts can be made more accessible. Of course, if you want to explore deeper into certain topic, you can always go to the library or the science museums, attend lectures and so on. Obviously for many people today, their go-to place for knowledge and information is the internet, but we do need to be careful, as the internet is rife with misinformation. Take everything you read online with a grain of salt I''d say. Check the sources and avoid clickbait. However, I do believe the online community is invaluable for the education of science and more importantly, the spread of knowledge.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_720f78edfa6b33181acdc2df', 'ielts_group_a1a56ff2c48862b2ff449beb', 'PART_3', 4, 'What do you think are the most important scientific discoveries in the last 100 years?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"If you asked me about the most important technological advances, I''d totally say the information technology. But scientific discoveries…, let me think. Penicillin, antibiotics – they certainly top the list. Modern surgery would never have existed had it not been for this miraculous discovery. Without it, the mortality rate of surgeries could have still been as high as 50% and humans would have been totally at the mercy of their fate. Not to mention that, without the use of antibiotics to prevent infection, all the modern medical feats, such as organ transplant would never have been possible. Unfortunately, that''s not the end of the story. Today we''re facing this grim threat of antibiotic resistance caused by abuse of antibiotics. It does keep me up at night thinking about the severity of this issue.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d8d8c5ac34b709df83af05af', 'ielts_group_a1a56ff2c48862b2ff449beb', 'PART_3', 5, 'Do you agree or disagree that there are no more major scientific discoveries left to make?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well I disagree. Although it does seem that the past few decades have seen so many incredible breakthroughs in science, such as the complete sequencing and mapping of the human genome, the big bang theory and artificial intelligence, in my opinion, the assumption that there is nothing further to discover is extremely unlikely. To quote American Scientist Neil Degrasse Tyson, often we just know enough about a subject to think we''re right, but not enough to know that we''re wrong. For example, quantum mechanics wouldn''t have developed if we had believed Newton had found the ultimate truth about physics. Another example is our human mind, as far as I know, there''re still so many questions unanswered, like the nature of consciousness. So I tend to believe science is an endless frontier and we will continue to make new discoveries that may fundamentally change our perception of the world.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0d069cc30b9f0a905bfbb410', 'ielts_group_a1a56ff2c48862b2ff449beb', 'PART_3', 6, 'Who should pay for scientific research – governments or private companies?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think certainly a mix of both, but government grants and non-profit foundations should play a major role. Firstly, some scientific research, like fundamental physics is not likely to yield any profit in the short term, so the private sector may lack the incentive to invest. And when the public interest is at stake, such as the research of certain vaccine, it will be dangerous to just give the market free rein to decide what to do. Finally, there''s the objectivity issue. The result is likely to be biased if the backer has a stake in the study''s outcome. For example, drug research sponsored by the pharmaceutical industry is more likely to end up favoring the drug under consideration. Therefore, when special interest groups are involved, it is vital to make sure safeguards are in place to detect those biases.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c19c65f219011b382da56772', 'ielts_group_fbe3db3c0008a1681cdd49df', 'PART_1', 1, 'Who do you spend most time studying/working with?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I’ve joined a study group with two of my classmates who share similar academic goals with me. We’re quite intimate and we almost have the same learning pace. I mean, when I study with them, I won’t lose focus easily, and I find myself more productive than studying alone.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5df24a7402549e135084d614', 'ielts_group_fbe3db3c0008a1681cdd49df', 'PART_1', 2, 'What kinds of things do you study / work on with other people?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Generally, we have a study session every weekend to go over all the key points we’ve learnt. We normally kick off by asking questions or using flashcards to test each other. Then we have a feedback loop by commenting on each other’s answers. If someone is quite good at a certain subject, we will ask him or her to reexplain the key concepts to consolidate knowledge for everyone.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_03b7db54b5bfeba84bb460ba', 'ielts_group_fbe3db3c0008a1681cdd49df', 'PART_1', 3, 'Are there times when you study/work better by yourself?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, yeah, let me see. If there are more than three people coming to the study group, it’s possible that the study session may end up becoming a gossip or hanging-out session. In that case, I would choose to study alone in my dormitory or a coffee shop to get rid of all the distracting stuff like aimless chatting. Also, if I am writing a paper or doing something which requires higher amount of independent thinking, I would work on my own.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_52445bbba78e4dfeef554d3a', 'ielts_group_fbe3db3c0008a1681cdd49df', 'PART_1', 4, 'Is it important to like the people you study/work with?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think it’s essential. If you can get along with each other, things can run more smoothly. For me, the key to enhancing studying efficiency is to find someone who is better than me in terms of every aspect of study. I mean, if that person is more self-disciplined or has a more diverse perspective towards things you are learning, you could be shaped in a positive way. That being said, it’s not easy to find a perfect study mate, so you’d better start from someone you are familiar with or simply depend on yourself.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b20e09724c5f0bc6129d9741', 'ielts_group_b984cf767b0f92d660ca99b4', 'PART_2', 1, 'Describe a tourist attraction you enjoyed visiting.', '["what this tourist attraction is","when and why you visited it","what you did there and explain why you enjoyed visiting this tourist attraction."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍\n\nWell, the tourist spot that stuck in my mind is the Imperial War Museum in London, which I visited roughly five years ago.\n\n交代背景信息\n\nAt that time, I was in a summer camp in London, so I had plenty of time at my disposal to walk through the city. As a museum buff, I had made a plan to visit museums of all kinds and IWM is on the top of my list, basically because it’s one of the world’s leading museums of war. On top of that, I had always been curious about modern wars, I mean, it’s indeed not a happy subject in a time of peace, but I couldn’t help wondering how ordinary people got caught up in over a century of conflicts and how wars reshaped our life in a rather cruel and profound way.\n\n描述景点的大致情况\n\nSo I paid a visit and had three well-spent hours there. I firmly believe that you would no doubt get stunned by the massive 15-inch twin guns in front of the museum immediately when you arrive. As I walked into the hall, I couldn’t take my eyes off those assorted weaponry, fight jets, huge tanks, and even some most lethal bombs. They made me feel like being in a war.\n\n描述印象最深的部分\n\nThe exhibition of mock-up trenches in WWI was something that truly astonished me, I mean, there were both lighting and sound effects going off above my head while I cautiously made my way through the dugout, and all of these gave me an authentic feeling of terror of being on the front line. I mean, I had watched those scenes in movies about wars, but I couldn’t have imagined how brutal it could be until I was there.\n\n描述感受和评价\n\nI would say it was a real mind-blowing museum with so much information to take in. It’s got compelling exhibits to take you back, and it also highlights and showcases important figures who might not even be mentioned in history books. Besides, all those deeply sad scenarios are brought to life by the visual stimuli, just like a unique and powerful reminder of the devastating consequences of wars and the constant yearning for peace. In a nutshell, it’s a spot you shouldn’t miss.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0ed315796220d94e28187839', 'ielts_group_b984cf767b0f92d660ca99b4', 'PART_3', 1, 'What are the most popular tourist attractions in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I tend to think that the Great Wall and Forbidden City in Beijing and Potala Palace in Tibet are still the top-rated historic spots in China, as they are the embodiments of all the mystery and exoticism of oriental culture for people from home and abroad. If you want to have a city break, walking along the Bund in Shanghai or throwing a visit to Guangzhou can be the first option for you. That being said, these days, there’s been a tendency that more and more tourists desire to explore off the beaten path, by that I mean, some lesser-known tourist destinations are getting all the rage, say, the terrace fields in the southern part of China, sacred mountains with Buddhist temples as well as old towns and vibrant cities of all kinds. There’s so much to see as China is such a broad country with a profound history and a dynamic present.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_bf72c13a759e5ee4a1dfaed5', 'ielts_group_b984cf767b0f92d660ca99b4', 'PART_3', 2, 'How do the types of tourist attractions that younger people like to visit compare with those that older people like to visit?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, fundamentally speaking, the difference of preference for tourist attracts between different age groups lies in the different motivations to travel. For the younger generation, they mainly travel to broaden their life experience by doing things like meeting other people, gaining knowledge of other cultures, studying or even shaping their identity as a traveler. Thus, they tend to travel to places which can meet those purposes, like joining a summer camp which guide them through all those top-notch universities in the UK or the States. They also like to visit famous spots in cosmopolitan metropolises, like London, New York, Paris, and Tokyo, simply because those cities have an appealing colorful atmosphere in which they can experience or express themselves freely. By contrast, older people have been there, in other words, what they aim to seek from traveling is generally not exploring the world with fresh eyes. Instead, they tend to arrange getaways to beach resorts and stay in star-rated hotels, or go on a luxury cruise with quality service. People with children also travel to places with natural beauty to bring their children close to the wild.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b7bad0bc2d2695ad4f337bfd', 'ielts_group_b984cf767b0f92d660ca99b4', 'PART_3', 3, 'Do you agree that some tourist attractions (e.g. national museums/galleries) should be free to visit?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I totally agree with this point. In my view, places like national museums or art galleries shouldn’t charge general admission on the grounds that they are not merely tourist attractions that aim at generating revenue, they should be free resources to educate both local citizens and visitors from abroad. The public also need museums to instill historic values or aesthetic tastes in them. On top of this, children and students need these places to compensate for family and school education, as they can constantly revisit a piece of artwork to deepen their understanding. I have read that one of the reasons why many people are in love with London is that most of the world-leading museums like the British Museum, National Gallery, Tate Modern, to name but a few, won’t charge a penny. Having said that, free entry requires a higher amount of funding from the government as well as more donations from philanthropists to ensure daily maintenance, management cost, and salary for staff. That’s why some of the museums, say, the Metropolitan Museum charges for admission to reduce the deficit.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_563be30a5ed243b217482e65', 'ielts_group_b984cf767b0f92d660ca99b4', 'PART_3', 4, 'Why is tourism important to a country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, for a start, tourism has played a crucial part in boosting domestic economy. For local people, a booming tourism industry can create job opportunities in various sectors, like accommodation, catering, entertainment, transport, and so on. Take Thailand as an example, a large population in this country are making a living by doing business on all kinds of scales with visitors across the world. Apart from the economic side of things, tourism can urge policymakers to attach importance to protecting natural tourist attractions if they want more visitors. This measure is beneficial for sustainable development in the long run and will ultimately form a virtuous circle for the overall development of a country.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b154327020667f2ca7e61a94', 'ielts_group_b984cf767b0f92d660ca99b4', 'PART_3', 5, 'What are the benefits to individuals of visiting another country as tourists?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, in my view, traveling overseas can bring us plenty of long-lasting personal benefits. For a start, it allows you to leave your old routine and drop into a new environment with new sights and sounds, which will force you to navigate unfamiliar places, read foreign languages, try new things and make quick decisions. All of these require mental processing, which will definitely sharpen your mind. On top of that, after an international trip, you’ll possibly come back with a brand new perspective towards your own life, as you are exposed to people from different cultures and social classes who have a completely different way of life from you. If you travel to a relatively undeveloped country, chances are you may feel more blessed and content after you return. Lastly, stepping away from home for a long while to gain exotic experience can break up the monotony of life. We need this to switch our pace of life, and this could enhance working efficiency after we return.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ff75d707db6d2c4a1431eb00', 'ielts_group_b984cf767b0f92d660ca99b4', 'PART_3', 6, 'How necessary is it for tourists to learn the language of the country they’re visiting?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well，it seems that learning a local language for travelling abroad is no longer that necessary in our hyper-connected world, as we can simply depend on technology such as google translate to overcome language barriers. But the truth is that connectivity could be unreliable, and your phone may get out of juice. So the way I see it is that it’s still needed to know a few commonly-used phrases in the local language before you hit the road, especially if you aim to visit some countries where English doesn’t really work, as it will make things a lot easier when you need help in a strange place. Another reason for this is that locals do appreciate and respect travelers who have taken the time to learn about their language, culture, and customs, even English is officially spoken there. Chances are, the more vocabulary you know, the easier you will feel to bridge the gap of communication, which will for sure enhance your traveling experience and bring you more possibilities on the road.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_76b06ddfb6cef5e074dbd68f', 'ielts_group_207db5273c1911f79750d56e', 'PART_1', 1, 'Do you have a favourite flower or plant?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think my favorite flower goes to daffodils. They come in bold, vivid color of yellow, and they are first bloomers in springs, bringing us hope. I still remember David Hockney painted them in his picture to boost people’s spirits during coronavirus with the touching title “Do remember they can’t cancel the spring”.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_06015896da87ce6d43c13a8a', 'ielts_group_207db5273c1911f79750d56e', 'PART_1', 2, 'What kinds of flowers and plants grow near where you live?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I live in an apartment in an urban area, so the vegetations I can find in my community are mainly decorative. There are shrubs like roses coming in various colors and herb-like grasses alongside the paths. People also grow large-sized plants like sycamore trees which provide handsome shade in scorching summer.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8c9bd3813635732bb3b0da80', 'ielts_group_207db5273c1911f79750d56e', 'PART_1', 3, 'Is it important to you to have flowers and plants in your home?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I would say it’s essential for me, as I find the presence of greenery and blossoms indoors quite revitalizing and they could be good home decor. Apart from being visually pleasing, I find them beneficial for both physical and mental well-being. I mean, they can improve air quality in the inner space and encourage you to live in the present moment to appreciate the colors and fragrances in a peaceful mood.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a4614b294741c58a0ae6a73c', 'ielts_group_207db5273c1911f79750d56e', 'PART_1', 4, 'Have you ever bought flowers for someone else?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I don’t buy flowers that often, but I once ordered a bunch of yellow roses to a close pal of mine to celebrate her birthday on a website called Next Flowers Home. I could choose the occasions, types, and features I want within my budget and the delivery was speedy. My friend was quite content with what I picked for her, which also made me happy.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_06ec3ccad01f39822394ee6b', 'ielts_group_8490468e5b80d07f5e54a94b', 'PART_2', 1, 'Describe a review you read about a product or service.', '["where you read the review","what the product or service was","what information the review gave about the product or service","and explain what you did as a result of reading this review."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍\n\nWell, as a music fanatic, I’ve always been keeping up with the newly-launched speakers or earphones in the market.\n\n交代背景信息\n\nLast year, I was thinking about updating my old speaker, a Marshall Kilburn, to a more portable one to carry it out for picnics. At that time, I was still on the fence about whether I should pick one wireless speaker from Bang & Olufsen, a celebrated Danish brand in the hi-fi industry. The thing which made me hesitate was the price, as it was way beyond my budget.\n\n描述评论的内容\n\nSo I kept browsing the webpages providing information related to portable speakers to help me make a wise purchase decision. Luckily, I found one review on What Hi-fi that gave me a round-up of the best B&O speakers in 2020. The article has a comprehensive list of all the speakers they’ve tested in budget, portability, and design. They’ve also listed pros and cons of the product to help me avoid a dud. Images and videos are also presented to showcase the differences in details.\n\n描述印象最深的部分\n\nWith the help of it, I soon found my ideal model, which was Beosound A1, and according to the review, it has been regraded as the lightest and most refined little speaker with an affordable price. I aspired to buy it for its expansive sound, weighty bass, and stunningly clean design. According to the review, the battery can go up to over 20 hours which perfectly meets my need to listen to music with first-class audible quality on the move without constantly charging it.\n\n描述感受和评价\n\nAfter I read this review, I made a quick order from its official online shop. It didn’t let me down when I unboxed it, though it almost set me back the price of a smartphone.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_11c880adeba934057d1c0089', 'ielts_group_8490468e5b80d07f5e54a94b', 'PART_3', 1, 'What kinds of things do people write online reviews about in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think people in China write reviews on a wide variety of things, either tangible or intangible. The most common ones are about products they purchased like digital devices, home appliances, cosmetics, food, and so on. These days reviews and testimonials on sneakers are all the rage in China, as there are a growing number of fans who are avid collectors of sneakers. Ratings on hotels, restaurants, gyms, and many other facilities which aim at providing service are also frequently checked by users. For example, in China, apps similar to Tripadvisor have won great popularity among the public. Additionally, reviews on music, movies, books, and video games can be found on websites specially made for certain groups of fans. By way of example, douban.com is like a combination of IMDB and Goodreads. Users can read comments on books, movies, or music written by professional or amateur critics and communicate with others in an online-based community.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ff56677f10c2165589e03fad', 'ielts_group_8490468e5b80d07f5e54a94b', 'PART_3', 2, 'Why do some people write online reviews?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it seems to me that the most common reason people leave customer reviews online is that they want to help others make wise purchasing decisions. This altruistic motivation can help potential customers save time and money. Another possibility is that people want to express their gratitude for an excellent product or service. Or they want to help companies make improvement on their products or service the other way round. That’s why customers sometimes write negative reviews to point out problems and offer suggestions for an upgrade, which could be beneficial for companies in the long run, as no product or service is flawless. An underlying psychological reason might be that people leave online reviews to celebrate things they are keen on, like gadgets, cosmetics, works of art, and so on. Voicing their own opinions on their favorite things can strengthen a sense of belonging and make them feel like being part of a group.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_21e5c8c88d302577121ec9a3', 'ielts_group_8490468e5b80d07f5e54a94b', 'PART_3', 3, 'Do you think that online reviews are good for both shoppers and companies?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"That’s for sure. As I’ve mentioned, online reviews and testimonials can get customers informed with insightful facts of products or service, including quality, user experience, company’s reliability, and an indication of what’s the best and worst could happen. These can help them make wiser purchasing decisions, especially for first buyers. I have read that customers read an average of seven reviews before they trust a business. For companies, positive reviews left by customers can build up their credibility to gain new buyers by word of mouth at zero cost. That being said, negative reviews can have a detrimental effect on companies as they turn away potential shoppers, especially in service sectors like hotels, restaurants, and hospitals. Nevertheless, negative reviews offer a perfect opportunity to turn the table as they present what should be refined in products or services in great detail. But I have to say fake reviews or spam really trash a solid reputation, so customers should take a critical look at reviews online.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9cc8bb8381f3c3aa558aa4df', 'ielts_group_8490468e5b80d07f5e54a94b', 'PART_3', 4, 'What do you think it might be like to work in a customer service job?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, as far as I know, if you work as a customer service representative, you are like a mediator between customers and the companies. They ought to support customers by providing helpful information, giving answers to their questions, and responding to complaints. They are always at the front line. In the past, they mainly fulfill their duties by answering phone calls, but now they also do these on the Internet. I don’t think this job has a relatively high degree requirement, but it doesn’t necessarily mean that it’s a piece of cake. I mean, you should have good communicating skills to help you deal with customers from all walks of life or even different cultural backgrounds. It takes tons of patience and calm as unhappy customers tend to lose their temper directly. So you also need to train yourself to be mentally strong so that you can dissolve negative emotions quickly and won’t feel bothered in your own life.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b4e6dcfcb452b3ffd6ad3c8c', 'ielts_group_8490468e5b80d07f5e54a94b', 'PART_3', 5, 'Do you agree that customers are more likely to complain nowadays?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I would say so. When customers are not satisfied with the quality of products or services they buy or any stage in the purchasing process, they are likely to complain. These days, the internet has brought everything to our fingertips, and that’s why customers tend to be more powerful than before. I mean, they can make complaints on products or services directly on their screens through plenty of channels, like customer service based on specific online shopping websites or their social media accounts, which takes a lot less courage or energy compared with the past. On top of this, customers these days have a better awareness of what they are entitled to do after purchasing. There are articles or videos online teaching them how to make complaints effectively.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f98e359c67cb4e60da5f72d0', 'ielts_group_8490468e5b80d07f5e54a94b', 'PART_3', 6, 'How important is it for companies to take all customer complaints seriously?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It’s pretty essential. I firmly believe that customer complaints can provide a great source of learning for companies to enhance their products or services in different aspects like quality, processes, or customer service. If companies keep on resolving issues, they can possibly take the second chance to prove themselves and save their market reputation or even turn unhappy shoppers into loyal brand ambassadors. Suppose a company simply turns away from their customers’ complaints and lets everything go “as is”. In that case, it will end up losing more as customers are very likely to post their bad experience online or directly tell people around them, which will be absolutely fatal to a company. That being said, companies shouldn’t think too much about those complaints which are invalid, like those comments made out of malice or be against their core belief in products design or services.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_37413a3e2c3d01a1f94fb18d', 'ielts_group_7feb5a01b864188661c471fb', 'PART_1', 1, 'Is summer your favourite time of year?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I wouldn’t say it’s my favourite. I mean, in summer, the weather is always unbearably hot and you always have to find ways to beat the heat. That said, I still kind of like summer as there’s so much to do during the season. Most importantly, I was born in summer, so that’s why I always have a special liking for summer.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0a10713b3740fa8d9f20d09d', 'ielts_group_7feb5a01b864188661c471fb', 'PART_1', 2, 'What do you do in summer when the weather’s very hot?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, when it gets really terribly hot in summer, I tend to stay in and chill out with movies or video games, of course with the room well air conditioned. I also like to go to the pool in our community to cool off, though it always gets packed out.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_03999e6d32e99923155e7a8f', 'ielts_group_7feb5a01b864188661c471fb', 'PART_1', 3, 'Do you go on holiday every summer?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I used to travel in the summertime when I was a student. My parents and I would go to the beach or to some other places in the south-west China, like Guiyang, to get away from the summer heat. But these days, since I have to work in summer, we rarely have the opportunity to do that, which is kind of a shame.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_156612a30d630bdea6772eb3', 'ielts_group_7feb5a01b864188661c471fb', 'PART_1', 4, 'Did you enjoy the summer holidays when you were at school?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, absolutely! I would say summer holidays are my all-time favorite part of my school life. I could have lazy mornings with no alarms. And I could totally lose myself in what I enjoyed doing without thinking about my study. And for me, summer holidays also meant catch-ups with friends at each other’s houses, sharing updates, which was really fun. More than that, every once in a while, my parents would drive us to the beach to have fun and unwind. So, yea, I loved the summer holidays when I was at school and I always see them as the time of my life.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fefaf3fa89cfc61bddffd389', 'ielts_group_151e897b2777e298677d7518', 'PART_2', 1, 'Describe a luxury item you would like to own in the future.', '["what item you would like to own","what this item looks like","why you would like to own this item","and explain whether you think you will ever own this item."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"想要拥有的物品\n\nOK, I’m going to talk about a luxury item that I would like to own in the future, which is the newly released MacBook Pro with the Apple M1 chip.\n\n对物品进行描述\n\nIt has a gorgeous look and is beautifully designed with a large screen, featuring a retina display, which is amazing because everything displayed on it is incredibly sharp. It’s made of aluminum, which feels really good and the texture also perfectly matches the color of space grey. It’s thin and light, which only weighs about one pound, I guess. It also has an all-new design with an optimized keyboard, a larger trackpad as well as some other wonderful features.\n\n想拥有这件物品的理由\n\nWhy I would like to own this item? Well, I think it’s mainly because my own laptop is kind of out-of-date, and it would crash from time to time, which really drives me crazy, so I desperately need a new one and the new MacBook Pro is well known for the excellent operating system and its stability. Also, compared with my laptop, this amazing device has an incredibly long battery life of more than 20 hours, which means I wouldn’t have to take the charger with me all the time and always worry about the battery life.\n\n是否认为自己将来能够拥有这件物品\n\nHowever, this technological marvel doesn’t come cheap. I’ve checked the price and it costs almost 10,000 RMB, which is obviously beyond my budget for now as I’m just a student. That said, despite the high price, it’s not totally unobtainable. I mean, after saving money for a year or so, I guess I’ll be able to afford it.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_592912fb49a210b76d85a0ba', 'ielts_group_151e897b2777e298677d7518', 'PART_3', 1, 'Which expensive items would many young people (in your country) like to buy?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I would say most young people in my country are drawn to tech items, especially those made by Apple, which are highly expensive. For example, the newly released iPhone12 Pro costs over 9,000 RMB. But that said, their products are really aesthetically pleasing with a beautiful and simple design, so they are still hugely popular among millennials. Also, young people in China would like to buy luxury brands, such as Rolex, Audi, Gucci and so on, which are famous for their good quality and durability.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fa906fc6e41d78083b34a8ec', 'ielts_group_151e897b2777e298677d7518', 'PART_3', 2, 'How do the expensive items that younger people want to buy differ from those that older people want to buy?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, the expensive items that younger people want to buy are often fancy and fashionable and can show their identity or individuality, such as famous brand bags, high-end watches and fabulous cars. The older people, on the other hand, are often more health-conscious, so the expensive things that they want to buy are usually health-related, such as tonics, which are often high-priced.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1d8db7ceb0b38385c0a7c405', 'ielts_group_151e897b2777e298677d7518', 'PART_3', 3, 'Do you think that people are more likely to buy expensive items for their friends or for themselves?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I guess it depends. I mean, for firm friends, people value them so they tend to be much more generous when it comes to spending money and they may sometimes even buy them something that is beyond their budget. But as for ordinary friends, I don’t think they are willing to splash out on a pricey item for them because they might not think it’s worth investing too much money in a relationship that doesn’t weigh much to them.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d4f387ecf7447fd9746384b1', 'ielts_group_151e897b2777e298677d7518', 'PART_3', 4, 'How difficult is it to become very rich in today’s world?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, if we’re just talking about becoming RICH, then I don’t think it will take too much doing. I mean, typically you need to be hard-working, self-reliant, and adventurous, doing the things most people dare not to do. But if we’re talking about becoming VERY rich, I would say in addition to all the good qualities that I mentioned earlier, you also need luck, which can be vitally important if you want to make big money. I guess there must have been a lot of people who could have made a fortune if they had had some luck on their side, but it’s a shame they didn’t. So, if you ask me, in today’s world, becoming very rich can be incredibly difficult.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_bad94e8ccd077af7a801d4af', 'ielts_group_151e897b2777e298677d7518', 'PART_3', 5, 'Do you agree that money does not necessarily bring happiness?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I agree. Of course, money is important and can buy you a lot of things, you know, big houses or fancy cars that can make you happy, but it doesn’t mean it can always bring people happiness. For many people, happiness is directly connected to having enough time with their family and friends rather than how much money they have. In other words, they can also feel genuinely happy even if they’re badly off as long as they can have a sound relationship with those they value in their life. Also, money can cause stress and anxiety, which is obviously not what happiness is about. Take celebrities for example, they’re generally fabulously rich, but they also suffer from tremendous stress which leads to depression and even suicides. Celebrity suicides are not uncommon in many countries, so I would say if money was really the basis of happiness, there wouldn’t be so many cases like that.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cdfc2f1e8a598eabe2066074', 'ielts_group_151e897b2777e298677d7518', 'PART_3', 6, 'In what ways might rich people use their money to help society?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, there are many ways that wealthy people can financially contribute to the society. The easiest way is to give away money to those in need, getting their lives back on track. In fact, there are lots of rich people who are already doing this. They help to build schools, hospitals and other essential infrastructure to help the people get education and better their lives. Of course, donating money is not the only way. Wealthy people could also influence and inspire those who want to be as successful as they are by sharing their valuable experience that helped make a name for themselves.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3e1afac1f357f3a0d09d07cb', 'ielts_group_68ddfbdf20a28980e0ec9037', 'PART_1', 1, 'What kinds of fast food have you tried?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I’m a food lover, so I’ve tried quite a few kinds of fast food, such as burgers, sandwiches, pizza, fried chicken, you name it. They taste really good! Although I know they’re not that healthy, I just can’t resist them.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7e9f102d314e419b53107e0e', 'ielts_group_68ddfbdf20a28980e0ec9037', 'PART_1', 2, 'Do you ever use a microwave to cook food quickly?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I often buy some ready meals in the convenience store beforehand. So, whenever I don’t feel like cooking when I get back home, I’ll use the microwave to heat the meal. It only takes a few minutes before it can be served, which is really quick and convenient.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5283a937004f5bf03fbcd159', 'ielts_group_68ddfbdf20a28980e0ec9037', 'PART_1', 3, 'How popular are fast food restaurants where you live?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I would say the fast-food restaurants where I live are hugely popular. I live in a community with a lot of offices around, so when lunchtime comes, you can see loads of people flocking into those restaurants for a quick meal because of the short lunch break.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_44993dcbdc19f0c5f8230b08', 'ielts_group_68ddfbdf20a28980e0ec9037', 'PART_1', 4, 'How popular are fast food restaurants where you live?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, actually I don’t normally go to a fast-food restaurant as I know the food there is not wholesome, but every now and then, especially when I don’t really have much of an appetite, I’ll go to McDonald or KFC for a combo with a burger, fried chicken and coke.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4a13065989937e8b5d0da655', 'ielts_group_35e27b944effd9e030de1524', 'PART_2', 1, 'Describe some technology (e.g. an app, phone, software program) that you decided to stop using.', '["when and where you got this technology","why you started using this technology","why you decided to stop using it","and explain how you feel about the decision you made."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"购买这款科技产品的背景和原因\n\nOK, I’m going to talk about the robot cleaner that I decided to stop using. About half a year ago, I decided to buy a robot cleaner because I was really tired of doing the cleaning after work. So I went online and ordered one.\n\n产品的功能描述\n\nActually, it did work like a dream in the beginning. It was smart and it was really quiet while it was working, producing no noise at all. I mean, sometimes I wouldn’t even notice that it was working. Also, it had a Wi-Fi built in, so I could control it using my phone remotely, which was really handy. Anyway, I was fairly satisfied with it because it really saved me a lot of time and energy during that period of time.\n\n决定停用这个产品的原因\n\nHowever, after two or three months, it didn’t work as well as it used to be. It would get stuck in the corner and stop running, so I had to stop what I was doing and go manually reset it, which was really troublesome. Also, it somehow started to produce a lot of noise while it was working and it was getting noisier and noisier over time, which was really annoying and that was what I couldn’t stand and also why I decided to stop using it. Actually, I have put it on an online second-hand market for sale.\n\n对做出停止使用这一决定的感受\n\nHow I feel about it? Well, I believe I made a good decision because I don’t have to stand the noise any more. And I don’t have to think about going fix it whenever it malfunctioned. So for me it’s quite a relief, although I’ve been doing all the cleaning all by myself since then.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fa258e567fcefe8b198926ab', 'ielts_group_35e27b944effd9e030de1524', 'PART_3', 1, 'What kinds of computer games do people play in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think MOBA, like League of Legends, is insanely popular in my country simply because it’s a fun game with strong multiplayer experience. Also, it’s not a pay-to-win game, which means you don’t have to pay real money to gain a massive edge over other players. First person shooter games, such as CrossFire, also enjoy tremendous popularity in China because it’s incredibly accessible and super stimulating that can bring people great excitement.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fd1d14f6683c03546db478ec', 'ielts_group_35e27b944effd9e030de1524', 'PART_3', 2, 'Why do people enjoy playing computer games?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think it’s mainly because playing computer games is fun and a great way to leave your worries behind. You can totally lose yourself in a virtual world, where you don’t have to worry about your work or study. That’s why computer games are so popular among young people who stress out. Another reason is that these days, as the technology advances, computer games are so well designed and the graphics are so incredibly aesthetically pleasing, making people easily indulge themselves in the game and even get addicted to it, even if they know it’s bad for them.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_10a9ef8ae152539c10135bb0', 'ielts_group_35e27b944effd9e030de1524', 'PART_3', 3, 'Do you think that all computer games should have a minimum age for players?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think it depends. Some computer games are fun and educational, which can benefit the kids mentally and physically if the kids are properly guided when playing the game. For those kinds of games, I don’t think an age restriction is necessary. However, some games, like first person shooter games, are quite violent and bad for kids’ mental health. Also, some games are sexually explicit, and playing them too much is definitely psychologically detrimental to the kids’ future development. So, for those types of games, having an age restriction is a must.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7630b392d260e0eb15f74ceb', 'ielts_group_35e27b944effd9e030de1524', 'PART_3', 4, 'In what ways can technology in the classroom be helpful?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think technology can help teaching and learning in various ways. For one thing, it can create a much more engaged environment, where active participation can be encouraged. For example, in a biology class, teachers can use the computer and the projector to screen videos or pictures of various animals instead of just letting students see the animals in the book, which can really bring a dull class to life. For another, technology encourages individual learning, which provides great opportunities for students to learn more effectively. For example, students can learn at their own speed, choosing when to review or when to skip ahead if they want to.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_009afb9fbaaa522d97e6e224', 'ielts_group_35e27b944effd9e030de1524', 'PART_3', 5, 'Do you agree that students are often better at using technology than their teachers?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I would say yes. Students these days are fairly smart and are pretty quick on the uptake, so it’s quite natural that they are more adept at using technology. Their teachers, on the other hand, are often in their 40s or so, meaning they may not learn new things as quickly as their students. Also, most teachers are busy with working and some of them have family responsibilities, leaving them very little time to figure out how a piece of technology is used.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_25b4b76e1b0f749abe779809', 'ielts_group_35e27b944effd9e030de1524', 'PART_3', 6, 'Do you believe that computers will ever replace human teachers?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think computers will never replace teachers in the future. It’s true that computer-based learning is gaining popularity these days, and in many regions, it does offer teachers great help to better conduct teaching. But it seems to me that the help computers can offer is just programmed instruction and assessment, which is strikingly different from what a high-quality teacher can do in the class. What I want to say is, apart from giving instructions and assessments, teachers guide students through activities that help them to think, analyze, and apply what they have learned in class into the real world. They provide personalized feedback to help students develop their critical and creative thinking. This is what really matters about teaching and learning and this is something that a computer could never do in a real class. So, I firmly believe that teachers will never be replaced by computers.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1eb3a7e9b50f94b23e41c772', 'ielts_group_6309c60c2c981dfc71553fb3', 'PART_1', 1, 'What did you study in history lessons when you were at school?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think we learnt tons of basic facts about past events just like other people did, especially those so-called turning points, as well as influential historic figures and battles that reshaped the course of human civilization. But fundamentally, it was exam-oriented and that made history lessons less engaging. And honestly speaking, I only have very vague memory about what I learned from school.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3499e16fb67b5388ed92640f', 'ielts_group_6309c60c2c981dfc71553fb3', 'PART_1', 2, 'Did you enjoy studying history at school? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, if you had the misfortune to do too much of it at school as I did, you’ll probably know how dull it can be. By that I mean, we had to learn everything on the coursebook by rote, like dates and facts. So it wouldn’t be surprising that most of us tend to steer well clear of the whole topic after we graduated from high school.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_348d2b08c5b48918683e9552', 'ielts_group_6309c60c2c981dfc71553fb3', 'PART_1', 3, 'How often do you watch TV programmes about history now? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Actually, programmes in this genre are not my kind of thing. But I do check the video clips about history from time to time according to my own interest. Maybe I just want to gain insight into why a country is in its current state or simply get fascinated by some inspirational leaders from the past. Compared to the history taught in school, those videos normally present more information from various perspectives, and they’ve sort of opened the lens for me.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_105e581d63e1548cc838f9fc', 'ielts_group_6309c60c2c981dfc71553fb3', 'PART_1', 4, 'What period in history would you like to learn more about? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, this is a tough one for me, as there are a couple of historical periods that I find compelling, like European Renaissance, Scientific Revolution as well as the Second World War, because they have drastically shaped our modern world. Time permitting, I’ll also read books on Big History, like Guns, Germs and Steel, for it possibly can provide me a more holistic view on human civilization.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_998f9290ed983a07a3beca34', 'ielts_group_14dba0d72578c0e033f4810a', 'PART_2', 1, 'Describe the neighbourhood you lived in when you were a child.', '["where in your town/city the neighbourhood was","what kind of people lived there","what it was like to live in this neighbourhood","and explain whether you would like to live in this neighbourhood in the future."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍\n\nWell, I spent most of my childhood in my grandparents’ apartment, which was actually one of the residential communities built for factory workers and their family in a large industrial zone in the suburb of the city.\n\n描述外观\n\nI think it was a typical community in China. The overall architecture was absolutely unfashionable, by that I mean, they were long, thin walk-up apartment buildings with five or six stories. There were two or three apartments on each landing. Generally speaking, it was a livable neighborhood. If you took a walk around, you would find a series of public service buildings, including schools, clinics, grocery stores, which were all within walking distance. \n\n描述人物\n\nAs I said, it was a residential complex for people who work in the same factory, so most of the dwellers used to be colleagues and it’s a commonplace to find people having acquaintances spanning two or three generations. In my memory, everybody greeted each other or struck up a chitchat when they took a stroll in the neighborhood. \n\n描述经历与感受\n\nCompared to my current modern community, life there was more heartwarming. People shared food and gave a hand to each other. Apparently, people seemed to have a much stronger bond and felt more socially-connected. On top of that, the neighborhood had a walkable size, so residents didn’t need to rise early to commute long distances to work or school.\n\n给出原因 \n\nUnfortunately, it’s unlikely for me to go back. The city is expanding outward and the whole area is experiencing rapid gentrification, so the old neighborhood has been replaced by brand new high-rise buildings. That’s quite a pity and how I wish I could turn the clock back.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_07e0cd2c6cd73824bfa4422e', 'ielts_group_14dba0d72578c0e033f4810a', 'PART_3', 1, 'What sort of things can neighbours do to help each other?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, if you are on good terms with your neighbors, they can lend a hand to you in many ways. By way of example, they can help you carry in the groceries, sign for your packages, or even babysit your kids. On top of that, they can also offer to watch over your house by watering your plants, feeding your pets as well as keeping an eye on things when you are away. Some neighborhood events can be organized by people who live on the same block, like throwing a party to celebrate an upcoming holiday or having everyone pitch in to clean up the sidewalks. That way, residents will have a better sense of community.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8e49c6a5ebe1d32baea78d77', 'ielts_group_14dba0d72578c0e033f4810a', 'PART_3', 2, 'How well do people generally know their neighbours in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It seems to me that people nowadays are not familiar with their neighbors as much as they used to do. Even though people are adjacent to each other, it doesn’t necessarily mean that folks who live nearby play an important role in our life. What I’m saying is that, we no longer need that much interaction with our neighbors as technology gives us instant access to almost everything. For example, you can be linked to your friends via social media and you can use delivery service when you are in need of some daily necessities. To build on my point a bit more, there has been a much greater population mobility in big cities these days, so many young people have to rent an apartment to live, which means they only stay temporarily, and they don’t really care who live next door.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5854f3ad77fb750e16277ec0', 'ielts_group_14dba0d72578c0e033f4810a', 'PART_3', 3, 'How important do you think it is to have good neighbours?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, if you’ve made up your mind to settle in a community, good neighbors undoubtedly matter a lot to your life quality. Just imagine, if you have really annoying neighbors, let’s say, they throw wild parties late at night with an overbearing manner or they dump waste on the sidewalks, and you can do nothing but putting up with that. But if you have friendly and considerate neighbors, things will be the other way around. I mean, they’ll respect your space and privacy, and they’re willing to take time to talk and smile to you. More importantly, they tend to reach out to you, which will enhance your sense of community. It’s a real blessing to have good neighbors.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3e936d33523068aa2ebd234e', 'ielts_group_14dba0d72578c0e033f4810a', 'PART_3', 4, 'Which facilities are most important to people living in cities ?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it’s widely known that cities have a larger geographical area and population. So a city should have a variety of amenities to meet the needs of its occupants. To keep a city functioning, facilities for transportation like streets, bridges, alleys, and traffic signals play a vital part, as they make a city connected. On top of that, water lines, storm drains, sanitary sewers, parking lots are also fundamental. Without them, a city can’t be a livable place. Public service facilities like schools, hospitals, parks and libraries are also essential for city dwellers. In fact, it is the standard of those facilities that decides whether a city is appealing or not.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3775b7eb952a8860eeab8bf3', 'ielts_group_14dba0d72578c0e033f4810a', 'PART_3', 5, 'How does shopping in small local shops differ from shopping in large city centre shops ?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, in terms of shopping experience, shopping in the heart of the city can definitely provide you with a wide selection of goods and your overall shopping experience will be enriched by a mix of activities which are available in a mall, such as dining in a range of restaurants, watching movies or even spinning on an ice rink. I think this is one of the incomparable appeals of a shopping complex. By contrast, people normally go to local grocery stores to shop for food or daily articles. It’s more like getting things for a more practical reason rather than for recreation.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_65c1c8f8537267331e0dc6c2', 'ielts_group_14dba0d72578c0e033f4810a', 'PART_3', 6, 'Do you think that children should always go to the school nearest to where they live ?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Not really. It’s common knowledge that attending a neighboring school is beneficial for both children and parents. To be more specific, children can have adequate sleep and their parents won’t get themselves in a rush to drop off and pick up their kids on time. That being said, physical distance is not the only standard when it comes to education. It’s a foregone conclusion that parents always want their kids to receive better education, but the problem is that the actual education resources are unequally distributed in a city. In this case, some parents will send their children to a school with better education quality, such as a private school rather than a nearby public school.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1d144eb42189333727ab2be4', 'ielts_group_28edbea726ac639756bd5b1a', 'PART_1', 1, 'Did you have a favourite book when you were a child? [Why/Whynot?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, an old favorite of mine is called The World of Sophia. I read it in the 5th grade and it was the first time I ever read a book about philosophy, about how those great thinkers see the world. It was mind-blowing and made me think out of the box. And it kind of enlightened me by instilling different values in my mind. I’ve read it a couple of times over the years and every time I read it through, I’ll get something new out of it.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_dfeebabfbc8f25442dd9c89d', 'ielts_group_28edbea726ac639756bd5b1a', 'PART_1', 2, 'How much reading do you do for your work/studies? [Why/Whynot?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, as an undergraduate doing liberal arts, I have tons of books to read every week, most of which are on the academic side of things, including textbooks, reference books on the reading lists for different disciplines. Recently, I’ve been reading a book called Theory of Literature, which is a classic book of criticism, recommended by one of my professors. I have to say it is very deep, but it’s expertly written and clearly explained.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_82d48e73d3fb51e15e702438', 'ielts_group_28edbea726ac639756bd5b1a', 'PART_1', 3, 'What kinds of books do you read for pleasure? [Why/Whynot?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, for me reading for enjoyment is not for instrumental purposes, it’s more about reading whatever you want based on your own interests and preferences. In my case, I read widely, and I don’t particularly favor a specific genre of books. For example, I’ve been hooked on manga for months, so now I’m deep in a novel that is set in Tokyo. Generally, it’s all about my fascination, which keeps changing from time to time.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7e4e690f2c26fdd50ced3593', 'ielts_group_28edbea726ac639756bd5b1a', 'PART_1', 4, 'Do you prefer to read a newspaper or a magazine online, or to buy a copy? [Why/Whynot?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, compared to physical ones, I like reading them online much better. I really like the fact that I don’t need to deal with old newspapers or magazines piled up on the floor after I read them, for I can browse the content on my screen. I’m even a paid subscriber to some news apps or online reading platforms and I’m quite content with the personalized and highly targeted news reading experience with reasonable expense.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ee2ac13a32d980afbb33f11f', 'ielts_group_d504126391ec19aebec0a0dd', 'PART_2', 1, 'Describe a big city you would like to visit.', '["which big city you would like to visit","how you would travel there","what you would do there","and explain why you would like to visit this big city."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍 The city I’d like to explore in the future is New York City, one of the most populous megacities in the world.\n介绍城市概况 I think everyone knows something about it from the TV series and movies we’ve streamed which are set in this bustling, vibrant place, like Friends, Home Alone and Sleepless in Seattle. It is from those scenes that I can picture those landmarks simultaneously in my mind like the Empire State Building, the Statue of Liberty and Times Square, to name but a few. It has the reputation of “the city that never sleeps” and I believe it will definitely make me feel alive and at the centre of everything with yellow taxi weaving through the traffic, brightly-lit theatres, and restaurants busy late into the night.\n介绍拟定的出行方式 Since New York City is over 10,000 km from where I live, I suppose the only viable means of transport to reach there are air and water. If I were to choose from these two modes, I’d opt for a flight as it’s far more time-saving compared to a cruise trip. \n描述计划中的旅行 It’s a huge city, so I think I would have countless things to do there. In fact, I can explore it in many ways, but as it is one of the greatest walkable cities, I’m expecting to tour around on foot. I’ll check iconic sights in Manhattan and quirky shops and café in Brooklyn. I shouldn’t miss the chance to view the city from above, so visiting some of the extraordinary observatories like some panoramic rooftop bars is definite. I would also eat my way around the world by touring the city’s neighborhoods.\n想要去这个城市的原因 Coming to the many reasons why I aspire to visit this city, I guess the main reason would be my fascination with its diverse culture and remarkable vitality. Other than that it’s a city that has witnessed so much, but remains to be so appealing. In a nutshell, traveling to the Big Apple has always been on my bucket list, and I can’t wait to embark on the trip.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_127f286eed93bf3f9f243ac6', 'ielts_group_d504126391ec19aebec0a0dd', 'PART_3', 1, 'What are the most interesting things to do while visiting cities on holiday?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In my view, it’s not the typical touristy things such as going sightseeing or dwelling in a star-rated hotel that make visitors thrilled to bits when they are having a city break. What really captures tourists would be things that can get them blend to the local culture and vibe, like sampling authentic food around the neighborhood or joining a carnival parade if there’s a festival celebration. Some people may find going on a shopping spree in big cities make their day, especially in cities with specialized shopping districts, like Tokyo, London and Hongkong, for there is a great selection of things to purchase from souvenir items to luxury products.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_efdc04964f2b8182893a55ba', 'ielts_group_d504126391ec19aebec0a0dd', 'PART_3', 2, 'Why can it be expensive to visit cities on holiday?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think the major reason is that there is always a higher demand for travelling on vacations. By that I mean, holiday makers generally flock to their destinations at the same time and this will lead to the rise of everything, like airfare and hotel rates, fees for local activities and other service. Another reason might be that people tend to be less strict with money when they are taking time off. Possibly this is a way to treat themselves. For example, some people may lead a frugal life during the whole year, but enjoy living in the lap of luxury in a fancy hotel for their holidays. That’s pretty much the reason why people tend to spend money like water during holidays.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9de3316e52063f10cf04d0ad', 'ielts_group_d504126391ec19aebec0a0dd', 'PART_3', 3, 'Do you think it is better to visit cities alone or in a group with friends?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It seems to me that there’s no winner between solo travel and group travel, as both of them have their highlights. If you travel on your own, you are free to choose your destinations in the city tour, make changes midway or simply loiter around. Plus, you can appreciate your own company without compromising with your personal preferences. For example, you can stay in an art gallery as long as you wish without being bothered by your friends. More importantly, it’s much easier to stick to your budget and save money. That being said, if you go with a bunch of friends, they can offer you safety and immediate help when you run into trouble. On top of that, your tour company will help you arrange an ideal itinerary as well as the best accommodation or restaurant, so you can travel light. In short, it really depends on your personal needs.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2d6bec53b702ba4a5f0d0991', 'ielts_group_d504126391ec19aebec0a0dd', 'PART_3', 4, 'Why have cities increased in size in recent years?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think cities are sprawling drastically due to the fact that more and more people move there for higher living standard, social amenities, and definitely more job opportunities. That way, cities have to expand to meet the need of a growing population. To elaborate on this, more lands will be transformed to residential areas and other necessities such as roads and public transportation, clinics, schools have to be planned and built alongside. So cities have to spread out to accommodate the change.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8d084c9f43fd8489d1256fb2', 'ielts_group_d504126391ec19aebec0a0dd', 'PART_3', 5, 'What are the challenges created by ever-growing cities?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think the challenges people have to fight off in the process of urbanization are huge. Firstly, fast urban growth may not guarantee the equal growth of infrastructure, so it may fail to keep up with residents’ needs and in the end bring chaotic looking to the cities such as the densely populated slums both on the edges and within the largest cities. Apart from that, cities have to seek ways to provide adequate food, sanitation and education for all people, which means more fund will be provided for public facilities. Last but not least, it’s easy to sacrifice environment for the sake of fast growth, so policy makers should ensure that it happens in a way that does not damage the land.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d9d7a46fe26df7a35dee3d54', 'ielts_group_d504126391ec19aebec0a0dd', 'PART_3', 6, 'In what ways do you think cities of the future will be different to cities today?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think remarkable changes will take place in the future. In terms of transportation, city dwellers will adopt more means rather than auto mobiles. I’ve heard that research on flying vehicles is already underway. Architectural design will undoubtedly take on a new look as well. Compared to current design, I think future buildings will be a combination of more functions, like a blend of office, residential, retail and even educational spaces, which will be handier for city occupants. In some cities nowadays, we can already get notifications of the best time to commute based on the big data-driven ecosystem. So I’d hazard a guess that cities will be much smarter in the future, providing you everything you want to know in real time in the palm of your hand.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_37d5cbc590cdd246447e6d93', 'ielts_group_099538c1c5e6481d6312cf53', 'PART_1', 1, 'What do you like to drink with your dinner? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I like to eat soup during dinner, as it not only adds flavor to the meal but also aids digestion after the meal. When I have hotpot or spicy dishes for the dinner though, I prefer to drink beer. A glass of ice-cold beer, along with the hot fiery dishes. It’s just sheer enjoyment!","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fbff1aeaa99a3b72053728e1', 'ielts_group_099538c1c5e6481d6312cf53', 'PART_1', 2, 'Do you drink a lot of water every day? Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I wouldn’t say I drink a LOT of water every day, but I think I’ve got a pretty moderate daily water intake, like 6 or 7 cups of water on a daily basis as it helps me sleep better, think more clearly and even puts me in a better mood. Sometimes when I’m outside on a hot day, or doing something that makes me sweat a lot, I’ll drink a bit more to stay hydrated.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_84411a957e8193d0f2a64bf3', 'ielts_group_099538c1c5e6481d6312cf53', 'PART_1', 3, 'Do you prefer drinking tea or coffee? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I’d say I’m more of a coffee person so I prefer coffee over tea. I like it because it picks me up in the morning and helps me to stay productive in the afternoon. I also like coffee for its delicate textures and pleasant flavors. As for tea, it’s just too bland and even sometimes a bit bitter, so it’s not for me.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_98322b5a51d1cd8b15ba5465', 'ielts_group_099538c1c5e6481d6312cf53', 'PART_1', 4, 'If people visit you in your home, what do you usually offer them to drink? [Why/why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, when my friends come over to my living place, I usually serve them with beverages, such as soft drinks as they’re easily available. I’ve got a coffee maker at home, so sometimes I’ll make them coffee if they prefer otherwise, especially during the wintertime. When older people drop by, however, like my in-laws, I often offer them tea or just water, because they’re more health-conscious and beverages will usually leave them cold.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_bb58592d2dedbeabaf3e17f1', 'ielts_group_93908430e09922123225cb90', 'PART_2', 1, 'Describe a monument (e.g., a statue or sculpture) that you like.', '["what this monument is","where this monument is","what it looks like","and explain why you like this monument"]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍 I’m going to talk about one of my favorite monuments, which is a sculpture of Zu Chongzhi, one of the most renowned mathematicians in China.\n展开描述 This memorial was erected in the 1980s and was conspicuously placed in front of the administration building of our school in honor of this great mathematician. It’s made of bronze and stands about 3 meters high, with his name and the figure 3.14 inscribed on the pedestal, indicating his great achievement in approximating the value of pi to 3.14. The sculpture depicts Zu Chongzhi in his 60s, who is sitting on the floor with his two legs crossed and his hands carrying some bamboo slips, deep in thought.\n作出对比 In fact, compared with the other works of art in the school that are beautifully designed and delicately carved, this sculpture is actually quite average in terms of design and craftsmanship. But despite all this, because of its mathematical significance, it’s considered one of the most symbolic and iconic sculptures on campus.\n给出原因 I like the sculpture because I love maths and I see him as my idol. The figure is like a mecca for me and all maths lovers in our school, and every year on Pi Day, the students, including me of course, will gather together in front of the figure in memory of this great mind and pay homage to what he contributed to maths. Another reason why I like it is that I think the memorial has brought me a lot of luck and inspiration. In fact, every time a maths exam is around the corner and I panic about it, I’ll go there, praying in front of it in the hope of passing the exam. And it really works!","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ceddfa3dc8424d114f1948c8', 'ielts_group_93908430e09922123225cb90', 'PART_3', 1, 'What kinds of monuments do tourists in your country enjoy visiting?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, in China, monuments of famous people such as political leaders and poets enjoy quite a lot of popularity. Most tourists visit those monuments to both admire the awe-inspiring structures for the historical value and pay homage to what the famous public figures contributed to the country. Ancient temples are also very much loved by tourists, as such monuments are not only rich in historic significance, enabling visitors to understand a certain piece of history, they also show great aesthetic value, showing tourists the beautiful design as well as the superb craftsmanship.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_307d491f4702029b34e2d34a', 'ielts_group_93908430e09922123225cb90', 'PART_3', 2, 'Why do you think there are often statues of famous people in public places?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think most statues of public figures are created as a type of commemoration of those who made tremendous sacrifice or contributions to their country and even to the whole world. These people mean so much to their countries so their statues are put up in public places such as in a square, in a park, or in front of a stadium, so that everyone can come to visit them and pay homage to what these famous people did. Such statues are so symbolically important that they’re not just for those who’ve passed away, these days more and more living famous people’s portrait sculptures have been erected, such as Michael Jordan, Cristiano Ronaldo and other household names who have put a kind of sport or their countries on the map. These statues are built in the most conspicuous places to honor these amazing people’s legacy. And these statues have become part of the urban landscape and in some cases even notable landmarks.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_88c8af1204f8997db8e4a51a', 'ielts_group_93908430e09922123225cb90', 'PART_3', 3, 'Do you agree that old monuments and buildings should always be preserved?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I partly agree with this because preserving old buildings or monuments can bring a place economic benefit. Since most old structures often feature unique qualities such as aged brick, cobblestone sidewalks, and antique street lamps that resonate with senior tourists and spark the imagination of younger tourists, if these old buildings are well-preserved, they not only add character to the area, but can also help attract investment, as well as tourists, which can obviously contribute to the local economy. Culturally speaking, historical sites, such as an ancient temple or a public figure’s statue, are a key ingredient in stabilizing older communities and bringing citizens together, which help develop an individual’s sense of belonging and community pride. But having said that, if an old building or monument, despite its historical value, becomes a threat to the public, let’s say, it becomes a fire hazard, posing a threat to the public’s interest, or if the land occupied by the old structures could be used in a way that’s more beneficial to the community, then I’d say it’s best to have them knocked down.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_44a45f35127ce6ac5535ddcf', 'ielts_group_93908430e09922123225cb90', 'PART_3', 4, 'Why is architecture such a popular university subject?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think one major reason for that is most students who’d choose architecture as their major aspire to be an architect, and architects are generally well-paid. According to data from Payscale, an architect can average more than $60,000 per year, and even an interior designer earns roughly $ 50,000 annually. So I think the handsome pay is arguably what motivates students to study this subject in college. Aside from money, transferable skills, such as strategic and logical thinking, complicated problems solving, as well as other know-how you can obtain are what this subject will offer, meaning even if you end up not as an architect, the skills and abilities you developed and gained while studying architecture can be your foundation for success in other areas. So that’s why I think architecture as a university subject enjoys such massive popularity around the world.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ad5a2586a4d2a03b3ae410e2', 'ielts_group_93908430e09922123225cb90', 'PART_3', 5, 'In what ways has the design of homes changed in recent years?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think over the past few decades, there have been significant changes in how houses are designed. Back in the days, most people used to focus on how to make their homes more aesthetically pleasing, indulging in an excess of ornaments, textures and patterns that could make their homes look more lavish and attractive. These days, however, with the rising housing price and thus shrinking living space, homeowners are more concerned with their homes’ functionality and practicality, and, most importantly, how to make full use of their home spaces. In some densely populated places, such as Hong Kong and Japan, home designers or interior designers often have to come up with multiple plans on how to fully utilize their clients'' limited home spaces to support inter- and multi-generational living.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_364020097e70d954d5e898c5', 'ielts_group_93908430e09922123225cb90', 'PART_3', 6, 'To what extent does the design of buildings affect people''s moods?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think both the exterior and interior design of a building can impact on one’s mood considerably. People appreciate and admire beauty, so when people see a building that is beautifully designed and aesthetically pleasing, it’s quite natural that it will put people in a good mood. Eiffel tower is a perfect example of this. Known for its captivating design, it never fails to take the visitors’ breath away and visitors are often ecstatic to see the wonder. Interior design also makes a difference when it comes to altering people’s mood. A building with a comfortable layout with well-apportioned furnishings can make you feel less burdened or more relaxed, while cluttered spaces can have a negative effect on your mood, which often leads to anxiety and stress.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b32f618dc7f2770bfcb2a782', 'ielts_group_9674ce2055dd050d3ce57d81', 'PART_1', 1, 'Do you think it''s better to use a paper map or a map on your phone? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, if you ask me, it’s definitely much better to use a digital map for its handiness and massive amount of up-to-date data available. It’s just a few quick taps on your phone to find your way or get to a new place, which is incredibly convenient, And besides, it’s totally free. That said, you definitely should not completely discard paper maps. They may come in handy when you visit a tourist attraction or some little-known places where there’s no cell signal, but if you want to use a map to basically go about your everyday life, a digital one is reliably much better.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6bc41434638612a4ab0faa5c', 'ielts_group_9674ce2055dd050d3ce57d81', 'PART_1', 2, 'When was the last time you needed to use a map? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I guess it should be when I was traveling in Japan with my wife a few years ago. Back then, the map apps were not as handy and popular as they’re now, so we bought a paper map to help us navigate. Thankfully the map came in very useful, with all the places we wanted to visit clearly labelled on it, so we didn’t have problems finding our way to a new place or back to the hotel. The only thing was the international data used during that trip was ridiculously expensive, which cost us quite a lot.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_93f2c0bcec3c092eb3731ef2', 'ielts_group_9674ce2055dd050d3ce57d81', 'PART_1', 3, 'If you visit a new city, do you always use a map to find your way around? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I don’t normally use paper maps if I travel to a new city, like when I have a city break, but I’ll definitely use a map app to navigate my way around, such as Gaode Map when I travel domestically or Google Maps when internationally. Those map apps are great tools, which not only help me get real-time GPS navigation, traffic, and transit information, but also help to explore local neighborhoods and tourist attractions by knowing where to eat, drink and go, which is incredibly handy.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e11b6a4cf4cacea740019fdf', 'ielts_group_9674ce2055dd050d3ce57d81', 'PART_1', 4, 'In general, do you find it easy to read maps? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I don’t think I find it hard to read maps because most of them are generally quite reader-friendly, with everything clearly labeled on it, such as the title, legend, scale and things like that. It can be a bit tricky for me to read if the map is too complex though. I remember there was one time I tried to read the full Tokyo metro map and it was all Greek to me. I mean, it took me ages to figure out which line to take.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7022c34269cac60c70212501', 'ielts_group_87f007ac09d2aab198c8817f', 'PART_2', 1, 'Describe an occasion when you had to do something in a hurry.', '["what you had to do","why you had to do this in a hurry","how well you did this","and explain how you felt about having to do this in a hurry."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"开篇介绍 I’m going to talk about a shopping experience, in which we had to be in a hurry. A few years ago, my wife and I traveled to Japan for our honeymoon. We joined a tour group, in which there were about 20 people. \n背景铺垫 I remember on the third day of the trip, the tour guide took us to Gotemba Premium Outlets, which was one of the largest outlet malls in Tokyo. It stood out for its rich selection of clothes and makeup, boasting brands such as Gucci, Nike, Celine, Armani, and much more. And most importantly, everything sold there was about 50% off! My wife was super excited about it as she was a shopaholic.\n描述原因 However, on the way to the destination, we got caught in a traffic jam, and due to the congestion, by the time we arrived there, it was already 4pm. And since we must get back to the hotel by 8pm for dinner, we were left with only one and half hours for the shopping.\n陈述过程 So, in order to make every single minute count, we almost rushed into the shops in search of the clothes, shoes, makeup and electronics that we had planned to buy. Thanks to the shopping list my wife made on the coach, we managed to get what we wanted when we were called to assemble at the coach.\n表达感受 How I felt about it? Well, although we had to do the shopping all in a rush, we were generally happy about it as we made it in the end within such a short period of time. That said, we also felt a bit disappointed because we had planned to try the food there and we also had planned to admire the beautiful view of Mount Fuji and take photos, as it was located right near the outlet and it was really gorgeous. But it was a shame that the limited time just got in the way of what could’ve been a fantastic experience.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3c3339c539ea645db14673b3', 'ielts_group_87f007ac09d2aab198c8817f', 'PART_3', 1, 'Do you think it''s OK to arrive late when meeting a friend?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"My view is that it’s acceptable if you’re late for the appointment with your friend once or twice. At least I wouldn’t mind if my friends are late for a meetup or something, especially when they’re justified or if they’re just a couple of minutes late. I mean, problems with excessive traffic, late trains or buses or family issues can sometimes cause the lateness. But having said that, if you’re always late or the lateness becomes a pattern, that would be totally unacceptable, as the tardiness or unpunctuality might make your friends feel undervalued or disrespected, and you could also be seen as someone who’s unreliable, which will definitely strain the relationship with your friends.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1c8009ba927f7a445bc0bf59', 'ielts_group_87f007ac09d2aab198c8817f', 'PART_3', 2, 'What should happen to people who arrive late for work?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think employees’ lateness for work should be dealt with accordingly. If they arrive late very occasionally or they can explain their lateness reasonably, then I think what should happen to them is just a kind verbal reminder about the effects of lateness and it shouldn’t be dealt with too harshly, as it could demotivate the employee and reduce the employee engagement. On the other hand, if some employees chronically arrive late for work and the lateness becomes a pattern, then they should be disciplined, such as writing them up and docking their pay for the lateness, to make sure the tardiness won’t persist, because if late arrivers are not called out or disciplined, it will not only lead to reduced productivity and profitability, but also, more importantly, hurt the team morale, with other employees who’re always on time feeling discouraged and disregarded.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_eda3151008e44f2a783eebbe', 'ielts_group_87f007ac09d2aab198c8817f', 'PART_3', 3, 'Can you suggest how people can make sure they don''t arrive late?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think one of the most effective ways for people who struggle with punctuality is to set lots of alarms. Let’s say, if you have a very important appointment with someone, you can set one alarm for when you have to leave the house and another one for whatever time your appointment starts. These frequent audible reminders can help get your attention in case you’ve lost track of time and help you arrive on time. These days, lots of apps on the phone can help do the work, and they work quite well. It’s also highly recommended that you always set aside some extra time for what you plan to do even if you’ve figured out exactly how long it will take. For example, if the trip to your workplace takes you about 30 minutes, it’s a good idea that you set off 20 minutes ahead of the scheduled time to avoid any incidents that may get in the way, such as traffic congestion, late trains and something like that.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a4ce9ad784ae51011b0ce661', 'ielts_group_87f007ac09d2aab198c8817f', 'PART_3', 4, 'Is it better to study for long periods or in shorter blocks of time?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think it’s definitely better to study in shorter blocks of time. Through studying small chunks of time, and with each chunk of time dedicated to accomplishing a specific task, you can be better concentrated and more likely to finish the task and feel rewarded, and such sense of accomplishment can further improve your productivity and enhance the willingness to study for longer periods of time. On the other hand, if you study non-stop for a long time, such as doing some research that requires you to go all out for the entire day, you’re more likely to feel tired or bored and then fall into distractions, which may result in diminished returns on your effort.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ee4f237118aafc055494a83c', 'ielts_group_87f007ac09d2aab198c8817f', 'PART_3', 5, 'What are the likely effects of students not managing their study time well?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think students’ poor time management for their study can lead to chronic procrastination. Students who fail to manage their study time usually end up letting the tasks sit until the last minute. And if they’ve let too many of them sit, they might miss the deadlines entirely, which may cause their grades to slip and jeopardize their academic future. Also, when students are bad at managing their study time, they may have to constantly stay up late to finish assignments or cram for exams, which will eat into their sleeping time, resulting in fatigue and even illness.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ab0e2af511f6351c70fad092', 'ielts_group_87f007ac09d2aab198c8817f', 'PART_3', 6, 'How important is it for students to have enough leisure time?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think having enough time for leisure is vitally important for students. These days, high school students and college students in particular are under massive pressure and facing intense competition, so they’re often too preoccupied with their studies to have any time for leisure. This is bad for them as it leads to fatigue, irritability and other mood changes, which will definitely have a negative impact on their studies and even wellbeing. For this reason, leisure time is hugely important to students as it serves as a stress reliever, enabling them to escape the pressures of their studies for a while, spend quality time with their family and friends, or do whatever they like to unwind, which not only helps sustain their performance in school, but also maintain their mental health.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_72ff5ca2404d7b7a43990602', 'ielts_group_abedc1ec6288c04ae34d78cf', 'PART_1', 1, 'What kinds of bills do you have to pay?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, as an adult living in China, I have to pay a bunch of bills to keep my life going smoothly. For example, I need to take care of my rent, my utility bills for electricity, gas, and water, my phone and internet bills and transportation fees. These bills are super important to keep me living comfortably and keep my credit score in good shape.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_435af21f325df3a237ab6ccb', 'ielts_group_abedc1ec6288c04ae34d78cf', 'PART_1', 2, 'How do you usually pay your bills – in cash or by another method? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I’m a big fan of using auto deduction to pay my bills, as it avoids all the hassle of manual bill paying. So, the money is just deducted from my bank account or Alipay account directly. One thing I like about using it is that it really helps with budgeting, as payment amount is more predictable. But I still need to keep track of account balances to get rid of overdraft fees or other issues.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d0f1e1584c8ac3c69f854c48', 'ielts_group_abedc1ec6288c04ae34d78cf', 'PART_1', 3, 'Have you ever forgotten to pay a bill? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"As I said, I’ve been using automatic bill deduction for a while, so I haven’t forgotten to pay a bill in recent years. It’s a really helpful tool because it automatically pays bills on a regular basis without me having to do it myself. This way, I don’t have to worry about late fees or damaging my credit score from missed payments.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c2545729bc451f77a979fc38', 'ielts_group_abedc1ec6288c04ae34d78cf', 'PART_1', 4, 'Is there anything you could do to make your bills cheaper? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yeah, there are definitely ways to make bills cheaper. I could try to reduce my energy consumption by unplugging electronics, using energy-efficient home appliances, and adjusting temperature settings. And for mobile phone and Internet bills, I could consider switching to a cheaper plan. But then again, some bills like rent and insurance are fixed, so there’s not much I can do to lower those costs.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5554745de1aef08c2e9c2ce2', 'ielts_group_f817d2aab5b23c5c769471f6', 'PART_2', 1, 'Describe some food or drink that you learned to prepare.', '["what food or drink you learned to prepare","when and where you learned to prepare this","how you learned to prepare this","and explain how you felt about learning to prepare this food or drink.","You will have to talk about the topic for one to two minutes. You have one minute to think about what you are going to say. You can make some notes to help you if you wish."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Learning to prepare a steak is an experience that I will always remember fondly. It all started two years ago when I decided to try my hand at cooking a steak in my apartment kitchen. Having always enjoyed eating steaks, I was eager to learn how to prepare one myself.\nTo get started, I scoured the internet for helpful tips and tricks on cooking the perfect steak. I came across some popular celebrity chef videos, including Gordon Ramsay’s tutorial on how to cook a steak. Watching his videos helped me get the hang of the cooking process and learn some essential techniques.\nSo, I headed to the local market and picked up a nice ribeye steak. Following Ramsay’s advice, I seasoned it generously with salt and pepper, rubbing it in to really bring out the flavor.\nNext, I preheated a cast-iron skillet on high heat and added a pat of butter and a drizzle of olive oil. Once the skillet was nice and hot, I carefully placed the steak on it, and the sizzling sound was music to my ears. I let it cook for 3~4 minutes on each side, using tongs to turn it over and basting it with the melted butter to make it extra juicy and delicious.\nOnce the steak was done, I took it off the skillet and let it rest on a cutting board for a few minutes to let the juices redistribute and make it even more tender. Then, I sliced it against the grain into thin slices and served it up with some tasty vegetables, including crisp-tender asparagus and mushrooms.\nOverall, learning to prepare a steak was an exhilarating experience. I was proud of myself for getting on to the ropes and mastering this new skill, and I enjoyed the satisfaction of creating a delicious meal that I could share with others.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c689318f44ee3f55d97e9541', 'ielts_group_f817d2aab5b23c5c769471f6', 'PART_3', 1, 'What kinds of things can children learn to cook?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, children can learn to cook a whole range of dishes, from quick and easy snacks like sandwiches and fruit salads to more complex meals like dumplings, stir-fried vegetables and soups. They can also whip up a batch of cookies, cakes or other desserts if they’re feeling fancy. Generally speaking, the key is to start with simple recipes and gradually move up to more complex ones as they build their skills and confidence in the kitchen. Apart from that, children can broaden their culinary knowledge by exploring other cuisines, such as Western or Japanese.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6ec8847f1ad41f94af6f881d', 'ielts_group_f817d2aab5b23c5c769471f6', 'PART_3', 2, 'Do you think it is important for children to learn to cook?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Absolutely, in my opinion, it’s essential for children to learn how to cook. It not only teaches them practical life skills but also helps them develop a better understanding and appreciation of food. Plus, cooking teaches children to be patient, organized, and responsible as they learn to plan, shop for and prepare meals on their own. Additionally, cooking can be a fun and rewarding experience for children, as it allows them to express their creativity, experiment with flavours and textures, and take pride in their culinary creations. Lastly, cooking can bring families together, as parents and children can bond over the preparation and enjoyment of meals.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ed566492ecdb6d036fb35b9f', 'ielts_group_f817d2aab5b23c5c769471f6', 'PART_3', 3, 'Do you think young people should learn to cook at home or at school?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Honestly, I believe that young people should learn to cook both at home and at school. Cooking at home can be a great way for kids to connect with their families, pass down traditional recipes, and learn about their cultural heritage. Plus, it can be a more relaxed and personal environment that encourages experimentation and creativity. On the other hand, cooking at school can provide a more structured and educational experience that exposes children to new recipes, techniques, and cuisines. It can also help them develop their teamwork and communication skills, as they work alongside their classmates to prepare meals. So, I think it’s important for children to have access to both settings.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6bdaa56cb67ca83501fa28c4', 'ielts_group_f817d2aab5b23c5c769471f6', 'PART_3', 4, 'How enjoyable do you think it would be to work as a professional chef?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, being a professional chef can be really enjoyable if you love cooking and are passionate about food. But let’s not forget that it’s also a very demanding and stressful job that requires a lot of hard work, long hours and creativity. For example, you have to stand for long hours, carry heavy pots and pans and work in a hot and sometimes cramped environment. On top of that, working as a chef means that you are often judged by peers, critics and customers, which can be a source of stress and anxiety. In a nutshell, it can be a remarkable and rewarding career, but it’s not for everyone.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4a3118136d4ecb5ccc0dd17d', 'ielts_group_f817d2aab5b23c5c769471f6', 'PART_3', 5, 'What skills does a person need to be a great chef?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"To become a great chef, you need a combination of technical skills, creativity, and a passion for cooking. Firstly, a chef must have strong basic cooking techniques, like chopping, grilling, and baking. They also need to have a deep understanding of ingredients and how to use them to create unique and flavorful dishes. But in my view, it’s creativity that really sets a chef apart. They need to be able to develop new recipes, experiment with ingredients, and present their dishes in a way that’s visually appealing. And finally, passion is an essential ingredient for success in the culinary world. I mean, cooking can be hard work and requires long hours, so chefs need to truly love what they do to excel in this profession.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5f5a57a7c3ceb58d294f4c28', 'ielts_group_f817d2aab5b23c5c769471f6', 'PART_3', 6, 'How much influence do celebrity/TV chefs have on what ordinary people cook?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think they have a big impact on people’s cooking habits. For a start, they bring new recipes and techniques to the table and make cooking exciting and approachable. People love their personalities and expertise, and often look to them for guidance on what ingredients, tools, and cookware to use. Another point is they do popularize certain food trends like avocado toast and kale salads. But it’s worth noting that not everyone can whip up the fancy dishes we see on TV. So, while celebrity chefs can inspire and teach us a lot, ultimately, it’s up to us to decide what we want to cook and how we want to do it.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_04d0b213d263d8f6e76c423f', 'ielts_group_c519422db00c2300207cfe48', 'PART_1', 1, 'Did you like studying science when you were at school? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Absolutely! I found science incredibly captivating and was always eager to learn more about the natural world. Physics, biology, and chemistry classes gave me a chance to explore topics like the laws of physics, the human body, and the environment. One particular experiment that stands out in my mind was in chemistry class, where we conducted a series of reactions to produce different colours of flames. This hands-on approach to science made it even more engaging for me.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5ac9dd3a318c161aa39c4747', 'ielts_group_c519422db00c2300207cfe48', 'PART_1', 2, 'What do you remember about your science teachers at school?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I had several science teachers throughout my schooling, but the ones who left a lasting impression on me were those who were passionate about their subjects and made learning enjoyable. They were knowledgeable and approachable, and always encouraged us to ask questions and explore our surroundings. I remember my biology teacher, who would bring interesting specimens and artefacts to show us. This practical demonstration ignited my interest in the subject, and I developed a deeper appreciation for the world around us.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0bf5307135347036b285812a', 'ielts_group_c519422db00c2300207cfe48', 'PART_1', 3, 'How interested are you in science now? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Although I’m not currently working in a science-related field, I remain fascinated by scientific advancements and discoveries. Every day, I try to keep up-to-date with the latest developments, from medical breakthroughs to technological advancements that are shaping our daily lives. For instance, I’m currently following the developments in quantum computing and how it has the potential to revolutionize computing as we know it.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0e523215a070555783c805cb', 'ielts_group_c519422db00c2300207cfe48', 'PART_1', 4, 'What do you think has been an important recent scientific development? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I believe the development of mRNA vaccines is a significant scientific breakthrough. Compared to traditional vaccines, they are more adaptable and faster to produce, which has the potential to revolutionize vaccine development for various diseases. The recent mRNA vaccines have demonstrated their effectiveness against COVID-19, which has helped speed up the vaccination process worldwide. This development has shown how science can directly and positively impact our daily lives, and I’m excited to see what other advancements science will bring in the future.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4126033ca8d496e265424738', 'ielts_group_358ebc2ab4dc75e4a754717b', 'PART_2', 1, 'Describe a tourist attraction in your country that you would recommend.', '["what the tourist attraction is","where in your country this tourist attraction is","what visitors can see and do at this tourist attraction","and explain why you would recommend this tourist attraction.","You will have to talk about the topic for one to two minutes. You have one minute to think about what you are going to say. You can make some notes to help you if you wish."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, if you’re ever in Hangzhou, China, make sure to check out West Lake, one of the most breathtakingly beautiful places in the world. It’s no wonder that it’s called the “paradise on earth”! It is surrounded by lush greenery and stunning scenery that attracts tourists from all over the world.\nWest Lake offers visitors an unforgettable experience that combines history, culture, and nature. You can take a leisurely boat ride, stroll along the many paths, or explore the numerous historic landmarks located nearby. The cherry trees, willows, and bamboo groves lining the paths add to the picturesque scenery, making it an Instagram-worthy spot.\nWhat I love about West Lake is that there are so many activities to enjoy. From paddle boating to hiking and cycling, there’s something for everyone to enjoy. You can go solo or with family and friends, and you’re sure to find something that appeals to you. One of the best things about West Lake is the tranquil and calming atmosphere. It’s the perfect place to unwind while taking in the beautiful surroundings. The cultural landmarks nearby provide a glimpse into the rich heritage of Hangzhou.\nOverall, I highly recommend visiting West Lake. It’s a must-see destination that’s sure to leave a lasting impression on anyone who experiences its beauty and charm. So, make sure to add it to your travel bucket list!","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_179e2e8aa8bba02d2a8e1630', 'ielts_group_358ebc2ab4dc75e4a754717b', 'PART_3', 1, 'What are the most popular museums and art galleries in … / where you live?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, when it comes to popular museums and art galleries in China, I think the Palace Museum, also known as the Forbidden City, takes the cake. It’s located right in the heart of Beijing and was the imperial palace for more than 500 years. The Palace Museum has an impressive collection of artefacts, artworks, and historical objects that showcase China’s rich culture and history. It attracts plenty of visitors every year from home and abroad. Other notable museums and art galleries in China include the National Museum of China, the Shanghai Museum, and the Guangdong Museum.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0c8e810f6933fbff762e9b9a', 'ielts_group_358ebc2ab4dc75e4a754717b', 'PART_3', 2, 'Do you believe that all museums and art galleries should be free?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"That’s a tough one. While I do think that museums and art galleries should be accessible to everyone, I don’t necessarily believe that they should be completely free. After all, these institutions require funding to maintain their collections, facilities, and staff. However, it’s essential to strike a balance between making these cultural treasures available to everyone and ensuring their financial sustainability. One possible solution could be to offer reduced admission fees for students, seniors, and low-income individuals while charging regular fees for others.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_069a8f3a1e6822f494173fe5', 'ielts_group_358ebc2ab4dc75e4a754717b', 'PART_3', 3, 'What kinds of things make a museum or art gallery an interesting place to visit?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"So, what makes a museum or art gallery interesting? Well, for starters, it should have a diverse and well-curated collection that’s both engaging and informative. The staff should also be knowledgeable and passionate about the artworks or artefacts on display and be able to provide context and insight. In addition, the museum or gallery’s architecture and design should complement the exhibits, creating an immersive and memorable experience for visitors. Finally, interactive exhibits, multimedia displays, and hands-on activities can also make a museum or art gallery more engaging and accessible to the mass audience. Ultimately, a great museum or art gallery should spark curiosity, inspire imagination, and deepen our understanding of the world around us.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_55f2d9181b07e66b08ac72a0', 'ielts_group_358ebc2ab4dc75e4a754717b', 'PART_3', 4, 'Why, do you think, do some people book package holidays rather than travelling independently?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, there are a few reasons for this. First of all, booking a package holiday is super convenient as everything is already sorted out for you. This is especially great if you’re short on time or if you’re going to a destination you’re not familiar with. Plus, you can often get better deals and discounts on accommodation, transportation, and activities with a package tour. And last but not least, if you’re a social butterfly, a package tour can be a great way to make new friends, as group tours are often included.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ff00c283385861878d6989fa', 'ielts_group_358ebc2ab4dc75e4a754717b', 'PART_3', 5, 'Would you say that large numbers of tourists cause problems for local people?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Oh yeah, definitely. When a lot of tourists descend on a destination, it can be tough on the local community. Resources like water, energy, and transportation can get stretched thin, which leads to more pollution and traffic congestion. This can be a real drag for the environment and locals. Plus, tourists don’t always understand the local customs and traditions, which can lead to misunderstandings and conflicts. Finally, when tourism drives up prices, it can make life difficult for locals who are just trying to get by.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7766a0069cf64b2ca1496c7a', 'ielts_group_358ebc2ab4dc75e4a754717b', 'PART_3', 6, 'What sort of impact can large holiday resorts have on the environment?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Big holiday resorts can really mess with the environment. For one thing, building these resorts can lead to deforestation, habitat destruction, and ecosystem disruption. Plus, these resorts use a lot of energy, water, and other resources, which can put a real strain on the local supply. This often leads to more pollution and waste, which is obviously not great. Additionally, the resorts themselves generate a lot of waste and sewage, which can seriously mess with local water sources and the marine life that depends on them. Finally, all the extra tourism can lead to more traffic, noise pollution, and infrastructure damage, which can really put a damper on the local environment.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6d76faabd8589af4d751e510', 'ielts_group_ed9e5e66931cfb7c9211d5b2', 'PART_1', 1, 'How often do you buy things online? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I buy things online pretty often, like three or four times a week. I often buy everyday essentials or small items that are hard to find in physical stores. It’s really economical and also super handy and straightforward to be able to shop from the comfort of my own home without having to leave and deal with crowds or traffic.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_26731b16d1824dc672e34a26', 'ielts_group_ed9e5e66931cfb7c9211d5b2', 'PART_1', 2, 'What was the last thing you bought online?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it should be the headphone that I bought the other week. I had been wanting to get myself a new headphone, but the one that I saw at the physical store was too pricey for me. Luckily there was an online promotion on the headphone, so I immediately placed an order online and received it in just a few days. It was a hassle-free experience and I was quite pleased with my purchase.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f6d78fdf526694da346503d6', 'ielts_group_ed9e5e66931cfb7c9211d5b2', 'PART_1', 3, 'Do you ever see things in shops and then buy them online? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, although I don’t do that very often, sometimes when I see something I really like but with a high price, I’ll go online to see if there’s a better price for the item. For example, just the other day, I saw a jacket that really caught my eye in the store, but the price was too steep, so I searched for it online and found the exact same style at a much lower price. I then made the purchase and received the jacket in a few days. It was really a great deal as I saved quite a lot of money.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_bb3620473e83e4514fa44f55', 'ielts_group_ed9e5e66931cfb7c9211d5b2', 'PART_1', 4, 'Do you think the popularity of online shopping is changing your town or city centre? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I definitely think that it’s changing my city, as more and more people opt for shopping from the comfort of their homes or through digital devices rather than visiting physical stores. This shift has led to a decline in foot traffic at physical stores, which has had a significant impact on businesses in my city. For example, due to the pandemic and the increasing trend of online shopping, a lot of small businesses and stores where I live have been forced to shut down, which is really a shame.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c6be4f8bd8f9ac1dcb87b783', 'ielts_group_8a3a7794d34f5c848f45317f', 'PART_2', 1, 'Describe a time when you enjoyed visiting a member of your family in their home.', '["who you visited and where they lived","why you made this visit","what happened during this visit","and explain what you enjoyed about this visit.","You will have to talk about the topic for one to two minutes.","You have one minute to think about what you are going to say.","You can make some notes to help you if you wish."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, this topic reminds me of a time when I visited my aunt and uncle in their home. They lived in a charming little cottage in the countryside, surrounded by trees and gardens. And just a few months ago, they finished redecorating their home, so they invited me and my parents over for a housewarming party,\nAfter we arrived there, my aunt and uncle warmly welcomed us and showed us around their newly decorated two-floored home. I was really impressed by their distinctive decoration style, a perfect mix of Chinese and American rustic style. After that, they gave us a tour of their lovely garden, where they shared about the various plants and flowers that they were taking care of.\nLater in the day, we took a long walk in the nearby woods, where we admired the gorgeous views and took lots of pictures together. I clearly remember we came across a little stream flowing through the woods, and we even caught some crabs and fish barefoot, which was tons of fun!\nAfter that, we headed back home and enjoyed a family meal together. I’d say it was really a great experience and we all had a wonderful time together! What I enjoyed most about this visit was the sense of peace and relaxation that I had there. The tranquility of the countryside, combined with the warmth and hospitality of my aunt and uncle, created a perfect atmosphere for unwinding and connecting with my family. It was a memorable and enjoyable experience and I really look forward to visiting their home again.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_17f1ec7d065f23dae26a088a', 'ielts_group_8a3a7794d34f5c848f45317f', 'PART_3', 1, 'When do families celebrate together in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, families in my country generally celebrate together during various traditional holidays, such as Chinese New Year, Mid-Autumn Festival, the Dragon Boat Festival and so on. During these holidays, especially the Chinese New Year, family members will gather together for family reunions no matter the distance. Of course, when it comes to birthdays or anniversaries of family members, people will also come together for a big family celebration, in which they eat, exchange gifts, and share updates with each other.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2300976987df9e5e738d3b6b', 'ielts_group_8a3a7794d34f5c848f45317f', 'PART_3', 2, 'How often do all the generations in a family come together in your country？', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, although Chinese people have a strong sense of family values, I would say all the generations in family don’t gather together as often as they used to. And one major reason I think is the increasing geographic mobility of families, with members often living in different parts of the country for work or studies, which makes it difficult to coordinate family gatherings that bring everyone together. Also, technological advancements such as social media and video calls have provided an alternative way to stay in touch with family members who live far away without needing to physically be in the same location. Although this makes it easier to maintain relationships, it also sadly means the reduction in face-to-face interactions for all the generations in a family.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d512ffb9a7c2733ab59faaf0', 'ielts_group_8a3a7794d34f5c848f45317f', 'PART_3', 3, 'Why is it that some people might not enjoy attending family occasions?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I guess one reason could be that some people are too reserved or withdrawn to be around others and might find it a bit uncomfortable or even overwhelming to have to socialize with others, even if they’re related. Another reason I can think of is that some people might be put off by the traditions that are expected to be followed at the family gathering such as the strict dress code or certain types of behavior. This is quite common among Generation Z, who may feel constrained and thus reluctant to participate in family events.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8b94b124ed6d641692eb0ac1', 'ielts_group_8a3a7794d34f5c848f45317f', 'PART_3', 4, 'Do you think it is a good thing for parents to help their children with schoolwork?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think it’s generally a good thing for parents to offer help with their children’s schoolwork. Firstly, when parents assist their children with schoolwork, they can provide guidance and support that can aid in understanding and completing assignments more effectively, which can lead to improved academic performance and better grades. Also, helping with schoolwork is a means for parents to show their concern for their child’s education and desire to be engaged in their life. This can obviously help to strengthen the parent-child relationship and enhance communication between family members. Having said that, it’s important for children to learn how to be independent and take responsibility for their own learning, so parents shouldn’t involve too much in the guidance of their child’s schoolwork.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9933344e4be0398d7c7ef8e1', 'ielts_group_8a3a7794d34f5c848f45317f', 'PART_3', 5, 'How important do you think it is for families to eat together at least once a day?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, in my view eating together as a family at least once a day is vitally important as it can provide a great opportunity for family members to sit together and connect with each other by having small talk or sharing updates. This can help to create a sense of togetherness and build stronger relationships between family members. Also, it helps parents to monitor their children’s eating habits and ensure that they are getting the proper nutrition. In fact, children who regularly eat meals with their families are more likely to have a healthy body weight and less likely to develop unhealthy eating behaviors such as binge eating or dieting.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a7337c437c4e076fc772a729', 'ielts_group_8a3a7794d34f5c848f45317f', 'PART_3', 6, 'Do you believe that everyone in a family should share household tasks?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I strongly believe that everyone should contribute when it comes to household chores, because sharing household tasks can promote a sense of equality and responsibility among family members, and it can also help to relieve the workload for any one individual in the family, creating a more harmonious and cooperative living environment. Also, sharing household tasks is a good way to teach children important life skills such as how to be responsible and take care of themselves and their surroundings.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_dd566d8e1c35164e052f9ffe', 'ielts_group_cb613aea06b5ce17b8c894dc', 'PART_1', 1, 'How many hours do you usually sleep at night?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I normally get around 6 or 7 hours of sleep per night, but sometimes when I need to stay up for work or studying, I end up getting much less sleep – sometimes as little as 5 hours or even fewer. I’ve always tried to get enough time for sleep though, so that I can be more alert, energized, and productive throughout the day.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0b256a2658f6f15818323397', 'ielts_group_cb613aea06b5ce17b8c894dc', 'PART_1', 2, 'Do you sometimes sleep during the day? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I do take a nap during the day from time to time, especially after lunch or if I didn’t get enough sleep the night before, and I find it a good way to recharge my batteries. That said, I try not to oversleep because too much sleep can somehow make me more tired and groggy.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4ffc3fa81f8ec292022f5d83', 'ielts_group_cb613aea06b5ce17b8c894dc', 'PART_1', 3, 'What do you do if you can’t get to sleep at night? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, if I have trouble getting to sleep at night, I usually try to relax by either reading a book or listening to some soothing music. More often than not, this will help me to fall asleep pretty quickly. But if that doesn’t work, I’ll resort to doing some light exercise to wear myself out to make sure I can go to sleep before it gets too late.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7ce280c7d6bb8b9fa82261b3', 'ielts_group_cb613aea06b5ce17b8c894dc', 'PART_1', 4, 'Do you ever remember the dreams you’ve had while you were asleep?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I can’t really remember my dreams when I go to sleep at night. Sometimes I’m aware that I had a dream when I wake up in the morning, but the harder I try to recollect it, the hazier it becomes. I really wish I could easily store and replay my dreams, because some of them are so captivating that it would be a shame to let them fade away from memory.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b22a3c00148ab426da73bb32', 'ielts_group_07ef8811b7c8bc30e44f5e8b', 'PART_2', 1, 'Describe a time when you met someone who you became good friends with.', '["who you met when and where you met this person what you thought about this person when you first met and explain why you think you became good friends with this person.","You will have to talk about the topic for one to two minutes. You have one minute to think about what you are going to say. You can make some notes to help you if you wish."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"For this topic, I’d like to talk about Jack, a friend I made during my freshman year in college. Back then, we were both in the same English class and assigned to work together on a project.\nTo be honest, Jack didn’t make much of an impression on me. I mean, he was pretty quiet and reserved, and he didn’t seem willing to contribute in the first place. But as we started working on it, I began to see more sides of his personality. He was actually a pretty solid guy with a great sense of humor. He was also quite smart and creative, who came up with plenty of good ideas for our project. We cooperated pretty well and ended up with a pretty good result on the project.\nAfter that, we became friends and I was surprised to find that we actually had a lot in common. We were both avid readers and big fans of movies and traveling. We even joined a book club together and would often have movie nights or go on weekend trips.\nWhy we became good friends? Well, I think it’s because we both felt so comfortable being ourselves around each other, and we had a strong foundation of mutual respect and trust. We also supported each other through tough times and celebrated each other’s successes. Even though it’s been many years since we graduated and we now live in different parts of the country, we still keep in touch and make an effort to visit each other whenever possible.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_223fc7da1390ddd6346eb8a0', 'ielts_group_07ef8811b7c8bc30e44f5e8b', 'PART_3', 1, 'How important is it for children to have lots of friends at school?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, although having friends at school can provide children with emotional support, companionship, and opportunities for socialization and play, I don’t think it’s necessarily essential for them to have a large number of friends as it could end up being distracting for their studies or lead to social anxiety due to the time commitment required to maintain all those friendships. For this reason, I think when it comes to friendship, quality is more important than quantity. In other words, children who have one or two close friends may be just as socially and emotionally well-adjusted as those who have many friends. So, the number of friends they have at school may not matter as much as feeling supported and valued, and having healthy relationships with their peers.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a55510a2d251703cc412f1cd', 'ielts_group_07ef8811b7c8bc30e44f5e8b', 'PART_3', 2, 'Do you think it is wrong for parents to influence which friends their children have?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I don’t think it’s wrong. I mean, parents have a responsibility to protect and guide their children in making good choices, so it’s natural and perfectly reasonable for them to want to steer their children towards positive friendships, and to express concerns about friends who may be a negative influence. Having said that, it’s also important for parents to strike a balance between guidance and control. I mean, if parents intervene excessively in their children’s selection of friends, it may cause a loss of trust between the parent and the child, and might even push the child to rebel against their parents’ wishes.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_295ba3f7ad65597b8265fa37', 'ielts_group_07ef8811b7c8bc30e44f5e8b', 'PART_3', 3, 'Why do you think children often choose different friends as they get older?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think the main reason for changes in children’s friendships is due to their natural development process. As they grow up, they go through several different stages of development that can affect their social circles. For instance, when they’re younger, children often make friends over shared activities like playing sports together. However, as they mature, they may become more independent and assertive, which can lead them to seek out different types of friendships and to be more selective about who they spend time with. Also, external factors like moving to a new neighborhood or attending a different school can significantly impact their social lives, leading to new opportunities to make new friends and join new social circles.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a5ea744c98794002c70ed4b8', 'ielts_group_07ef8811b7c8bc30e44f5e8b', 'PART_3', 4, 'If a person is moving to a new town, what is a good way for them to make friends?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think an effective way to make new friends when they’re relocating to a new town is by joining a local club or organization that shares their interests or hobbies. These places can offer great opportunities for them to meet like-minded people and build connections with them through shared activities such as sports. It’s also a good idea to make friends through social media platforms like Facebook or Instagram, where they can look for groups or pages that are relevant to what they’re interested in or the things that they have in common with the locals, and this can generally help them get to know more people and expand their network of friends.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9ea38a4c011c2b7495a441fa', 'ielts_group_07ef8811b7c8bc30e44f5e8b', 'PART_3', 5, 'Can you think of any disadvantages of making new friends online?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, one big challenge that I can think of when you’re trying to make new friends on the Internet is that because you never really know who you’re talking to, there’s always the possibility that they may misrepresent themselves by using fake names or profile pictures to hide their true identity, which can be dangerous and thus get in the way of establishing trust, building connection and forming a genuine friendship with the person. Another drawback is that although it can be quite straightforward to hit it off with someone online, it usually takes a lot of time and effort to maintain the friendship, and once you become busy or take a break from the Internet for a while, the online friendship can easily drift apart.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6e4898b82094e507b284793b', 'ielts_group_07ef8811b7c8bc30e44f5e8b', 'PART_3', 6, 'Would you say it is harder for people to make new friends as they get older?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I would say so, and it is generally more challenging because when people get older, they tend to have fewer opportunities to meet new people due to changes in life circumstances, such as retirement, relocation, or a decrease in social activities. Also, they may become more set in their ways and less open to new experiences and perspectives, and this can make it more difficult for them to make new connections and form new friendships. Having said that, there’re still plenty of opportunities available for those who are getting on in years to socialize and make friends, such as community events or volunteer work. So, it’s important for them to be more proactive and engage themselves in those activities to seek out social relationships so that they can feel more supported or valued, even at the late stage of their life.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1311737ab35f09f9249ea4ff', 'ielts_group_29202ba9f987d6c4ab97215b', 'PART_1', 1, 'Can you find food from many different countries where you live? [Why/Why not?] .', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Oh, definitely! The city I currently live in is a real economic and cultural hub with a large population of foreigners, which is likely the reason why we’re spoiled for choice when it comes to international food. What I mean is that you can find a wide range of restaurants serving Italian, American, Japanese, and even Mexican cuisines. So, I would say it’s like a paradise for foodies.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4d6faf483a2d36ae954b3afd', 'ielts_group_29202ba9f987d6c4ab97215b', 'PART_1', 2, 'How often do you eat typical food from other countries? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, in my case, it’s pretty rare, basically because I’m more used to the taste of Chinese cuisine or homemade dishes. Yet I would check out local snacks known for their exotic flavours when I go on a trip, as it makes an important part of travelling.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_644e8ea83fc897f23bb9682c', 'ielts_group_29202ba9f987d6c4ab97215b', 'PART_1', 3, 'Have you ever tried making food from another country? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yeah, I’ve tried my hand at making some foreign dishes. In fact, during my vacation in Chiang Mai, I had the opportunity to attend a cooking class where a local chef demonstrated how to prepare authentic Thai dishes such as green curry chicken and mango sticky rice. But I rarely attempt to do this at home, as I don’t want to end up with a disaster in my kitchen, with burned pots and inedible meals. In a word, it’s too much effort.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ca8f166c750773492b22731a', 'ielts_group_29202ba9f987d6c4ab97215b', 'PART_1', 4, 'What food from your country would you recommend to people from other countries? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Oh, that’s really tough to pick just one or two types of food, as there are countless must-try dishes out there in China. But the one on the top of my list would be Dim Sum, especially when you travel to southern China. Believe it or not, it’s like a party on a plate, with all these palatable bite-sized goodies like dumplings, buns, and rolls. Yet it’s more than just the taste. What I mean is that it’s the hustle and bustle vibes of the dim sum restaurants that you shouldn’t miss.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB)
ON CONFLICT (id) DO UPDATE SET
    topic_id = EXCLUDED.topic_id,
    part = EXCLUDED.part,
    sort_no = EXCLUDED.sort_no,
    question_text = EXCLUDED.question_text,
    cue_points = EXCLUDED.cue_points,
    recommended_expressions = EXCLUDED.recommended_expressions;

INSERT INTO ielts_question (
    id, topic_id, part, sort_no, question_text, cue_points, recommended_expressions
)
VALUES
    ('ielts_q_1a3eddae51a64bfc08c20778', 'ielts_group_3941dfe59fa9ef46cfbf514a', 'PART_2', 1, 'Describe a law that was introduced in your country and that you thought was a very good idea.', '["what the law was","who introduced it","when and why it was introduced","and explain why you thought this law was such a good idea."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"The law I’ve chosen to talk about is the nationwide crackdown on smoking in public places. I’m not sure of the exact year when it was rolled out, but I guess it was roughly ten years ago.\n\nIn my country, smoking in public places would run rampant back then. That’s why before this law kicked in, chances were high that you would see someone puffing away nearby in restaurants, parks or even indoor workplaces.\n\nI believe the government saw the urgent need to address this issue head-on, so they enacted this law. Moreover, I’m convinced that this law had full support from the public for the detrimental impact on public health and well-being.\n\nIf the law hadn’t been implemented, the air in public places would have continued to be filled with toxic fumes, proven to bring about respiratory diseases and even lung cancer. Nowadays, violators of this regulation face fines and penalties for a definite. Additionally, as I mentioned, you may encounter social disapproval, such as receiving glares and comments or being publicly criticised on social media, as people are increasingly intolerant of this behaviour.\n\nI reckon this law was a stroke of genius. Without its introduction, non-smokers would still suffer from the harmful effects of secondhand smoke, so that is one reason why I say so. Another reason is that it prompts smokers to reflect on their habit and potentially quit it altogether. To put it in a nutshell, the crackdown on smoking in public places serves as one of the best examples of proactive governance in my country.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cfdd938245ca8c14d292d41d', 'ielts_group_3941dfe59fa9ef46cfbf514a', 'PART_3', 1, 'What kinds of rules are common in a school?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, when it comes to rules in schools, you’ve got a whole mix of stuff going on. I mean, there are the usual academic rules, like showing up to class on time and getting your homework done by the deadline. But it doesn’t stop there. You’ve also got rules about how to behave, like treating your teachers with respect and following the dress code. And let’s not forget about zero-tolerance policies for things like bullying or cheating. In a word, it’s all about keeping things in line, making sure everyone feels safe, and creating an environment where learning can really take off.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_69635814c399e9f2ba7b1e38', 'ielts_group_3941dfe59fa9ef46cfbf514a', 'PART_3', 2, 'How important is it to have rules in a school?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"They’re absolutely crucial. It seems to me that they’re the backbone of maintaining order and safety in schools. What I mean is that they set the boundaries for how children are supposed to act. Without them, there would be chaos. But it’s not just about keeping order, rules also teach children some real-life skills they’ll need down the road. Like how to manage their time properly, and how to control themselves even when they don’t feel like it. And let’s not forget about respect, as rules can teach children how to respect others and space, which is pretty important in the real world.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_bf33b4f7adcb1f2e8efe124f', 'ielts_group_3941dfe59fa9ef46cfbf514a', 'PART_3', 3, 'What do you recommend should happen if children break school rules?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, when it comes to kids breaking school rules, I believe it’s important to handle each situation on a case-by-case basis. For minor issues like chatting in class or skipping homework, having a conversation with them about why the rule matters and getting them to straighten up might address the problem. But when it’s serious stuff, like bullying or vandalism, it’s time to take decisive action. Teachers may need to bring out the big guns, like suspension or involving the police if necessary. Ultimately, it’s all about teaching them the importance of their actions and helping them learn from their mistakes. What matters most is guiding them towards growth and improvement for the future.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f9fcbce196e38c1bf0db5f4b', 'ielts_group_3941dfe59fa9ef46cfbf514a', 'PART_3', 4, 'Can you suggest why many students decide to study law at university?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, there’re a couple of reasons for this. Firstly, it’s their inner drive to chase after justice and fairness, maybe even leave a mark on society. In other words, it’s common for young people to be passionate about making the world better by devoting themselves to the legal system. On top of that, their potential job opportunities are quite attractive. I mean, being a lawyer, a judge, or working for the government can probably bring them decent pay and prestigious status in the long run. So, it’s like a mix of passion and the lure of a bright future.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_479d9bf9739ee12195854fba', 'ielts_group_3941dfe59fa9ef46cfbf514a', 'PART_3', 5, 'What are the key personal qualities needed to be a successful lawyer?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, when it comes to being a successful lawyer, there are a few key qualities that really stand out. First and foremost, they should have a sharp analytical mind. In other words, they must be able to tackle those complex cases with laser-like precision. Plus, they should be excellent at communicating, I mean, a good lawyer should be a smooth talker in the courtroom to sway judges with silver-tongued arguments. Last but definitely not least, they should be as calm as a cucumber to make sound judgements even in challenging situations.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_299b471e990d2ba8533cf524', 'ielts_group_3941dfe59fa9ef46cfbf514a', 'PART_3', 6, 'Do you agree that working in the legal profession is very stressful?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I completely agree. Working in the legal profession can be highly stressful indeed. As a lawyer, you have to contend with tight deadlines, high-stakes cases, and clients who seem to expect the world from you. Plus, you should be super meticulous, which is part and parcel of this job. So, you’re constantly digging into every little detail of a case, trying to find that one crucial clue to help your client out. Yeah, overall, it’s definitely a tough gig.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e377656b2fa47586ff5e45c8', 'ielts_group_de52fe85145ede9c154e1fbe', 'PART_1', 1, 'Have you travelled a lot by plane? [To where?/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I’ve flown to various destinations for work, business, and holidays. Although I’m not particularly fond of flying, with the long-distance travel to the airport and the anxiety associated with take-off, it has been necessary for these purposes.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a814ca6cdb0816c29e6b50d1', 'ielts_group_de52fe85145ede9c154e1fbe', 'PART_1', 2, 'Why do you think some people enjoy travelling by plane?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yeah, you know, some people just love hopping on planes. They’re all about that sense of adventure and exploring new places, you know? Plus, there’s the whole convenience thing – being able to zip across the globe in no time. And let’s not forget those spectacular views from up there and the excitement of taking off and landing. It’s like a little adrenaline rush every time.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_afa3d4afc1aa6c59567f80cd', 'ielts_group_de52fe85145ede9c154e1fbe', 'PART_1', 3, 'Would you like to live near an airport? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Absolutely not. Living near an airport is just not my thing. I mean, airports are usually tucked away in the suburbs, far from the lively city atmosphere that I thrive in. And let’s be honest, the non-stop racket from planes coming and going would totally destroy any chance of having some peace and quiet. Yeah, I’ll pass on that one for sure.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6ce1e09bb00cee4772002dbc', 'ielts_group_de52fe85145ede9c154e1fbe', 'PART_1', 4, 'In the future, do you think that you will travel by plane more often? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I’m not sure. I mean, I might end up using high-speed railways more for domestic trips in the future. With China’s strong railway network, it feels like a pretty solid option, and I’d rather steer clear of any potential flight headaches, like flight cancellations or delays. But when heading overseas, I’ll opt for planes.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fa195b490a816a5ec339f2ed', 'ielts_group_4911a974930a69e3b0c65383', 'PART_2', 1, 'Describe a person from your country who has won a prize, award or medal.', '["who this person is","which prize, award or medal they received what they did to win this","and explain whether you think it was right that this person received this prize, award or medal."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"So, the person I want to talk about is Liu Cixin, a renowned Chinese author, particularly famous for his sci-fi masterpiece, The Three-Body series.\n\nI’ve known about Liu Cixin since my middle school days. Back then, he was just a budding writer, publishing his captivating short stories in a magazine called Science Fiction World. He wasn’t quite the household name he is today, but even back then, his ability to weave tales was undeniable. His stories had this magnetic quality to them that just drew you in and held you spellbound, often prompting deep reflections on the relationship between humanity and technology, as well as on human nature itself.\n\nSo, fast forward a bit, and Liu Cixin totally nails it with The Three-Body Problem, the first book in his trilogy. And guess what? He clinches the Hugo Award for Best Novel, which is like the holy grail for sci-fi writers, you know? I mean winning it is every writer’s dream. So, you can imagine the buzz when Liu Cixin snagged this prestigious award for his outstanding work.\n\nNow, here’s the thing – I’ve followed his journey from those early days, and seeing him achieve such monumental success is truly inspiring. He’s put in the hard work, honing his craft and pouring his passion into his writing. So, did he deserve that Hugo Award? Absolutely. He’s not just an exceptional writer; he’s a visionary reshaping the landscape of science fiction literature. In a word, if anyone deserved recognition, it’s him.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fa23154c433db4b6b1670a8a', 'ielts_group_4911a974930a69e3b0c65383', 'PART_3', 1, 'What types of school prizes do children in your country receive?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, in my country, kids receive a variety of prizes at school. They may take home a prize for excelling in subjects like math or science or for showcasing their artistic talents in art class, or athletic talents in sports competitions. But it’s not just about academics. By that I mean they also get rewarded for their kindness and willingness to lend a hand, such as participating in classroom cleanup or assisting their peers.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4bb774d7c3cc1d30f02e9af1', 'ielts_group_4911a974930a69e3b0c65383', 'PART_3', 2, 'What do you think are the advantages of rewarding schoolchildren for good work?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, when kids are rewarded for their hard work, it’s like a big thumbs-up, letting them know they’re on the right track. For one thing, it boosts their confidence and instills a sense of pride in their accomplishments. Additionally, it gives them an extra push to keep giving their best effort. Moreover, when their peers see their friends being rewarded, it gently encourages them to step up and make a difference.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e652dbd18dd211be257ebdb0', 'ielts_group_4911a974930a69e3b0c65383', 'PART_3', 3, 'Do you agree that it’s more important for children to receive rewards from their parents than from teachers?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Honestly, I don’t believe it’s a matter of one being more significant than the other. I’m saying that both parental and teacher rewards are part and parcel of children’s growth. Parental rewards, for instance, tend to convey love and support, providing emotional backing for kids, which is absolutely crucial for them. But then again, let’s not forget the significance of teacher rewards. They are also meaningful, as they are based on a child’s performance at school, such as taking a test or actively participating in class, offering children feedback from a more objective perspective. That’s why I’d say both types of rewards hold considerable value in their own way.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_be07acde58a8edb0ecefc939', 'ielts_group_4911a974930a69e3b0c65383', 'PART_3', 4, 'Do you think that some sportspeople (e.g., top footballers) are paid too much money?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Absolutely, their salaries are immense. By way of example, NBA superstar athletes like LeBron James or Kevin Durant are not just athletes; they’re brands for their teams or even the whole game. I suppose that’s why their contracts and endorsement deals are worth astronomical figures, which dwarf those of professionals in other industries like doctors and researchers. That being said, if we consider the popularity of the sport and the profit it generates, it could be argued that their high earnings are justified.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4b345d44ee9a43d0300f8f56', 'ielts_group_4911a974930a69e3b0c65383', 'PART_3', 5, 'Should everyone on a team get the same prize money when they win?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yeah, it might seem a bit unfair. But I would argue that different players bring different things to the table. Take, for instance, those players who score important goals or make those game-saving plays. They should get a bigger prize money because they’re crucial to the team’s success. Football clubs recognize this by giving each player their own contract, showing they’re all valued differently. But even those players who might not get as much attention still play a vital role in supporting the team. So, in the end, the money should be divided up based on how much each player helps the team out.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4e649d52ef8a99cec6a47dc8', 'ielts_group_4911a974930a69e3b0c65383', 'PART_3', 6, 'Do you agree with the view that, in sport, taking part is more important than winning?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"If you ask me, I would say participating in sports is no doubt super valuable, but personally, I’m all about winning. Don’t get me wrong, being in the game is great for growing personally, picking up tips from your rivals, and building teamwork. Plus, it’s just a blast to be out there on the field or court, giving it your all. But let’s be real: winning brings serious perks like fame, cash, and motivation to keep pushing yourself. It’s not just about the glory – it’s about the doors that winning can open for you, whether it’s sponsorship deals, recognition, or even just the satisfaction of knowing you’re the best at what you do. So, while being part of it all is cool, winning is where it’s really at for me.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2a7e21057e5b6a714f81a3ef', 'ielts_group_dae65a678d05b232a5ecc9a5', 'PART_1', 1, 'Do you prefer spending holidays with friends or with family? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, before I got married, I would definitely prefer to spend holidays with my friends. Holidays with them were always carefree and spontaneous, with no rules to follow and plenty of opportunities to have fun. But now that I have started a family, I would prefer to go on holidays with my wife and my daughter, because it’s a wonderful opportunity not only for us to strengthen our family bonds but also a chance for my little girl to explore new places and see the world through her own eyes.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1ee762bebb26e9c14482cae1', 'ielts_group_dae65a678d05b232a5ecc9a5', 'PART_1', 2, 'What kind of holiday accommodation do you like to stay in? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, as for holiday accommodation, I enjoy staying in cozy and comfortable places. I’m not too picky about luxury or extravagant accommodations. I mean, I prefer a homely atmosphere where I can feel at home. You know, a nice bed, clean facilities, and a welcoming environment, those are what I look for in holiday accommodation, even if it may go over budget.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_67e01dba21b23b1bb5c1ce43', 'ielts_group_dae65a678d05b232a5ecc9a5', 'PART_1', 3, 'What plans do you have for your next holiday?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"My next holiday plans? Well, I’ve been thinking about going on a beach getaway with my family. We’ve been very busy recently, so we really want some time to get away. I’m considering a coastal destination where we can totally switch off and simply have a great time together. The only thing is that I don’t know if I can spare enough time for that, but I’ll try my best to make it happen.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d27bcc36055c66e60ef15590', 'ielts_group_dae65a678d05b232a5ecc9a5', 'PART_1', 4, 'Is your city or region a good place for other people to visit on holiday? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think my city is an absolutely wonderful holiday destination for visitors. It’s known for the rich cultural heritage, picturesque landscapes, and great local food. It’s also visitor-friendly because of the well-developed infrastructure, especially the highly efficient transport system, which makes it super easy for people to get around. The local people are really nice and friendly too, so I highly recommend people pay a visit to my city during their holidays.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_156f6b1f2daf7bae0e3d417d', 'ielts_group_cf271b1b57f37b5e25dcbcdb', 'PART_2', 1, 'Describe a car journey you made that took longer than expected.', '["where you were going","who you were with","how you felt during the journey","and explain why this car journey took longer than expected."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"OK, I’m going to talk about a car journey I took that ended up being much longer than we anticipated. It was about five years ago, before the pandemic, three of my best friends and I had planned a trip to a neighboring province during May Day, a five-day holiday, to get away a little bit. Since all of us have driving licenses and the destination was relatively close by, we decided to go there by car.\n\nEverything was going quite smoothly in the beginning. As we drove on the motorway, we snacked, chatted, and even sang to pass the time. However, after about two hours on the road, we found ourselves stuck in a terrible traffic jam. At first, I thought it wouldn’t take too long, but it took us literally over two hours to finally break free from the congestion.\n\nRealizing that we were falling behind schedule, we decided to speed up a bit in order to catch up. But to make matters worse, we experienced a flat tire along the way. I clearly remember we spent about an hour fixing the tire, and by the time we were done, it was getting dark, and we still had a long way to go before reaching our destination.\n\nAnyway, we finally arrived at our destination around 2 or 3 o’clock in the early morning, and all of us were completely drained and in no mood for anything. We quickly checked in, took a shower, and went straight to bed. The next day, all of us overslept and ended up losing a significant portion of our time for the holiday.\n\nFor me, it was an exhausting and disappointing journey. If everything had gone according to plan, we would have arrived in the afternoon and had plenty of time to enjoy the holiday. Unfortunately, the unexpected traffic congestion and the flat tire turned our trip into a complete letdown. Next time, I don’t think I’ll travel long distances by car.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_16ed113639dc86ee5fd32276', 'ielts_group_cf271b1b57f37b5e25dcbcdb', 'PART_3', 1, 'How interested are young people in your country in learning to drive?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, young people in my country are actually quite keen on learning how to drive. And I think it’s because, for young people, driving is often seen as a really cool and glamorous thing and it can give them a sense of independence. In fact, a load of young people will choose to sign up for a driving course during like summer or winter holidays. Another reason is that, these days, having a driver’s license can open up a lot of opportunities, especially when it comes to jobs and mobility. Many young people see it as a boost to their employability. You know, being able to drive means they can take on jobs that require travel or commuting, which gives them more flexibility and options in terms of where they can work or what they can do.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_860ff8fad166f0fb8b12c4f5', 'ielts_group_cf271b1b57f37b5e25dcbcdb', 'PART_3', 2, 'What are the differences between driving in the countryside and driving in the city?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think driving in rural areas and driving in urban areas are like two different worlds. When you’re behind the wheel in the countryside, since the roads are usually less crowded with fewer traffic lights and less congestion, you can often drive along without much hassle, and you can also appreciate the scenic views, take your time, and truly enjoy the journey. On the other hand, driving in the city can be quite challenging. Because the streets are often very busy and packed with cars, buses, and pedestrians, all rushing around, you have to constantly stay alert and keep an eye on traffic signals, lane changes, and all the hustle and bustle around you. Also, parking in urban areas can be a real pain in the neck whereas it’s not a problem in rural areas because there’re a lot of open spaces to park your cars.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d4131fbdfe35b810345fbdae', 'ielts_group_cf271b1b57f37b5e25dcbcdb', 'PART_3', 3, 'Do you consider most drivers where you live to be good drivers?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, when it comes to most drivers where I live, I’d say the majority of them are pretty decent behind the wheel. They follow the rules, drive responsibly, and prioritize safety. They are well aware of the severe consequences of reckless driving or drunk driving, and they understand that engaging in such behaviors not only puts their own lives at risk but also endangers the lives of others on the road. Of course, you’ll always come across road rage or aggressive driving every now and then, but they’re the exception rather than the norm.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_899888c2e6b576958cc393b5', 'ielts_group_cf271b1b57f37b5e25dcbcdb', 'PART_3', 4, 'How popular are electric cars in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think electric cars are gaining incredible popularity in my country. I mean, electric cars used to be seen as a luxury, which were prohibitively expensive, but these days, with the government offering incentives and subsidies, their prices have been coming down, and they seem to have become increasingly commonplace. Also, in the past, people would worry about running out of battery while driving an electric car, but now, with the tremendous breakthrough in battery technology, you can go on much longer trips without having to constantly think about finding a charging station. Plus, the charging infrastructure is expanding, making it easier to recharge your electric car wherever you go.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ec20d2f360a04c6a7c17a78f', 'ielts_group_cf271b1b57f37b5e25dcbcdb', 'PART_3', 5, 'In what ways could more people be persuaded to buy electric cars?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think there are a few things that could really help talk more people into buying electric cars. One of the key factors is raising awareness. Many people still have some misconceptions or doubts about electric vehicles, so it’s important to educate them about the benefits and let them know that electric cars are not only good for the environment but also cost-effective in the long run. Another crucial aspect is improving the charging infrastructure. Although the number of charging station is on the increase, lots of people still feel uncertain about whether they can easily charge their electric cars wherever they go. So, it’s important that we have more charging stations available, both in public spaces and at home, so that people won’t feel paranoid about running out of battery power on longer trips or having difficulties finding a place to charge up.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_db8d4e62365c35784fbfbb6e', 'ielts_group_cf271b1b57f37b5e25dcbcdb', 'PART_3', 6, 'Do you think all cars will be electric one day?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it’s kind of hard to say for sure, but there’s a lot of talk about whether all cars will be electric someday. My view is that, despite the challenges like building charging infrastructure and addressing consumer preferences, with the advancements in electric vehicle technology and the global push for reducing carbon footprints, it’s just a matter of time before all drivers switch from petrol cars to electric ones, and so it’s not too crazy to imagine a world where all cars run on electricity.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0cae97a8023fe95cddf42f55', 'ielts_group_05a1753c2dc851356c08c679', 'PART_1', 1, 'Do you have a favourite café? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I do have a café that I really love. It’s a nice little café called “The haven”, which is just a few minutes’ walk from my place. The vibe there is really laid-back and welcoming, and the coffee is always superb. It’s my favorite hangout to catch up with friends or just enjoy a bit of quiet time to myself.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4f41b969724f05a48ec40e0a', 'ielts_group_05a1753c2dc851356c08c679', 'PART_1', 2, 'Do you often go to cafés by yourself? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Oh yes. Oftentimes, I go to cafés alone and I quite enjoy it. I’m kind of introverted, so compared with going there with friends, which can make me feel a bit inhibited or awkward, I personally find it a better way for me to unwind and have some me time without any distractions.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f2b1e7331471d74c69b59ec1', 'ielts_group_05a1753c2dc851356c08c679', 'PART_1', 3, 'What do you think helps to make a café very popular? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think one of the most important things is the quality of the food and drinks served there. If a café offers tasty and unique options, it’s more likely to attract customers. Also, the overall ambiance and vibe of the place can contribute to the popularity of a café. An inviting atmosphere with pleasant décor, soothing music, and even a bit of that “local hangout” feel can really draw people in. And of course, the location matters too. I mean, a café that’s conveniently situated and easy to access is definitely going to have an edge over its competitors.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6f52f8560a8060d0e0c361d3', 'ielts_group_05a1753c2dc851356c08c679', 'PART_1', 4, 'Why do some people prefer cafés that are part of large chains, rather than small, local cafés?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think it’s mainly because these chain cafés offer a sense of familiarity and consistency. They often have standardized menus, similar layouts, and professional service, which can be comforting for some people. Also, compared with local cafés, which are often located at some certain spots, chain cafés, like Starbucks, you know, one of the most famous café brands in my country, are much more easily accessible, making them more appealing to coffee lovers.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a07588f78ab877315b7fbd2e', 'ielts_group_bc3f8dba11e4bde21e48cb76', 'PART_2', 1, 'Describe a place you visited that has

beautiful views.', '["where this place is","when and why you visited it","what views you can see from this place","and explain why you think these views are so beautiful."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"OK, I’m going to talk about Jiuzhaigou Valley, a place I visited that captivated me with its stunning views. Jiuzhaigou Valley is located in the northern part of Sichuan Province in China. It’s also a UNESCO World Heritage site.\n\nAbout five years ago, I had the opportunity to visit this enchanting place during the summer holidays with my family. I decided to go there because I have a great passion for exploring natural scenic spots, and after I had seen some amazing pictures of its vibrant colored lakes and picturesque landscapes on social media, I was instantly impressed, so I booked our tickets and set off with my family the next day.\n\nAs I arrived there, I felt like I was stepping into a wonderland. The serene landscapes, the dense and colorful forests, and the majestic snow-capped peaks in the distance, everything was absolutely stunning. I just couldn’t help taking pictures and each of them taken was wallpaper worthy. As we walked along the footpaths, I came across these remarkable crystal-clear turquoise lakes, which were also what impressed me most. They were so clear that I could see the vivid colors and intricate details of the submerged vegetation and rocks beneath the surface. It was like looking into a window to another world, which was unbelievably beautiful. Standing by the edge of these lakes, I felt completely relaxed, as if time had paused just for me.\n\nBut it was a shame that it rained that day, so we didn’t spend much time exploring that place, and due to our schedule, we left for another destination the next day. However, I was still deeply impressed by how gorgeous Jiuzhaigou Valley was. I would say I’m pretty well-traveled, but there’s never been a place like that that makes me want to visit again.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_677af956d5bc6595ad9566f1', 'ielts_group_bc3f8dba11e4bde21e48cb76', 'PART_3', 1, 'Do you agree that most beauty products are a waste of money?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I wouldn’t say that most beauty products are a waste of money. I mean, some beauty products, like skincare or makeup items, can really make a difference for many people on enhancing their appearance, boosting their confidence, or addressing specific skincare concerns. However, some high-end beauty products are just way too overpriced, with the actual cost of the ingredients being a tiny fraction of the retail price. And the claims they make on their products are often stretching or even unrealistic. Cosmetic companies pour money into advertising, hyping up their products, but the actual effect of the products often fail to live up to the hype. That’s why it’s important for consumers to do their homework and pick products that really meet their needs and budget.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_92e951948e910f799b6e9b9a', 'ielts_group_bc3f8dba11e4bde21e48cb76', 'PART_3', 2, 'How does the beauty industry advertise its products so successfully?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, frankly, the beauty industry is truly masterful when it comes to marketing and advertising, and I think a big part of it is playing on those deep-seated insecurities that a lot of people have about their appearance. Cosmetic companies know exactly how to trigger that sense of not being good enough, and then offer these “magical” solutions that are going to transform them. Also, the visuals they use in their adverts are just captivating. They use flawless models and aspirational imagery to create the illusion that if you just buy this product, you’ll achieve that level of perfection and beauty too. Social media platforms like Instagram and YouTube have also contributed to the success of beauty product advertising. Influencers and celebrities team up with brands, promoting products and sharing their personal experiences, which can be incredibly influential to consumers.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_88491e9a764f82dcf47b7d5a', 'ielts_group_bc3f8dba11e4bde21e48cb76', 'PART_3', 3, 'What do you think of the view that beauty products should not be advertised to children?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I absolutely agree with this and I believe it’s really inappropriate and unethical that the beauty industry targets children with their marketing. At that impressionable age, kids are already so vulnerable to insecurities and feelings of not measuring up. Constantly sending messages that suggest they need to look a certain way or use specific products can lead to body image problems and low self-esteem. Instead, I think the focus should be on promoting healthy habits, self-acceptance, and education about skincare and personal hygiene. Advertising targeted towards children should prioritize their well-being and development rather than promoting beauty standards.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b0b0efe473d27679d45d21e3', 'ielts_group_bc3f8dba11e4bde21e48cb76', 'PART_3', 4, 'Why do many people equate youth with beauty?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I’d say it’s probably because, for many people, youth is linked with vitality, energy, and overall good health. Having smooth skin, lively hair, and a youthful look is seen as appealing and attractive. Also, societal standards and media influence play a significant role in this kind of mindset. Advertisements and popular culture often showcase young models and celebrities, reinforcing the idea that being young equals being beautiful.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8ea5c3d467590f0248745cb9', 'ielts_group_bc3f8dba11e4bde21e48cb76', 'PART_3', 5, 'Do you think that being beautiful could affect a person’s success in life? Why might society’s ideas about beauty change over time?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think being physically attractive can definitely gain you an edge over others. Research shows these people are more likely to be seen as competent, trustworthy, and likeable, and so people are more willing to offer opportunities or privileges to them. Taking the film and television industry as an example, it’s often the case that good-looking people have a higher chance of being discovered by talent scouts, then landing auditions, and shooting to fame overnight. Likewise, in the job market, companies, more often than not, favor the candidates who are more attractive over those with an average appearance, even if they’re all qualified for the position. Having said that, lasting success is not just about what’s on the surface. I mean, beauty might open some doors for you, but it’s your qualities, like your skills, personality, and hard work that keep your success going; otherwise, the success will be just a flash in the pan.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_757dc002aec12c185d0526e4', 'ielts_group_19667131ad766ba4769dff54', 'PART_1', 1, '1. How much walking do you do in your daily life?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Quite a lot. I can’t stand having a sedentary lifestyle. In fact, I make a point of taking a brisk 30-minute walk after lunch or in the evening to hit my daily step goal and clear my head. It’s become a non-negotiable part of my routine and my favorite way to unwind.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3b1a691fe9d352a1e32545d9', 'ielts_group_19667131ad766ba4769dff54', 'PART_1', 2, '2. Did you walk more when you were at school than now?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Oh, absolutely! Back in school, I was forever dashing between classes, sprinting to the canteen, or hustling to the library—constantly on the move. These days, though, unless I deliberately carve out time for it, I don’t walk nearly as much.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_05b07d16dfe2a3f1f4ae166d', 'ielts_group_19667131ad766ba4769dff54', 'PART_1', 3, '3. What places are there to go for a walk near where you live?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"At the moment, I live in a neighborhood right in the heart of the city. Fortunately, we’re surrounded by several parks with lush green spaces that are perfect for leisurely strolls. But my absolute favorite is the riverside footpath—it offers expansive open spaces with picturesque views of passing boats, which always feels like a breath of fresh air from urban life.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c4825854a10b976145e27982', 'ielts_group_19667131ad766ba4769dff54', 'PART_1', 4, '4. Would you ever like to go on a walking holiday?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"To be honest, I’ve never tried that, but I’m absolutely keen to give it a shot. Trekking through off-the-beaten-track locations like mountains, coastal paths, and forests sounds amazing. It must be challenging to cover long distances on foot, but the rewards would be incredible.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_21c6ef5347e6bd84f0adcbb1', 'ielts_group_c7b9e7d256bbe46d29d9264d', 'PART_2', 1, 'Describe a play or a film you have seen that you would like to see again with friends.', '["what play or film you’d like to go to see again","who you would go with","what other people have said about this play or film","and explain why you would like to see this play or film again with friends."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I’d like to talk about a film I’d love to rewatch with friends, Perfect Days, directed by Wim Wenders.\n\nHonestly, it’s not a typical action-packed blockbuster, but it’s a quiet gem that has stuck with me since I first watched it. The story follows Hirayama, a public toilet cleaner in Tokyo, who leads a super-minimal life. He lives in a tiny apartment and follows the same routine every day, but he’s spiritually wealthy. His attention to little things—like sunlight filtering through leaves or the cassette tapes he plays in his old van—makes me rethink what happiness really means.\n\nI want to watch this film again with my friend Rene, who’s a real movie buff. She’s always had this knack for finding hidden cinematic treasures and has great taste in arthouse films like this. With news of a big-screen re-release in China, we’re planning to catch it in theatres.\n\nI’ve read several reviews online. Critics went wild over this film. Some called it “a meditation on modern life”, while others said it’s “too slow yet beautiful”. But everyone agrees the acting is next-level, especially in the final scene: tears flow silently as Hirayama drives to Feeling Good, a moment that embodies pure cinematic magic.\n\nWhy rewatch it with friends? Well, when I first watched it, I was just absorbing the vibe. But since this film is layered like an onion, I want to catch those subtle details I missed, like how his daily routines shift almost invisibly. Plus, Rene and I always have deep conversations after watching such films. In a nutshell, this film is a constant reminder to rethink our approach to life.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d55dba0ad54689ab6e96f2c4', 'ielts_group_c7b9e7d256bbe46d29d9264d', 'PART_3', 1, '1. What are the most popular kinds of plays or shows at theatres in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, to put it bluntly, modern local plays and stand-up comedy are absolutely dominating China’s theatre scene right now. I mean, if you walk into any theatre in Shanghai, you’ll find half the posters feature millennials’ job burnout or dating disasters, all served with dark humour that hits too close to home. Sure, Broadway musicals like Cats still sell out in big cities for their glamour, but the real hype is in shows that let people laugh through the hardships of life. Frankly, that’s exactly the catharsis busy city dwellers crave these days.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_351ab70ee1062567580e49c8', 'ielts_group_c7b9e7d256bbe46d29d9264d', 'PART_3', 2, '2. How easy is it to get tickets to the theatre?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"To be honest, getting theatre tickets in China is pretty straightforward these days. You can still buy at the box office, but nowadays most people just book through apps like Damai or Maoyan with just a few taps. That said, the real issue is the monopoly-like control by these platforms, which sometimes leads to chaotic sales for popular shows. Take Broadway hits like The Phantom of the Opera or star-studded productions—tickets vanish within minutes, leaving desperate fans at the mercy of scalpers jacking up prices even threefold. Honestly, while technology makes access easier, the system’s still stacked against ordinary theatregoers for high-demand performances.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ed9514e26f3623fb8f176b5e', 'ielts_group_c7b9e7d256bbe46d29d9264d', 'PART_3', 3, '3. Do you think theatres need to do more to attract younger audiences?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, absolutely! Take traditional Chinese opera as an example—many young folks find the plots and language heavy-going. That’s why theatres need to modernize these classics. Take for example, the Youth Edition Peony Pavilion has shortened the runtime and added subtitles, which made it a hit with students. On top of that, theatres should boost their social media influence—imagine promoting shows through short videos or selling creative products like opera-themed phone cases. Lastly, student discounts are essential since tickets can be unaffordable for them. Without lowering these financial barriers, it would be difficult to turn young casual viewers into regulars.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_10274da459519bf3b4922088', 'ielts_group_c7b9e7d256bbe46d29d9264d', 'PART_3', 4, '1. What do you think attracts people to working as an actor?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I’d say the appeal of acting is multi-layered. For starters, there are the obvious perks like fame and financial rewards, that A-list lifestyle is glamorous. But beyond that, it’s a career that’s inherently dynamic. Unlike desk jobs with repetitive tasks, actors get to reinvent themselves constantly—that must be exhilarating. What really fascinates me, though, is how the profession taps into that human desire for self-actualization. You’re not just memorizing lines; you’re embodying stories that can move people globally. I mean, where else could you profoundly impact audiences while fulfilling your own creative potential? That’s pretty powerful stuff.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6b58ecfdb68051e1b478d72f', 'ielts_group_c7b9e7d256bbe46d29d9264d', 'PART_3', 5, '2. What are some of the qualities that a person needs to have if they want to become an actor?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, to break it down, I’d highlight the following essential qualities. First and foremost, strong memorization skills—you see, actors need to absorb scripts quickly and deliver lines naturally. On top of that, there’s emotional intelligence—I mean, the ability to draw on different feelings and portray them authentically, whether for comedy or drama. And lastly but equally important, resilience, as rejection is constant in this field, so you really need that mental toughness to keep going after failed auditions.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ce1033723f1734942e741fd7', 'ielts_group_c7b9e7d256bbe46d29d9264d', 'PART_3', 6, '3. Can you think of any disadvantages of working as an actor?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Absolutely. Acting strikes me as a classic case of “you win some, you lose more.” The most obvious drawback is the unstable income—one moment you’re booked solid, and the next, you’re scrambling for gigs. Then there’s the relentless pressure to stay relevant in a cutthroat industry—constantly worrying about critics’ opinions or being replaced by younger talent. Beyond the spotlight, loneliness poses another significant challenge. The unpredictable nature of an actor’s schedule often isolates them from family and disrupts daily routines. This explains why, behind the on-screen glamour, many performers grapple with profound emptiness.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_deaadd8c09dc3f255312fdc7', 'ielts_group_7a880c9981b18bb3226d3eaa', 'PART_1', 1, '1. What’s your favourite fruit?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Oh, definitely tangerines! They’re the perfect combo of sweetness and tanginess, and they’re super juicy when you peel them. Plus, the bright orange colour is an instant mood booster for me. What appeals to me the most is that they’re not as overpriced as other trendy “superfruits” these days, yet they’re packed with vitamin C. That’s why they’ve always been my go-to fruit.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_74795151c84b4e27ac0bad0c', 'ielts_group_7a880c9981b18bb3226d3eaa', 'PART_1', 2, '2. Are there any kinds of fruit that you don’t like eating?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, if you ask me, I’d say durian. I know it’s widely known as the “king of fruits” and loved by many of my friends, but I just can’t stand its pungent smell—it reminds me of rotting onions. The texture’s even worse; it’s like swallowing sweetened clotted cream mixed with stringy bits. Honestly, even durian-flavoured candies freak me out!","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1fe8a7aec438aaeeb79aa88f', 'ielts_group_7a880c9981b18bb3226d3eaa', 'PART_1', 3, '3. Do you like eating cooked food that has fruit in it?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Personally, it’s not my cup of tea. For example, in China there’s a dish called pineapple pork which is a famous Cantonese dish. I’ve tried it a few times, but I just can’t get used to the way warm, mushy fruit clashes with salty flavours—it feels wrong to me. If you ask my opinion, fruits are meant to be eaten raw to get their natural zing.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_30ac91d34dba4f87201407d3', 'ielts_group_7a880c9981b18bb3226d3eaa', 'PART_1', 4, '4. Where’s the best place to buy fruit where you live?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"If I’m in a rush, I’ll just order fruit through grocery delivery apps. They’ll leave it at my doorstep within an hour! But for better quality and prices, I go to a nearby wholesale market. The produce there is freshly harvested, and there’s a much wider variety. Plus, I actually enjoy haggling with the vendors—it adds to the experience.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_37a0340bd202c7910f59492e', 'ielts_group_2cfa04d72a3a866c0ac96c77', 'PART_2', 1, 'Describe a time when you changed a plan you had made.', '["what your original plan was","why you changed it","what new plan you made","and explain how you felt about changing your plan."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Let me tell you about my snorkelling trip that got canceled in Phuket last monsoon season.\n\nI mean, my original plan was this meticulously organised 3-day island-hopping adventure, complete with underwater photography sessions and sunset cruises. Everything looked perfect, at least on paper.\n\nTo be honest, the first day was excellent—turquoise waters, powdery beaches, everything went swimmingly. Unfortunately, on day two, Mother Nature threw a spanner in our plans. Out of nowhere, a tropical storm blew in – winds picking up like angry spirits, and then the rain started bucketing down mercilessly. Frankly, the waves became wild horses galloping across the sea. At that point, our boat captain called off everything, saying, “It never rains but it pours”—which, in hindsight, was spot-on. I slumped into disappointment, staring at my futile preparations. Had I known earlier, I’d have cancelled this trip altogether.\n\nThankfully, here’s the silver lining—our resort offered complimentary massage therapies. That said, the therapeutic experience proved magical, melting away resentment like ice in sunshine. What’s more, over ginger tea, I swapped stories with globetrotters whose adventures made mine pale in comparison.\n\nNow, while snorkelling remains firmly on my bucket list, this detour taught me something crucial—life’s best unplanned moments often arrive unexpectedly. In other words, when Plan A sinks, Plan B may come to your rescue. Hopefully next time, I’ll remember this lesson when travel plans go sideways.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b96538c04643276ca97dad06', 'ielts_group_2cfa04d72a3a866c0ac96c77', 'PART_3', 1, '1. What kinds of plans do friends make together?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, friends usually plan various leisure activities. They might go shopping, watch movies, or plan weekend getaways and concert outings. On top of that, they often engage in hobby-based stuff. For instance, they could join a hiking club, train for a marathon, or attend a painting workshop. Just as the saying goes, “Birds of a feather flock together.” Moreover, friends also make elaborate plans to celebrate special moments. They might throw surprise parties for each other’s birthdays, or organize themed gatherings to mark important milestones, such as graduations or job promotions.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a040c42bcb12f9ad5bc927e6', 'ielts_group_2cfa04d72a3a866c0ac96c77', 'PART_3', 2, '2. Do you think it’s better to discuss future plans with friends or with family?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It really depends. Generally speaking, friends tend to relate better to personal choices like career shifts or dating dilemmas. For example, if you’re torn between settling down and focusing on your career, friends might give unbiased advice, whereas parents would probably push for marriage. That said, when it comes to major moves like relocating abroad, cutting off contact with your family isn’t a wise option, as you need their support in many ways, such as practical input on visa arrangements, financial support, or even childcare help. At the end of the day, it’s a balancing act.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_19ee6147a5cca19c87c287ef', 'ielts_group_2cfa04d72a3a866c0ac96c77', 'PART_3', 3, '3. When making plans for the future, is it important not to copy friends?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, definitely. To be honest, it’s completely normal to get ideas from friends when planning ahead. I mean, seeing people you trust do something similar does give that initial sense of security. But the thing is, if we just mirror their choices without proper reflection, things can get messy quickly. Take degree choices for instance: I’ve noticed that loads of students go into fields like marketing or computer science simply because their social circle does. The problem kicks in when they realise their strengths don’t align with the coursework at all; you can imagine the stress that follows. That’s why I firmly believe that when it comes to major life decisions, we should build plans around our natural talents and core values. After all, we’re all wired differently.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c72f97ab7438921c9dc2900b', 'ielts_group_2cfa04d72a3a866c0ac96c77', 'PART_3', 4, '1. When people are choosing what to study, how important is it that their course should lead directly to a career?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, that’s a classic dilemma. Think about it: how many of us end up in jobs exactly matching our degree titles? Don’t get me wrong: career-driven degrees like engineering are gold for giving that quick start with their hands-on training and internships. But take philosophy graduates, for example. On paper, they seem job-ready for nothing specific, yet some of them end up thriving in business or tech. I suppose the reason is that those abstract courses wire your brain to tackle problems in ways that no technical manual can teach. So ultimately, while job-specific skills get you through the door, it’s the transferable skills that help you climb the career ladder.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a2e275a86b350242e9976685', 'ielts_group_2cfa04d72a3a866c0ac96c77', 'PART_3', 5, '2. Why is it a good idea to get some work experience before deciding on a future career?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, here’s the thing about internships—they let you test the waters without signing your life away. Many young graduates switch tracks after realising the fact that they don’t really match their first career options. Additionally, no lectures or textbooks can teach you the messy stuff, like calming down a furious client or decoding your boss’s cryptic emails; these are things you can only learn through real-world experience. Lastly, even the most mundane tasks, like making coffee runs and handling spreadsheets, can enhance your CV and help you stand out in the job market later on.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a352751d311de88e9197e6f5', 'ielts_group_2cfa04d72a3a866c0ac96c77', 'PART_3', 6, '3. How easy do you think it is for people to change from one career to another?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"To be honest, it’s no walk in the park. As the saying goes, different fields are worlds apart. So, embarking on a brand-new career means starting from scratch: you have to acquire new certifications, adapt to unfamiliar work cultures, and rebuild professional networks; all of which require dedication and willpower. But on the flip side, it’s liberating. I’ve seen people thrive after escaping dead-end jobs. So yeah, it’s tough but doable with grit.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cfdfb8d04afd51ba45e9b7fb', 'ielts_group_4c7570cefaaee4de3fa529b3', 'PART_1', 1, '1. Did you enjoy going to museums when you were a child?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, when I was a kid, I wasn’t really into museums, to be honest. I mean, they always felt kind of quiet and, you know, a bit boring for a little kid who just wanted to run around and have fun. But I do remember going on some school trips to museums, and back then, I kind of enjoyed it just because I got to hang out with my classmates.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6a1d672728bfcef2f53d11de', 'ielts_group_4c7570cefaaee4de3fa529b3', 'PART_1', 2, '2. Are there any interesting museums near where you live now?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Oh yes, there’re a couple of them not far away from my place. For example, there’s a local history museum that showcases the area’s development over the years. It’s an absolutely fascinating place to go if you’re into history or want to know more about the region. And there’s also an art museum that often holds exhibitions from contemporary artists. It’s a great place to visit if you’re fond of modern art.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1d932998788de694420420f3', 'ielts_group_4c7570cefaaee4de3fa529b3', 'PART_1', 3, '3. Do you think it is best to go to museums by yourself or with friends?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think going to museums by myself is probably the best choice. I mean, when I go alone, I can take my time and really lose myself in the exhibits I find interesting. There’s no rush, no pressure to keep up with someone else’s pace. Sometimes I even stop and read all the little signs next to the artwork, which is something I probably wouldn’t do if I were with friends.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_171e5573d6c75eb9c06949ad', 'ielts_group_4c7570cefaaee4de3fa529b3', 'PART_1', 4, '4. When you visit another city or country, do you think it’s important to go to a museum there?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think it’s a pretty good idea to do so. I mean, museums kind of help you get a feel for the local culture. Like, you can learn about the city’s past or see what kind of art people there care about. It’s also a nice way to slow down during a trip and just enjoy something different. So yeah, I wouldn’t say it’s a must, but it’s definitely worth checking out if you have time.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5b35cd246898acaf81163d6c', 'ielts_group_3ff18c7c784776d56a7b6b2c', 'PART_2', 1, 'Describe a piece of work you did for your job or your studies that you felt very satisfied with.', '["what this piece of work was","why you did this piece of work","who or what helped you to do this work","and explain why you felt so satisfied with this piece of work."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, one piece of work that I felt really satisfied with during my studies was when I had to write a research paper for one of my university courses. It was about language acquisition and how children learn languages in their early years.\n\nI chose this topic because, you know, I’ve always been really curious about how people pick up languages, especially when they’re young. Also, it was something that really tied into what I wanted to do in my career, teaching English, you know. So, I thought it would be a great opportunity to explore the topic more deeply.\n\nSpeaking of the help that I got, well, I had some great resources to help me out. First of all, my professor was super supportive, who gave me lots of guidance and pointing me in the right direction when I got stuck. I also spent quite a bit of time in the library reading academic papers and books, which gave me a lot of ideas and food for thought in this area. But what inspired me the most was the discussions that I had with my classmates. We often bounced ideas off each other, and I think this kind of collaboration really helped me refine my thoughts.\n\nWhy did I feel satisfied? Well, it was partly because all the hard work paid off. I ended up getting a pretty good grade on the project. But honestly, it wasn’t just about the grade. I mean, I was pleasantly surprised by how well I did, but what meant even more to me was the process itself. The research, the writing, the feedback, all of them came together in a way that really taught me a lot. It felt incredibly rewarding to see how everything clicked in the end, and more than anything, it was the sense of growth I experienced that made the whole thing so satisfying.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_88c2964a8998a80fa6fcdb74', 'ielts_group_3ff18c7c784776d56a7b6b2c', 'PART_3', 1, '1. What are some aspects of people’s lives that they can often be dissatisfied with?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think one area people really feel dissatisfied with is their career. You know, a lot of people might feel like they’re stuck in a job that doesn’t match their interests or doesn’t pay enough. And when you’re doing the same thing every single day without a sense of progress, it’s obviously hard to stay motivated and satisfied. Also, many people struggle with balancing their job and personal life. I mean, working long hours can leave you with little time or energy for your family, hobbies, or even just rest. Over time, that kind of lifestyle can make people feel really frustrated or even burnt out.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_062fd2662b1831d0f2b7537c', 'ielts_group_3ff18c7c784776d56a7b6b2c', 'PART_3', 2, '2. Would you say that having ambitions in life is always a positive thing?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I wouldn’t say that having ambitions is always a positive thing. I mean, on one hand, ambition pushes people to grow, to achieve more, and to aim higher in life. It’s definitely a driving force behind success. But on the other hand, if someone becomes too obsessed with their goals, they might ignore their health, relationships, or even lose sight of what really makes them happy. It can lead to, you know, a lot of stress and burnout, especially if they’re constantly comparing themselves to others. So yeah, ambition can be great, but only if it’s balanced with self-care and realistic expectations.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f3757254d9147fbf6014e5df', 'ielts_group_3ff18c7c784776d56a7b6b2c', 'PART_3', 3, '3. What do you believe the most important components are of a satisfying life?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, for me, one of the most important ingredients is having meaningful connections with other people. I mean, strong social bonds with family, friends, and even the wider community provide a sense of belonging and support that is crucial for our well-being. Feeling connected and having people to share your life with, you know, that makes a huge difference. Another vital component I would say is having a sense of purpose. Well, it doesn’t necessarily need to be some grand, world-changing goal, but rather feeling like you’re contributing something, whether it’s through your work, your hobbies, or your involvement in your community. This feeling of contribution can be incredibly satisfying, and that is also what makes life rewarding and meaningful.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_73f4c51650549281c52cd6ac', 'ielts_group_3ff18c7c784776d56a7b6b2c', 'PART_3', 4, '1. What makes a job more satisfying: a high salary or having good colleagues?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, that’s a difficult question. I mean, both are important in different ways. But if I had to choose, I’d probably say having good colleagues can gain you more job satisfaction. I mean, when you work with people who are friendly, supportive, and easy to get along with, it really helps you enjoy your day, even if the job itself is stressful. Of course, a high salary is important too. It gives you a sense of security and allows you to enjoy life outside of work, but let’s be honest, if you’re surrounded by toxic workmates, even a well-paid job can feel like a nightmare. So yeah, I’d say a good team often matters more than money, at least in the long run.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6deff4c54479130b8e892831', 'ielts_group_3ff18c7c784776d56a7b6b2c', 'PART_3', 5, '2. Do you think people need to change jobs regularly if they want to stay satisfied at work?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think it really depends on the person and the type of job they have. I mean, some people feel more satisfied when they face new challenges and get to learn different skills, so changing jobs from time to time helps them stay motivated and avoid getting bored. But others might prefer stability and a clear career path, and they feel more fulfilled when they can grow deeper in one role over time. What I want to say is, not everyone wants to start over again and again. So, I’d say people don’t necessarily need to change jobs on a regular basis to feel satisfied, but for some, it can be a good way to keep things fresh and exciting.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_540b51fbb02a4ec0cfbb4d74', 'ielts_group_3ff18c7c784776d56a7b6b2c', 'PART_3', 6, '3. Is it possible to find job satisfaction in all types of work?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I guess it is possible, but not everyone will find it easy. I mean, job satisfaction is a really personal thing. Some people can feel satisfied even in very basic or repetitive jobs, as long as they feel they’re doing something rewarding or working with people they like. Take a cleaner or a delivery person for example, their jobs might not seem that exciting or glamorous, but if the work environment is supportive and they feel respected, it can also make a huge difference. So yeah, I think people can find satisfaction in most kinds of work with the right mindset and environment. But of course, it’s not always that simple.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9a57f244617a332ba99674a8', 'ielts_group_30dd1453a158f896cd3ac708', 'PART_1', 1, '1. What do you think your best personal qualities are? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I guess one of my best personal traits is that I’m pretty easy-going. I mean, I don’t get upset easily and I’m usually able to stay calm even under pressure. Also, people say I’m a good listener, which I think is kind of important, especially when someone just wants to vent or share stuff.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_98f6a816e75d2b9b639b3998', 'ielts_group_30dd1453a158f896cd3ac708', 'PART_1', 2, '2. Do you have the same personal qualities as your parents? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yeah, I’d say so. My dad is really patient and rarely loses his temper, and I think I’ve inherited that from him. As for my mum, I definitely take after her in terms of personality. She’s super outgoing, maybe even more than I am. So yeah, I guess I’ve got a bit of both!","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4066a802b8d658dd36b47d81', 'ielts_group_30dd1453a158f896cd3ac708', 'PART_1', 3, '3. What personal qualities are important to you in a friend? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, for me, honesty is definitely essential. I really value friends who are genuine and speak their mind, even if it’s not always what I want to hear. I just can’t stand being lied to. I also think being supportive is a key quality. You know, someone I can truly count on when things get tough, not just a fair-weather friend who only shows up when life is good.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1c2d5ede20f191f71e877865', 'ielts_group_30dd1453a158f896cd3ac708', 'PART_1', 4, '4. Do you think you have the personal qualities to be a good/successful leader? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think I do have some of the qualities that make a good leader. For one, I’m quite good at listening and taking other people’s opinions into account before making decisions, which I think is really essential in leadership. I’m also pretty organized and goal-oriented. Having said that, I still have a lot to learn, like how to handle conflicts better or motivate people in tough situations.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6e12a529cb2fb24cf03fe5bb', 'ielts_group_392aba00ef18c66d2f0e6f38', 'PART_2', 1, 'Describe a time when you had a long discussion about a news story.', '["what the news story was about","who you discussed this news story with","what people’s opinions were","and explain why you had such a long discussion about this news story."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"OK, I’m going talk about a time when I had a really long but interesting discussion with my friends about a news story about artificial intelligence. It was about how AI was being used to replace some human jobs, especially in areas like teaching.\n\nAnyway, I remember it was about maybe 2 months ago, we were hanging out at a café on a weekend, and one of my friends brought it up because he had read an article online saying that some companies in China had already started using AI teachers in classrooms, which he thought was amazing. We took a lot of interest in the topic, because a few of us are working in education or tech.\n\nSo, that was how the discussion began. Some of us thought it was a great idea. You know, more efficient, cost-effective, and AI never gets tired. But others were a bit worried, saying that it could take away the human touch in teaching, and might lead to job losses. I was personally kind of in the middle. I mean, for me, AI can be helpful, but it shouldn’t fully replace real people, especially in jobs that need empathy and communication.\n\nAnyway, that day we ended up talking for almost two hours because everyone was so engaged and had a lot to say. Since it’s a topic that could affect all of us in the near future, it naturally led to such a long and meaningful discussion. Although we didn’t exactly agree on everything, it was a really intriguing conversation that gave us plenty of food for thought.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b0587487c301586122d6f918', 'ielts_group_392aba00ef18c66d2f0e6f38', 'PART_3', 1, '1. How do most people find out about the news in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think these days most people in China find out about news mainly through digital platforms, like smartphones. I mean, if you open an app like WeChat or Weibo, you can immediately see what’s happening, because these apps constantly update you with breaking news and trending topics. Short-video platforms like Douyin, which you might know as TikTok, are also very popular for catching up on news, especially among younger people. But of course, if you’re older, you might still prefer traditional ways, like watching TV. You know, channels like CCTV news are still really common in homes, and a lot of older folks rely on these for daily news updates.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_920ba5ba3794882faa9b4a14', 'ielts_group_392aba00ef18c66d2f0e6f38', 'PART_3', 2, '2. Are people more interested in local news than national news?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it’s kind of hard to say. I mean, if you’re thinking about your day-to-day life, you might find local news more appealing, because it directly affects things like the weather forecast, traffic conditions, or even what’s happening in your neighborhood. I mean, local news is just more relatable, and you usually feel it immediately. But, on the other hand, national news is also important to a lot of people because it covers bigger issues, like new policies or economic developments that can influence their job prospects, education, or housing. So yeah, I guess most people would follow both types, but it kind of depends on what’s more relevant to their lives at that moment.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c66c082f1322eb576a7718ec', 'ielts_group_392aba00ef18c66d2f0e6f38', 'PART_3', 3, '3. How important is it to know about international news?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think it’s quite necessary. If you pay attention to what’s happening globally, it can really help you expand your perspective. I mean, you get to understand how people in different parts of the world live, what challenges they’re facing, and how different countries interact with each other. Also, staying informed about international news can help you make better decisions in your own life. For example, if you’re planning to travel abroad, invest your money, or even choose your career path, knowing what’s going on internationally could definitely help you avoid potential risks and take advantage of new opportunities.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_dad4aa5bb6f3224606c604ff', 'ielts_group_392aba00ef18c66d2f0e6f38', 'PART_3', 4, '1. Why are discussion programmes involving members of the public popular on [TV and radio]?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I’d say it’s mainly because they’re really interactive and engaging. You know, when ordinary people participate and express their opinions, it makes you feel more connected and engaged. I mean, it’s like you’re part of the conversation yourself. Another reason would be that these programmes tend to reflect real-world perspectives. I mean, instead of just hearing experts or celebrities talking, you’re listening to everyday people who might share your own experiences or concerns, so the discussions feel more relevant and genuine.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f06e3e659ef8a15685748b88', 'ielts_group_392aba00ef18c66d2f0e6f38', 'PART_3', 5, '2. What kinds of people want to take part in discussion programmes?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think if you’re someone who really enjoys expressing your own views, you’ll probably want to get on a discussion programme. I mean, when you’ve got strong feelings about an issue, like something related to politics, education, or social trends, you might want to jump at the chance to explain your side and debate with others. Also, I’d say if you’re the type of person who wants your voice to be heard by a wider audience or even influence public opinion, it’s also a great idea to take part in a discussion show, where, you know, you can get a mic, a platform to voice your opinion publicly.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c6b18cfb9afaeacc63b43ea8', 'ielts_group_392aba00ef18c66d2f0e6f38', 'PART_3', 6, '3. Do discussion programmes influence people in a good or bad way?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I’d say people can be influenced in both ways. On the positive side, these programmes often expose you to different viewpoints, helping you understand complex issues better. I mean, when you hear people with various backgrounds share their opinions, it can really broaden your mind and help you become more open-minded. But on the other hand, if the discussions become too heated or biased, they might negatively influence you by spreading misunderstandings or even encouraging conflicts. You know, sometimes people get emotional and say things that aren’t exactly balanced, which might lead you to form incorrect or incomplete views about certain topics.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0de82f66d4cb3d0c9e0dee91', 'ielts_group_83a3e38171e470100168370a', 'PART_1', 1, 'Which part of your country do most people live in?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Most people in China live in the east part of the country, especially on the east coast. That is because it is the most developed area in China and there are a lot of big cities.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_bee5eafaa1f9dae01c21e402', 'ielts_group_83a3e38171e470100168370a', 'PART_1', 2, 'Tell me about the main industries there.', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"One of the main industries in China is agriculture. It is the very foundation of the economy. More than half of the population work in this industry. Another industry is manufacturing. It provides people with clothes, machinery and many other products, and is very important for foreign trade.One of the main industries in China is agriculture. It is the very foundation of the economy. More than half of the population work in this industry. Another industry is manufacturing. It provides people with clothes, machinery and many other products, and is very important for foreign trade.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ab30c8eed101c903e16de2e2', 'ielts_group_83a3e38171e470100168370a', 'PART_1', 3, 'How easy is it to travel around your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Travelling around China can be easy in most areas. You can take a plane or an express train to nearly every big city in the country. However, you may find it difficult to get to remote areas, where planes and fast trains are still not available.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9f7c98f3db892c050c9f5d9f', 'ielts_group_83a3e38171e470100168370a', 'PART_1', 4, 'Has your country changed much since you were a child?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It has changed a lot since I was a child. China is now opening itself to the world, and the economy continues to grow very fast. It has become more urbanised and people live a much better life. A lot of people now have their own cars and they live in bigger houses.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_50f525d173036fd215f8992c', 'ielts_group_76536b1403c1a9b391ee805e', 'PART_2', 1, 'Describe a well-known person you like or admire.', '["who this person is","what this person has done","why this person is well known","and explain why you admire this person."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"The person I admire the most is Liu Xiang. He was champion of the 1 10-metre hurdles at 2004 Athens Olympic Games. He now is one of the most famous athletes in the world.\n\nLiu Xiang was only 21 years old when he won the first gold medal in the men''s 110m hurdles for Asia. He broke the Olympic record set by Allen Johnson of the United States in Atlanta Olympic Games in 1996. And in the following years, he won a lot of medals in all kinds of events. At present, he is active in world competitions and various social activities.\n\nLiu Xiang is a household name because he is the first Chinese to win the Olympic gold medal in 1 10m hurdles. And he is even the pride of the whole Asia because in the past, western people thought of yellow people as a weaker race that could not do well in running, but Liu Xiang''s success changed such opinion.\n\nI admire Liu Xiang very much because he is the honour of China and Asia. He represents the strength of our country and builds a new image of Chinese and Asian people. In addition, he is a very interesting and good-hearted person. He can sing very well, and he often makes advertisements to promote public welfare.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_045d450b5bd9a0a6cc15ba7a', 'ielts_group_76536b1403c1a9b391ee805e', 'PART_3', 1, 'What kind of people become famous people these days?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Nowadays, singers, actors and actresses often become famous. People get to know them from the mass media. Every day, we can see them on TV, in newspapers or on the Internet. And those who sing or act well can quickly become popular stars.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ca8950377227665e98dffce7', 'ielts_group_76536b1403c1a9b391ee805e', 'PART_3', 2, 'Is this different from the kind of achievement that made people famous in the past? In what way?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"This is quite different from things in the past. At that time, people became famous because of their titles. We paid a lot of attention to people. s positions, and we. often heard the names of government officials the president, the ministers and other officials. They made achievements in the political field, and people of higher ranks were more famous than people of lower ranks.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c6a1a99ef7e4d71d999bd00e', 'ielts_group_76536b1403c1a9b391ee805e', 'PART_3', 3, 'How do you think people will become famous in the future?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In the future, people will become famous by showing their talents in different ways and making impact on society. Writers can become famous by writing excellent books. Athletes can become famous by winning international competitions. And business people can become famous byrunning big companies and making much money. Every person has a chance to be successful and famous if they completely show their strengths and influence.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cf84b249033a6d346b8f6ac9', 'ielts_group_76536b1403c1a9b391ee805e', 'PART_3', 4, 'What are the good things about being famous? Are there any disadvantages?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There are some advantages of being famous. First, it can give people a sense of achievement. Famous people are always confident of themselves and believe that they are better than others. Second, they can make more money than ordinary people do. They have higher salaries and can earn a lot of money by making advertisements. Certainly they have a heavy price to pay for all those gains. For one thing, as far as I know, many celebrities are under too much stress and it really causes health and mental problems. For another, privacy is always an issue. Most celebrities, especially film stars or singers, always complain that they can ''t live a normal life because wherever they go, whatever they do, there is always someone who keeps an eye on them, which can be really annoying.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cae36aff1842190612f8a5de', 'ielts_group_76536b1403c1a9b391ee805e', 'PART_3', 5, 'How does the media in your country treat famous people?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"The media in China use famous people to make money. Television, radio, newspapers and the Internet report stories about them, make programmes of them and even create stars on their own to attract the public eye. Famous people bring them a larger audience, which means they can have greater revenue from advertising and other services.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c346a5afb2a8fb775e7e9191', 'ielts_group_76536b1403c1a9b391ee805e', 'PART_3', 6, 'Why do you think ordinary people are interested in the lives of famous people?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Ordinary people are interested in the lives of famous people mainly for two reasons. First, they are curious about those people. As a result, they try to find detailed information about the personal lives of famous people, even about things highly private. Second, they admire famous people and want to imitate them. Famous people are their role models. They want to know more about their lives and try to learn from them.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6bba95fb5cbaa227fdcaf161', 'ielts_group_142c209f98f0afbe862e70a3', 'PART_1', 1, 'What''s your favourite colour? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"My favourite colour is black.\n\nBecause black is said to be a tolerant colour. That is to say, all the other colours can be mixed into the colour black.\n\nBecause black clothes make me look very cool. And it makes me look thinner as well.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6dad7fb1339ebb5b19f270f0', 'ielts_group_142c209f98f0afbe862e70a3', 'PART_1', 2, 'Do you like the same colours now as you did when you were younger? [Why / Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"No, I used to like pink and purple a lot when I was a little girl. By and by, I grew to like black a lot. Maybe because black clothes make me look cool and thinner.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b566e569e15f13e3e9a19635', 'ielts_group_142c209f98f0afbe862e70a3', 'PART_1', 3, 'What can you learn about a person from the colours they like?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, some people believe the colours one likes have much to do with his or her personality. I agree with that. For example, \"red\" people tend to be very passionate and energetic; \"blue\" people might be a bit gloomy; \"yellow\" people can be the carefree type.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_475603c201e3c260bacde0c9', 'ielts_group_142c209f98f0afbe862e70a3', 'PART_1', 4, 'Do any colours have a special meaning in your culture?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes. Say, \"red\" means lucky and joyous in the Chinese culture. So people use red stuff a lot on holidays or celebrations while white has the opposite meaning. Sometimes, it is used to show sadness and respect. For example, people always wear a small white flower to attend a funeral.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e944e2a29b164d4bfe80e431', 'ielts_group_45a2c2796902a4f0c9d3f791', 'PART_2', 1, 'Describe a song or a piece of music you like.', '["what the song or music is","what kind of song or music it is","where you first heard it","and explain why you like it."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"My favourite song is called Cinderella written and sung by a Chinese pop star, Zheng Jun.\n\nCinderella is a very romantic song. of slow beat. It''s about a man courting a ludy. And the lyrics go like this,\n\n\"Oh my Cinderella, you may not be the most beautiful girl in the world. But you are s0 lovely in my eye... Am Idrcaming that now I can be with you? How I wish I would never wake up from this sweet dream.\n\nI first heard the song on a tape that my boyfriend made me. We were in the same university and he made methe tape as a birthday present. On a tape of 60 minutes, he recorded nothing but this song, time after time, ten timesall together. I fell in love with the song as soon as I heard it.\n\nNow many years have passed. Cinderella is still my favourite song. Firstly, it always reminds me of the happydays I spent in the university. Secondly, the music of the song is extremely charming. By using some traditionalinstruments from Yunnan Province, the singer Zheng Jun depicts a peaceful scene of the Yunnan Province, as wellas a beautiful lowe that everybody dreams of.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7b8976796f73f4e7a853b226', 'ielts_group_45a2c2796902a4f0c9d3f791', 'PART_3', 1, 'What kinds of music are popular with young people in your culture?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Young people in China have many choices on music nowadays. Some of them like local pop music; some like Japanese and South Korean music; some like music from America and the UK; and there''re classic music lovers, too.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ff59452bf5ad32eda25a37d6', 'ielts_group_45a2c2796902a4f0c9d3f791', 'PART_3', 2, 'What do you think influences a young person''s taste in music?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I can think of at least three factors that may influence a young person ''s taste in music. The first is their family background. Children are very likely to have the same hobbies and interests as their parents. The second factor is the child s personality, for people tend to like the kind of things that echo their own thoughts. The third factor can be the influence from the mass media. The largescale promotion of certain kind of music might wash the children s brains easily.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c1198e09693e12d0c326bdc3', 'ielts_group_45a2c2796902a4f0c9d3f791', 'PART_3', 3, 'How has technology affected the kinds of music popular with young people?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In the age of high technology, electronic music becomes more and more popular among young people. On one hand, some people believe this kind of music reflects the features of this age perfectly. On the other hand, with the popularization of computers, everybody can make their own electronic music by using computers, which makes this kind of music even more popular.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4eebf8365e2eec17beacb6f1', 'ielts_group_45a2c2796902a4f0c9d3f791', 'PART_3', 4, 'Tell me about any traditional music in your culture.', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"China has a long history of playing musical instruments and enjoying music. Many of the ancient musical instruments are very popular even today. For example, the guzheng, the erhu, the dizi, the xiao. They all make great music and people from all over the world come to China to learn how to play traditional Chinese music with them.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5e7da65e05677ed4903ddae7', 'ielts_group_45a2c2796902a4f0c9d3f791', 'PART_3', 5, 'How important is it for a culture to have musical traditions?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It is very important. Firstly I think music can help to carry the history, traditions and heritage of a culture. Secondly, it''s a great way for people to express themselves and communicate with others, even if they don'' t understand each other ''s languages. Thirdly, to compose and enjoy music, people need to have great creativity and improvisational skills and they all represent the liveliness of a culture.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_600dedd96733ce77737098ad', 'ielts_group_45a2c2796902a4f0c9d3f791', 'PART_3', 6, 'Why do you think countries have national anthems or songs?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think it''s one of the most important symbols of a country. It carries the traditions of a country, records the crucial moment in a country'' s history, and embodies the spirit of a nation. That ''s why many people can be moved to tears upon hearing their national anthem","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0e710feb6b2a18c8f75e5ff3', 'ielts_group_36d2813a131477f61f7b6fd9', 'PART_1', 1, 'Do you prefer relaxing at home or going out in the evening? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I prefer going out to staying at home in the evening. At home you can only watch TV or surf the Internet, while outside there are a lot more activities. If you go out, you can get some fresh air and meet people, which is exciting. And there are always new experiences and surprises.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a31a439bf141b55699b97a16', 'ielts_group_36d2813a131477f61f7b6fd9', 'PART_1', 2, 'When you go out for an evening, what do you like to do?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In the evening, I often go shopping. And it is particularly suitable at summer times, when it is hot during the day. After dinner, I will go to department stores or the supermarket with my friends. It is extremely relaxing and enjoyable. I can buy things I like, walk on the street, and enjoy the beautiful night scene of the city. When I am a little tired, I would buy some drink and chat with my friends for a while.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_21b332eb0287de4dcb8722fd', 'ielts_group_36d2813a131477f61f7b6fd9', 'PART_1', 3, 'How popular is this with other people in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It is very popular in China to go shopping in the evening. People often go out with their family or friends. It is a good way to relax and have fun. And you can exercise instead of staying at home. More importantly, people have a chance to talk to each other and exchange feelings.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2d859ba07c6207c1d5e035b5', 'ielts_group_36d2813a131477f61f7b6fd9', 'PART_1', 4, 'Is there any kind of entertainment you do not like? [Why / Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t like going to discos, though it is very popular among young people. Maybe it is a good way to ease the pressure from work, but I prefer a milder way to relax. Discos are noisy and people there are often unreliable, and you may as well get yourself drunk. It is bad for your health.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_db553fa87f1d91887b150ddc', 'ielts_group_e1ec64901a15a914a970d2e0', 'PART_2', 1, 'Describe one of your friends.', '["how you met","how long you have known each other","how you spend time together","and explain why you like this person."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I met my best friend Jane when I was in junior high school. We were classmates but we didn''t know much about each other at first. One day I got very low marks in the exam and felt extremely upset. But Jane appeared with a big smile on her face. She didn''t talk much but let me listen to a song, Rainbow, by Jeff Chang. She said there would be a beautiful rainbow in the sky after heavy rain, and that I should not lose confidence. I was very grateful and we became friends.\n\nSo far we have known each other for nearly ten years. Now we are still in the same university.\n\nWe often go out shopping after exams and have dinner together at birthdays. And when I encounter big problems, I would find her and ask for advice. She is always there when I am in trouble, and I am always willing to help her no matter what happens.\n\nI do really like her because she is so nice and agreeable to be with. She is a good listener. I can always talk about my emotions without feeling the smallest pressure or uneasiness in front of her. And she is very understanding and can give me sensible advice. She is very important to me.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b030cc3731442c4bdb9bfe04', 'ielts_group_e1ec64901a15a914a970d2e0', 'PART_3', 1, 'What do you think are the most important qualities for friends to have?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Good friends listen to each other. They try to understand your feelings and moods and help you solve problems. Good friends are dependable and trustworthy. They don''t betray, put you down or hurt your feelings. Good friends respect each other. They are not possessive and give you room to change. And Good friends speak the truth. They give you compliments when you succeed and also disagree when you are doing wrong.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5643bc8379bc2a6445a403dd', 'ielts_group_e1ec64901a15a914a970d2e0', 'PART_3', 2, 'Which are more important to people, their family or their friends? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Both family and friends are important, but they play different roles in people'' s lives. On the one hand, people grow up and get primary education from their family. Family provide them with the very basic things that they need - food, clothes and shelter. On the other hand, friends may understand each other better than family. They spend more time. together and exchange ideas more often.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4b10c103498d86da3b4805c1', 'ielts_group_e1ec64901a15a914a970d2e0', 'PART_3', 3, 'What do you think causes friendships to break up?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Friends often break up for two reasons. First, they lose trust in each other. Trust is exactly where friendship is based. If friends don'' t act in the interest of each other or even turn against each other, they can no longer be friends. Second, they interfere too much with each other'' s life. Friends can be intimate, but they should never be possessive and dominant. If they don ''t respect each other''s privacy or allow others to make their own decisions, they will lose their friends.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a082315e3ed8a3191ebc9da7', 'ielts_group_e1ec64901a15a914a970d2e0', 'PART_3', 4, 'What other types of relationship, apart from friends or family, are important in people''s lives today?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Apart from friends or family, colleagues and other people related to your work are also important. It is because nowadays people do not always stay at home or spend time with their friends. They work outside and have to deal with their colleagues, bosses, customers, suppliers and other business people. It is very important to form sound relationships with these people because it can greatly help with your career.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4ae358c5e6d64ee46d5265b7', 'ielts_group_e1ec64901a15a914a970d2e0', 'PART_3', 5, 'Have relationships with neighbours where you live changed in recent years? How?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"The relationships with neighbours in my city have changed in recent years. In the past, people lived in the same courtyard. They often went out after dinner and talked about everything they were interested in. And they would ask their neighbours for help if they needed anything. However, nowadays most people live in the flat or villas. They can hardly meet each other. Every day, people are busy with their own lives and they don''t pay attention to what is happening to their neighbours. Therefore, the relationships with neighbours become weaker and weaker.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_08d71a5150516563ae861a72', 'ielts_group_e1ec64901a15a914a970d2e0', 'PART_3', 6, 'How important do you think it is for a person to spend some time alone? Why / Why not?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It is very important for a person to spend some time alone. When you are with people, you are influenced by them and cannot behave like your true self. By and by you will get tired and lose your direction. So, a person needs to spend some time alone. Read some books, drink some coffee, or go into the woods, you will be refreshed and able to set clear goal for your life.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7ac20a44d91d14c6974fd320', 'ielts_group_7541522dc2f531d9b1a837b4', 'PART_1', 1, 'How important are clothes and fashion to you? [Why / Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think clothes and fashion are different from each other. Clothes are important to me, for I want to dress myself beautifully, appropriately and I want the clothes I wear to show my personality and individuality. While fashion to me, is not very important. Fashionable things are not necessary to my taste and they don'' t always suit me.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ae05b11d40a270427fa5afeb', 'ielts_group_7541522dc2f531d9b1a837b4', 'PART_1', 2, 'What kind of clothes do you dislike? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t like formal clothes very much. They always make me feel stiff and uneasy. I prefer casualwear, T-shirt, jeans etc.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0ae5ebcfeb04c658c3e35009', 'ielts_group_7541522dc2f531d9b1a837b4', 'PART_1', 3, 'How different are the clothes you wear now from those you wore 10 years ago?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I was still in Senior High School ten years ago. At that time, I had to wear the school uniform, and thus didn’t have many choices to make. And now I''ve been working for a few years. I usually wear formal clothes for work. And I prefer casual wear in my spare time.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8c84c0f317f370ffd206e7c4', 'ielts_group_7541522dc2f531d9b1a837b4', 'PART_1', 4, 'What do you think the clothes we wear say about us?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think the clothes people wear, the colours and the styles, tell a lot about their personality, individuality, and sometimes their social status.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a4cff1b297b3c5405ec3fdfc', 'ielts_group_66cbbb6619acf1e96804021d', 'PART_2', 1, 'Describe a festival that is important in your country.

You should say：

when the festival occurs

what you did during it

what you like or dislike about it

and explain why this festival is important.', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''d like to talk about the Chinese Valentine''s Day. It is on the 7th of July, on the Chinese Lunar Calendar.\n\nAs a tradition, people will gaze at the sky, watch the Stars of Vega and Aquila, and then tell the love story between Niulang and Zhinv on that night.\n\nI like the festival because of the beautiful tale about it. According to the tale, Niulang, the Star of Aquila, is a poor cowherd, and Zhinv, the Star of Vega, a daughter of the Queen of Heaven. The two fall in love with each other, get married and have two children. However, the Queen of Heaven gets very angry when she learns about it. She takes Zhinv away from Niulang and their two children, and then puts a silver river between them, forbidding them to see each other again. Years pass, Zhinv is still very sad and misses her husband and children very much. Finally, the Queen of Heaven shows a little mercy, allowing the couple to meet once every year on a bridge over the silver river, that is the Milky Way, on the 7th of July.\n\nThe festival is very important for the Chinese, especially the young people for it''s about love and is very romantic. More and more people are celebrating it as the Chinese Valentine''s Day. Moreover, I think this tale shows the amazing talents and imaginations of the ancient Chinese people, which makes the festival very important as well.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5cfe54f6b1c5cbfca39b320c', 'ielts_group_66cbbb6619acf1e96804021d', 'PART_3', 1, 'Why do you think festivals are important events in the working year?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think there are mainly two reasons. Firstly, it is a great way for people to have some relaxation and entertainment every now and then during a year of hard work and business. Secondly, people can learn a lot about their own history and tradition by celebrating these festivals. It helps them to gain a better understanding of who they are and where they come from (their origin).","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_cc210487e99ee3357af3a107', 'ielts_group_66cbbb6619acf1e96804021d', 'PART_3', 2, 'Would you agree that the original significance of festivals is often lost today? Is it good or bad, do you think?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, that''s true. And I think it''s neither good nor bad, but something inevitable. All the festivals came into being in certain historical back grounds. They don''t exist anymore, making it difficult for people to remember the festivals'' original significance. And now the most important thing about a festival is that people can have relaxation and fun.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_768d6d4e8f2d0d9994bbb33e', 'ielts_group_66cbbb6619acf1e96804021d', 'PART_3', 3, 'Do you think that new festivals will be introduced in the future? What kind?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I do believe various festivals will be introduced in the future. It can be set up to show people''s respect to a certain person, to commemorate a certain day or event, or just for people to have fun. Anyways, people enjoy all kinds of festivals. So, the more, the better.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a78b848e606146cbeeeba826', 'ielts_group_66cbbb6619acf1e96804021d', 'PART_3', 4, 'What role does the media play in festivals, do you think?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think the media can help to enhance the atmosphere of a festival, as there are usually many celebrations on TV, radio, etc. during the festivals. On the other hand, the media enables people to know more about the festivals from other countries and to enrich their own culture by adopting some of them.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_07eb27b045f1b7e9dd32d5e2', 'ielts_group_66cbbb6619acf1e96804021d', 'PART_3', 5, 'Do you think it''s good or bad to watch festivals on TV? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Again, I think it''s neither good nor bad, for people have their own preference. Some people enjoy watching celebrations on TV. Some people like to be part of the festivals, to join in the celebrations themselves. While some other people may take these festivals quite personally. They want to celebrate the festivals quietly by themselves or with their friends or family members. These are all good choices.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f1ea60dc6b6d1657ea468357', 'ielts_group_66cbbb6619acf1e96804021d', 'PART_3', 6, 'How may globalisation affect different festivals around the world?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"On one hand, I think globalization helps to introduce the festivals of one country or culture to other parts of the world, which is a good thing. On the other hand, the festivals celebrated by some minor cultures or small groups are very likely to die away, when people''s attention is diverted to the cultures and ideologies of the major economies around the world.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c8ce858b80382434e33c53dd', 'ielts_group_7e039fae864af0d84279fc77', 'PART_1', 1, 'Do you enjoy dancing? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I really like to dance. It is one of my favorite activities. Ever since I was a llttle child I liked to watch dances and participate in them also. It just makes me feel so happy and free and gives me a chance to express myself artistically.\nparticipate in 参与 artistically 在艺术上","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2562d2dea6fefc1b4ae55592', 'ielts_group_7e039fae864af0d84279fc77', 'PART_1', 2, 'Has anyone ever taught you to dance? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, you know, in university there are dance classes that you can attend. The dance instructor that I had was very nice and showed a lot of patience with me, because at that time I felt like I had \"two left feet\", if you know what I mean. So he really helped me to have more confidence in not just dancing but also in other aspects of my life. I really miss him.\ndance instructor 舞蹈教练 two left feet 笨手笨脚","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9e5e00fe338e86e00a0202d1', 'ielts_group_7e039fae864af0d84279fc77', 'PART_1', 3, 'Tell me about any traditional dancing in your country.', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"You know I would really like to tell you about traditional dances in China but the younger generation here in China are more interested in hip hop and break dancing and things of the West. I know there are a lot of traditional dances in China, like lion dance or Yanko Dance, and some of them are quite pretty, but to be honest I am not very good at them.\nhip hop 街舞 break dancing 霹雳舞 \nIlion dance 舞狮子 Yanko Dance 秧歌","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_883acea29ff06dacd849d59c', 'ielts_group_7e039fae864af0d84279fc77', 'PART_1', 4, 'Do you think that traditional dancing will be popular in the future? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think there is a place for it in the future, but I am not sure how popular it will be. It would be a pity to me if we didn''t preserve our dances and culture because it is so unique, but how all this will play out in the future I am just not sure.\npreserve 保存 unique 独特的\nplay out 发展，发生","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_42b0b8bdee2ef59baa521d1e', 'ielts_group_95dbab4c6e653a8eed8757e7', 'PART_2', 1, 'Describe someone in your family who you like.', '["how this person is related to you","what this person looks like","what kind of person he/she is","and explain why you like this person."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"点题：I guess off the top of my head I would say my older brother is someone who I really like.\n外貌和特质：Although he is five years older than I am, he will always be my hero. He is pretty tall and thin although he cats quite a bit. He is one of those people that can eat what they want and not gain any weight. He is pretty athletic and loves to run and play football and row boats, and, just pretty much challenges himself to succeed in any sport. You should see when he jumps how high he gets in the air.\n原因：Even though he is a good sportsman, there are other qualities that I admire about him, for instance, he is also a good student and gets good grades in school. I think that''s because he is the older brother he feels he has to set a good example. I know that my brother is not perfect and he has his faults but I still admire just everything about him. One thing that I really like about him is that he is loving and kind and considerate of others'' feelings. When he got married I was his best man and had a very good time at the wedding, but at the same time it was hard to let him go, knowing that now he was going to have different responsibilities, and I wasn''t going to see him that much. All in all, I have many good memories of my older brother and we still see each other now and again and are able to catch up on what is happening in each other''s life.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2594e92d9eb555fb7940de00', 'ielts_group_95dbab4c6e653a8eed8757e7', 'PART_3', 1, 'In what ways can people in a family be similar to each other?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, there are many ways that people in a family are similar. One way is that they have the same blood; they are all related to each other physically. I think that the other way they are similar is that they live with each other, so they begin to pick up habits and traits that each other has. They can begin to talk alike and react in the same ways.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_afd60028e9f3b838272d381e', 'ielts_group_95dbab4c6e653a8eed8757e7', 'PART_3', 2, 'Do you think that daughters are always more similar to mothers than to male relatives? What about sons and fathers?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Daughters and mothers are naturally closer to each other just because they are of the same sex. They just seem to understand each other better than a father would. Of course there are things about their mothers that some daughters do not want to be like, but usually they are able to come to grips with this issue and develop close bonds. A father and a son can be close; a lot depends on how much time a father is able to spend with his son and how much respect they are able to show to each other.\ncome to grips with 处理，解决 close bonds 亲密的联系","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_feac031f93ea89ab44719b0c', 'ielts_group_95dbab4c6e653a8eed8757e7', 'PART_3', 3, 'In terms of personality, are people more influenced by their family or by their friends? In what ways?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, of course people''s personalities are influenced first by their families, and then later on, when they are attending school, they are much more influenced by their friends.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_91aa53623cc1f3e788ef1cd7', 'ielts_group_95dbab4c6e653a8eed8757e7', 'PART_3', 4, 'Where can people in your country get information about genetic research?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I suppose, like in most countries, if you want information about anything, the place to look would be on the Internet. You start your search there and see where it takes you. Genetic research is not the kind of thing that you might find at the corner store in any neighborhood.\ngenetic research 基因研究","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b6a6e2817340a1393e364405', 'ielts_group_95dbab4c6e653a8eed8757e7', 'PART_3', 5, 'How do people in your country feel about genetic research?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I don''t know so much about this topic, because I am not a scientist or anything, but I suppose that there are pros and cons to this subject. Sometimes when I think of this, I am a little scared and think about mad scientists and Dr. Frankenstein and that kind of stuff. I have heard that there are some good possibilities in this type of research, but off the top of my head the only thing that I can think of is stem cell research. But even that is a bit controversial.\nDr. Frankenstein 科学怪人 controversial 有争议的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_82e6084f86462e55b9bd7cf6', 'ielts_group_95dbab4c6e653a8eed8757e7', 'PART_3', 6, 'Should this research be funded by governments or private companies? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, whoever wants to fund this kind of research should be able to do so at their own discretion. If governments have the money and support from their constituents then they could invest in this research. Now, of course, private companies also have money and could invest in this research, and I should see of no law that would prevent them from doing so.\nat their own discretion 由他们自己决定 constituent 选民","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_631789eb2d6b6b0dab5749c0', 'ielts_group_119b66c935ff9a76920b9393', 'PART_1', 1, 'Which instrument do you like listening to most? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think I definitely prefer listening to the guitar, more than any other instruments. Especially acoustic guitars. There''s just something very beautiful and soothing about it; it can sound simple, but you can also play more complicated pieces of music with it.\nacoustic guitar 木吉他 soothing 使人平静的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ab0717f4740f6f3587c9e375', 'ielts_group_119b66c935ff9a76920b9393', 'PART_1', 2, 'Have you ever learned to play a musical instrument? [Which one?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I learned how to play the piano when I was younger. But I can''t stand it. It was too boring and too difficult, besides, I didn''t like to practice.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_97a6fed7d93ed7ba4f1d8c5f', 'ielts_group_119b66c935ff9a76920b9393', 'PART_1', 3, 'Do you think children should learn to play a musical instrument at school? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Oh, I think that music is a very important part of a person''s education. Being able to make music is a wonderful talent to have. As with many other things, the earlier you start learning, the better.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_557caa578ab8c74c684ef8e5', 'ielts_group_119b66c935ff9a76920b9393', 'PART_1', 4, 'How easy would it be to learn to play an instrument without a teacher? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"That would depend on the instrument, I guess. Some instruments are fairly simple to play, like a mouth organ or a guitar, and you can learn from books. For other instruments, I think you''d probably need a teacher.\nmouth organ 口琴","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c4e34a1f41e079ebbbc21bbf', 'ielts_group_10a31090a1fe3e9c9c12ddc8', 'PART_2', 1, 'Describe something healthy you enjoy doing.', '["what you do","where you do it","who you do it with","and explain why you think doing this is healthy."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"点题：Well…um, you know I''m not a particularly sporty person—I''m actually quite lazy！But one thing I do like to do is to go to the spa.\n位置和人员具体活动：There''s a spa not too far away from where I work, that I like to go to on a regular basis. Sometimes my mom or my sister comes with me, and sometimes I invite some of my colleagues after work.\n原因：There''s a really big pool there, which is great, because swimming is one of the best forms of exercise. My mom and I could swim back and forth for ages! We go swimming in the pool, take a long sauna, l have a massage, get our faces done, get our fingernails manicured—the whole works!\nAfterwards you just feel so relaxed, and clean and fresh- it''s a wonderful feeling, especially since this city can be so dirty, grimy and polluted! Going to the spa is great for your skin, gives you good exercise, relaxes any tense muscles, is good for your heart and most of all it relieves pressure from your mind and gives you some time to spend with others. After you get home from the spa, and go to bed, you always have deep sound sleep, which is wonderful for your health.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_383d7e4e683ada8b5dec193f', 'ielts_group_10a31090a1fe3e9c9c12ddc8', 'PART_3', 1, 'What do most people do to keep fit in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It differs from place to place, and person to person. The older generation enjoys Taiji, some aerobics, walking or jogging in the park. Younger people often like team sports, such as basketball or football, and many go to the gym. People drink different types of tea, go on special diets, or take some sort of herbal medicine to stay fit and healthy.\naerobics 有氧运动 herbal medicine 草药\ngo to the gym 去健身房","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_30326442001ea9876becce4b', 'ielts_group_10a31090a1fe3e9c9c12ddc8', 'PART_3', 2, 'How important is it for people to do some regular physical exercise?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Very important your life could depend on it. Everybody needs to have regular exercise；I read somewhere that even just 8 minutes of solid exercise to get your heart pumping is enough to do the trick. A lot of diseases，heart attacks, and health problems could be prevented through consistent exercise. \nsolid exercise 实实在在的锻炼 consistent 持续的 \ndo the trick 管用","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_89c4d431b8ba6de3e3195b52', 'ielts_group_10a31090a1fe3e9c9c12ddc8', 'PART_3', 3, 'Why do some people think that modern lifestyles are not healthy?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, with so much processed food and so lite time to exercise and pollution in almost every sphere of life, it is easy to see why the modern lifestyle is not healthy. With so many people moving to the cities and the cities becoming overcrowded, which leads to congestion and massive traffic jams, you can see why it is becoming more and more difficult to have a healthy lifestyle. Pressure is another big issue that comes from today''s frantic way of living.\ncongestion 堵塞","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9df2da491293cff6451ecabc', 'ielts_group_10a31090a1fe3e9c9c12ddc8', 'PART_3', 4, 'Why do some people choose to lead unhealthy lives?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"A lot of people just can'' help it as they are almost forced by the circumstances to lead unhealthy lives. It is so much easier to light up a cigarette when tension and pressure levels rise than it is to go out fora walk or a jog to relieve pressure. Likewise when the day is done, why not relax with your buddies over some drinks at a bar, than take a lit time to get quiet and meditate and feel your worries just melt away.\nlikewise 同样，也 meditate 冥想","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_28ad9c14efbaf094dcada3bb', 'ielts_group_10a31090a1fe3e9c9c12ddc8', 'PART_3', 5, 'Should individuals or governments be responsible for making people''s lifestyle healthy?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Governments should just stay out of people''s lifestyle. Individuals should take responsibility for their lifestyles. If they are leading a life that is in effect killing them slowly each day, then they should look around at what other lifestyles are available to them.\nIn effect 从作用上来看","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1e78b1a0ce38a4701d6ef698', 'ielts_group_10a31090a1fe3e9c9c12ddc8', 'PART_3', 6, 'What could be done to encourage people to live in a healthy way?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, there are many methods to encourage people to live in a healthy way. You could have athletes that lead a healthy lifestyle encourage others to get exercise every day. You could have actors and actresses promote a healthy way of living. Of course educating people about the advantages of healthy living is also important to encouraging others to live healthy lifestyles.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8d1646a9bb5a81578d9a5ead', 'ielts_group_d25eefd3ba32c335dc627e9c', 'PART_1', 1, 'How do most people travel to work where you live?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Most people where I live travel by public transport to work and back. They will either travel in buses or the subway.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f745ecd5fe86c041af6d82a3', 'ielts_group_d25eefd3ba32c335dc627e9c', 'PART_1', 2, 'What traffic problems are there in your area? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, we don''t have so many traffic problems where I live. I live beyond the fourth ring road in Beijing and traffic is pretty smooth by the time it gets here. I guess the only problem here would be going into the city at rush hour. The subway cars are a little crowded, as a matter of fact you feel a lite like a sardine traveling in a tin can.\nsardine 沙丁鱼","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_69fd3f193b2f55f82c3a985f', 'ielts_group_d25eefd3ba32c335dc627e9c', 'PART_1', 3, 'How do traffic problems affect you?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, it depends on what kind of mood I am in, as to whether I am affected by traffic problems or not. If I am late and trying to get somewhere to an appointment then I am affected quite a bit by traffic problems. I get very frustrated and a lit angry when I am under this kind of pressure. If I am just going on an outing and have no timetable and I get stuck in traffic then I either people-watch or listen to my MP3 player or read something.\nget stuck in traffic 堵在路上","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_19159e1f1871a300609424b8', 'ielts_group_d25eefd3ba32c335dc627e9c', 'PART_1', 4, 'How would you reduce the traffic problems in your area?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I would call a moratorium on taking your car to work and have everyone go back to riding bicycles. I know this sounds simplistic and in practical terms, it probably wouldn''t be accepted but that is what I would do to help solve the traffic problem.\nmoratorium 晋令 simplistic 过于简单化的\nin practical terms 实际上","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7734933eb0808363f8b12e73', 'ielts_group_b9a82c8d6e52355734298222', 'PART_2', 1, 'Describe a game or sport you enjoy playing', '["what kind of game or sport it is","who you play it with","where you play it","and explain why you enjoy playing it."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"点题：I don''t know when I fell in love with basketball but at some point in my life, I just felt that if you are going to play a game and get exercise why not really make the most of it.\n细化描述：I played on my high school team for a couple of years and then played for my neighbourhood team. There is just something about bouncing a ball while running at the same time and looking for your teammates to throw the ball to or throwing the ball into the basket if no one is able to take a pass. That is just magic.\n解释原因：It is hard for me to explain how much I enjoy playing basketball to someone who hasn''t played but I will try. It is a fast game and I think that the best athletes in the world play basketball. To me it is almost like watching a ballet on a hardwood floor. I play basketball with whoever would like to play, which is another reason why I like playing. It is usually easy to get a game going. You just have to go to a court with a ball or even without and just start shooting and jumping and rebounding, and dribbling and before you know it you have a game going and some new friends.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_af183c7531bc66b1c733515f', 'ielts_group_b9a82c8d6e52355734298222', 'PART_3', 1, 'How have games changed from the time when you were a child?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t think they have changed that much. Kids pretty much like to run and play hide and seek and outdoor games. I think that the games are pretty much the same. I do think that what has changed is the amount of time that is spent outside playing games. When l was growing up, playing games meant going outside and getting exercise, but now it seems that playing games means staying inside and spending hours on the computer playing computer games.\nhide and seek 捉迷藏","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_adb9800041c7bafb4a779fa0', 'ielts_group_b9a82c8d6e52355734298222', 'PART_3', 2, 'Do you think this has been a positive change? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"This is definitely not a positive change. Unless monitored by parents, children are going to opt for the easy thing to do which is playing computer games and eating snacks. This is going to make for a very unhealthy generation unless something is done about it.\nopt for 选择 make for 带来，导致","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1666373e7028e8ddbeb51626', 'ielts_group_b9a82c8d6e52355734298222', 'PART_3', 3, 'Why do you think children like playing games?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"If you mean outdoor games then I think that playing games helps kids to get exercise, make friends and blow off a lot of energy. They enjoy running around in the fresh air and sunshine and competing with one another.\nblow off 释放，发泄","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_095b228068721e3ae7d45e07', 'ielts_group_b9a82c8d6e52355734298222', 'PART_3', 4, 'Do you think competitive games are good or bad for children? In what ways?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"A little competition is not bad when playing games. But when it becomes the most important thing, it becomes something negative and is not good for a child''s development. Games should be something that is played for fun and recreation and relaxation. When it becomes more than that then the game is out of balance.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9b9f74c2c36c7b9307e805af', 'ielts_group_b9a82c8d6e52355734298222', 'PART_3', 5, 'How can games sometimes help to unite people?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"When you are playing a game as a team and working with others then this helps to build teamwork skills. Just about anything that you do with others helps to bond you with them and helps you to get to know other people. When you are playing games, more often than not, you are relaxing and letting your hair down a little, and you can get to know another side of a person.\nlet your hair down 放松","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_06d4969a27ff7993b690c0fe', 'ielts_group_b9a82c8d6e52355734298222', 'PART_3', 6, 'Why is competition often seen as important in today''s society?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In today''s society because of increasing population and diminishing resources including good jobs, it has become important to compete with your peers. A little of this competition as I said before can be healthy and can motivate you to do your best, but when it is the primary reason for what you do then this can be unhealthy for the person as well as the country.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6bacf164dc613d302d75ec49', 'ielts_group_231b1ea0eff1f925ffd2ee08', 'PART_1', 1, 'Do you prefer to have one particular friend or a group of friends? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In some ways this would depend on the occasion, what I''m doing, etc. But overall I''d prefer to have one very close and dear friend, I''m a quiet person by nature, and I often feel awkward or tense in big groups of people. I''m more comfortable with just one person, and then you can learn to know each other more deeply.\n\nby nature 本性上 tense 紧张 awkward 窘迫","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0bbe6f4883cddb9e5384c2bd', 'ielts_group_231b1ea0eff1f925ffd2ee08', 'PART_1', 2, 'What do you like doing most with your friend/s?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think just sitting around the table and talking over a good meal. The atmosphere is relaxed and informal, we joke a lot, we play around, and have good conversations together and catch up on what''s happening in each other''s lives.\n\ncatch up on 弥补","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8514dcea0114ce6245752f76', 'ielts_group_231b1ea0eff1f925ffd2ee08', 'PART_1', 3, 'Do you think it''s important to keep in contact with friends you knew as a child?[Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I guess so. It''s always sad to lose a good friend, especially from childhood. I think that most people who have kept in contact with their childhood friends have very special and meaningful relationships with them, and can keep their childhood memories alive.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_507051fa492e350775209a87', 'ielts_group_231b1ea0eff1f925ffd2ee08', 'PART_1', 4, 'What makes a friend into a good friend?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"A good friend has many qualities. Perhaps the most important qualities are real love, sincerity and honesty, respect, believing in each other, encouraging each other. Also a good friend is always there for you, always patient - a good friend never gives up on you.\n\nsincerity 真诚","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_bb2409c3a73db5c3018d7faf', 'ielts_group_72f239afcc47eb8453cd3268', 'PART_2', 1, 'Describe an important choice you had to make in your life.', '["when you had to make this choice","what you had to choose between","whether you made a good choice","and explain how you felt when you were making this choice."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"点题讲述：Let me see... some time ago, I had to decide whether or not to move from the city I lived in to go to another city to study.\n\n感受：This wouldn''t have been a very hard decision, because I wasn''t really happy about where I was living; I didn''t feel like my life was going anywhere, and I needed a change. It wouldn''t have been a hard decision, except for the fact that I''d be leaving my boyfriend. We''d been together for almost a year, and were extremely close. It''s always been difficult for me to make decisions, and I procrastinated along time before making this one; I felt confused, unhappy, and so very tired. I knew that if I stayed with him I probably would have been very happy ... but who knows for how long, right? So I decided to move to a different city. Even though it was hard at first, and I was very lonely, I think that I''ve learned a lot, made a lot of progress, and my character has changed and developed for the better. I don''t regret making this choice, although I still miss my boyfriend and sometimes I wonder what life might have been like, if we were still together.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4f6f0825e96cdd9fe0fd801e', 'ielts_group_72f239afcc47eb8453cd3268', 'PART_3', 1, 'What are the typical choices people make at different stages of their lives?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Perhaps some of the more important decisions people are faced with are, what to study, what kind of career they would want, what job to take, if they should travel, who to marry, how to raise their children, etc. Of course, there are many little choices that we make day-by-day that shape our character and our future.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f09099de2366ca4eb6e39e70', 'ielts_group_72f239afcc47eb8453cd3268', 'PART_3', 2, 'Should important choices be made by parents rather than by young adults?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t think so. Once a person has reached adulthood he should be mature enough, and responsible enough to make his own decisions. When parents make decisions for their grown children, it often results in them feeling resentful or pressured, with both sides blaming each other. It makes the young adult lazy and indecisive. Parents should let their children learn how to make decisions, even if it has some bad consequences: the experience is good for them.\n\nresentful 愤恨的 indecisive 优柔寡断的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7ffac32d23ea0df8e92fe4ce', 'ielts_group_72f239afcc47eb8453cd3268', 'PART_3', 3, 'Why do some people like to discuss choices with other people?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"To get advice, I suppose, additional information, and an outside perspective - which can really help, especially if you’re feeling emotional about this choice. It''s wise to benefit from the experiences of others. A person''s perspective is limited, and it is important to see the big picture, in moments of important decision. Also, sometimes you just need to get the weight off your chest - just talking about the situation helps clarify it in your mind and see the pros and cons, etc.\n\nperspective 视角 get the weight off your chest 一吐为快\n\nemotional 情绪化的 clarify 使清晰","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e2eccdf4c61b413938129bf0', 'ielts_group_72f239afcc47eb8453cd3268', 'PART_3', 4, 'What kind of choices do people have to make in their everyday life?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There are loads of choices that people can make in their everyday life but most of the choices are centered on what they are going to wear or what they are going to eat. You know actually most people don''t like to make choices because they take so much work to try and figure out what is the best thing to do in any given situation. Most people, to be honest, would like others to make choices for them.\n\nloads of 很多的 be centred on 集中于","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5c1bdbcc09094ec0a72b7b3c', 'ielts_group_72f239afcc47eb8453cd3268', 'PART_3', 5, 'Why do some people choose to do the same things every day? Are there any disadvantages in this?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"As I just said, a lot of people don''t like to make choices, too much work, they say, so they just get into a rut or a routine and do the same things every day. Now some things are good that you do them every day, like brushing your teeth but other things should change as “variety is the spice of life.”\n\nrut 一成不变的局面","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_36fd83b24a526cbb16334789', 'ielts_group_72f239afcc47eb8453cd3268', 'PART_3', 6, 'Do you think that people today have more choices to make today than in the past?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Oh, people have a lot more choices today than in the past. You can see that as evidenced by the number of channels on a TV, or the number of sites on the Internet or the number of brands of foods that you can choose from in a supermarket. Choices just seem to keep coming at people and how they deal with these choices, sometimes even tiniest details choices, can make or break a life.\n\nmake or break 决定成败","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_951ac8e4bfd0659e12a879d1', 'ielts_group_84467184f8e30142e2ba9b72', 'PART_1', 1, 'How do you usually contact your friends? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I usually chat with my friends by MSN Messenger or by Email because I''m a mouse potato. I spend a great deal of time on the computer every day. If there''s a serious topic to talk about, I will choose face-to-face communication because eye contact and body language can avoid misunderstanding.\n\nmouse potato 电脑迷（仿couch potato构词） eye contact 眼神交流\n\nbody language 肢体语言 misunderstanding 误解","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_73e1dfb532679a8b8cdb7019', 'ielts_group_84467184f8e30142e2ba9b72', 'PART_1', 2, 'Do you prefer to contact different people in different ways? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I do. For those acquaintances, I don''t see them face-to-face very often, just greet them on some festivals by telephone. I like to meet my close friends every weekend because I know they are my real friends and will last forever.\n\nacquaintance 认识的人 greet 问候 \n\nlast forever 永远持续","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_23cf97b8be26ab5f12344843', 'ielts_group_84467184f8e30142e2ba9b72', 'PART_1', 3, 'Do you find it easy to keep in contact with friends and family? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes. It''s easy for people to keep in touch with each other by many ways: letters, digital cameras, cell phones, blogs, and so on and so forth. Email is the most convenient way to contact people if you have their email addresses. But the only pain for me is that sometimes I have to email too many people back, whatever hypocritically or sincerely.\n\ncell phone 手机 blog 博客\n\nso on and so forth 等等 pain 痛苦\n\nhypocritically 虚伪的 sincerely 真诚的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_39d0fb298afd7ea58f2e2236', 'ielts_group_84467184f8e30142e2ba9b72', 'PART_1', 4, 'In your country, did people in the past keep in contact in the same ways as they do today?[Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"People in the past contacted each other mainly by handwriting letters. Today, emails are used more because they don''t have to go wait a day and have a stamp. But getting a hand written letter seems to spark a more personal felling. I think it is a lost art in this modern world of text messaging and emails.\n\nhandwriting letters手写的书信 stamp邮票\n\nspark闪烁，闪耀 personal felling个人感觉\n\nlos tart失传的艺术 text messaging手机短信","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_00e227f55b0893edc088dbcf', 'ielts_group_69053798733fcba75dfda9c3', 'PART_2', 1, 'Describe a party that you enjoyed.', '["whose party it was and what it wascelebrating","where the party was held and who went to it","what people did during the party","and explain what you enjoyed about this party."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"点题： OK, I’d like to talk about a party I attended last year, it was enjoyable.\n\n聚会目的： One thing our family does every year is to all come together in my grandmother’s house celebrate her birthday. Her birthday comes in December, just 2 days after the Christmas.\n\n地点人员： The whole clan was there. That is, my entire extended family including my uncles, aunts, cousins, and grandparents. We go to my grandmother''s house because she''s old and finds it difficult to travel very far, so it''s easier if we come to her. I also saw my Uncle Bernard who''s living in Germany, He can tell some side-splitting jokes.\n\n活动： We had a huge meal with my grandmother which everyone helped to cook. We sat around our dinner table eating delicious food and catching up on all our news. Every family member gave my grandmother a gift and a best wish.\n\n为何喜欢： I love these big get-togethers because it''s the only time I get to see some of my relatives. We live all over the country so without family events like this one we might not see each other at all. I like the way everyone is relaxed and enjoying themselves and not thinking about the pressures of their normal lives back home. It was rather a family party than a birthday party for us. It''s great for everyone to catch up and come together as a family. We also played games together and generally had fun. By the end I was so tired I was falling asleep on my feet but it was good fun.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1a3d1258a3ba2d705a7a70c8', 'ielts_group_69053798733fcba75dfda9c3', 'PART_3', 1, 'What are the main reasons why people organise family parties in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It''s great being able to see everyone again and enjoy one another''s company. It''s also a great way to share the love everyone has for the family and bring us closer together. People say \"You can choose your friends, but you can''t choose your family, which means that even if your family members are annoying you can''t change the situation. Sometimes there can be arguments and the atmosphere can turn sour. It''s also difficult to get away and do your own thing if there''s so much pressure to be together as a family during these occasions.\n\ncompany朋友；伙伴 turn sour变味","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_14ef8bb1b1cc2eda7c63ec07', 'ielts_group_69053798733fcba75dfda9c3', 'PART_3', 2, 'In some places people spend a lot of money on parties that celebrate special family events. Is this ever true in your country? Do you think this is a good trend or a bad trend?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It does happen somewhere in China. I think the main reason people tend to push the boat out for special family events like weddings is that it''s a unique event that will only happen once in their lives. They want to make it special and something to remember. Another factor is the desire to impress all your friends and relatives who will come to the family events. Not only do you want them to have fun and enjoy the occasion but you also want to show off a bit. I don''t think it''s a good trend to splash out ridiculous amounts of money on special family events.\n\npush the boat out举行在狂欢的聚会 ridiculous荒唐\n\nshow off炫耀 splash out肆意挥霍","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_da1e314bb8656b024d91346d', 'ielts_group_69053798733fcba75dfda9c3', 'PART_3', 3, 'Are there many differences between family parties and parties given by friends? Why do you think this is?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Gathering with friends is more relaxed, there''s usually a disco or bowling, more interesting. Family parties are a bit boring because there are usually food and talking. Also, friend''s party can reinforce the bonds of a social group. In some contexts, it can strengthen business related bonds, strengthen a sense of team and make contacts to further one''s career.\n\nreinforce 加强 social group社会团体\n\nbusiness bond生意圈 sense of team团队感","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_462fc10dbe63eb6faa370e77', 'ielts_group_69053798733fcba75dfda9c3', 'PART_3', 4, 'What kinds of national celebration do you have in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There are many kinds of national days in China. New Year''s Day. It is a grand occasion for the Chinese people. They celebrate the New Year like people all over the world. Spring Festival, which is held on the first day of the fist lunar month and lasting for two weeks, is regarded by the Chinese people as the grandest and most important annual festival. Oct, 1st is China''s National Day. It is a festival of great importance 10 the people nationwide and they celebrate it with great felicitation.\n\ngrand重要的，重大的 lunar month阴历月\n\nnationwide全国性的 felicitation庆祝","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f64b9b8caae39bd63aa9d3c1', 'ielts_group_69053798733fcba75dfda9c3', 'PART_3', 5, 'Who tends to enjoy national celebrations more: young people or old people? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I will say: Seniors. Kids today are not taught what our national celebrations mean. I mean it truly means. It''s one thing to say we got our National day on Oct 1st, or what Labor day means, but the youth of today are not taught or experienced enough to enjoy them other than as a day off or a day to BBQ. Seniors, on the other hand, have in many cases served in the army, or have good friends who have, or lived through a war. Seniors understand and appreciate our national celebrations more, so they maybe not \"enjoy\" like partying. but revere them more.\nLabor day劳动节 a day off放假一天\nSeniors老年人 served in the army在军中服役，当兵\nrevere崇敬，尊敬","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2d1dc9186f3abec0c792c878', 'ielts_group_69053798733fcba75dfda9c3', 'PART_3', 6, 'Why do you think some people think that national celebrations are a waste of government money? Would you agree or disagree with this view? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I totally agree with that. I''m fed up with those never-ending national celebrations. Spending too much money on vanity projects is extravagant, and it''s \"a sheer waste of the tax payers'' money\". The government should use this money to quickly resettle the disaster stricken victims. I believe: what is taken from the people is used in the interests of the people.\nfed up厌倦，厌烦 never-ending无休止的\nvanity projects形象、面子工程 extravagant铺张浪费的\nsheer绝的，十足的 disaster stricken victims灾民\nresettle重新定居，安居\nwhat is taken from the people is used in the interests of the people取之于民，用之于民","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b292af6cc4af93e7d54fc25c', 'ielts_group_fd87f9e8244663575b2c6990', 'PART_1', 1, 'What kinds of thing make you laugh?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, lots of stuff can make me laugh in my daily life. A joke, a comedy, a funny face, there are too many tolist. I laugh hardest at something that people doing goofy weird things.\n\ngoofy愚笨的 weird奇怪的，怪异","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ebf58662954e706e537964e3', 'ielts_group_fd87f9e8244663575b2c6990', 'PART_1', 2, 'Do you like making other people laugh? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Of course I do. I have sense of humour and I can laugh people''s head off I think I may have been a jester in a previous life. I like seeing them smile and know that it''s because of me. And also it''s a nice way to have someone remember you.\nsense of humour幽默感 laugh one''s head off使笑得人前仰后合\n\njester爱开玩笑的人 previous life前世，前生","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_96ed23cb7e3118564cb3f525', 'ielts_group_fd87f9e8244663575b2c6990', 'PART_1', 3, 'Do you think it''s important for people to laugh? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, laughing is good for health because when we laugh, we get rid of stress. Also, while we are laughing, more face muscles are activated. So laughter may prove to be the best medicine, at least as far as the heart is concerned. \nget rid of stress去除压力 face muscle面部肌肉\n\nlaughter笑","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ef32678224e3a97aa4797243', 'ielts_group_fd87f9e8244663575b2c6990', 'PART_1', 4, 'Is laughing the same as feeling happy, do you think? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Laughing is generally associated with feeling happy, but it does not always mean the person is happy. Sometimes people laugh when they are mad, scared, or feeling uneasy. Another example is sarcastic laugh does not represent feeling happy either.\n\nassociated with与……联系在一起 scared害怕的\n\nuneasy不自在的，不安的 sarcastic laugh讥讽的笑","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f93bbab7afce100492cda497', 'ielts_group_17acb821a6dce8305b7b17c8', 'PART_2', 1, 'Describe an idea you had for improving something at work or college.', '["when and where you had your idea","what your idea was","who you told about your idea","and explain why you thought your idea would make an improvement."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"点题: I would like to talk about the smart idea I had 1 year ago for improving my English. Talking in the English Corner.\n\n交代背景: I had really bad feeling about my Spoken English about a year ago. My pronunciation and tone were understandable but the irritating thing is that I couldn''t express myself with ease. For instance, I always felt frustrated about talking with others.\n\n介绍想法: I read English books loudly at home everyday, but actually it didn''t work at all. 2 months after my self-practicing, I came across an American asking for directions, I tried to help, but couldn''t say anything. Then I realized that I should spend time on real talking, not reading. An idea popped up in mind: Practicing in English Corner.\n\n可以有何改善: There was a biggest English corner around my campus and I could go there everyday. There were many English-speakers being surrounded by Chinese students who wanted to chat. English corner is a good place as where we may exchange English study experience, widen our sight and improve interest in English. I would grasp every chance to talk to foreigners there and if I kept on speaking English everyday, my language ability will be greatly improved. It won''t take too long, I would find that I could express my idea in English without difficulty. Everyone knows that practice makes perfect, English corner could help me to overcome the biggest problem—shyness, which accounts for 90% of my disappointment.\n\n点题: OK. That''s my idea for improving English. I just started last month, hopefully I will succeed.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8f9776a4b9c210dc48aeabf2', 'ielts_group_17acb821a6dce8305b7b17c8', 'PART_3', 1, 'Some people think that education should be about memorising the important ideas of the past. Do you agree or disagree? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well. Personally, I don''t agree with that. Memorising past ideas is the same as rote learning, which is learning by repetition. The amount of knowledge we obtain through rote learning accounts for a minor part of our learning process. The priority of education is to provide a solid foundation and accumulation of academic knowledge which is utilized as basis of future research. Employing the knowledge itself and the corresponding methods for further academic fulfillment encourages initiatives.\n\nrote learning机械学习 repetition 重复\n\nsolid foundation坚实的基础 accumulation积聚，累积\n\nacademic knowledge学术知识 utilize 利用\n\nacademic fulfillment学术实践 initiatives 创新精神","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_851d04235f4c0c6f8bf26edc', 'ielts_group_17acb821a6dce8305b7b17c8', 'PART_3', 2, 'Should education encourage students to have their own new ideas? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes. In fact, that''s the basic framework of education, Education should encourage students and build up their inner abilities so that they can reach for the skies and build up their dreams. It definitely encourages them as it gives them the confidence of reality. But unfortunately, I don''t see this being implemented in the public schools.\n\nframework结构，框架 inner abilities内在能力\n\nreality 现实 implement实现，实行","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_06e0aaf46cdf11d69796b03c', 'ielts_group_17acb821a6dce8305b7b17c8', 'PART_3', 3, 'How do you think teachers could help students to develop and share their own ideas?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Teachers can have them brainstorm in groups or have a sheet where students anonymously share ideas. Another good way is: setting up a website where people ask all kinds of questions and other people get to answer them. Anyway, education should encourage student''s independent thinking. which results from what they absorb from past important ideas.\nbrainstorm头脑风暴 anonymously匿名地\nshare ideas分享想法 independent thinking独立思考\n\nresult from由于，起因于 absorb吸收","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b53566cd8294190abc0605ea', 'ielts_group_17acb821a6dce8305b7b17c8', 'PART_3', 4, 'Should employers encourage their workers to have new ideas about improving the company? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Of course they should It can improve the bottom line and productivity. Also, it can encourage teamwork, dedication and allegiance amongst the staff and retention is the key to a successful company. What''s more, encouraging workers to have new ideas make bosses approachable, so workers feel like they are contributing to their company. Employers might get some ideas out of the workforce. Anyway, the employees work there and any ideas they might have for improving the company should be welcome.\nbottom line盈亏 productivity生产率\n\ndedication奉献 allegiance忠诚\nretention保持力，凝聚力 approachable易接近的,亲切的\n\ncontribute to 贡献给，有助于 workforce劳动力","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_364f950446680be0748d8c96', 'ielts_group_17acb821a6dce8305b7b17c8', 'PART_3', 5, 'Do you think people sometimes dislike ideas just because they are new? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t think so. There''s nothing to do with \"new and old\". Everyone is scared of the unknown. People dislike new ideas mainly because those ideas haven''t been put into practice yet. Every idea throughout history has already come to fruition. A new idea without a strategy, without action, is useless. So whatever new or old, putting into practice is the key.\nnothing to do with 与……无关 be scared 害怕\n\nunknown未知 fruition结果","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0ca6ce0f7955e0c7295b7883', 'ielts_group_17acb821a6dce8305b7b17c8', 'PART_3', 6, 'What is more difficult: having new ideas or putting them into practice? Which is more important for a successful company?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I would say that putting ideas into practice is by far the more important for sccessful company. An old phrase that \"Ideas are cheap\" is true. Excellent strategies, plans, and product ideas are the easy parts of being successful. The more important and harder part is executing in the market. Arnold Glasgow said, \"Ideas not coupled with action never become bigger than the brain cells they occupied.\" It''s implementation that creates the real value. Ideas by themselves are worthless, unless they are followed with action.\n\nby far到目前为止 ideas are cheap创意是廉价的\nstrategy策略 Arnold Glasgow阿诺德·格拉斯哥(管理学家)\n\nbrain cell脑细胞 implementation施行，履行","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4c6d53e06b49d16e7462860e', 'ielts_group_4553756e69e805f9168cc6ef', 'PART_1', 1, 'Have you ever been in very cold weather? [When?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I have. I went to the Harbin which is a big city located in Northeast of China in the winter a few years ago for my sister''s wedding, I''m someone who hates coldness then I got a really bad cold. But luckily, the wedding was nice.\n\ncoldness寒冷 bad cold感冒","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_52a67dce6f6c4bf9e7d6b70a', 'ielts_group_4553756e69e805f9168cc6ef', 'PART_1', 2, 'How often is the weather cold where you come from?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''m a local here in Beijing where we have a clear division of the four seasons, which means we would normally have several months of winter every year.\n\nlocal本地人 clear division清晰的划分","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_22d3e6cd6252bd08528071c1', 'ielts_group_4553756e69e805f9168cc6ef', 'PART_1', 3, 'Are some parts of your country colder than others? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, of course. China is such a big country with huge space for its huge population. We do have areas in different geographical altitudes. I''m not really an expert on this, but I think the territory of China expands to areas called '' tropical zone''，‘ moderate zone’ and ‘subfrigid zone’.\n\nhuge population巨大的人口 geographical地理的\n\naltitude海拔，高度 tropical zone热带区\n\nmoderate zone温带区 subfrigid zone亚寒带区","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4474a1823baec61fbac32a0f', 'ielts_group_4553756e69e805f9168cc6ef', 'PART_1', 4, 'Would you prefer to live in a hot place or a cold place? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I personally prefer warm places, for really simple reason, because I just cannot stand the coldness of winter. Plus, though I''m not sure about the reason, people in hot places are normally slim. Perhaps it''s because they don''t have good appetite and eat less.\n\nwarm place温暖的地方 cannot stand无法忍受\n\nslim苗条的 appetite 胃口","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_58a0ca3d250fea658bb784c7', 'ielts_group_8621aea614e86e12bfe41274', 'PART_2', 1, 'Describe a competition (e.g. TV, college/work or sports competition) that you took part in.', '["what kind of competition it was and how you","found out about it","what you had to do","what the prizes were","and explain why you chose to take part in this competition."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"点题：Let me talk about a badminton competition I took part in last summer.\n\n从何得知：Last summer, the student union organized a badminton tournament in our college. Posters of this competition were all over the campus.\n\n作何准备：For this badminton competition, I had to prepare some basic equipment: A racket and many badminton balls, Badminton rackets look a lot like tennis rackets, but they are much more delicate. The ball is called birdie. The birdie has a small rubber half a ball on one end, and it fans out with feathers on the other end to help it to fly.\n\n比赛奖励：The prizes for the tournament are awarded to 1st & 2nd place included: up to Y 500 cash, value barbecue coupon for￥200.\n\n为何参加：I always love to play badminton especially in the summer time. It is a game I really enjoy, so play it whenever I can get a willing partner. It is a lot like tennis, but I can play badminton anywhere. I do not have to go to a tennis court to play and I can play in between classes without getting sweaty. It is a game that takes a lot of energy so you get plenty of exercise playing badminton. The main reason I chose this competition was that everyone, man or woman, has an equal chance to compete. There are so many sports that require height or strength to be good; it is refreshing to play one that I have an equal opportunity to win. Maybe that is why I got very competitive and energetic when I played. I love the game; it was fun and rewarding, and I felt alive when playing.","translation":"","usageNote":"原题库提供的参考表达"},{"type":"EXPRESSION","expression":"tournament","translation":"比赛，锦标赛 racket球拍","usageNote":""},{"type":"EXPRESSION","expression":"birdie","translation":"羽毛球的球 rubber half a ball橡胶半球","usageNote":""},{"type":"EXPRESSION","expression":"fan out","translation":"拍打出去 barbecue coupon烧烤代金券","usageNote":""},{"type":"EXPRESSION","expression":"willing partner","translation":"愿合作的搭档 tennis court网球场","usageNote":""},{"type":"EXPRESSION","expression":"rewarding","translation":"有益的","usageNote":""}]'::JSONB),
    ('ielts_q_c3967fdc397bf1b24f78e12e', 'ielts_group_8621aea614e86e12bfe41274', 'PART_3', 1, 'Why do you think some school teachers use competitions as class activities?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think one important responsibility of teachers is to promote the students'' desire to be someone strong and prepare them for the future. Competition never sleeps. This is an awareness without which anyone joining the labour market would not succeed. It''s always better to realize the cruelty before the students get shocked in the future.\n\npromote促进 awareness认识\n\nlabour market劳动力市场 get shocked被震惊","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a4bdef4772ae828159683dc9', 'ielts_group_8621aea614e86e12bfe41274', 'PART_3', 2, 'Do you think it is a good thing to give prizes to children who do well at school? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I do think so. For one thing, people by nature make all their efforts to gain the most pleasure and avoid pain. Children love games and having fun indeed, and they hate study. So if a child achieves something at school, a prize will apparently enhance his or her sense of satisfactory, which has always resulted in constant good performance. For the other, those children who cannot get the prize would feel that they want the same thing. Then prizes become a strong motivator for them.\n\nby nature生性，本性 pain痛苦\n\napparently 显然地 enhance加强，增强\n\nsense of satisfactory满足感 constant持续的\n\nmotivator动力","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB)
ON CONFLICT (id) DO UPDATE SET
    topic_id = EXCLUDED.topic_id,
    part = EXCLUDED.part,
    sort_no = EXCLUDED.sort_no,
    question_text = EXCLUDED.question_text,
    cue_points = EXCLUDED.cue_points,
    recommended_expressions = EXCLUDED.recommended_expressions;

INSERT INTO ielts_question (
    id, topic_id, part, sort_no, question_text, cue_points, recommended_expressions
)
VALUES
    ('ielts_q_b7ad6e9ae5365fdfc44560c8', 'ielts_group_8621aea614e86e12bfe41274', 'PART_3', 3, 'Would you say that schools for young children have become more or less competitive since you were that age? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I would say, as far as I know, schools in China have become more competitive. Children in primary schools are requested by their parents and teachers to learn the knowledge for secondary school students, only as a preparation for their future school entrance examination. Once they pass the exam, the vicious circle continues. Secondary school students spend a huge amount of time doing studies much beyond their capability. It was not like this when I was a child. I had more time to enjoy myself.\n\nprimary school小学 secondary school中学\n\nentrance examination入学考试 vicious circle患性循环\n\nbeyond capability超出能力范国","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e55fce24298511b84f9bf5af', 'ielts_group_8621aea614e86e12bfe41274', 'PART_3', 4, 'What are the advantages and disadvantages of intensive training for young sportspeople?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''m only a layman in this field, so I''m not so confident of judging whether there''s any advantage or disadvantage. I could only answer the question according to my own knowledge. I think if intensive training is necessary for a particular sport, it''s better to start early than doing it when someone is not physically qualified anymore. There normally seems 10 be a short career life for sportspeople, perhaps an early start brings a lengthened career.\n\nlayman门外议 physically qualified身体上\n\ncareer life职业生涯 lengthened延长的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_414a30904adddc3bf506ca91', 'ielts_group_8621aea614e86e12bfe41274', 'PART_3', 5, 'Some people think that competition leads to a better performance from sports stars. Others think it just makes players feel insecure. What is your opinion?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"l agree with the latter view. Personally I think laziness is an inborn nature of people, and only could we make progress when there''s strong pressure and motivation for success, or even the threat of being punished for being a loser. Competition is a good and elective approach 10 force one to pursue greater achievement and greater honour.\n\nlatter 后面的 laziness懒情\n\ninborn nature天性 loser失败者\n\napproach途径，手段","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_395e45f812d9e4a17d470ef9', 'ielts_group_8621aea614e86e12bfe41274', 'PART_3', 6, 'Do you think that it is possible to become too competitive in sport? In what way?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"No. never. If we find something very or too competitive. it seems we are cither not qualified or even incompetent or there are people who are equally competent or even stronger. I would say it''s a good way to motivate people, I mean, to motivate some people, because there are always someone who are incapable of taking responsibility and facing threats. And it''s the same for sportspeople in their search for the infinity of humankind.\n\nincompetent无能力的 equally同样地，同等地\n\nmotivate激励 incapable无能力的\n\ninfinity 无限 humankind人类","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e0245eb8941a1372ed0ceee5', 'ielts_group_1ff13574127bc8c89b6fd1b2', 'PART_1', 1, 'How do you usually travel to work or college? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t have a car, so I usually use public transport. I take subway the most often because it''s quite convenient for me. Sometimes I will ride bicycle to avoid being stuck in heavy traffic.\n\npublic transport 公共交通 subway 地铁\n\nconvenient 方便的 be stuck in 堵住\n\nheavy traffic 堵车，拥堵的交通","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0cfcef9fcc6915928a584bbb', 'ielts_group_1ff13574127bc8c89b6fd1b2', 'PART_1', 2, 'Have you always travelled to work/college in the same way? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I have, because for a beiinger, subway is the only form of transportation I can rely on. I used to travel by bus, but a 20 minutes'' run could take more than an hour during peak hour. If I travel by underground, however, I can plan my time to work precisely according to my experience and traffic won''t be of any concerns.\n\nbeijinger 北京人 rely on 依靠，依赖\n\npeak hour 高峰期 precisely 准确地，精确地\n\nconcern 担心，关切","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_da2de716407ea313ef2af000', 'ielts_group_1ff13574127bc8c89b6fd1b2', 'PART_1', 3, 'What do you like about travelling to work/college this way?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Traveling by subway is a 100% time guaranteed transportation for a city dweller. Plus, it offers opportunity for me to refresh myself; I mean, spiritually refresh and reflect what I did yesterday and plan for the future if possible.\n\ntime guaranteed 有时间保证的 city dweller 城市居民\n\nrefresh 提起精神 spiritually 精神上地","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_daf1d06b7563381833223a45', 'ielts_group_1ff13574127bc8c89b6fd1b2', 'PART_1', 4, 'What changes would improve the way you travel to work/college? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There are many things to do for the improvement. Adding more garbage or trash cans, lowering the fare, upgrading the access for those with physical challenges, and opening up the shops on some subway stations where at one time, you could buy all kinds of things. All of these can make the station more up to date.\n\ngarbage 垃圾 trash 垃圾\n\nfare 费用 upgrade 升级\n\nphysical challenge 身体不便","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_451b16d4f54e13928615b097', 'ielts_group_e88102f2ae8f46a99bee4ffa', 'PART_2', 1, 'Describe a piece of electronic equipment that you find useful.', '["what it is","how you learned to use it","how long you have had it","and explain why you find this piece of electronic equipment useful."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"点题：The electronic thing I found useful is an Electronic English-Chinese Dictionary. This gadget was given by my granny on my 18th birthday. It''s handy, glossy, light weight, and super thin.\n\n外观：It has a PDA style interface, where I could write an unknown character, then have the dictionary magically tell me what it was.\n\n为何选择：I''d say that it was in high school that l''ve really felt the urge to get one to help with my English learning. I had this gadget with me everywhere in the last 3 years of my high school. As I mentioned, it''s completely portable and very light weight, so it''s easy to put into my back pocket.\n\n为何有用：The dictionary includes not only definitions, but plenty of usage examples and sentences. It contains great idiomatic and colloquial phrases, both for US and UK English—in addition to the more \"standard\" used meanings. Also, the word search history list makes it very easy to jump back to a word you looked up earlier, making it a very valuable study tool. Its popularity amongst young people also has had a persuasive effect on me. I personally think my electronic dictionary is the single best investment.\n\n重点词汇：\n\ngadget小物件，小玩意 handy方便的\n\nglossy有光泽的 light weight轻的\n\nsuper thin超薄的 interface界面\n\nmagically魔法般地 portable便携的\n\nidiomatic习语 colloquial口语的\n\nsearch history list历史查询列表 \n\npersuasive有说服力的\n\ninvestment投资","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fb3df26d13146f7bde67898d', 'ielts_group_e88102f2ae8f46a99bee4ffa', 'PART_3', 1, 'What kinds of machine are used for housework in modern homes in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I would have to say washing machine, vacuum cleaner, rice cooker, coffee maker, electric kettle, air conditioner, furnace, etc. Those would be the ones I couldn''t live without or I mean wouldn''t want to do without.\n\nwashing machine 洗衣机 vacuum cleaner 吸尘器\n\nrice cooker 电饭煲 coffee maker 咖啡壶，咖啡机\n\nelectric kettle 电热水壶 furnace 炉子","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_72faa7c06f01653d4f934fff', 'ielts_group_e88102f2ae8f46a99bee4ffa', 'PART_3', 2, 'How have these machines benefited people? Are there any negative effects of using them?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"With the aid of electrical equipment, we are able to work quickly and efficiently. It makes our life easier and convenient. However, there are some disadvantages of using electrical equipment. People will become totally dependent on equipment and not to do things they could do themselves. Sometimes using electrical equipment might be quite expensive because it will consume large amount of electricity. Lastly, people could get electrocuted if using them carelessly, which happens every year.\n\naid 帮助 dependent 依赖的，依靠的\n\nelectrocute 触电，电击 consume 消耗，花费","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c4b54d3bff261c4ea92c069b', 'ielts_group_e88102f2ae8f46a99bee4ffa', 'PART_3', 3, 'Do you think all new homes will be equipped with household machines in the future? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Electricity has truly become the lifeblood of our society. Right now we can''t live without electrical devices because we rely on them to make our life easier. Many of us have become addicted to what can be done with indoor plumbing, the Internet and cell phones. All homes without household machines is possible but it would take a lot of adjusting. We''d have to buy all the non-electric tools to make life workable—wood/cook stove, build an outdoor ice box, dig a well to keep food cool, and top it off with lots of patience, as nothing is fast and easy in a non-electrical world.\n\nlifeblood 血液 electrical devices 电子设备\n\naddicted to 对.....上瘾 indoor plumbing 家用工具\n\nice box 冰箱","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c296a02d755d1bd975fd9182', 'ielts_group_e88102f2ae8f46a99bee4ffa', 'PART_3', 4, 'What kinds of equipment do most workers need to use in offices today?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think people at work rely much on modern technology, especially computer and Internet. Many people can''t spell some words right because they are too used to the Office Software which provides users with the spelling check. They can also use Internet to collect data and information and analyze them. Modern equipment provides all kinds of resources which will be of great help to people''s work.\n\nOffice Software 办公软件 spelling check 拼写检查\n\ncollect data 搜集数据","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0195f31579a0fc8eeaaedb95', 'ielts_group_e88102f2ae8f46a99bee4ffa', 'PART_3', 5, 'How have developments in technology affected employment in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Technology has allowed computers and machinery to replace manpower. Also, it has made it easier to do some labour intensive jobs with fewer hours. I think it eliminated jobs via increased productivity and made work safer in many areas of industry. For example, a lot of welding on cars is done by robots, which was done by people in the past.\n\nmachinery 机器 manpower 人力\n\nlabour intensive 劳力密集的 еlіmіnаtе 去除，消除\n\nproductivity 生产力 welding 焊接","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_0a73f2055f45111f2882f777', 'ielts_group_e88102f2ae8f46a99bee4ffa', 'PART_3', 6, 'Some people think that technology has brought more stress than benefits to employed people nowadays. Would you agree or disagree? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, I do think so. There used to be plenty of mindless, repetitive and mechanical jobs in all three sectors of the economy, and lots of unskilled people who have to do them. However, with the development of computers and robotics, these people are now substituted by modern technology and are facing the threat of job security. As far as I know, there has been a huge number of people who''ve been made redundant because their jobs are rather routine and can be done by cold machines.\n\nmindless 不用脑子的 repetitive 重复的\n\nmechanical 机械的 unskilled 无技能的\n\nrobotics 机器人技术 substitute 取代，代替\n\nredundant 多余的 routine 一成不变的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6e4a21698e1e4e2edcd97ede', 'ielts_group_8b6320adfe6d211e9465affb', 'PART_1', 1, 'How well do you know the people who live next door to you?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I know all my neighbours. There are a couple living next door who are in their late 20''s. They have two kids and lots of other family members, that I have mostly met. The mom works as a respiratory therapist and the dad is a cop. They are almost like extended family to me. They are always willing to help us if in need and we feel the same for them.\nrespiratory therapist 呼吸治疗师 cop警察\nextended family 大家庭","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ff7b4944bd34499d7a3edbef', 'ielts_group_8b6320adfe6d211e9465affb', 'PART_1', 2, 'How often do you see them? [Why/Why not? ]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Very often. My neighbours have always invited me for dinner. They are the best neighbours I''ve ever known. The great thing about them is that they aren''t fakes but really are genuine and nice people. I am about to move soon and I am really. going to miss them. Hopefully, I will have such great neighbours in the next neighbourhood.\nfake 虚伪的人，骗子 genuine 真诚的\nneighbourhood 小区，社区","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_23cacc9df07e400f052072c4', 'ielts_group_8b6320adfe6d211e9465affb', 'PART_1', 3, 'What kinds of problem do people sometimes have with their neighbours?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Neighbourhood disputes are a very common occurrence, I have been affected by some of the issues that frequently crop up. The most common issue that causes tension between neighbours seems to be noise. Arguments can arise over who looks after shared facilities, or garden areas, especially in flats. Boundary disputes are also a popular reason for complaint about the neighbours.\ncrop up 突然发生 tension 紧张\nboundary dispute 边界争执 complaint 抱怨，投诉","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_72f173308443b5d56547b4e3', 'ielts_group_8b6320adfe6d211e9465affb', 'PART_1', 4, 'How do you think neighbours can help each other?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There are many things to do. To keep an eye on others'' place as the neighbours work at night or go out of town. To exchange cell numbers with neighbours so just in case anyone needs any help with anything. To invite neighbours if possible to functions you may host at your home. People who know each other in their community are more likely to turn to each other for help, and in the long term cope better with crises and emergencies.\nkeep an eye on 照看，留意 function 聚会\ncommunity 小区，社区 in the long term 长期来说","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6da9a7174748b8132a1f3f6d', 'ielts_group_8cdceb8d1e65c5b7171a74f8', 'PART_2', 1, 'Describe a time when you were asked to give your opinion in a questionnaire or survey', '["what the questionnaire/survey was about","why you were asked to give your opinions","what opinions you gave","and explain how you felt about giving your opinions in this questionnaire/survey."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"何种问卷: Well it was hard to think of a questionnaire that I filled out, but I could talk about the evaluations we had to fill out at the end of every semester in university.\n问卷目的: Obviously, the school wanted our feedback on the quality of the teacher and our interest in the course. Teacher evaluation by students can go a long way in enhancing the professional performance of teachers. The school also wanted any suggestions that we might have about how to improve in the future.\n答卷感受: I wanted to be helpful to the school, and the form never took very long to fill out, but I still felt a bit uncomfortable with the process. Even though the form was confidential, I was a little concerned about teachers figuring out which form was mine and it seemed awkward to say anything particularly bad about any of the teachers, even if I hadn''t really cared for their classes. It is said that teacher evaluation is vital because it provides specific tips for improvement so that the teacher can learn and grow as much as possible by this. But in my opinion, it’s still hard to give negative feedback about a person. In addition, I never really had any particular suggestion for the school and usually just left that part blank. But hopefully it was still at least a little helpful.\n\n重点词句\n\nfill out 填写 enhance 提高，增强\nnegative feedback 负面反馈意见 evaluation 评估\nconfidential 保密的 go a long way 对……有很大的帮助\nvital 至关重要的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d9280061da69f54b2b6325f1', 'ielts_group_8cdceb8d1e65c5b7171a74f8', 'PART_3', 1, 'What kinds of organisation want to find out about people''s opinions?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Businesses, schools, news sites, and governmental departments all need to do surveys to find out people''s opinions. Businesses need to do market research to learn how people might react to new products and how much they are willing to pay. If they don''t know about their customers well it can be a disaster. Universities need to know that their students are satisfied with campus life and learn what new programs students might like. Newspapers always want to learn people''s opinions about different social issues. And of course, governments occasionally do a census to learn as much as they can about their citizens.\ngovernmental 政府的，政府性质的 campus life 校园生活\nsocial issue 社会问题 census 社会调查，普查","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f4f02bfdaa91d58c238ee3f0', 'ielts_group_8cdceb8d1e65c5b7171a74f8', 'PART_3', 2, 'Do you think that questionnaires or surveys are good ways of finding out people''s opinions?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Surveys have a lot of problems, but they are probably the best way to find out opinions. One major disadvantage of questionnaires is that many people won''t really take them very seriously. I don''t like to fill out surveys and often throw them out or fill them in without thinking things over. So maybe the information gathered isn''t very reliable. However, there is no other more cost-effective way to get opinions from a large group of people.\none way or anther 无论如何 craving 渴望，欲望\nhardwired 嵌入的 primitive 原始的\nplague 瘟疫 social turbulence 社会动荡\nbe free from 摆脱，不受制约的 govern 指导，控制\nbehavioral pattern 行为模式 pursue 追求","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d0a2ffde178b8a6d40db2b1a', 'ielts_group_8cdceb8d1e65c5b7171a74f8', 'PART_3', 3, 'What reasons might people have for not wanting to give their opinions?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I suppose there are a lot of reasons for not giving their opinions. Some people are naturally shy and feel intimidated by questions. Other people might be very busy and not want the hassle of stopping to give a response. There are a lot of groups that demand our attention these days. A third reason that people might not want to share their opinions is that they don''t have any well-defined opinions to give. I’m sometimes very impartial to a lot of things — especially new products — and don''t want to have to take the time to think through my opinion. I guess other people feel that way too.\n\nnaturally 天生的 intimidated 胆怯的\nhаѕѕlе 烦扰，麻烦 well-defined 清楚的，清晰可辨的\nimpartial 公正的，不偏不倚的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_06b353a1eee8fe3220acafde', 'ielts_group_8cdceb8d1e65c5b7171a74f8', 'PART_3', 4, 'Do you think it would be a good idea for schools to ask students their opinions about lessons?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It''s definitely a good idea. I feel that schools need to get constructive feedback in order to develop classes that students will find useful. Education techniques change very quickly these days and I think it''s important for a university to regularly change and adapt. Academic organisations should be as innovative as possible. They can try new programs, ask students their opinions and then decide if they should keep them or not. Also, learning really depends on the quality of the teacher and a school needs to know how students feel about their teachers'' teaching methods so they can make sure they are using the best teachers available.\n\nconstructive 建设性的 academic organisation 学术机构\ninnovative 创新的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_262b931cf1dca428ebfe43cb', 'ielts_group_8cdceb8d1e65c5b7171a74f8', 'PART_3', 5, 'What would the advantages for schools be if they asked students their opinions?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There are many potential advantages of asking students for opinions. They need to keep up to date with students'' desires in order to give them a good learning experience. In addition, it''s possible that students might have really creative suggestions for new programs or services that school administration couldn''t have thought of on their own.\npotential advantage 潜在优势 keep up to date 与时俱进\nlearning experience 学习体验 creative suggestion 创建性的建议","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5f1108d1a31da16a496bd400', 'ielts_group_8cdceb8d1e65c5b7171a74f8', 'PART_3', 6, 'Would there be any disadvantages in asking students'' opinions?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Overall I think there are more advantages than disadvantages to asking students for their opinions, but I suppose I could think of a few disadvantages. One, for example, is that schools need to focus on the core quality of the education but students might put more emphasis on less essential issues, like extracurricular activities or groups. As a result, the school might. feel pressured to change their focus. Additionally, maybe some opinions should be ignored, like if students think coursework is too difficult, the school shouldn''t necessarily ease requirements. \ncore quality 核心质量 emphasis 重点，强调\nextracurricular 课余的 pressured 有压力的\nease requirement 简化需求","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b3c80ecc981fba791da58071', 'ielts_group_b185e26c3c5e9973c7aa5abe', 'PART_1', 1, 'Which magazines and newspapers do you read? [Why? ]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''d like to keep myself informed about international politics and business. The Economist offers the best quality. I really like it. It gives thorough coverage of news from around the world, including places that are often overlooked in other sources. Also, it has a wry sense of humor. I find the captions of the photos to be quite enjoyable.\nkeep someone informed 使某人被告之 coverage 新闻报道 \noverlook 忽略，忽视 wry 挖苦的，讽刺的\nsense of humor 幽默感 caption 说明文字","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c3e2ef333686dfae8ea787b9', 'ielts_group_b185e26c3c5e9973c7aa5abe', 'PART_1', 2, 'What kinds of article are you most interested in? [Why? ]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I enjoy reading articles about international affairs, economic analyses, technological developments, trends, food and travel. I prefer neutral analysis, not just opinions from the left and right. I am not interested in reading any gossip and speculation. I want the facts as far as it is possible, although I know that facts\" are not as they appear.\ninternational affairs 国际事务 trend 潮流趋势\nneutral analysis 中立的趋势 gossip 绯闻，流言\nspeculation 炒作","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_6f61b0b2e4cf7202c0c5a824', 'ielts_group_b185e26c3c5e9973c7aa5abe', 'PART_1', 3, 'Have you ever read a newspaper or magazine in a foreign language? [When/Why? ]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I learned German for two years at university and during this time we were supposed to read German novels as part of the course, but I normally read the English translation as I felt that my German was not at the appropriate level. However, I then realized the only way to get it to the appropriate level is to just read and practice. We should start with children''s books and work our way up.\nbe supposed to 应该（做某事） appropriate level 适合的水平\nwork one''s way up 努力向上","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_833eb6e67515189e0c75191f', 'ielts_group_b185e26c3c5e9973c7aa5abe', 'PART_1', 4, 'Do you think reading a newspaper or magazine in a foreign language is a good way to learn the language? [Why/Why not? ]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes. Buy the unabridged audio books or magazines to read and listen at the same time, so the audio components are an advantageous help to develop pronunciation skills. It is a very good and effective method to learn a second language. \nunabridged 未删减的，完整的 audio component 音频部分 \nadvantageous 有利的，有益的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3ebd3340283ec4f2b8923379', 'ielts_group_99c3910269d1f58c6cee65f9', 'PART_2', 1, 'Describe a restaurant that you enjoyed going to.', '["where the restaurant was","why you chose this restaurant","what type of food you ate in this restaurant and","explain why you enjoyed eating in this restaurant."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"引出话题：I often eat at a dumpling restaurant in a hutong near the Forbidden City. It''s down a small street and is a real best-kept-secret.\n去的频率：I don''t go there often because it''s right in the center of Beijing and I live on the outskirts, so it''s pretty difficult to get there unless you''re already nearby. I''d say I go there every couple of weeks or so.\n食物：Being a dumpling restaurant, they obviously serve dumplings! You get around twenty dumplings in еасh ѕеrvіng whісh іѕ mоrе thаn еnоugh fоr mе. Тhеу dоn''t ѕеrvе оthеr tуреѕ оf fооd but mаkе uр for it by making especially nice dumplings. I like to dip them in vinegar and then eat them whole. When I took some friends there they said the dumplings were the best ones they''d ever eaten.\n为何喜欢：After a meal at this place you feel really full and satisfied. It''s guaranteed to stop you feeling hungry. I also like it because it''s really cheap! It''s only a small restaurant and there''s no decoration apart from a few ornaments behind the counter, but that''s part of its charm: it''s a simple, friendly place. The neighborhood is great too: it''s historical and picturesque and there''s always some interesting people walking around or riding their bicycle. You can relax and enjoy your meal without feeling rushed as you are at larger places that play annoying music or are too crowded. Another great thing is that you always get your food served right away without having to wait, so you can walk right in and start eating.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_4ff19bb03e6f39b326bc1cb0', 'ielts_group_99c3910269d1f58c6cee65f9', 'PART_3', 1, 'Why do you think people go to restaurants when they want to celebrate something?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think there are probably a lot of reasons why people go to restaurants, but two of the main ones are that it''s very easy for everyone to relax and have a good time and that it''s not as much of a hassle as having a party at home. Most restaurants these days have really fun causal atmospheres so people instantly feel comfortable talking. You can also reserve a private room if you like. Perhaps the more important reason is that throwing a party at your home is a lot more trouble. You need to do lots of planning and food preparation. Then, after the party your house is a mess. I held a party once and when everyone left, my home looked like a disaster zone. It took me a long time to clean up. So, I personally would rather celebrate in a restaurant.\ncausal 随意的，休闲的 instantly 立即地\nreserve 预定 disaster zone 灾区","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f50cd056450fc3542e7284f9', 'ielts_group_99c3910269d1f58c6cee65f9', 'PART_3', 2, 'Which are more popular in your country: fast food restaurants or traditional restaurants?Why do you think that is?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It depends on what you want to do. Fast food restaurants are rapidly becoming popular for several reasons. One is that white collar workers have really hectic schedules and may just want to grab a quick bite for lunch before getting back to work. So now there are rows and rows of fast food chains in the business districts. Another reason that fast food is becoming popular is that places like McDonald''s create a family friendly atmosphere, they even have play areas. Families with toddlers may not take them to a more formal place. However, here in China, traditional restaurants will also continue to be popular for a long time. Chinese people take their cuisine very seriously and traditional restaurants are the best place to go if you want a huge variety of food or authentic dishes. Traditional restaurants are also extremely important for occasions like big business events or family get-togethers.\nwhite collar 白领 hectic schedule 紧张、忙乱的日程\ntoddle 刚学会走路的孩子 cuisine 饭菜\nauthentic dish 地道的食物 get-together 聚会","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9c1fa097e5855ca2b0f728a1', 'ielts_group_99c3910269d1f58c6cee65f9', 'PART_3', 3, 'Some people say that food in an expensive restaurant is always better than food in a cheap restaurant - would you agree?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I can see why some people would say that, but I have to disagree. At least, it''s not always better. Some of my favorite meals have been in small local eateries and even dive restaurants. Although the food is simple, it''s often both hearty and delicious——like a home cooked meal. Of course, if you are a person with refined tastes, you might still be better off going to a high-end restaurant.\neatery 小餐馆 dive restaurant 价格便宜的餐厅\nrefined taste 高雅的品味 high-end restaurant 高档餐厅","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d9d50c9ca1d820b9bd0869aa', 'ielts_group_99c3910269d1f58c6cee65f9', 'PART_3', 4, 'Do you think there will be a greater choice of food available in shops-in the future, or will there be less choice?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes, there is already a much greater variety of food available in shops than there was a decade ago and I think this trend will continue for a long time. When my parents were my age, they had virtually no choice whatsoever. They could only buy what was available in the small local shop or vegetable market. Now there are countless supermarkets with huge selections of food. For example, in addition to regular items most supermarkets have an international aisle where you can buy imported foods. Also many seasonal fruits and vegetable can now be bought year round. If you can''t find what you want in a regular supermarket, you can also visit specialty shops that exclusively sell tea or chocolate or other gourmet items. \naisle 通道 exclusively 专门地\ngourmet 美食家","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b98facc6ad2a62f9b8c0c75b', 'ielts_group_99c3910269d1f58c6cee65f9', 'PART_3', 5, 'What effects has modern technology had on the way food is produced?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Modern technology has affected food in a great number of ways. Farming is mechanized now, so fields are more productive, and also there are less people involved in farming than before. Another way modern technology has affected food production is now scientists can bioengineer new foods, like bigger tomatoes or seedless watermelons. Perhaps one more way food production has been affected is people buy a lot of prepackaged foods, which are extremely convenient, but don''t always taste as good. Thus, modern technology is both good and bad for food production.\nmechanized 机械化的 bioengineer 生物工程\nseedless 无籽的 prepackaged food 预先包装好的食物","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1300f1c65e2cba0a4c99fefc', 'ielts_group_99c3910269d1f58c6cee65f9', 'PART_3', 6, 'How important is it for a country to be able to grow all the food it needs, without importing any from other countries?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well I think it''s extremely important that a country is self-sufficient, and that it can always provide enough for its people, but a country doesn''t necessarily need to grow all of its own food. For example, if we have free trade, we can import a variety of foods and products that can''t be made domestically. It''s definitely important that a country is capable of growing all its most basic foods though, for example, staple foods like rice and grain. If we have to import rice from other countries, there is a risk that prices might fluctuate sharply and that could negatively affect lower income people.\nself-sufficient自给自足的 domestically 本土地，国内地\nbe capable of 有能力的，能……的 fluctuate波动，浮动","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_36d3bd9bd396d74bc1b89645', 'ielts_group_41f1302c7af473958943a541', 'PART_1', 1, 'Do you like to have flowers in your home? [Why/Why not? ]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Yes. Flowers are decorative and they send forth fragrance. They make my room more colorful and alive. Flowers make the air inside a little fresher and also give my apartment a more homey feeling.\ndecorative 装怖性的 send forth fragrance散友香气\ncolorful and alive多彩而有生气的 homey家的，舒廼的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fe5340b5a4c94a43c5be663e', 'ielts_group_41f1302c7af473958943a541', 'PART_1', 2, 'Where would you go to buy flowers? [Why? ]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t buy flowers in a real flower shop. For convenience, I buy flowers online in bulk for huge discounts and free shipping. At the click of my mouse, they''ll put together a selection of beautiful flowers sourced daily and deliver my bouquet to my address\nbulk大量 free shipping免費运送\nsourced daily毎天来摘的 bouquet花束","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1217cab49c240455ade661a8', 'ielts_group_41f1302c7af473958943a541', 'PART_1', 3, 'On what occasions would you give someone flowers?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''m not a person who fancies giving flowers to express my affection to someone, but if I have to, I may pick the occasion when a friend is recovered from illness and coming out of the hospital, because what he needs, at that moment, is something refreshing and full of prospect. People around me send flowers on many occasions, such as business opening, wedding, Valentine ''s Day and so on. \n\nfancy喜炊,想要 affection喜爰,感情\nrefreshing使清爽的 full of prospect充満希望的\nbusiness opening升止","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_daa930861111de76d3cd69cc', 'ielts_group_41f1302c7af473958943a541', 'PART_1', 4, 'Are flowers important in your culture? [Why/Why not? ]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Very important. Flowers are a perfect gift to express your wishes to your near and dear ones. They don''t cost much but say it all. Fresh flowers can lift someone''s spirits, while dried flowers can be used to decorate homes. Also, flowers have many meanings in China. Peony represents prosperity and wealth, and carnation stands for love and respect.\nspirit精神 dried flower干花\npeony牡丹 prosperity繁栄,共旺carnation 康乃馨","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c8a69a4edf5c2f107d2c9f98', 'ielts_group_523a7248575cb6f10d226585', 'PART_2', 1, 'Describe a meeting you remember going to at work, college or school.', '["when and where the meeting was held","who was at the meeting","what the people at the meeting talked about and explain why you remember going to this meeting."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"时间地点人物：Well, I think I''ll talk about our annual meeting at work. My company holds a large meeting with all the different offices once a year at the end of the fourth quarter. Everybody attends, including all of the major bosses and the company president. It''s really a spectacular affair. Last year it was out of town and we all stayed in a fancy hotel for two days over the weekend.\n会议主题：There were a lot of meetings to attend and we were all pretty busy, but it was actually tremendous fun. The president made a long speech about our successes in the last year and planned for the next.\n具体内容及原因：It was quite inspiring and we all felt grateful for his praise. After that there were awards given out to employees that had performed particularly well over the year and most people received their annual bonus. When the meetings were all finished, there were plenty of recreational activities to participate in, like KTV. It was a great opportunity to get to know my coworkers a bit better. Overall it was quite fun and completely unlike typical meetings, and that is probably why I remember it so fondly.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9806bb195f878a73fc40b394', 'ielts_group_523a7248575cb6f10d226585', 'PART_3', 1, 'What are the different types of meeting that people often go to?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"People go to many different kinds of meeting. Probably the most common, and definitely the most boring, are meetings at the workplace. There are department meetings, sales meetings, meetings with clients and even networking events. I have to attend a weekly meeting every Monday. Besides work, people go to meetings in order to socialize. There are clubs for people that like hiking, sports, or music. One type of meeting that I like to attend in my free time is a regular English corner. It''s a good chance for me to meet other people that are also serious about improving their English and practice with them.\ndepartment meeting部门会议 sales meeting销售会议\nhiking 徒步旅行","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_717ce145fc02aadeb26dca79', 'ielts_group_523a7248575cb6f10d226585', 'PART_3', 2, 'Some people say that no-one likes to go to meetings - what do you think?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I can definitely understand that opinion. Frankly a lot of meetings at my work are a tremendous waste of time. They can drag on for hours and sometimes it feels like my managers just want a chance to make themselves seem important, rather than actually contributing to a project. I''d rather focus my time and energy on dealing with my beavy workload. However, I understand that meetings are a necessary evil. Sometimes it''s the only way to guarantee good communication. Meetings tend. to go best when they involve a small group of essential people and you have very clear goals. So it depends on how well meetings are run at your company.\ntremendous巨大的 drag on 拖延\ncontribute to 对…….有贡献","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_aa7f8877a457c560ba120b42', 'ielts_group_523a7248575cb6f10d226585', 'PART_3', 3, 'Why can it sometimes be important to go to meetings?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Meetings are important for a lot of reasons. If you participate and make good contributions, you can impress your boss and perhaps get a promotion. Also, more basically, meetings are important for effective communication and to ensure that everyone is on schedule with their projects. They can even give you sense of teamwork and make you feel more motivated. If you work in a competitive industry, sometimes meetings can be useful for training. They keep you up to date on new policies and products so you can work more effectively.\nsense of teamwork团队合作意识 motivated激励的，有积极性的\ncompetitive industry 竞争性产业","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_629beb7f4566dd0cf1784f99', 'ielts_group_523a7248575cb6f10d226585', 'PART_3', 4, 'Why do you think world leaders often have meetings together?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, I think it''s essential that world leaders have frequent meetings together for a variety of reasons. We live in a globalised world now and the actions of one country affect everybody. Look at the recent, financial crisis, it started in one country but quickly spread everywhere and all nations in the world suffered a little. Governments need to make deals so that trade continues to develop and grow. Also, these days, leaders need to work together on even more important international issues. I feel that environmental protection is one of the biggest ones. Leaders from all countries need to agree to work together if anything is going to be accomplished. Also regular meetings between leaders can help the people of both nations feel more comfortable with each other and guarantee peace\nglobalised 全球化的 financial crisis \ninternational issue guarantee peace 保证和平","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8dbf201f2ac41ec49bb11152', 'ielts_group_523a7248575cb6f10d226585', 'PART_3', 5, 'What possible difficulties might be involved in organising meetings between world leaders?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''m sure it''s very difficult to organise meetings between important leaders. First and foremost, they are all busy running their countries and don''t have time to squander, so things need to be scheduled very tightly. Second of all, I can imagine that security is vitally important. Leaders need to be protected very carefully so you need extra guards and all plans about the scheduled trip must be top secret. So transportation, accommodation and lots of personnel all need to be arranged for the visit to go smoothly. Last but certainly not least, they need to ensure that they get proper and positive media coverage, so they need to coordinate with reporters as well.\n\nfirst and foremost首要的是 squander\nschedule安排 tightly紧密地\ngo smoothly顺利的进行 media coverage媒体报道","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9bb442110025411f32ea572b', 'ielts_group_523a7248575cb6f10d226585', 'PART_3', 6, 'Do you think that meetings between international leaders will become more frequent in the future? Or will there be less need for world leaders to meet?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I suspect that meetings between world leaders will either become more common in the future, or stay as common as they are now. I understand that with advanced communication tools like phones or even video-conferencing, it is unnecessary to meet face to face, but part of the reason world leaders meet is to create good feelings between their countries. This can only be done well in person.\ncommunication tool 沟通/交流工具 video-conferencing视频会议 \nin person 亲自","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_171d2c9e14ff27d9e35701ea', 'ielts_group_aebd012c55d1f2ab2284180a', 'PART_1', 1, 'How often do you watch television? [Why/Why not? ]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''m not a couch potato, so I watch it very seldom. The shows are all pretty worthless and non-entertaining. The commercials are stupid and take up more time than the programmes. I just leave the TV on for background in the morning from Monday to Friday because the daily news is on.\ncouch potato电视迷 worthless无价值的\nnon- entertaining 无趣的，无娱乐性的 commercial广告\nbackground背景","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9418445ff1541ee432e422c5', 'ielts_group_aebd012c55d1f2ab2284180a', 'PART_1', 2, 'Which television channel do you usually watch? [Why? ]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I''m a big football fan, so I watch ESPN the most often. ESPN focuses on sports-related programming but I personally think it should broadcast more football games instead of NASCAR, golf, hockey, and women''s college basketball, and it should show more football highlights on sports center.\nESPN (Entertainment Sports Programming Network)娱乐体育节目电视网\nsports-related 与体育相关的 broadcast播放，播送\nNASCAR纳斯卡赛车比赛 hockey曲棍球\nHighlights集锦，精彩场面","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8f7b7817c380b2c4b54027ba', 'ielts_group_aebd012c55d1f2ab2284180a', 'PART_1', 3, 'Do you enjoy the advertisemets on television? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t like TV advertisements, and I usually close and rest my eyes when they come on. The ads can be amusing for the first few times, but the insistent bombarding of the same advertisement just drives me crazy. And on some channels they come on too frequently, actually spoiling the program itself. I''ll turn to another channel if this happens.\nad广告 amusing有趣的，好玩的\ninsistent 持续不断的 bombard轰炸，猛轰\nspoil 破坏","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f933f3f75eb8286ccdedbfea', 'ielts_group_aebd012c55d1f2ab2284180a', 'PART_1', 4, 'Do you think most programes on television are good? [Why?/ Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t think so. There are many TV shows with tons of violence and sex nowadays. I think the designers of the shows aim their programming at people with low self-esteem. Only few programmes are interactive or brain powering shows, which can actually help people. There should be more educational TV programmes today.\n\ntons of 大量的 self-esteem 自尊\ninteractive互动的 brain powering锻炼脑力的\neducational教育的;有关教育的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_00d51596a3f2590178e34b40', 'ielts_group_179a6b8e70b8d5da0e7dc5c4', 'PART_2', 1, 'Describe a friend of your family you remember from your childhood.', '["who the person was","how your family knew this person","how often this person visited your family","and explain why you remember this person."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"点题：I want to tell you about my best friend, Sam, who I met when we were both only five years old. He hasn''t changed much since then. He''s still a little fat, with short brown hair, and always laughing.\n相识：Sam is an American. Honestly, at first, I think we both just wanted to practice our language skills; that''s why I invited him to my house and introduced him to my family, but I believe that something more grew out of this relationship. We became close friends.\n活动：We were both interested in fantasy stories, so we used to play games where we would act out made-up adventures about knights and dragons, alien and robots, and other far-fetched scenarios. We were also big fans of computer games, so we''d talk about them constantly, and of course we''d play them together as well. I often went round to his house and ate dinner here, which was great because his mum always seemed to cook much nicer food than I''d get at home.\n原因：I''ll always remember Sam well because he was my closest companion during my time at primary school. We were best friends and played together all the time. He''s such a larger than life character; he always has a story to tell and a joke to share. It''s hard to forget such a unique person. Nowadays we live on opposite sides of the world and lead very different lives, but I''m sure we''ll always be friends.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_190083e914e5c20d8d6e484b', 'ielts_group_179a6b8e70b8d5da0e7dc5c4', 'PART_3', 1, 'What do you think makes someone a good friend to a whole family?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Well, in order to be a good friend to the whole family, they need to have all the usual traits of a friend, like loyalty, sincerity, and consideration, but they also need to care about and look after the needs of the entire family. My dad has an old friend that is like an uncle to us. Whenever he comes over, he brings gifts and asks lots of questions to show that he is interested in everyone, but I think this kind of friend is pretty rare.\ntrait特点，特征 loyalty忠诚\nsincerity真诚 соnѕіdеrаtіоn考虑周到的，体贴\nrare稀罕的，珍贵的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3e3c6e92d9571c2f76bda0ba', 'ielts_group_179a6b8e70b8d5da0e7dc5c4', 'PART_3', 2, 'Do you think we meet different kinds of friend at different stages of our lives? In what ways are these types of friend different?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"We definitely meet different friends at different times. My childhood friends were all just children that lived nearby and that I could play with. As long as we could play together happily, we could be friends. Maybe I wasn''t as selective then, but they are still some of my dearest friends. Later, my friends were largely high school or university classmates and having common interests was the most important thing. Many of my university friends shared the same major with me. Now many of my friends are coworkers, and I''d say that although we get along well together we don''t have the same kind of deep friendship I''ve had in the past.\nSelective认真挑选的 dеаrеѕt frіеnd最挚爱的朋友 \ncoworker同事 deep friendship 深厚的友谊","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7d0335bf0c355c31ed592f63', 'ielts_group_179a6b8e70b8d5da0e7dc5c4', 'PART_3', 3, 'How easy is it to make friends with people from a different age group?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It''s not that easy to make friends with people from different age groups, but still possible. For one thing, you are going to have fewer things in common and therefore less to talk about. You may even find that there is a small generation gap between you. After joining the working world, it may be easier to make close friends with people from different age groups. I have become friends with some of my older coworkers. We can talk about our shared interest in work and I value the experience and wisdom they are able to share with me. Maybe someday I will have the chance to do that with younger friends.\nage group年龄组，年龄段 generation gap代沟\nexperience and wisdom 经验和智慧","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_91f13b94cfa1b600e6be5403', 'ielts_group_179a6b8e70b8d5da0e7dc5c4', 'PART_3', 4, 'Do you think it is possible to be friends with someone if you never meet them in person? Is this real friendship?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Honestly, I don''t think that it''s possible for people to have real relationship with people that they have never met in person. I know that nowadays many people have internet relationships and I have even heard stories, (of people dating on the internet without ever meeting, but I don''t think that is real relationship. It''s too easy to deceive a person about who you really are and it lacks genuine intimacy. I think in the end it''s just a fantasy.\ndate约会 deceive欺骗\ngenuine intimacy 真正的亲密关系 fantasy幻想，白日梦","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_037a284fafd24a27f2dc1681', 'ielts_group_179a6b8e70b8d5da0e7dc5c4', 'PART_3', 5, 'What kind of influence can friends have on our lives?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Friends influence our lives in many ways. There are even several old sayings that suggest the people you spend time with determine who you are. I can give a few examples. If you spend time with hardworking successful people, they will motivate you to work harder. However, if your friends just waste away their days in internet cafes, you may also eventually just slack off and not try so hard. Friends can also more directly influence our lives by providing suggestions and advice when we need them.\nmotivate激励 internet cafe网吧\neventually 最终 slack off散漫，懈怠","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d9710234efdf2b48bfc55657', 'ielts_group_179a6b8e70b8d5da0e7dc5c4', 'PART_3', 6, 'How important would you say it is to have friends from different cultures?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Having friends from different cultures can be fairly important. At the very least, there are lots of advantages to having them. If you want to study a language, they are real asset to your learning. You can practice together and get the hang of how people actually talk in a natural setting. Of course, foreign friends also give you the opportunity to expand your horizons; they have different perspectives on important issues and different ways of doing things.\nfairly important非常重要的 asset 有用的人（或事物）\nget the hang of 得知…….的要领 natural setting自然情境\nexpand one''s horizon开拓某人的视野 perspective视角，观点","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_88a5d127348928a2828d6b7a', 'ielts_group_48b131afd9427f5dda2dbde5', 'PART_1', 1, 'What games are popular in your country? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Children enjoy playing games, but not all adults do. I''ve seen kids playing marbles. Tug of war is also popular, which is a game that directly puts two teams against each other in a test of strength. Back to my childhood, hopscotch, was my favorite game.\n\nplaying marbles 玩弹球 tug of war 拔河比赛\n\nhopscotch 跳房子游戏","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5fb983c3e6ee11dab7db267b', 'ielts_group_48b131afd9427f5dda2dbde5', 'PART_1', 2, 'Do you play any games? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I like playing competitive games because the winner feels like they have achieved something. Real life is a competitive experience, and it''s not right to pull the wool over children''s eyes and make them think that they''ll never have to compete with anyone. They think the idea that ''everyone''s a winner'' is rather naive.\n\ncompetitive 竞技的，竞争的 pull the wool over one''s eyes 瞒过某人\n\nEveryone''s winner. 每一个人都是赢家。","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b7f80414965520aea74299ef', 'ielts_group_48b131afd9427f5dda2dbde5', 'PART_1', 3, 'How do people learn to play games in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Games were quite simple a few decades ago. One huge difference in modern times is that we now have thousands of complicated computer games to choose from. It''s pretty easy to find breakthroughs on the Internet for players.\n\ndecades ago 数十年前","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ed07573ec0716ec85084494f', 'ielts_group_48b131afd9427f5dda2dbde5', 'PART_1', 4, 'Do you think it''s important for people to play games? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Games and sports are very important. We can relieve the stress and exercise the body. We can learn about good sportsmanship and improve hand-eye coordination through physical sports.\n\nsportsmanship 运动员精神 hard-eye coordination 手眼协调能力\n\nphysical sports 体育运动","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_469d8e6cb1652b3f6d26d646', 'ielts_group_1f507310f4b8e6eeddc1449a', 'PART_2', 1, 'Describe an open-air or street market which you enjoyed visiting.', '["where the market is","what the market sells","how big the market is","And explain why you enjoyed visiting this market."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"地理位置：A ￡2 bus ride from the city center hotel will drop you to this street market. It is so tucked away and so well hidden that despite its very central location I sometimes even forget it exists.\n销售商品：If you are looking for clothes or accessories, then this might be your place. Don''t take your wallet unless you are prepared to buy something, as you will surely get tempted! It would be criminal not to give this place 5 stars. All the different li stalls specialising in everything you can think of.\n市场大小：This place is much bigger than it seems from the front. It is also really big, so it might be good to wander around a bit and look at the choices before you settle on what you want to buy. The massive range of snack bars, cafes and stalls will keep you occupied for hours.\n喜爱缘由：When I first ventured into this market, I wandered around with my jaw hanging open. It''s a shopper''s heaven. I go there every Wednesday. That''s when they have their 10% discount. I can get some very famous designer suits, shirts, sweaters, and pants. It makes me look very stylish, but it''s on the cheap. This place has such a charm—less crowded, and it''s a gem in the centre of London.","translation":"","usageNote":"原题库提供的参考表达"},{"type":"EXPRESSION","expression":"bus ride","translation":"车程 central location中心位置","usageNote":""},{"type":"EXPRESSION","expression":"get tempted","translation":"经不住诱惑 specialise in专攻","usageNote":""},{"type":"EXPRESSION","expression":"massive range of","translation":"大量的 venture into贸然进入，闯入","usageNote":""},{"type":"EXPRESSION","expression":"pants","translation":"短裤，裤子 charm魔力","usageNote":""},{"type":"EXPRESSION","expression":"drop...to","translation":"把…送到 accessory饰品","usageNote":""},{"type":"EXPRESSION","expression":"It would be criminal not to...","translation":"不就像是在犯罪 wander around a bit闲逛一会儿","usageNote":""},{"type":"EXPRESSION","expression":"snack bar","translation":"小吃店 with one''s jaw hanging open瞠目结舌的","usageNote":""},{"type":"EXPRESSION","expression":"stylish","translation":"时髦的 gem宝石","usageNote":""},{"type":"EXPRESSION","expression":"tucked away","translation":"隐蔽的 your place宝地","usageNote":""},{"type":"EXPRESSION","expression":"stall","translation":"货摊 settle on决定","usageNote":""},{"type":"EXPRESSION","expression":"keep one occupied","translation":"使繁忙 designer suit品牌西服","usageNote":""},{"type":"EXPRESSION","expression":"on the cheap","translation":"便宜的","usageNote":""}]'::JSONB),
    ('ielts_q_ede5a4ca511f08eb1f6c77c4', 'ielts_group_1f507310f4b8e6eeddc1449a', 'PART_3', 1, 'Do people in your country enjoy going to open-air markets that sell things like foods or clothes or old objects? Which type of market is more popular? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think most Chinese people enjoy shopping there. Young people like to wander around side-street stalls and open-air flea markets. Clothes are competitively priced and fashionable. It caters for the needs of young people, they can bargain at ease. Although there are modern supermarkets in China, old people prefer to buy the freshest meat and vegetables at the open-air wet markets. Unlike in the big food chains, shoppers develop a certain relation with the vendors, and they can learn how the vegetables have been grown, and who produced them. This creates a sense of security over the origin of the food.\n\nwander around闲逛 side-street stalls路边摊\n\nflea market跳蚤市场 competitively priced价格优惠的\n\nfashionable时髦的 cater for迎合\n\nbargain砍价 at ease自由自在\n\nwet market农贸市场 vendor摊贩\n\na sense of security安全感 the origin of the food食品来源","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7a0bf5bc1a4fae5f3403ff4d', 'ielts_group_1f507310f4b8e6eeddc1449a', 'PART_3', 2, 'Do you think markets are more suitable places for selling certain types of things? Which ones? Why do you think this is?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In my humble opinion, markets are supposed to be like giant yard sales with a wide range of old, interesting items and knick knacks. You can see troll dolls living next to antique typewriters; you may find wall clock you''ve always been longing for. During the weekend, I always look for antiques or vintage clothes and jewelries. I think an antique flea market is a very fascinating place. I prefer to browse for antiques and collectibles. It has been part and parcel of my life.\n\nin my humble opinion依我拙见 be supposed to应该，被期待\n\ngiant yard sale大型旧货销售 a wide range of大量的\n\nknick knacks小玩意 troll doll印第安毛娃\n\nantique typewriter古董打字机 wall clock挂钟\n\nlong for渴望 antique古玩\n\nvintage clothes and jewelries老式的衣服和首饰 antique flea market古玩跳蚤市场\n\nbrowse for浏览 collectible收藏品\n\npart and parcel of不可或缺的部分","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_2ba4dfff19ed9625fa3d09da', 'ielts_group_1f507310f4b8e6eeddc1449a', 'PART_3', 3, 'Do you think young people feel the same about shopping at markets like as older people? Why is that?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t think so. Current markets are occupied by lots of branded and cheap goods. We should pay considerable and mandatory attention that young generation gets fascinated towards these cheap brands. Pocket money or salary from part time jobs has made shopping a favourite pastime for present youths. While older people think and feel differently, they just visit vegetable markets for the freshest vegetables and fruits. And they are more likely to buy clothes in brand stores in order to guarantee the quality.\n\nbe occupied by 充斥着 branded 有品牌的\n\npay considerable and mandatory attention 给予大量必要的关注 get fascinated towards 被…迷住\n\npastime 消遣 youth 年轻人\n\nbrand store 品牌专卖店 guarantee the quality 保证质量","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_151c9778d5505c4332cdfe48', 'ielts_group_1f507310f4b8e6eeddc1449a', 'PART_3', 4, 'What do you think are the advantages of buying things from shops rather than markets?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"First and foremost, the customer service in those shops was better than that in markets. There are salespeople absolutely everywhere you looked and they are very polite. I have never been so impressed with the staff at upscale designer boutiques in my life. They are not snooty and even encouraged me to try things on. Besides, shops offer the convenience of shopping hours, which extend far into the evening or even 24 hours a day. So there''s less stress to make it to the shops on time. Last but not least, in big shops, children can be left in a play area whilst the parents do their shopping. So parents are less stressed and pestered into buying unnecessary items. However, markets are somewhat inconvenient in these respects.\n\nfirst and foremost首要的是 absolutely 绝对地\n\nupscale designer boutiques高档时装店 snooty 高傲的\n\ntry...on试穿 extend far 延伸\n\nstress压力 on time 按时\n\nlast but not least最后但同样重要的是 be pestered 被纠缠\n\nsomewhat有些","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c43839e528f58647274f1873', 'ielts_group_1f507310f4b8e6eeddc1449a', 'PART_3', 5, 'How dose advertising influence what people choose to buy? Is this true for everyone?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"While you may be taking advertising for granted, it does seek to influence what everyone spends his money on. Many people don''t believe that they''re susceptible to being influenced, let alone manipulated by advertising. However, it wouldn''t be so omnipresent if it didn''t work. Advertising is informing people of the existence of products which they might be interested in buying. People are more willing to go with what''s familiar with than what''s not. In media, people are usually influenced by what''s \"hot\" in the products that they see in TV shows, movies or commercials. Generally that type of advertising just sits in people''s minds until they actually see the product at a store. It entices people to buy sooner or later.\n\ntake…for granted 认为…理所应当 seek to企图\n\nbe susceptible to 易于 let alone更不用说\n\nmanipulate 操控 omnipresent无所不在的\n\nexistence 存在 go with买，赶时髦\n\ncommercial 广告 sit in one''s mind深印心中\n\nentice 诱惑 sooner or later迟早","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8d50981ec1a9ca8249b23a87', 'ielts_group_1f507310f4b8e6eeddc1449a', 'PART_3', 6, 'Do you think that any recent changes in the way people live have affected general shopping habits? Why is this?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"With today''s busy lifestyle there''s a growing trend towards shopping online, e-commerce has been around for a long time and it is breaking into traditional markets more than ever before. Not just books, CDs and holiday trips can be bought online, but all sort of other products and services that were unimaginable in the past. Besides, the supermarkets and convenience stores stayed open for longer and longer hours to meet the needs of white-collar.\n\nE-commerce 电子商务 be around 出现\n\nBreak into 闯入 all sort of 各种各样的\n\nUnimaginable 难以想象的 convenience store 便利店\n\nWhite-collar 白领","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b13b79e62d028e63e3807f3b', 'ielts_group_fe8c31c1dd295bc6f4d555a7', 'PART_1', 1, 'When do people give gifts or presents in your country?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Chinese people give gifts on many festivals, and there are some hard-and-fast rules to gift giving in China. For example, under no circumstances give a clock or a watch as a gift because it symbolises the end of your life, and you may cause offence.\n\nhard-and-fast rules 硬性规定 under no circumstances 决不\n\ncause offence 冒犯，得罪，伤感情","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_7866395d65f4ce2f3ba7b384', 'ielts_group_fe8c31c1dd295bc6f4d555a7', 'PART_1', 2, 'Do you ever take a gift when you visit someone in their home? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It''s not necessary, but it''s always thoughtful to do so. People think it''s a nice gesture if you bring a small gift when visiting someone''s household. It shows you appreciate being invited and that you want to repay the favour.\n\nthoughtful 体贴的，关切的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_ebf193235063ffd1b58c755b', 'ielts_group_fe8c31c1dd295bc6f4d555a7', 'PART_1', 3, 'When did you last receive a gift? [What was it?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"My girlfriend gave me a watch a few weeks ago because she thought I''d like it. It''s not pricey, but the thought counts even more. I was very touched by her thoughtfulness.\n\ncount ever more 更有价值 thoughtfulness 体贴","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_474ddc773475002c66cf372c', 'ielts_group_fe8c31c1dd295bc6f4d555a7', 'PART_1', 4, 'Do you enjoy looking for gifts for people? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"No. It can be pretty tricky trying to find the perfect gift, especially if the recipient is already well-off. I don''t have enough time to get clues by guessing what they''d like based on their hobbies and interests. Also, I''m rather tight-fisted when it comes to money.\n\nTricky 难的，复杂的 recipient 接受者，接纳者\n\nTight-fisted 舍不得花钱的，吝啬的 when it comes to… 当提到，就…而论","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_df44cd85f653dd8df6237c3a', 'ielts_group_afb4752239c4283306b37e36', 'PART_2', 1, 'Describe something you did that was new or exciting.', '["what you did","where and when you did this","who you shared the activity with","and explain why this activity was new or exciting for you."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"点题：My father gave me an early birthday gift—tickets of the concert of the Beethoven''s Ninth Symphony. Actually I hadn''t been inside of any music hall before.\n地点时间：At Friday night, we went to the local music hall. As for this venue, it was our first time there, and everything went surprisingly smoothly including traffic, parking, souvenir stand and restrooms. It''s a great night out. It was absolutely great that they played lots of popular light classics. There''s always a high standard of playing of classical music.\n陪行人员：I went to the concert accompanied by my friends. We listened in air-conditioned comfort and enjoyed the presenters as well. Finally, all of us were on the edge of our seats.\n解释原因：Besides, the acoustics is so fantastic that many world-famous artists have been attracted to perform in this hall. The sound is clear, full-bodied, and clean for every vocal part and the mix is perfect. I was very impressed by the terrific ambiance and intimacy of the hall. It is the most recommended concert hall throughout the city. I mean, there is no other place that is compatible with here. Not to be missed!","translation":"","usageNote":"原题库提供的参考表达"},{"type":"EXPRESSION","expression":"the Beethoven''s Ninth Symphony","translation":"贝多芬第九交响曲 venue 场地","usageNote":""},{"type":"EXPRESSION","expression":"surprisingly smoothly","translation":"惊人地顺利地 souvenir stand 纪念品专柜","usageNote":""},{"type":"EXPRESSION","expression":"restroom","translation":"卫生间 night out 夜生活","usageNote":""},{"type":"EXPRESSION","expression":"light classics","translation":"轻古典音乐 air-conditioned 空调开放的","usageNote":""},{"type":"EXPRESSION","expression":"on the edge of one''s seat","translation":"异常兴奋，有浓厚兴趣 acoustics 音响效果","usageNote":""},{"type":"EXPRESSION","expression":"full-bodied","translation":"醇厚的 vocal part 声乐部分","usageNote":""},{"type":"EXPRESSION","expression":"terrific ambiance","translation":"极佳的氛围 intimacy 舒适感，亲近感","usageNote":""},{"type":"EXPRESSION","expression":"be compatible with","translation":"与…相配","usageNote":""}]'::JSONB),
    ('ielts_q_c01cf2885dc2dcbf6dc36a5f', 'ielts_group_afb4752239c4283306b37e36', 'PART_3', 1, 'Why do you think some people like doing new things?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Trying new things would involve high risk. Despite this fact, however, some people prefer to face new challenges rather than following a routine. I think, the main reason why they like to try new things is their characters. I am, by nature, an adventurous person. My mother used to say that she struggled hard to stop me climbing trees when I was small. May be I displayed my character from my childhood itself. I would like to try new things as opposed to repeating the same old thing.\n\nhigh risk 高风险 follow the routine 遵循常规\n\nby nature 天生地 adventurous 爱冒险的\n\nstruggle hard to 很难… display 显示\n\nas opposed to 相对于","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c51aa1019c5e9fac036c2442', 'ielts_group_afb4752239c4283306b37e36', 'PART_3', 2, 'What problems can people have when they try new activities for the first time?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"When it comes to doing something out of the realm of experience, firstly, they may suffer from the problem of no motivation to do this, maybe nothing interests them. People should know how they can motivate themselves. I think it is one of the most important factors that lead a person towards success. Besides some people pressure themselves, they are freaking worried about making mistakes. This can impose much pressure on them. Maybe keeping calm is the trick for success.\n\nout of the realm of experience 经验之外的 motivation 动力\n\nmotivate 激励 lead…towards 将…领向\n\nfreaking 十分地 impose pressure on 对…造成压力\n\ntricky 技巧","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_90a0d1cbe695a0b40f74e2b3', 'ielts_group_afb4752239c4283306b37e36', 'PART_3', 3, 'Do you think it''s best to do new things on your own or with other people? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I’m scared of trying new things on my own and I’m used to having friends tag along with me. When I do new things without any company, I may feel awkward and I fear that I will make a complete fool out of myself by either being too quiet or babbling. My mind is always telling mc that I''m stupid and everybody else is intelligent, it causes me to feel inadequate. If I was to bring a friend along I would behave normally. I think we have to be with others because that''s how a society functions. Look at any animal group—ants, lions...all creatures that are pack animals have to work together in order for the group to survive.\n\ntag along with 跟着 without any company 无人陪伴\n\nawkward 窘迫的 make a complete fool out of 出丑\n\nbabbling 喋喋不休的 inadequate 信心不足的\n\nnormally 正常地 function 运转","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_a5aab913869b1e15b4d7d541', 'ielts_group_afb4752239c4283306b37e36', 'PART_3', 4, 'What kinds of things do children learn to do when they are very young? How important are these things?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Young kiddies should learn how to cook and do other chores, like sweeping, changing a light bulb, coz this will prepare them for the future when they leave the nest. They can also build responsibility and earn respect from their parents. That''s what most of children are missing today. There is nothing worse than seeing teenagers live at home and let their parents do all the work. Parents need to help them prepared for the real world and let them become a capable person ready to cope with life.\n\ndo chores 做家务 sweeping 打扫\n\nchanging a light bulb 换灯泡 nest 窝，巢\n\nearn respect from 赢得…的尊重 there is nothing worse than 没有比…更糟糕的了\n\nprepared 准备好的 capable 有能力的\n\ncope with 应对","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_475edd310171e3d9ca556ad2', 'ielts_group_afb4752239c4283306b37e36', 'PART_3', 5, 'Do you think children and adults learn to do new things in the same way? How is their learning style different?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"In my perspective, they are totally different. Young children are natural learners and are naturally motivated to learn about new things. Especially, preschoolers learn differently from adults. Play is essential to early learning and play is the main way children discover new things. But adults learn new things from relevant experiences already in place. They fit the new thing into their existing skills. Besides adults are generally much more receptive to learning when they understand the new information being taught. \n\nnatural 天生的 preschoolers 学龄前儿童\n\nbe essential to 对…非常重要 already in place 已有的\n\nfit into 适用于 be receptive to 善于接受","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_226d2487b09aaf902f63183f', 'ielts_group_afb4752239c4283306b37e36', 'PART_3', 6, 'Some people say that it is more important to be able to learn new things now that it was in the past. Do you agree or disagree with that? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Frankly I can''t agree any more. Now we are under constant pressure to learn new things. It can be daunting. It can be exhilarating. Some pundits deride the current era as just another bubble. Whether it is or not, at this point, new, heady tech is emerging every day, people have to have the ability to keep pace with the times. No one could discount the way that mobile and other breakthroughs are changing our way of life, people around the globe should be able to catch up with them. Comparing people today to the people of the 1970s or before, never before have us had such luxury. That''s partially a good thing.\n\nconstant持续不断的 daunting 令人畏惧的\n\nexhilarating令人振奋的 pundit 某一领域的专家\n\nderide嘲笑 bubble 泡沫\n\nat this point此时此刻 heady 令人陶醉的\n\nkeep pace with the times跟上时代的步伐 breakthrough 突破\n\naround the globe世界各地的 luxury 奢华\n\npartially不完全地","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5a73a24ce4e1162da7069e5a', 'ielts_group_8acd2e4393cc50fb34169fc9', 'PART_1', 1, 'How often do you make telephone calls? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I make phone calls a lot every day. If I go to a foreign country, it''s more expensive to make a call—but I believe actually inside Europe these roaming charges are going to actually come down. When I go to other countries, I usually buy a local SIM card and put it in an old phone and then I just use it as a pay-as-you-go phone.\nroaming charges 漫游费 pay-as-you-go phone 现收现付电话","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5009b30df8ea3d1d0f6437a0', 'ielts_group_8acd2e4393cc50fb34169fc9', 'PART_1', 2, 'Who do you spend most time talking to on the telephone? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"My friends. I like chatting with them every day because I am a cell phone addict. My phone is on a contract. My tariff is one where I pay £20 and I get 250 texts and I think 125 minutes to any phone. \ncell phone addict 手机成瘾者 My phone is on a contract. 我的手机是签约机。","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_3ccbf876b19cce4ce9690e61', 'ielts_group_8acd2e4393cc50fb34169fc9', 'PART_1', 3, 'When do you think you''ll next make a telephone call? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t know. Actually, I''ve been diagnosed with phone-phobia. I''s a psychological condition which makes me have extreme fear of using the telephone. I''m afraid even to listen to voice-mail messages. Whenever I pick up the phone, I break out in cold sweat. I actually get clammy.\nbe diagnosed with被诊断为 phone-phobia手机恐惧症\nvoice-mail message语音留言 break out in cold sweat冒冷汗\nclammy湿冷的","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b5e27c3053ddf644a11b7302', 'ielts_group_8acd2e4393cc50fb34169fc9', 'PART_1', 4, 'Do you sometimes prefer to send a text message instead of telephoning? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I prefer texting message. My texting thumb is fantastically quick because I understand the predictive text function so I don''t put in each letter.\ntexting thumb短信拇指 predictive text function 短信提醒功能","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f288c48df008d97dd02433a4', 'ielts_group_0fe700e0b5624994169f8c61', 'PART_2', 1, 'Describe a journey [e.g. by car, plane, boat] that you remember well.', '["where you went","how you travelled","why you went on the journey","And explain why you remember this journey well."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"旅游地点：After finishing a 4 year degree in Civil Engineering, I decided to have a break from looking at buildings, roads and bridges and then headed to South Korea. I was having a fab time there. \n出游方式：Travelling by train I kept myself occupied by looking out of the window at the landscapes as they flashed by. I went with a good friend and we spent a lot of time together. We had memorable conversations on the long train journeys about live, society, religion… all very deep stuff.\n出游目的：When I was a little girl, I heard that South Korea, even if it is a small country, has its unique culture, where traditions and innovations, old and new, coexist. I wanted to feast my eyes and experience this culture at the same time.\n至深印象：I''ll never forget this trip because it was the first time I was travelling without a home base. Most of the cities in Korea are perfectly safe, as it is well populated and every major venue, shopping area, tourist destination is safe well lit, properly patrolled. Even I go out at night as a single woman, I''m not scared. Chejudao has many wonderful walking areas and lots of hiking areas and beaches to explore by foot. The food overall was very good and close to what a lot of high end Korean places serve in China. Since it was a vacation, it was pretty easy to slip into the relaxed Korean lifestyle. The trip was wonderful.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_1f162ca69b6bcc1575e7d548', 'ielts_group_0fe700e0b5624994169f8c61', 'PART_3', 1, 'Why do people need to travel every day?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Nowadays most of us commute a long way to work. Even some students need to tolerant a very long journey each day. Due to the boom in the housing market, people have to rent in the suburbs to reduce their living cost. Both house prices and distance between home and workplace have more than doubled. Besides, many properties are not located within easy reach of community facilities. Residents have to travel to hospital, pay their utility bills and dine out. \ncommute 通勤 tolerate 忍受\nboom 繁荣 in the suburbs 在郊区\nhouse price 房价 property 房产\nwithin easy reach of 在…的附近 pay the utility bill 付水电账单\ndine out 外出就餐","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_e5ebeb0923f2e14542b163bc', 'ielts_group_0fe700e0b5624994169f8c61', 'PART_3', 2, 'What problems can people have when they are on their daily journey, for example to work or school? Why is this?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Traffic is always bumper to bumper. It''s common that there are crashes leading to traffic jams. After one day''s work, people may sometimes get sleepy at the wheel and actually couldn’t handle their tiredness. It hazards drivers lives. Also, whether by bus or on foot, children''s commute to school or simply to the bus stop can be dangerous. In addition to traffic accident, child-trafficking is very common.\nbumper to bumper 拥堵的 crash 撞车\ntraffic jam 交通拥堵 get sleepy 犯困\nat the wheel 在车上 handle tiredness 控制疲惫感\nhazard 使遭受危险 child-trafficking 拐卖儿童","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_64257c17c145960652a12b7d', 'ielts_group_0fe700e0b5624994169f8c61', 'PART_3', 3, 'Some people say that daily journeys like these will not be so common in the future. Do you agree or disagree? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I totally agree. The daily activity most injurious to happiness is commuting. I think in the future, most companies will take advantage of technological advances and employees may have more flexibility. Flexibility enables individuals to make changes to the working time and the location of workplace. Traffic congestion will not be white collars headache. Flexibility would be mutually beneficial to both the employer and employee and result in superior outcomes.\ninjurious 伤害的 take advantage of 利用\ntechnological advance 技术进步 flexibility 灵活性\ntraffic congestion 交通拥堵 white collar 白领\nheadache 令人头痛的事 be mutually beneficial to 对…互利\nresult in 导致 superior outcome 有益的结果","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_57d5284a2e4b68af8977b2bb', 'ielts_group_0fe700e0b5624994169f8c61', 'PART_3', 4, 'What do you think people can learn from travelling to other countries? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Travel is a form of learning because it exposes a person to cultures other than one''s own, and it takes him to places that have historical or cultural significance. If a person travels to foreign countries, he or she may come to understand what sorts of material lives the people have and what sorts of attitudes they have towards various things. Besides, I think traveling is the fastest and best way to learn a new language. Coz you immerse yourself in the culture and language. Needless to say your language will be improved to a large extent.\nexpose to 使暴露于 other than 不同于\nsignificance 意义 material life 物质生活\nimmerse oneself in 使自己沉浸于 needless to say 毋庸置疑 \nto a large extent 很大程度上","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_92911bed511868927bc018d9', 'ielts_group_0fe700e0b5624994169f8c61', 'PART_3', 5, 'Can travel make a positive difference to the economy of a country? How?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Sure. Tourism may boost the economy in many aspects. When more and more people fly to the country, airline industry is benefitted. For their food, lodging, etc., the respective businesses are boosted. As many new shiny and different kinds of beautiful things people can find in the country, they will buy all those things for them and their kith and kin, and the small scale industries will be boosted. The tourism industry will soar as people travel throughout the country from one corner to another, likewise, the per capita income and national economy will be boosted.\nin many aspects 在很多方面 fly to 乘…飞往\nlodging 房屋出租 respective 各自的\nkith and kin 亲友 small scale industry 小规模产业\nsoar 飞腾 likewise 同样地\nper capita income 人均收入","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_9fd5923ec643ab2f4e8f2cbf', 'ielts_group_0fe700e0b5624994169f8c61', 'PART_3', 6, 'Do you think a society can benefit if its members have experience of travelling to other countries? In what ways?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think so. If people only learned about other countries from the news, they''d think the world was a horrible place. Coz the media always sensationalises and simplifies a story. A major component of any travel should be to bring home the knowledge and experiences you acquired abroad, and find ways to apply them to better your life. For example, I am encouraged to write to our mayor to push for the resumption of train service, so we can benefit from convenient public transport like our European friends, and lessen congestion on our roads. \nhorrible 可怕的 sensationalise 大肆渲染 \nsimplify 简化 a major component of 一个重要部分\nacquire 获得 better 改善\npush for 强烈要求 resumption 重新开始\nlessen congestion 缓解拥堵","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5160d4ab80eec1b662e1d25b', 'ielts_group_cd2f7f56c24afb9f8628847e', 'PART_1', 1, 'How popular are bicycles in your home town? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It''s less popular than it was 10 years ago. Because our living condition is advancing rapidly, more and more people can afford private cars to commute to work or school. The government is also paving more roads and expressways to meet the needs of new automobile owners.\nliving condition 生活条件 advancing 进步\npave 铺（路） expressways 高速公路","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_c3f461702881f5d6fcb6a49f', 'ielts_group_cd2f7f56c24afb9f8628847e', 'PART_1', 2, 'How often do you ride a bicycle? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I ride a bike to work every day as it is faster than walking, and I don''t have to get on a crowded bus. Plus, the traffic is always heavy in big city, especially in the rush hour. People can get stuck on road for two or more hours. So obviously a bicycle is the best way of transportation.\nrush hour 高峰期 get stuck 被堵...；被卡在...","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_8491a36a44fba378610a4308', 'ielts_group_cd2f7f56c24afb9f8628847e', 'PART_1', 3, 'Do you think that bicycles are suitable for all ages? [Why/Why not?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"It''s dangerous for kids to ride bicycles in China because there are many cars that turn very fast when you cross the intersection. I think that kids need to wear helmets. I hardly ever see anyone wear any kind of protective gear. \ncross the intersection 过十字路口 helmet 钢盔，头盔\nprotective gear 保护装置","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_5da6398137e4932d3a4d28dd', 'ielts_group_cd2f7f56c24afb9f8628847e', 'PART_1', 4, 'What are the advantages of a bicycle compared to a car? [Why?]', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"The thought of riding a bike becomes mere nostalgia of times when we were younger. However, if you stop to think about it, there are many benefits to riding a bicycle. Riding bicycles have physical, financial, and eco benefits. These reasons for cycling are great, and the benefits can make you happier and healthier.\nNostalgia 怀旧之情","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_d47886c909c25e71b42ec8f6', 'ielts_group_209774cb19d30e19e90df3d4', 'PART_2', 1, 'Describe a person who has done a lot of work to help people.', '["who this person is/was","where this person lives/lived","what he/she has done to help people","and explain how you know about this person."]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"话题卡说明：\n人物话题是雅思口语的核心话题,考官主要考查考生是否能描述各类人物,如家人、朋友等。在讨论Describe a person who has done a lot of work to help people这个话题时,选择的人物需要有典型特征，一定有爱心、热衷于帮助他人。在描述人物五官相貌、性格特征等时，若举些实例，将使得考生的答案更具有说服力。类似的话题卡还有Describe a singer or musician, Describe a child you know等。\n\n点题：I want to tell you about my bosom friend, Sam, who I met when we were both only five years old.When I think of him, the thing which stands out most is his constantly smiling face. His sense of humour, and his warm and caring disposition made his inner-self beautiful.\n居住区域：He and I lived in the same neighbourhood. Teens and adults in this block all paid tribute to him and described him as a good-hearted, quiet yet outgoing boy who loved basketball. I''ll always remember him because he was my closest companion before he left home to university.\n所做善行：One day a few years ago when we were working at Starbucks it was pouring outside. Before the store was supposed to close he saw a woman walking without an umbrella in the pouring rain andI holding a baby. He grabbed his umbrella and ran outside in the rain and said, . Madam, do you want an umbrella?\" She was so happy and thanked Sam so much.\n了解程度：He was always concerned for others and ready to help those in trouble. As virtuous cycles,others helped him happily if he needed. Besides he always lent me a hand whenever I was in trouble or I had a puzzled and anxious look on my face. Nowadays we live on opposite sides of the world and lead very different lives. When I see it is him calling, my heart beats like a drum, and just hearing his voice on the phone can make me smile so big that my cheeks hurt. He always tries hisI hardest to protect me. If only the world were full of people like him, and then we''d be able to feel safe.","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_f4cba0f8bb02305e1fb8a18c', 'ielts_group_209774cb19d30e19e90df3d4', 'PART_3', 1, 'What are some of the ways people can help others in the community? Which is most important?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There are a lot of things we can do to help in your community, whether it''s with your mom''s chores, or if a friend is upset. We can also do volunteer work. I walk dogs for the local lost dogs'' home and visit kids in hospital and read for old guys a couple times a month. There are many little things you can do to reach out to other people. Children are always in need of help. Helping at community clubs as a teen sponsor or mentor is a crucial task. Sometimes school guidance counselors sponsor teens to come up with skits that have positive messages. What these“older siblings”said left a deep impression to those children. \nchore家务 upset心烦的\nwalk a dog遛狗 reach out to帮助\nin need of 需要 sponsor保荐人\nmentor导师 skit小喜剧\nschool guidance counselor 学校辅导员 older siblings哥哥姐姐","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_de2ff32efdbe222e5a427793', 'ielts_group_209774cb19d30e19e90df3d4', 'PART_3', 2, 'Why do you think some people like to help other people?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"Because they are willing to put themselves in other people''s shoes. Being compassionate gives them a strong reason to help someone else. Instead of considering volunteering as something you do for people who are not as fortunate as yourself, they think of it as an exchange. Most people find themselves in need at some point in their lives. So today you may be the person with the ability to help, but tomorrow you may be the recipient of someone else''s volunteer effort.\nput oneself in one''s shoes从..的角度思考 compassionate有同情心的\ninstead of不是..而是... exchange交换\nat some point在某些时候 recipient接受者","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_47ae99ff67d82a43b620e18a', 'ielts_group_209774cb19d30e19e90df3d4', 'PART_3', 3, 'Some people say that people help others In the community more now than they did in the past. Do you agree or disagree? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I don''t agree with this view. I think people are also less likely to help than before. The majority of people are more arrogant and self-centred than the past generations. We have less patience and tolerance for each other, let alone sympathy. Narcissism and hate is on the rise in both rural and urban communities. Particularly, the rich are more focused on holding onto and attaining wealth, unlike the poor spend more time with friends and loved ones.\narrogant 傲慢自大的 self-centered 以自我为中心的\ntolerance 宽容 let alone 更不用说\nsympathy 同情心 narcissism 自恋\nbe on the rise 上涨 hold onto 紧抓不放","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_73c35dd0f6871c8be075a252', 'ielts_group_209774cb19d30e19e90df3d4', 'PART_3', 4, 'What types of services, such as libraries or health centres, are available to the people who live in your area? Do you think there are enough of them?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"There are a number of important neighbourhood conveniences, like grocery store chain, dry cleaners, salon or barber, a range of restaurants to suit different tastes, natural spaces for enjoying the outdoors, and a gym that meets personal fitness needs. Things like this are too numerous to mention. But it couldn''t be better if there are coffeehouses or bars for hanging out and socialising, and auto-related amenities like a car wash and fueling station.\nneighbourhood convenience社区便利店 grocery store chain连锁商店\ndry cleaner干洗店 salon沙龙\nbarber理发店 a range of一些\nfitness健身\nThings like this are too numerous to mention.诸如此类,不胜枚举。\ncoffeehouse咖啡馆 hang out和朋友在一起，闲逛\nauto-related汽车相关的 amenity便利设施\ncar wash洗车处 fueling station加油站","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_fc4604f1de139f7922591869', 'ielts_group_209774cb19d30e19e90df3d4', 'PART_3', 5, 'Which group of people generally need most support in a community? Why?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"I think older people are with high support needs and we have the responsibilities to empower them to enjoy a better life. They must live in nursing care homes, or sheltered housing, or relatives homes,but many of them live in substandard private sector housing and some even live alone. Almost two thirds of older people felt they needed help in some aspects of daily living. The group of older people with high support needs is growing, becoming increasingly diverse and changing, and the prevalence of some conditions, such as dementia, increases.\nolder people老年人 empower使能够\nnursing care home医疗护理中心 sheltered housing长者居住所\nsubstandard不够标准的 private sector housing私人房屋\ndiverse多种多样的 prevalence盛行\nconditions健康状况 dementia痴呆","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
    ('ielts_q_b7b7f770d8b0d268c64e2a1e', 'ielts_group_209774cb19d30e19e90df3d4', 'PART_3', 6, 'Who do you think should pay for the services that are available to the people in a community? Should it be the government or individual people?', '[]'::JSONB, '[{"type":"RECOMMENDED_RESPONSE","expression":"For some public services, like heath care, they should be charged by governments. For example, one Community Service Card can help you and your family with the costs of health care. You will just pay less on some health services and prescriptions. But other services, like fitness centre, are borne by those consumers. Coz they satisfy individual needs.\nheath care医疗机构 prescription处方药.\nbe charged by由...支付 be borne by由...承担","translation":"","usageNote":"原题库提供的参考表达"}]'::JSONB),
