ON CONFLICT (id) DO UPDATE SET
    topic_id = EXCLUDED.topic_id,
    part = EXCLUDED.part,
    sort_no = EXCLUDED.sort_no,
    question_text = EXCLUDED.question_text,
    cue_points = EXCLUDED.cue_points,
    recommended_expressions = EXCLUDED.recommended_expressions;
-- ===== Achievement unlocks =====
CREATE TABLE IF NOT EXISTS user_achievement_unlock (
    user_id UUID NOT NULL,
    achievement_id VARCHAR(64) NOT NULL,
    unlocked_at TIMESTAMPTZ NOT NULL,
    acknowledged_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT user_achievement_unlock_pk
        PRIMARY KEY (user_id, achievement_id),
    CONSTRAINT user_achievement_unlock_id_check
        CHECK (BTRIM(achievement_id) <> ''),
    CONSTRAINT user_achievement_unlock_acknowledged_at_check
        CHECK (acknowledged_at IS NULL OR acknowledged_at >= unlocked_at)
);

CREATE INDEX IF NOT EXISTS idx_user_achievement_unlock_pending
ON user_achievement_unlock (user_id, unlocked_at, achievement_id)
WHERE acknowledged_at IS NULL;

COMMENT ON TABLE user_achievement_unlock IS
'用户已解锁的成就节点及中央达成弹窗展示确认状态';

COMMENT ON COLUMN user_achievement_unlock.user_id IS
'逻辑关联 user.id，不设置数据库外键';

COMMENT ON COLUMN user_achievement_unlock.achievement_id IS
'服务端成就目录中的稳定节点 ID，例如 conversation-1';

COMMENT ON COLUMN user_achievement_unlock.unlocked_at IS
'服务端首次确认该节点达成的时间';

COMMENT ON COLUMN user_achievement_unlock.acknowledged_at IS
'中央达成弹窗已经展示并关闭的时间；为空表示等待展示';

CREATE TABLE IF NOT EXISTS user_achievement_state (
    user_id UUID PRIMARY KEY,
    initialized_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE user_achievement_state IS
'用户成就系统首次历史初始化状态';

COMMENT ON COLUMN user_achievement_state.user_id IS
'逻辑关联 user.id，不设置数据库外键';

COMMENT ON COLUMN user_achievement_state.initialized_at IS
'首次完成历史成就静默初始化的时间';
-- ===== User feedback =====
CREATE TABLE IF NOT EXISTS user_feedback (
    id UUID PRIMARY KEY,
    feedback_no VARCHAR(32) NOT NULL UNIQUE,
    user_id UUID,
    lookup_code_hash CHAR(64) NOT NULL,
    category_id VARCHAR(32) NOT NULL,
    title VARCHAR(80) NOT NULL,
    description VARCHAR(2000) NOT NULL,
    environment VARCHAR(200),
    status VARCHAR(24) NOT NULL,
    reply VARCHAR(4000),
    replied_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT user_feedback_number_check CHECK (feedback_no ~ '^FB-[0-9]{8}-[A-F0-9]{12}$'),
    CONSTRAINT user_feedback_category_check CHECK (category_id IN (
        'quick-start',
        'account-login',
        'ai-training',
        'audio',
        'learning-records',
        'membership',
        'privacy-security',
        'feedback'
    )),
    CONSTRAINT user_feedback_status_check CHECK (status IN (
        'SUBMITTED',
        'IN_PROGRESS',
        'RESOLVED',
        'CLOSED'
    )),
    CONSTRAINT user_feedback_title_check CHECK (BTRIM(title) <> ''),
    CONSTRAINT user_feedback_description_check CHECK (BTRIM(description) <> ''),
    CONSTRAINT user_feedback_reply_time_check CHECK (
        (reply IS NULL AND replied_at IS NULL)
        OR (reply IS NOT NULL AND BTRIM(reply) <> '' AND replied_at IS NOT NULL)
    )
);

CREATE INDEX IF NOT EXISTS idx_user_feedback_user_created
ON user_feedback (user_id, created_at DESC)
WHERE user_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_user_feedback_status_updated
ON user_feedback (status, updated_at DESC);

COMMENT ON TABLE user_feedback IS
'帮助中心用户反馈、处理状态及工作人员回复';

COMMENT ON COLUMN user_feedback.user_id IS
'登录用户的逻辑关联 user.id；匿名反馈为空，不设置数据库外键';

COMMENT ON COLUMN user_feedback.lookup_code_hash IS
'匿名查询码的 SHA-256 摘要，不保存查询码明文';
-- ===== Interview practice =====
CREATE TABLE interview (
    id VARCHAR(64) PRIMARY KEY,
    user_id UUID NOT NULL,
    session_id VARCHAR(64) NOT NULL UNIQUE,
    job_title VARCHAR(255) NOT NULL,
    difficulty VARCHAR(16) NOT NULL,
    role_summary JSONB NOT NULL,
    recording_object_key VARCHAR(512),
    recording_duration_seconds INTEGER,
    completed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT interview_difficulty_check
        CHECK (difficulty IN ('BASIC', 'STANDARD', 'CHALLENGE')),
    CONSTRAINT interview_recording_duration_check
        CHECK (recording_duration_seconds IS NULL
            OR recording_duration_seconds >= 0)
);

CREATE INDEX idx_interview_user_completed_at
ON interview (user_id, completed_at DESC)
WHERE completed_at IS NOT NULL;

CREATE TABLE interview_question (
    interview_id VARCHAR(64) NOT NULL,
    question_no INTEGER NOT NULL,
    question_type VARCHAR(16) NOT NULL,
    question_text TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT interview_question_pk
        PRIMARY KEY (interview_id, question_no),
    CONSTRAINT interview_question_no_check
        CHECK (question_no >= 1),
    CONSTRAINT interview_question_type_check
        CHECK (question_type IN ('MAIN', 'FOLLOW_UP'))
);

CREATE TABLE interview_report (
    interview_id VARCHAR(64) PRIMARY KEY,
    report_type VARCHAR(16) NOT NULL,
    overall_score NUMERIC(4, 1) NOT NULL,
    overall_summary TEXT NOT NULL,
    fluency_score NUMERIC(4, 1) NOT NULL,
    fluency_evaluation TEXT NOT NULL,
    fluency_action_suggestion TEXT NOT NULL,
    logic_coherence_score NUMERIC(4, 1) NOT NULL,
    logic_coherence_evaluation TEXT NOT NULL,
    logic_coherence_action_suggestion TEXT NOT NULL,
    grammar_control_score NUMERIC(4, 1) NOT NULL,
    grammar_control_evaluation TEXT NOT NULL,
    grammar_control_action_suggestion TEXT NOT NULL,
    pronunciation_intelligibility_score NUMERIC(4, 1) NOT NULL,
    pronunciation_intelligibility_evaluation TEXT NOT NULL,
    pronunciation_intelligibility_action_suggestion TEXT NOT NULL,
    vocabulary_expression_score NUMERIC(4, 1) NOT NULL,
    vocabulary_expression_evaluation TEXT NOT NULL,
    vocabulary_expression_action_suggestion TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT interview_report_type_check
        CHECK (report_type IN ('FULL', 'PARTIAL')),
    CONSTRAINT interview_report_overall_score_check
        CHECK (overall_score BETWEEN 0 AND 100),
    CONSTRAINT interview_report_fluency_score_check
        CHECK (fluency_score BETWEEN 0 AND 100),
    CONSTRAINT interview_report_logic_coherence_score_check
        CHECK (logic_coherence_score BETWEEN 0 AND 100),
    CONSTRAINT interview_report_grammar_control_score_check
        CHECK (grammar_control_score BETWEEN 0 AND 100),
    CONSTRAINT interview_report_pronunciation_intelligibility_score_check
        CHECK (pronunciation_intelligibility_score BETWEEN 0 AND 100),
    CONSTRAINT interview_report_vocabulary_expression_score_check
        CHECK (vocabulary_expression_score BETWEEN 0 AND 100)
);
-- ===== IELTS learning assets =====
-- IELTS learning assets: per-Part topic attribution, per-Part diagnostics,
-- mock-test totals, check-ins and recording persistence.

ALTER TABLE user_ielts
    ADD COLUMN IF NOT EXISTS current_streak_days INTEGER NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS total_check_in_days INTEGER NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS last_check_in_date DATE;

ALTER TABLE user_ielts
    ADD CONSTRAINT user_ielts_current_streak_days_check
        CHECK (current_streak_days >= 0),
    ADD CONSTRAINT user_ielts_total_check_in_days_check
        CHECK (total_check_in_days >= 0);

ALTER TABLE ielts
    ADD COLUMN IF NOT EXISTS topic_selection_method VARCHAR(16),
    ADD COLUMN IF NOT EXISTS part1_topic_id VARCHAR(64),
    ADD COLUMN IF NOT EXISTS part2_topic_id VARCHAR(64),
    ADD COLUMN IF NOT EXISTS part3_topic_id VARCHAR(64);

-- Historical Part practices can be attributed exactly. The old model only
-- retained the Part 2/3 bundle for a mock test, so historical Part 1 topic IDs
-- intentionally remain NULL instead of being fabricated.
UPDATE ielts
SET topic_selection_method = CASE
        WHEN mode = 'MOCK_TEST' THEN 'RANDOM'
        ELSE 'USER_SELECTED'
    END,
    part1_topic_id = CASE
        WHEN mode = 'PART_PRACTICE' AND selected_part = 'PART_1'
            THEN selected_topic_id
        ELSE part1_topic_id
    END,
    part2_topic_id = CASE
        WHEN (mode = 'PART_PRACTICE' AND selected_part = 'PART_2')
            OR mode = 'MOCK_TEST'
            THEN selected_topic_id
        ELSE part2_topic_id
    END,
    part3_topic_id = CASE
        WHEN (mode = 'PART_PRACTICE' AND selected_part = 'PART_3')
            OR mode = 'MOCK_TEST'
            THEN selected_topic_id
        ELSE part3_topic_id
    END
WHERE topic_selection_method IS NULL
   OR part1_topic_id IS NULL
   OR part2_topic_id IS NULL
   OR part3_topic_id IS NULL;

ALTER TABLE ielts
