CREATE TABLE ielts_part_evaluation (
    part_evaluation_id VARCHAR(96) PRIMARY KEY,
    ielts_id VARCHAR(64) NOT NULL,
    session_id VARCHAR(64) NOT NULL,
    part VARCHAR(8) NOT NULL,
    fluency_coherence_score NUMERIC(3, 1),
    lexical_resource_score NUMERIC(3, 1),
    grammatical_range_accuracy_score NUMERIC(3, 1),
    pronunciation_score NUMERIC(3, 1),
    summary TEXT,
    strengths TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    improvements TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    recommended_expressions TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    evaluation_status VARCHAR(16) NOT NULL DEFAULT 'PENDING',
    failure_reason TEXT,
    completed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ielts_part_evaluation_session_unique UNIQUE (session_id),
    CONSTRAINT ielts_part_evaluation_practice_part_unique
        UNIQUE (ielts_id, part),
    CONSTRAINT ielts_part_evaluation_part_check
        CHECK (part IN ('PART_1', 'PART_2', 'PART_3')),
    CONSTRAINT ielts_part_evaluation_status_check
        CHECK (evaluation_status IN ('PENDING', 'COMPLETED', 'FAILED')),
    CONSTRAINT ielts_part_evaluation_fluency_check
        CHECK (fluency_coherence_score IS NULL
            OR fluency_coherence_score BETWEEN 0 AND 9),
    CONSTRAINT ielts_part_evaluation_lexical_check
        CHECK (lexical_resource_score IS NULL
            OR lexical_resource_score BETWEEN 0 AND 9),
    CONSTRAINT ielts_part_evaluation_grammar_check
        CHECK (grammatical_range_accuracy_score IS NULL
            OR grammatical_range_accuracy_score BETWEEN 0 AND 9),
    CONSTRAINT ielts_part_evaluation_pronunciation_check
        CHECK (pronunciation_score IS NULL
            OR pronunciation_score BETWEEN 0 AND 9),
    CONSTRAINT ielts_part_evaluation_completion_check
        CHECK (
            (evaluation_status = 'COMPLETED'
                AND completed_at IS NOT NULL
                AND summary IS NOT NULL
                AND BTRIM(summary) <> '')
            OR evaluation_status IN ('PENDING', 'FAILED')
        )
);

INSERT INTO ielts_part_evaluation (
    part_evaluation_id,
    ielts_id,
    session_id,
    part,
    fluency_coherence_score,
    lexical_resource_score,
    grammatical_range_accuracy_score,
    pronunciation_score,
    summary,
    strengths,
    improvements,
    recommended_expressions,
    evaluation_status,
    completed_at,
    created_at,
    updated_at
)
SELECT
    'ielts_part_' || session_id,
    ielts_id,
    session_id,
    part,
    fluency_coherence_score,
    lexical_resource_score,
    grammatical_range_accuracy_score,
    pronunciation_score,
    summary,
    strengths,
    improvements,
    recommended_expressions,
    'COMPLETED',
    updated_at,
    created_at,
    updated_at
FROM ielts_evaluation
WHERE assessment_type = 'DIAGNOSTIC'
ON CONFLICT (session_id) DO NOTHING;

