-- ===== IELTS topic title and history normalization =====
-- Keep learner-facing Part 2/3 topic names in English. The imported question
-- bank contains an English Part 2 cue-card question for every bundle, so it is
-- also the most reliable source when older rows contain translated titles.
WITH english_titles AS (
    SELECT DISTINCT ON (topic_id)
        topic_id,
        BTRIM(
            REGEXP_REPLACE(
                question_text,
                '^(Describe|Talk about)\s+',
                '',
                'i'
            ),
            ' .?'
        ) AS title
    FROM ielts_question
    WHERE part = 'PART_2'
      AND BTRIM(question_text) <> ''
    ORDER BY topic_id, sort_no
)
UPDATE ielts_topic AS topic
SET title = UPPER(LEFT(english_titles.title, 1))
        || SUBSTRING(english_titles.title FROM 2),
    updated_at = CURRENT_TIMESTAMP
FROM english_titles
WHERE topic.id = english_titles.topic_id
  AND topic.topic_type = 'PART_2_3_BUNDLE'
  AND english_titles.title <> '';

-- Older mock-test records predate the explicit per-Part topic columns. Recover
-- an exact topic only when the stored first question has one unambiguous match.
WITH part1_matches AS (
    SELECT practice.ielts_id, MIN(question.topic_id) AS topic_id
    FROM ielts AS practice
    JOIN ielts_question AS question
      ON question.part = 'PART_1'
     AND question.question_text = practice.content -> 'part1' -> 0 ->> 'question'
    WHERE practice.part1_topic_id IS NULL
    GROUP BY practice.ielts_id
    HAVING COUNT(DISTINCT question.topic_id) = 1
)
UPDATE ielts AS practice
SET part1_topic_id = part1_matches.topic_id,
    updated_at = CURRENT_TIMESTAMP
FROM part1_matches
WHERE practice.ielts_id = part1_matches.ielts_id;

WITH part2_matches AS (
    SELECT practice.ielts_id, MIN(question.topic_id) AS topic_id
    FROM ielts AS practice
    JOIN ielts_question AS question
      ON question.part = 'PART_2'
     AND question.question_text = practice.content -> 'part2' -> 0 ->> 'question'
    WHERE practice.part2_topic_id IS NULL
    GROUP BY practice.ielts_id
    HAVING COUNT(DISTINCT question.topic_id) = 1
)
UPDATE ielts AS practice
SET part2_topic_id = part2_matches.topic_id,
    updated_at = CURRENT_TIMESTAMP
FROM part2_matches
WHERE practice.ielts_id = part2_matches.ielts_id;

WITH part3_matches AS (
    SELECT practice.ielts_id, MIN(question.topic_id) AS topic_id
    FROM ielts AS practice
    JOIN ielts_question AS question
      ON question.part = 'PART_3'
     AND question.question_text = practice.content -> 'part3' -> 0 ->> 'question'
    WHERE practice.part3_topic_id IS NULL
    GROUP BY practice.ielts_id
    HAVING COUNT(DISTINCT question.topic_id) = 1
)
UPDATE ielts AS practice
SET part3_topic_id = part3_matches.topic_id,
    updated_at = CURRENT_TIMESTAMP
FROM part3_matches
WHERE practice.ielts_id = part3_matches.ielts_id;
